# Bin subdir name (script-dir-relative, qwen3 convention). Everything generated --
# params/programs bins AND the weights_export/ tree -- lives under it.
_BIN_SUBDIR = _CFG["paths"].get("bin_dir", "pi05_libero_bin")


def _weights_export_dir(script_dir=None):
    if script_dir is None:
        script_dir = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(script_dir, _BIN_SUBDIR, "weights_export")


# openpi's own env override for its cache root. Pointing it at the model's bin dir is
# what keeps the real-openpi path and the openpi-free path writing to the SAME place.
_OPENPI_DATA_HOME = "OPENPI_DATA_HOME"
_LEGACY_CKPT_CACHE = "~/.cache/openpi"


def _ckpt_cache_root(script_dir=None):
    """Root the raw upstream checkpoint downloads into <model>_bin/.

    Model convention (nn_lib.ensure_hf_model): a model's upstream weights live under
    its own ``<model>_bin/`` inside the model dir -- self-contained and deletable with
    the model, never a machine-global cache. pi05 was the outlier here: openpi's
    maybe_download defaults to ~/.cache/openpi. It honors OPENPI_DATA_HOME though, so
    setting that to the bin dir fixes BOTH the real-openpi path and the openpi-free
    one with a single mechanism (and an explicitly-set OPENPI_DATA_HOME still wins).
    """
    env = os.environ.get(_OPENPI_DATA_HOME)
    if env:
        return env
    if script_dir is None:
        script_dir = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(script_dir, _BIN_SUBDIR)


def _ckpt_local_dir(script_dir=None):
    """Where the checkpoint lands: <cache root>/<netloc>/<path>, openpi's own layout."""
    import urllib.parse
    parsed = urllib.parse.urlparse(_CFG["paths"]["openpi_checkpoint"])
    return os.path.join(_ckpt_cache_root(script_dir), parsed.netloc, parsed.path.strip("/"))


def ensure_tokenizer(script_dir=None):
    """Lazily materialize the PaliGemma SentencePiece tokenizer; return its path.

    Note this comes from a DIFFERENT bucket than the checkpoint
    (gs://big_vision, also public), which is why the pi05 checkpoint download
    alone never produces it -- openpi fetches it separately at tokenizer
    construction. Same cache root as everything else, so it lands in <model>_bin/.
    Idempotent and network-free once present (4 MB).
    """
    path = os.path.join(_ckpt_cache_root(script_dir),
                        *_CFG["paths"]["paligemma_tokenizer"].split("//")[1].split("/"))
    if os.path.exists(path):
        return path
    maybe_download, _ = _import_openpi()
    _prepare_ckpt_cache(script_dir)
    _original_print(f"[pi05_libero] fetching PaliGemma tokenizer -> {path}")
    # openpi needs gs={"token": "anon"} for this bucket; the fallback is anonymous
    # already and ignores the kwarg.
    return str(maybe_download(_CFG["paths"]["paligemma_tokenizer"], gs={"token": "anon"}))


def _prepare_ckpt_cache(script_dir=None):
    """Point openpi's cache at the bin dir, adopting any pre-existing ~/.cache copy.

    Returns the local checkpoint dir. The adopt step means an existing 12 GB download
    is moved rather than re-fetched (a rename when both sit on one filesystem).
    """
    import shutil
    root = _ckpt_cache_root(script_dir)
    os.environ[_OPENPI_DATA_HOME] = root          # openpi reads this at call time
    local = _ckpt_local_dir(script_dir)

    if not os.path.exists(os.path.join(local, "params")):
        import urllib.parse
        parsed = urllib.parse.urlparse(_CFG["paths"]["openpi_checkpoint"])
        legacy = os.path.join(os.path.expanduser(_LEGACY_CKPT_CACHE),
                              parsed.netloc, parsed.path.strip("/"))
        if os.path.exists(os.path.join(legacy, "params")):
            _original_print(f"[export] adopting existing checkpoint {legacy} -> {local}")
            os.makedirs(os.path.dirname(local), exist_ok=True)
            shutil.move(legacy, local)
    return local


def _weights_export_complete(wdir):
    """True iff wdir has a manifest.json and every .npy file it lists. Read-only."""
    manifest_path = os.path.join(wdir, "manifest.json")
    if not os.path.exists(manifest_path):
        return False, None
    try:
        with open(manifest_path) as f:
            manifest = json.load(f)
    except (ValueError, OSError):
        return False, None
    missing = [e["file"] for e in manifest.values()
               if not os.path.exists(os.path.join(wdir, e["file"]))]
    return (not missing), manifest


_OPENPI_MISSING_MSG = """\
pi05_libero needs the upstream pi05 checkpoint to export its weights, and NEITHER
source for it is usable in this environment: `openpi` is not importable, and the
openpi-free fallback (pi05_ckpt_noopenpi.py) could not load either.

The fallback is the normal path and needs only jax + orbax-checkpoint + flax,
which the engine env already has. So this almost always means one of those is
missing or broken:
    pip install "orbax-checkpoint" "flax" "jax"

Installing openpi proper also works, but is far heavier and NOT required:
    cd models/pi05_libero && pip install -r pi_requirements.txt
(openpi is not on PyPI under that name -- the PyPI `openpi` is an empty 0.0.0
placeholder -- so that file pulls the real one from git.)

Either way, re-run this script: the export runs once (~13 GB, from the pi05
checkpoint cached under <model>_bin/) and every later run detects the export
and skips the step.

Underlying import error: {err}
"""

_FALLBACK_ANNOUNCED = False


def _import_openpi():
    """Return (maybe_download, restore_params), or raise ImportError with the raw cause.

    The checkpoint source is needed exactly once (the weight export) and never for
    inference, which runs from params.bin on the FPGA. Two ways to get it:

      1. openpi proper, if it happens to be installed (pi_requirements.txt pulls it
         from git; PyPI's `openpi` is an empty 0.0.0 placeholder stub).
      2. pi05_ckpt_noopenpi -- the default path. Both symbols the export needs turn
         out to need none of openpi's model code: maybe_download is an anonymous
         HTTPS pull of a PUBLIC GCS bucket into the same bin-dir cache path, and
         restore_params is a plain orbax restore. Same cache, byte-identical export,
         without openpi's jax[cuda12]/lerobot/wandb dependency tree.
    """
    try:
        from openpi.models.model import restore_params
        from openpi.shared.download import maybe_download
        return maybe_download, restore_params
    except ImportError as openpi_err:
        # sys.path[0] is the script dir when run directly, but not when imported.
        _here = os.path.dirname(os.path.abspath(__file__))
        if _here not in sys.path:
            sys.path.insert(0, _here)
        try:
            from pi05_ckpt_noopenpi import import_openpi_fallback
        except ImportError as err:
            raise ImportError(f"{openpi_err} (fallback unavailable too: {err})") from err
        global _FALLBACK_ANNOUNCED
        if not _FALLBACK_ANNOUNCED:      # called twice per export; say it once
            _FALLBACK_ANNOUNCED = True
            _original_print(
                f"[export] openpi not importable ({openpi_err}) -- using the openpi-free "
                f"checkpoint path (pi05_ckpt_noopenpi: anonymous GCS download + orbax restore)")
        return import_openpi_fallback()


def _flatten_params(tree, prefix=""):
    """Flatten a params PyTree (nested dicts) to {dotted_name: np.ndarray}."""
    flat = {}
    for key, value in tree.items():
        name = f"{prefix}{key}"
        if isinstance(value, dict):
            flat.update(_flatten_params(value, prefix=f"{name}."))
        else:
            flat[name] = np.asarray(value)
    return flat


def _canonical_name(name):
    """Checkpoint leaf name -> manifest key.

    Strips a trailing ``.value`` (orbax wraps every leaf) and a leading ``params.``:
      params.PaliGemma.img.Transformer.encoder_norm.bias.value
        -> PaliGemma.img.Transformer.encoder_norm.bias
    Verified 1:1 against the checkpoint: 51 leaves <-> 51 manifest entries.
    """
    if name.endswith(".value"):
        name = name[: -len(".value")]
    if name.startswith("params."):
        name = name[len("params.") :]
    return name


def _restore_flat_params(cfg):
    """Resolve the checkpoint (downloading if needed) and return {name: np.ndarray}."""
    maybe_download, restore_params = _import_openpi()
    ckpt_url = cfg["paths"]["openpi_checkpoint"]
    _prepare_ckpt_cache()                        # download into <model>_bin/, not ~/.cache
    _original_print(f"[export] resolving checkpoint: {ckpt_url}")
    ckpt_dir = maybe_download(ckpt_url)          # cached under the bin dir, idempotent
    params_path = Path(ckpt_dir) / "params"
    _original_print(f"[export] restoring params from: {params_path}")
    params = restore_params(params_path, restore_type=np.ndarray)

    flat = {}
    for raw_name, arr in _flatten_params(params).items():
        name = _canonical_name(raw_name)
        if name in flat:
            raise RuntimeError(f"[export] duplicate name after canonicalization: {name}")
        flat[name] = np.asarray(arr)
    _original_print(f"[export] {len(flat)} leaves restored")
    return flat


def _do_export(cfg, out_dir):
    """Write every checkpoint tensor to out_dir as .npy + a manifest.json.

    Tensors are stored EXACTLY as the checkpoint has them (JAX-style (in, out)
    layout); _npy()'s consumers transpose at load time. Do NOT transpose here.
    """
    flat = _restore_flat_params(cfg)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    manifest = {}
    total_bytes = 0
    for name in sorted(flat):
        arr = flat[name]
        np.save(out_dir / f"{name}.npy", arr, allow_pickle=False)
        manifest[name] = {"shape": list(arr.shape), "dtype": str(arr.dtype),
                          "file": f"{name}.npy"}
        total_bytes += arr.nbytes
        _original_print(f"[export]   {name}  {tuple(arr.shape)}  {arr.dtype}")

    with open(out_dir / "manifest.json", "w") as f:
        json.dump(manifest, f, indent=2)
    _original_print(f"[export] wrote manifest.json ({len(manifest)} entries)")
    _original_print(f"[export] done -> {out_dir}  ({total_bytes / 1e9:.2f} GB)")
    return manifest


def ensure_weights_export(script_dir=None):
    """Lazily materialize ``weights_export/`` on first run (mirrors nn_lib.ensure_hf_model).

    No-op -- and provably read-only -- when the export is already complete: it only
    stats manifest.json and the files it lists. Otherwise it downloads the openpi
    checkpoint (cached in <model>_bin/, idempotent) and exports it.
    """
    wdir = _weights_export_dir(script_dir)
    complete, manifest = _weights_export_complete(wdir)
    if complete:
        return wdir

    _original_print(
        "\n" + "=" * 78 +
        "\n[pi05_libero] weights_export/ is missing or incomplete -- running the"
        "\n              one-time weight download + export step."
        "\n"
        f"\n              target : {os.path.abspath(wdir)}"
        "\n              size   : ~13 GB on disk (plus the openpi checkpoint cached"
        "\n                       under pi05_libero_bin/)"
        "\n              time   : expect this to take a while (download-bound)."
        "\n"
        "\n              This happens ONCE. Subsequent runs detect the export and skip it."
        "\n" + "=" * 78 + "\n")

    # _import_openpi raises ImportError carrying ONLY the raw cause, so
    # _OPENPI_MISSING_MSG renders exactly one set of install instructions.
    try:
        _import_openpi()
    except ImportError as err:
        raise RuntimeError(_OPENPI_MISSING_MSG.format(err=err)) from err

    _do_export(_CFG, wdir)

    complete, _ = _weights_export_complete(wdir)
    if not complete:
        raise RuntimeError(
            f"[pi05_libero] export finished but {wdir} is still incomplete. "
            f"Inspect the exporter output above.")
    _original_print(f"[pi05_libero] weights_export ready: {os.path.abspath(wdir)}")
    return wdir

# Pre-compiled bin location (paths.* are script-dir-relative, qwen3 convention).
BIN_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), _BIN_SUBDIR)

# Vision-geometry scalars that _weight_init_vision DERIVES and publishes on the instance
# (see its `V = self._cfg["vision"]` block and VIS_HEAD_OUT = hk.shape[1]). They are NOT
# DRAM addresses and NOT class attributes, so a run_from_bin engine -- which replaces the
# whole weight-init path with a params.bin restore -- never gets them, yet tensor_init/
# _tensor_init_vision/run_vision all read them. They are therefore persisted into
# programs.json's `derived` block at dump time and restored verbatim by Pi05Libero_Run.
#
# Persisted rather than recomputed from config on purpose: these are what the compiled
# programs were actually BUILT against. Recomputing from pi05_libero_config.json would
# silently diverge from the baked programs if the config were ever edited after a dump
# (garbage output, not an error), and VIS_HEAD_OUT is not config-derived at all -- it
# comes from the exported head-kernel's real shape.
#
# Derived by an AST sweep of the weight_init call graph vs everything reachable in bin
# mode; dump_programs_to_file asserts this list still covers every such attr.
_BIN_DERIVED_ATTRS = ("VIS_H", "VIS_NH", "VIS_D", "VIS_DP", "VIS_I", "VIS_I_PAD",
                      "VIS_S", "VIS_PATCH_K", "VIS_HEAD_OUT")


class _DebugStop(Exception):
    """Raised by Pi05Libero_UnifiedEngine._debug_op to unwind out of a compile_*
    method once the configured DEBUG_STOP_AFTER checkpoint has been emitted +
    halted, so only a partial (but valid, halted) program gets captured."""
    pass


def init_hang_prevention(ue):
    """5-step hardware clear. MUST stay identical to Pi05Libero_Run's path (see skill gotchas)."""
    halt = bytes(64)
    ue.dma_write(DMA_DEVICE_H2C, DRAM_INSTRUCTION_ADDR, halt, len(halt))
    print("[Init] HALT written to instruction DRAM base")


class Pi05Libero_UnifiedEngine(UnifiedEngine):
    _cfg = _CFG
    HIDDEN_SIZE       = _cfg["lm"]["hidden_size"]
    NUM_LAYERS        = _cfg["lm"]["num_layers"]
    NUM_HEADS         = _cfg["lm"]["num_heads"]
    NUM_KV_HEADS      = _cfg["lm"]["num_kv_heads"]
    GROUP_SIZE        = _cfg["lm"]["num_heads"] // _cfg["lm"]["num_kv_heads"]
    HEAD_DIM          = _cfg["lm"]["head_dim"]
    INTERMEDIATE_SIZE = _cfg["lm"]["intermediate_size"]
    VOCAB_SIZE        = _cfg["lm"]["vocab_size"]
    ROPE_THETA        = _cfg["lm"]["rope_theta"]
    RMS_NORM_EPS      = _cfg["lm"]["rms_norm_eps"]
    OPS               = _cfg["ops"]
    LM_QUANT          = _cfg["ops"]["lm_quant"]

    # Stepwise micro-op debug mode (see debug_stepwise.py): None = normal full
    # compile. Set to an int N (or via env var PI05_DEBUG_STOP_AFTER) to halt
    # the program immediately after the Nth _debug_op() checkpoint is emitted,
    # instead of compiling the whole thing -- lets us DMA-read that op's exact
    # HW output and assert it against a CPU reference before trusting the next
    # op. Move N up one at a time as each checkpoint passes.
    DEBUG_STOP_AFTER = None

    # Multi-engine-safe prefix early stop: None = compile all NUM_LAYERS. Set to an
    # int L to halt the prefix program right after layer L's residual2, on EVERY
    # engine (a layer boundary is the only lockstep point across shards -- see
    # _emit_prefix_body). Used by dual_engine_gates' prefix ladder; DEBUG_STOP_AFTER
    # is refused when the prefix is sharded.
    PREFIX_STOP_AFTER_LAYER = None

    # A/B knob for the 832-vs-576 prefix experiment (--keep-masked-slots).
    # False (default): all-zero image slots are DROPPED from the prefix -> 576 tokens.
    # True: they are carried as -inf-masked placeholder rows -> 832 tokens, ~1050
    # GFLOP/inference of provably-dead work. See run_vision.
    KEEP_MASKED_SLOTS = True

    # Whether the vision ENCODER skips all-zero (padding) image slots.
    # False (default): every slot is encoded on-HW, incl. LIBERO's all-zero 3rd
    # camera -- a full 3-slot vision pass, matching the GPU (which runs SigLIP on
    # all slots). True: skip the encoder for zero slots (saves a 27-layer pass).
    # Independent of masking: a zero slot is ALWAYS recorded in
    # masked_vision_slots and masked out of attention either way; when encoded,
    # its output is overwritten by a finite 1e-6 placeholder before the prefix.
    SKIP_ZERO_VISION_SLOTS = False

    # Text tokens reserved after the vision rows. The prefix length is DERIVED
    # (n_vision_rows + this), not read from config.prefill_max_seq_len -- that key
    # hardcoded "exactly 2 real cameras" and asserts out on a genuine 3-image obs.
    # Worst real LIBERO prompt is 62 tokens (libero_spatial t4).
    PREFIX_TEXT_BUDGET = 64

    def __init__(self, script_dir=None, **kw):
        layout = self._cfg["dram_layout"]
        kw.setdefault("params_dram_base", int(layout["params_dram_base"], 16))
        kw.setdefault("tensor_dram_base", int(layout["tensor_dram_base"], 16))
        kw.setdefault("program_dram_base", int(layout["program_dram_base"], 16))
        super().__init__(**kw)
        self.script_dir = script_dir or os.path.dirname(os.path.abspath(__file__))
        env_stop = os.environ.get("PI05_DEBUG_STOP_AFTER")
        if env_stop is not None:
            self.DEBUG_STOP_AFTER = int(env_stop)
        self._debug_counter = 0
        self._debug_halt_info = None

    def _debug_op(self, name, dram_addr, numel, shape=None, ue=None):
        """Call after emitting each op worth independently verifying. Assigns
        the next checkpoint index; if it matches DEBUG_STOP_AFTER, halts the
        program right here and raises _DebugStop so the caller's compile_*
        method unwinds early (catch it around the main body, then fall through
        to whatever finalization/subroutine-compile code normally follows).

        ``ue`` selects which engine's instruction stream the halt is emitted
        into (multi-engine encoder: every engine must halt at the SAME
        checkpoint index, else the un-halted engine keeps running and
        overwrites shared buffers). Defaults to self (engine 0)."""
        idx = self._debug_counter
        self._debug_counter += 1
        if self.DEBUG_STOP_AFTER is not None and idx == self.DEBUG_STOP_AFTER:
            (ue or self).generate_instruction_halt()
            self._debug_halt_info = {"idx": idx, "name": name, "addr": dram_addr,
                                      "numel": numel, "shape": shape}
            raise _DebugStop()
        return idx

    # ---- weights -----------------------------------------------------------
    def weight_init(self):
        """Loads all weights to params DRAM. Vision-encoder weights are owned by a
        concurrently-edited helper (_weight_init_vision); LM prefix-stack weights
        (embedder + 18 Gemma layers) are owned by _weight_init_lm_prefix below."""
        # First run on a fresh machine: materialize weights_export/ before any .npy read.
        # No-op (stat-only) once the export is present.
        ensure_weights_export(self.script_dir)
        if hasattr(self, "_weight_init_vision"):
            self._weight_init_vision()
        self._weight_init_lm_prefix()
        if hasattr(self, "weight_init_action_expert"):
            self.weight_init_action_expert()
        # Params-allocator checkpoint for run_from_bin. tensor_init allocates params too
        # (store_identity_matrix), so a bin run that rewound the params pointer all the
        # way to params.json's total would place the identity matrix PAST every weight
        # instead of at the address the programs bake. Record the boundary so
        # load_params() can restore exactly this pointer and let tensor_init re-allocate
        # (and re-write) the identity matrix at its original address.
        self._params_ofs_after_weight_init = self.get_params_dram_usage()

    # -- Vision encoder weights (SigLIP So400m/14, 27 layers) ----------------
    def _weight_init_vision(self):
        """Loads the SigLIP vision-encoder weights (``PaliGemma.img.*``) from
        ``weights_export/*.npy`` into params DRAM.

        Quantization policy: every matmul weight matrix (patch-embed kernel, q/k/v/out
        projections, MLP Dense_0/Dense_1, head projection) -> IF4 (q4_64) via
        ``store_quantized_weight``. LayerNorm scale/bias, every bias, and the additive
        pos-embedding stay bf16 via ``store_weight``.

        The engine's quantized matmul (``matmat_mul_core`` with ``is_B_quantized=True``)
        computes ``A @ Bᵀ`` where B is stored **N×K** (out,in) row-major (see
        ``matmat_mul_core`` docstring) — the opposite of the JAX/Flax ``.kernel`` layout
        (K,N = in,out) used by this checkpoint, so every kernel is ``.T``-transposed
        before quantization.
        """
        wdir = _weights_export_dir(self.script_dir)
        with open(os.path.join(wdir, "manifest.json")) as f:
            manifest = json.load(f)

        def _load(name):
            info = manifest[name]
            return torch.from_numpy(np.load(os.path.join(wdir, info["file"])))

        def _store_q4(mat_nk):
            """mat_nk: 2-D tensor already in N×K (out,in) layout."""
            packed, _ = _mlc_quantize_q4_64(mat_nk.to(torch.bfloat16).contiguous())
            return store_quantized_weight(self, packed)

        V = self._cfg["vision"]
        H  = V["hidden_size"]        # 1152
        NH = V["num_heads"]          # 16
        D  = V["head_dim"]           # 72
        DP = 128                     # padded head_dim for flash attention (72 -> 128)
        I  = V["intermediate_size"]  # 4304
        NP = V["num_patches"]        # 256
        PS = V["patch_size"]         # 14
        # matmat_mul_core_pbi's quantized-B path asserts K % UE_VECTOR_SIZE(64) == 0 (the scale
        # DRAM stride is linear in the K blocks). Patch-embed K=588 and the MLP inner dim
        # I=4304 are NOT 64-aligned, so pad both up to the next multiple of 64 with zeros
        # (extra input features / channels contribute exactly 0, so results are unaffected).
        PATCH_K = PS * PS * 3                                              # 588 (raw patch feature count)
        PK = ((PATCH_K + UE_VECTOR_SIZE - 1) // UE_VECTOR_SIZE) * UE_VECTOR_SIZE  # 640
        IP = ((I + UE_VECTOR_SIZE - 1) // UE_VECTOR_SIZE) * UE_VECTOR_SIZE        # 4352
        self.VIS_H, self.VIS_NH, self.VIS_D, self.VIS_DP = H, NH, D, DP
        self.VIS_I, self.VIS_I_PAD, self.VIS_S, self.VIS_PATCH_K = I, IP, NP, PK
        # The flash kernel applies an internal 1/sqrt(head_dim_pad) scale; pre-scale Q by
        # sqrt(head_dim_pad/head_dim) so the *effective* scale is the correct 1/sqrt(head_dim)
        # (proven pattern, see project_vision_attn_headdim_pad_unpad memory). Folded into the
        # Q weight/bias here so no extra runtime broadcast-mul is needed.
        q_scale = math.sqrt(DP / D)

        # --- patch embedding (K padded 588 -> 640; caller must zero-pad the patchified
        # pixel input to width PK too, see _tensor_init_vision) ---
        k = _load("PaliGemma.img.embedding.kernel").reshape(-1, H)          # [588, 1152] (K,N)
        b = _load("PaliGemma.img.embedding.bias")                          # [1152]
        k_pad = torch.zeros(PK, H, dtype=k.dtype)
        k_pad[:PATCH_K] = k
        self.vis_embed_scale, self.vis_embed_data = _store_q4(k_pad.T)     # -> [1152, 640] (N,K)
        self.vis_embed_bias = store_weight(self, b)
        self.vis_pos_embed = store_weight(self, _load("PaliGemma.img.pos_embedding").reshape(NP, H))

        # ---- K-SLICED PROJECTION WEIGHTS (2D vision shard: rows x K) ----------
        # Cut here, at weight-init, because B is stored N x K: a K-slice is a
        # COLUMN slice of B's rows -- strided, one gap per row -- so unlike an
        # N-shard it CANNOT be reached by shifting B_DRAM_ADDR. It has to be
        # materialized and re-quantized on the host, exactly like the denoise
        # mlp_down_k blobs.
        #
        # Re-quantizing a slice is exact, not approximate: quantize_q4_64 blocks
        # along K in groups of 64 and _col_split cuts on whole 64-blocks, so a
        # slice's blocks are BIT-IDENTICAL to the corresponding blocks of the
        # full-matrix quantization. The only numeric difference from the unsplit
        # matmul is bf16 accumulation ORDER across the partial sums.
        #
        # ONLY fc2 IS SLICED, and the reason is the matmul ABI, not preference:
        # matmat_mul_core reads A as M x K row-major with row stride K*bpe -- there
        # is no separate A-stride/lda. So a K-split is only expressible where A is
        # ALREADY a dense [M, Kc] buffer. That holds for fc2, whose A is fc1's
        # per-engine N-split output. It does NOT hold for q/k/v (A = the shared
        # [S, H] LayerNorm output) or for out-proj (A = the shared [S, HP]
        # attention output): a K-slice of those is strided, and slicing their
        # weights would produce blobs nothing can consume. They stay row-parallel.
        #
        # fc1 needs no host slicing at all -- it is N-split, and B is stored N x K,
        # so an N-slice is a contiguous ROW BLOCK reachable by address arithmetic.
        #
        # The full-width fc2 blob is kept alongside the slices (the 1-K-group path,
        # the SNR checks and the torch reference read it); ~68 MB of the params
        # region's ~513 MB of headroom.
        _vis_nk = self._vis_grid(self._num_engines("VIS"))[1]

        def _store_q4_k(mat_nk):
            """mat_nk (N,K) -> [(scale, data)] per K-slice, in engine order."""
            K = mat_nk.shape[1]
            sl = self._col_split(K, _vis_nk)
            assert all(kc % UE_VECTOR_SIZE == 0 for _, kc in sl), (
                f"vision K-slice of K={K} into {_vis_nk} is not 64-aligned ({sl}); "
                f"the q4_64 scale blocking would not line up with the full matrix")
            return [_store_q4(mat_nk[:, k0:k0 + kc].contiguous()) for k0, kc in sl]

        if _vis_nk > 1:
            print(f"    [vis] K-slicing fc2 weights {_vis_nk} ways x 27 layers for the 2D "
                  f"vision shard (fc1 is N-split by address arithmetic; q/k/v/out stay "
                  f"row-parallel -- no A-stride in the matmul ABI)")

        pfx = "PaliGemma.img.Transformer.encoderblock"
        ln0_w, ln0_b = _load(f"{pfx}.LayerNorm_0.scale"), _load(f"{pfx}.LayerNorm_0.bias")
        ln1_w, ln1_b = _load(f"{pfx}.LayerNorm_1.scale"), _load(f"{pfx}.LayerNorm_1.bias")
        q_k, q_b = _load(f"{pfx}.MultiHeadDotProductAttention_0.query.kernel"), _load(f"{pfx}.MultiHeadDotProductAttention_0.query.bias")
        k_k, k_b = _load(f"{pfx}.MultiHeadDotProductAttention_0.key.kernel"), _load(f"{pfx}.MultiHeadDotProductAttention_0.key.bias")
        v_k, v_b = _load(f"{pfx}.MultiHeadDotProductAttention_0.value.kernel"), _load(f"{pfx}.MultiHeadDotProductAttention_0.value.bias")
        o_k, o_b = _load(f"{pfx}.MultiHeadDotProductAttention_0.out.kernel"), _load(f"{pfx}.MultiHeadDotProductAttention_0.out.bias")
        d0_k, d0_b = _load(f"{pfx}.MlpBlock_0.Dense_0.kernel"), _load(f"{pfx}.MlpBlock_0.Dense_0.bias")
        d1_k, d1_b = _load(f"{pfx}.MlpBlock_0.Dense_1.kernel"), _load(f"{pfx}.MlpBlock_0.Dense_1.bias")

        self.vis_layer_addrs = []
        for l in range(27):
            la = {}
            la['ln0_w'] = store_weight(self, ln0_w[l])
            la['ln0_b'] = store_weight(self, ln0_b[l])
            la['ln1_w'] = store_weight(self, ln1_w[l])
            la['ln1_b'] = store_weight(self, ln1_b[l])

            # Q/K/V projections: pad each head's OUTPUT block D->DP (72->128) with zero
            # columns/bias, concatenated per head (col h*DP:h*DP+D real, h*DP+D:h*DP+DP
            # zero) -- the proven qwen2.5_vl_3b "qk_padded/v_padded" pattern. This keeps
            # every per-head DMA stride a full DP*bpe=256B (AXI-beat aligned) instead of
            # D*bpe=144B (NOT a multiple of the 32B AXI beat), and needs no separate
            # real-vs-padded strided copy at attention time.
            def _pad_proj(k_l, b_l, scale=1.0):
                k2d = k_l.reshape(H, NH, D)                    # (K, heads, D)
                k_pad = torch.zeros(H, NH, DP, dtype=k2d.dtype)
                k_pad[:, :, :D] = k2d * scale
                b_pad = torch.zeros(NH, DP, dtype=b_l.dtype)
                b_pad[:, :D] = b_l * scale
                return k_pad.reshape(H, NH * DP).T, b_pad.reshape(NH * DP)  # (N,K), (N)

            qk, qb = _pad_proj(q_k[l], q_b[l], q_scale)
            la['q_scale'], la['q_data'] = _store_q4(qk)
            la['q_bias'] = store_weight(self, qb)

            for short, kk_l, kb_l in (('k', k_k[l], k_b[l]), ('v', v_k[l], v_b[l])):
                kk, kb = _pad_proj(kk_l, kb_l)
                la[f'{short}_scale'], la[f'{short}_data'] = _store_q4(kk)
                la[f'{short}_bias'] = store_weight(self, kb)

            # Out projection: pad each head's INPUT block D->DP (zero rows) to match the
            # padded-concatenated attention-output layout (padded columns are exactly 0 on
            # both sides, so the extra zero rows contribute nothing either way).
            o3d = o_k[l].reshape(NH, D, H)                      # (heads, D, out)
            o_pad = torch.zeros(NH, DP, H, dtype=o3d.dtype)
            o_pad[:, :D, :] = o3d
            ok = o_pad.reshape(NH * DP, H).T                    # (N=H, K=NH*DP)
            la['o_scale'], la['o_data'] = _store_q4(ok)
            la['o_bias'] = store_weight(self, o_b[l])

            # fc1 (Dense_0): pad OUTPUT width I->IP with zero columns/bias so fc1's own
            # output buffer is directly IP-wide (real values in [0:I], exact zeros in
            # [I:IP] since both weight and bias are zero there) — no separate scatter needed.
            d0k_pad = torch.zeros(H, IP, dtype=d0_k.dtype)
            d0k_pad[:, :I] = d0_k[l]
            d0b_pad = torch.zeros(IP, dtype=d0_b.dtype)
            d0b_pad[:I] = d0_b[l]
            la['fc1_scale'], la['fc1_data'] = _store_q4(d0k_pad.T)          # [4352,1152] (N,K)
            la['fc1_bias'] = store_weight(self, d0b_pad)

            # fc2 (Dense_1): pad INPUT (K) I->IP with zero rows (fc1's padded zero columns
            # contribute exactly 0 through these zero weight rows).
            d1k_pad = torch.zeros(IP, H, dtype=d1_k.dtype)
            d1k_pad[:I] = d1_k[l]
            la['fc2_scale'], la['fc2_data'] = _store_q4(d1k_pad.T)          # [1152,4352] (N,K)
            la['fc2_bias'] = store_weight(self, d1_b[l])
            if _vis_nk > 1:
                la['fc2_k'] = _store_q4_k(d1k_pad.T.contiguous())

            self.vis_layer_addrs.append(la)

        self.vis_encoder_norm_w = store_weight(self, _load("PaliGemma.img.Transformer.encoder_norm.scale"))
        self.vis_encoder_norm_b = store_weight(self, _load("PaliGemma.img.Transformer.encoder_norm.bias"))

        hk = _load("PaliGemma.img.head.kernel")   # [1152, 2048] (K,N)
        hb = _load("PaliGemma.img.head.bias")
        self.VIS_HEAD_OUT = hk.shape[1]
        self.vis_head_scale, self.vis_head_data = _store_q4(hk.T)          # [2048,1152] (N,K)
        self.vis_head_bias = store_weight(self, hb)

        print(f"_weight_init_vision done; params DRAM usage: {self.get_params_dram_usage()} bytes")

    # -- LM prefix stack weights (Gemma-2B: embedder + 18 layers) ------------
    def _npy(self, name):
        """Load one exported weight array (float32) from weights_export/<name>.npy."""
        path = os.path.join(_weights_export_dir(self.script_dir), f"{name}.npy")
        return torch.from_numpy(np.load(path).astype(np.float32))

    def _quant_store(self, w2d):
        """w2d: (out, in) float32 -> quantize_q4_64 -> store_quantized_weight. in-dim must be %64==0."""
        w2d = w2d.to(torch.bfloat16).contiguous()
        packed, _ = _mlc_quantize_q4_64(w2d)
        return store_quantized_weight(self, packed)

    def _weight_init_lm_prefix(self):
        """Loads the Gemma-2B prefix LM stack: token embedder (host-side gather table,
        kept resident as bf16 for use at compile_prefix time) + per-layer RMSNorm
        (bf16, unquantized) + attn/mlp matmul weights (IF4 q4_64, per quant policy)."""
        H, D, I = self.HIDDEN_SIZE, self.HEAD_DIM, self.INTERMEDIATE_SIZE
        NH, NKV = self.NUM_HEADS, self.NUM_KV_HEADS

        # Embedder: kept as a host-resident bf16 lookup table (gather, not a matmul) —
        # rows are indexed directly at compile_prefix() time, no DRAM matmul weight needed.
        self.embedding_table = self._npy("PaliGemma.llm.embedder.input_embedding").to(torch.bfloat16)

        q_all = self._npy("PaliGemma.llm.layers.attn.q_einsum.w")          # (18, 8, 2048, 256)
        kv_all = self._npy("PaliGemma.llm.layers.attn.kv_einsum.w")        # (18, 2, 1, 2048, 256)
        o_all = self._npy("PaliGemma.llm.layers.attn.attn_vec_einsum.w")   # (18, 8, 256, 2048)
        ln1_all = self._npy("PaliGemma.llm.layers.pre_attention_norm.scale")  # (18, 2048)
        ln2_all = self._npy("PaliGemma.llm.layers.pre_ffw_norm.scale")        # (18, 2048)
        gate_up_all = self._npy("PaliGemma.llm.layers.mlp.gating_einsum")     # (18, 2, 2048, 16384)
        down_all = self._npy("PaliGemma.llm.layers.mlp.linear")               # (18, 16384, 2048)

        self.lm_layer_addrs = []
        for l in range(self.NUM_LAYERS):
            la = {}
            # rms_norm_core multiplies by GAMMA directly, no implicit +1 (confirmed
            # by reading rms_norm_core's eltwise_mul_core call in user_dma_core.py --
            # same gotcha already handled correctly for the action-expert's plain
            # AdaRMSNorm via AE_ONES_DRAM). Gemma checkpoints store this weight as a
            # DELTA from 1 (pi05_torch_ref.rms_norm applies `normed * (1.0 + scale)`),
            # so the raw checkpoint value must be pre-offset by +1 here to match --
            # this was a real bug: layer0's ln1 SNR was -3.17dB with the raw value.
            la["ln1"] = store_weight(self, ln1_all[l] + 1.0)
            la["ln2"] = store_weight(self, ln2_all[l] + 1.0)

            # q_einsum[l]: (heads, d_in=2048, head_dim=256) each head is (in,out) -> transpose
            # to (out,in) per head, stack heads along N (out) axis -> (heads*head_dim, d_in).
            q_heads = [q_all[l, h].transpose(0, 1) for h in range(NH)]       # each (256, 2048)
            q_2d = torch.cat(q_heads, dim=0)                                  # (2048, 2048) = (N,K)
            la["q_scale"], la["q_data"] = self._quant_store(q_2d)

            k_2d = kv_all[l, 0, 0].transpose(0, 1)   # (head_dim, d_in) = (256, 2048)
            v_2d = kv_all[l, 1, 0].transpose(0, 1)
            la["k_scale"], la["k_data"] = self._quant_store(k_2d)
            la["v_scale"], la["v_data"] = self._quant_store(v_2d)

            # attn_vec_einsum[l]: (heads, head_dim, d_out) -> merge (heads,head_dim) as
            # the K (in) axis, matching the (seq, heads*head_dim) attn-output layout,
            # transpose to (out, in).
            o_2d = o_all[l].reshape(NH * D, H).transpose(0, 1)   # (2048, 2048) = (N=d_out, K=heads*hd)
            la["o_scale"], la["o_data"] = self._quant_store(o_2d)

            # Gated MLP, split gate/up/down into two FF_HALF=8192-wide halves each --
            # NOT for correctness (gate/up's own N=16384 already fits matmat_mul_core_pbi
            # fine) but so down_proj's K=16384 input is available as two ALREADY-
            # SEPARATE, naturally-contiguous FF_HALF buffers from the moment they're
            # written, with no strided/gather DMA extraction step needed afterward.
            # matmat_mul_core_pbi asserts K*16 <= URAM_NEAR_FULL_ELEMENTS; K=16384
            # fails that (16384*16=262144 > 262080) so down_proj genuinely cannot run
            # as one full-K matmul (confirmed via the assertion firing when tried).
            # The old fix materialized the two K-halves via _dram_split_copy (a
            # strided per-row column-slice DMA) AFTER computing gate*up at full width
            # -- that strided copy was the confirmed hang trigger (debug_stepwise_
            # prefix.py bisection: clean through layer0_mlp_gate_up, hangs at
            # layer0_mlp_split_copy). This mirrors parakeet_test.py's proven FF_HALF
            # K-split pattern instead: split gate/up into two N=FF_HALF matmuls FIRST
            # (each writes its own naturally-separate buffer), multiply each half
            # independently, then down-project each half (K=FF_HALF, safely under the
            # URAM cap) and sum the two partial results -- no strided DMA anywhere.
            #
            # LANE-GENERIC (see PREFIX_MLP_LANES): the same slicing, `lanes` ways
            # instead of hard-coded 2, so a column lane can be handed to each engine.
            # gate/up slice along N (whole output rows of the (N,K) matrix), so the
            # q4_64 blocking -- which runs along K -- is untouched. down slices along
            # K, and each lane is re-quantized over its OWN K-slice; that is exactly
            # what the lo/hi code already did, and FF_LANE % 64 == 0 (enforced in
            # _prefix_mlp_lanes) guarantees no scale block is ever cut in half.
            #
            # STORE ORDER IS LOAD-BEARING: all gates, then all ups, then all downs.
            # At lanes == 2 that reproduces the historical
            # gate_lo/gate_hi/up_lo/up_hi/down_lo/down_hi sequence address-for-address,
            # so the single-engine params layout is unchanged.
            gate_2d = gate_up_all[l, 0].transpose(0, 1)   # (16384,2048) = (N,K)
            up_2d = gate_up_all[l, 1].transpose(0, 1)
            down_2d = down_all[l].transpose(0, 1)         # (2048,16384) = (N,K)
            lanes, _ = self._prefix_mlp_lanes()
            FF_LANE = gate_2d.shape[0] // lanes
            for i in range(lanes):
                sl = slice(i * FF_LANE, (i + 1) * FF_LANE)
                la[f"gate_l{i}_scale"], la[f"gate_l{i}_data"] = self._quant_store(gate_2d[sl].contiguous())
            for i in range(lanes):
                sl = slice(i * FF_LANE, (i + 1) * FF_LANE)
                la[f"up_l{i}_scale"], la[f"up_l{i}_data"] = self._quant_store(up_2d[sl].contiguous())
            for i in range(lanes):
                sl = slice(i * FF_LANE, (i + 1) * FF_LANE)
                la[f"down_l{i}_scale"], la[f"down_l{i}_data"] = self._quant_store(down_2d[:, sl].contiguous())

            self.lm_layer_addrs.append(la)
        print(f"_weight_init_lm_prefix: {self.NUM_LAYERS} layers loaded")

    # ---- tensors -----------------------------------------------------------
    def tensor_init(self, max_seq_len=512):
        """Allocate activation/KV buffers. Addresses chosen by allocate_tensor_dram.
        NOTE: every buffer's innermost dim must be a multiple of 64 (pad if not)."""
        bpe = 2
        S, H, I, D = max_seq_len, self.HIDDEN_SIZE, self.INTERMEDIATE_SIZE, self.HEAD_DIM
        KV = self.NUM_KV_HEADS * D
        self.KV_HEAD_STRIDE = S * D * bpe
        self.KV_LAYER_STRIDE = self.NUM_KV_HEADS * self.KV_HEAD_STRIDE
        kv_total = self.NUM_LAYERS * self.KV_LAYER_STRIDE
        self.LAYER0_K_DRAM = self.allocate_tensor_dram(kv_total)
        self.LAYER0_V_DRAM = self.allocate_tensor_dram(kv_total)
        self.LAYER0_INPUT_DRAM    = self.allocate_tensor_dram(S * H * bpe)
        self.LAYER0_PRE_NORM_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.LAYER0_Q_DRAM        = self.allocate_tensor_dram(S * H * bpe)
        self.LAYER0_K_PROJ_DRAM   = self.allocate_tensor_dram(S * KV * bpe)
        self.LAYER0_V_PROJ_DRAM   = self.allocate_tensor_dram(S * KV * bpe)
        self.LAYER0_Q_PERM_DRAM   = self.allocate_tensor_dram(S * H * bpe)
        self.LAYER0_ATTN_OUT_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.LAYER0_ATTN_SCRATCH_DRAM = self.allocate_tensor_dram((D * S + max(D, 64) * S) * bpe)
        self.LAYER0_ATTN_RESULT_DRAM  = self.allocate_tensor_dram(S * H * bpe)
        # Shared-subroutine flash attention (mirrors compile_encoder's vision
        # pattern): the flash body is compiled ONCE and jumped to from every
        # (layer, head) call site instead of being statically re-emitted 18x
        # (one full seq_len=1024 attention body per layer was the actual root
        # cause of compile_prefix hanging for hours -- prefill_flash_attention_core
        # has no PBI/runtime-loop mode at all, only flash_attention_core does).
        # K/V need no per-head marshalling (MQA: same buffer for every head,
        # already fixed at LAYER0_K_PROJ_DRAM/LAYER0_V_PROJ_DRAM); only Q needs
        # copying into this fixed scratch slot before each jump, and OUTPUT
        # needs copying out after each return.
        self.LAYER0_FLASH_Q_DRAM = self.allocate_tensor_dram(S * D * bpe)
        self.LAYER0_FLASH_OUT_DRAM = self.allocate_tensor_dram(S * D * bpe)
        self.LAYER0_FLASH_ATTN_P_DRAM = self.allocate_tensor_dram(S * S * bpe)
        self.LAYER0_O_PROJ_DRAM   = self.allocate_tensor_dram(S * H * bpe)
        # Gated MLP, FF_HALF-split (see _weight_init_lm_prefix's down_proj comment for
        # why: avoids a strided-DMA K-split extraction that was the confirmed hang
        # trigger). Each half is independently computed/multiplied/down-projected.
        # LANE-GENERIC (see PREFIX_MLP_LANES). Same order as before -- all gates,
        # all ups, all mults, then the per-lane down partials -- so lanes == 2
        # reproduces the historical GATE_LO/GATE_HI/UP_LO/... addresses exactly.
        # Total gate/up/mult bytes are INVARIANT in the lane count (lanes *
        # S*(I/lanes) == S*I); only the partials grow, by (lanes-2) * S*H*bpe.
        lanes, mlp_col_split = self._prefix_mlp_lanes()
        FF_LANE = I // lanes
        self.PREFIX_MLP_LANES_RESOLVED = lanes
        self.LAYER0_MLP_GATE_DRAM = [self.allocate_tensor_dram(S * FF_LANE * bpe) for _ in range(lanes)]
        self.LAYER0_MLP_UP_DRAM   = [self.allocate_tensor_dram(S * FF_LANE * bpe) for _ in range(lanes)]
        self.LAYER0_MLP_MULT_DRAM = [self.allocate_tensor_dram(S * FF_LANE * bpe) for _ in range(lanes)]
        self.LAYER0_MLP_PARTIAL_DRAM = [self.allocate_tensor_dram(S * H * bpe) for _ in range(lanes)]
        # Ping-pong accumulators for the lanes-1 partial adds. eltwise with OUT
        # aliasing either input is a CONFIRMED HANG (see compile_prefix), so the
        # reduce alternates between these two and lands its LAST add directly in
        # LAYER0_MLP_DOWN_DRAM -- no in-place step anywhere in the chain.
        self.LAYER0_MLP_ACC_DRAM = [self.allocate_tensor_dram(S * H * bpe) for _ in range(2)]
        self.LAYER0_MLP_DOWN_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.FINAL_NORM_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.LOGITS_DRAM     = self.allocate_tensor_dram(self.VOCAB_SIZE * bpe)

        # Zero the K/V cache. NOT cosmetic: this DRAM cannot be READ until it has been
        # WRITTEN at least once -- an untouched address returns EIO from dma_read, it does
        # not return garbage. (Verified: a 4KB read at 0xE0068000 fails, the identical read
        # after writing 4KB of zeros there succeeds.)
        #
        # The prefix only fills the first prefix_len rows of each (layer, head) slab, but
        # these buffers are sized for max_seq_len, so the tail of every slab stays virgin.
        # dump_prefix_kv reads the whole kv_total span and used to walk straight into it --
        # that is the source of the two `dma_read error: [Errno 5]` lines, and the reason
        # the failing offsets were spaced exactly KV_LAYER_STRIDE apart.
        # Written in explicit 1MB chunks of one small buffer: _dma_write_retry's own
        # chunking indexes a torch tensor by BYTE offset (data.flatten()[offset:...]),
        # which desyncs past the first chunk for a multi-MB tensor.
        _chunk = self.DMA_CHUNK_BYTES
        zeros_kv = torch.zeros(_chunk // bpe, dtype=torch.bfloat16)
        for _kv_base in (self.LAYER0_K_DRAM, self.LAYER0_V_DRAM):
            for _off in range(0, kv_total, _chunk):
                _n = min(_chunk, kv_total - _off)
                self._dma_write_retry(DMA_DEVICE_H2C, _kv_base + _off, zeros_kv, _n)
        if IS_VLM:
            # NOT in params.bin — must be re-allocated here (see skill gotchas).
            # store_identity_matrix always produces a fixed UE_VECTOR_SIZE(64)x64 identity;
            # it is reused as-is by the flash kernel regardless of head_dim/head_dim_pad.
            self.identity_addr = store_identity_matrix(self)
            self._tensor_init_vision()
        print(f"tensor_init done; tensor DRAM at 0x{self.get_tensor_dram_addr():X}")
        self.dram_region_map("after tensor_init")

    def _tensor_init_vision(self):
        """Allocate vision-encoder activation/scratch DRAM. Appended at the END of
        tensor_init (after all LM buffers) so no earlier LM buffer address shifts
        (Pi05Libero_Run must mirror this ordering — see skill gotchas)."""
        bpe = 2
        H, NH, D, DP, I, IP, S = (self.VIS_H, self.VIS_NH, self.VIS_D, self.VIS_DP,
                                   self.VIS_I, self.VIS_I_PAD, self.VIS_S)
        PK = self.VIS_PATCH_K   # 640 (588 padded to a multiple of 64), patch-embed matmul K
        HO = self.VIS_HEAD_OUT  # 2048, head projection output width

        # Patchified pixel input (host pre-patchifies raw pixels into [S, 588], mirroring the
        # torch reference's unfold+reshape, zero-padded to width PK=640 — no on-device
        # patchify is compiled here). Zero the whole buffer once so the pad columns
        # [588:640] the host never writes stay exactly 0 (matches the zero-padded kernel).
        self.VIS_PIXEL_IN_DRAM   = self.allocate_tensor_dram(S * PK * bpe)
        self.dma_write(DMA_DEVICE_H2C, self.VIS_PIXEL_IN_DRAM,
                        torch.zeros(S * PK, dtype=torch.bfloat16), S * PK * bpe)
        self.VIS_PATCH_PROJ_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.VIS_IO_A_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.VIS_IO_B_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.VIS_LN_OUT_DRAM = self.allocate_tensor_dram(S * H * bpe)
        # Q/K/V/attn-result are per-head-padded (D->DP=128, see _weight_init_vision's
        # _pad_proj) so every per-head DMA stride is AXI-beat aligned.
        HP = NH * DP
        self.VIS_Q_DRAM = self.allocate_tensor_dram(S * HP * bpe)
        self.VIS_K_DRAM = self.allocate_tensor_dram(S * HP * bpe)
        self.VIS_V_DRAM = self.allocate_tensor_dram(S * HP * bpe)
        self.VIS_ATTN_RESULT_DRAM = self.allocate_tensor_dram(S * HP * bpe)
        self.VIS_O_PROJ_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.VIS_RESIDUAL_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.VIS_MLP_INTER_DRAM = self.allocate_tensor_dram(S * IP * bpe)  # padded I->IP (see fc1/fc2)
        self.VIS_MLP_OUT_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.VIS_POST_LN_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.VIS_HEAD_OUT_DRAM = self.allocate_tensor_dram(S * HO * bpe)

        # Per-layer output snapshots (probe_nan_report): the real per-layer
        # output buffer (VIS_IO_A/B_DRAM) ping-pongs between two shared
        # buffers, so only the LAST layer's value survives a full run --
        # copy each layer's residual2 output to its own dedicated slot too,
        # so a single post-run readback can NaN-check every layer at once
        # instead of paying for 27 separate halt-recompile-rerun cycles.
        self.VIS_LAYER_SNAPSHOT_DRAM = [self.allocate_tensor_dram(S * H * bpe) for _ in range(27)]

        # LN zeros-replay buffer, shared by every LN call (see layer_norm_core_dram_pbi).
        self.vis_zeros_addr = self.allocate_tensor_dram(max(H, I) * bpe)
        self.dma_write(DMA_DEVICE_H2C, self.vis_zeros_addr,
                        torch.zeros(max(H, I), dtype=torch.bfloat16), max(H, I) * bpe)

        # §7 shared-subroutine per-head attention (proven smolvlm2/qwen2.5vl pattern): one
        # flash body reused across all (layer, head) call sites via strided-DMA head
        # marshalling. Buffers are padded to DP=128 (head_dim 72 -> 128, see hw_notes/
        # project_vision_attn_headdim_pad_unpad); only the real 72 columns are ever written
        # by the per-head gather/scatter, so the padded tail columns stay zero forever once
        # zero-initialized here — K's padded lanes dot to 0 and V's padded lanes contribute
        # 0 to the weighted sum, so attention math is unaffected and no explicit unpad
        # selection-matrix step is needed (the padding is self-annihilating by construction).
        self.VIS_FLASH_Q_DRAM = self.allocate_tensor_dram(S * DP * bpe)
        self.VIS_FLASH_K_DRAM = self.allocate_tensor_dram(S * DP * bpe)
        self.VIS_FLASH_V_DRAM = self.allocate_tensor_dram(S * DP * bpe)
        self.VIS_FLASH_OUT_DRAM = self.allocate_tensor_dram(S * DP * bpe)
        self.VIS_FLASH_ATTN_P_DRAM = self.allocate_tensor_dram(S * S * bpe)
        # unified_attention_core_dynamic scratch: V.T[DP,S] + score/P[S,S] + scaled_q[S,DP].
        self.VIS_ATTN_SCRATCH_DRAM = self.allocate_tensor_dram((DP * S + S * S + S * DP) * bpe)
        # Zero additive bias (batch=S, aligned=S): vision attention is bidirectional/unmasked,
        # so a single (S, S) zeros buffer is reused for every (layer, head) call.
        self.VIS_ZERO_BIAS_DRAM = self.allocate_tensor_dram(S * S * bpe)
        self.dma_write(DMA_DEVICE_H2C, self.VIS_ZERO_BIAS_DRAM,
                        torch.zeros(S * S, dtype=torch.bfloat16), S * S * bpe)
        zeros_dp = torch.zeros(S * DP, dtype=torch.bfloat16)
        for addr in (self.VIS_FLASH_Q_DRAM, self.VIS_FLASH_K_DRAM, self.VIS_FLASH_V_DRAM):
            self.dma_write(DMA_DEVICE_H2C, addr, zeros_dp, S * DP * bpe)
        print(f"    _tensor_init_vision done; tensor DRAM at 0x{self.get_tensor_dram_addr():X}")

    # ---- matmul dispatch ---------------------------------------------------
    def _matmul(self, M, K, N, A, proj, la, OUT, ue=None, **kw):
        """Dispatch a (M,K)@(N,K)^T matmul against per-layer weight dict `la`, keyed by
        `proj` (e.g. 'q', 'k', 'v', 'o', 'gate', 'up', 'down'). All LM prefix weights are
        IF4 q4_64 per quant policy.

        ``ue`` selects the emitting engine (row-sharded multi-engine prefix);
        defaults to self (engine 0). Weights/scales are SHARED_FULL -- every
        engine reads the same params DRAM, nothing is duplicated."""
        assert self.LM_QUANT == "q4_64", f"unsupported LM_QUANT={self.LM_QUANT}"
        return (ue or self).matmat_mul_core(
            M=M, K=K, N=N, A_DRAM_ADDR=A, B_DRAM_ADDR=la[f"{proj}_data"],
            OUTPUT_DRAM_ADDR=OUT, is_B_quantized=True, data_type=TYPE.IF4,
            SCALE_DRAM_ADDR=la[f"{proj}_scale"], **kw)

    def _dram_copy(self, size_bytes, src, dst, ue=None):
        """DRAM->DRAM copy via a SRAM roundtrip, chunked through URAM_A. Used to
        stage per-layer K/V projections into the persistent KV-cache region.
        ``ue`` selects the emitting engine (multi-engine encoder); defaults to self."""
        bpe = 2
        eng = ue or self
        elems = size_bytes // bpe
        chunk = min(URAM_NEAR_FULL_ELEMENTS, elems)
        sram = 0x00000
        for start, take in eng.chunk_ranges(elems, chunk):
            off = start * bpe
            eng.accelerator_memory_to_sram(src + off, sram, take)
            eng.sram_to_accelerator_memory(sram, dst + off, take)

    def _dram_split_copy(self, rows, row_elems, col_offset, col_take, src, dst):
        """Extract a column slice [col_offset : col_offset+col_take) from a (rows,
        row_elems) row-major DRAM buffer into its own tightly-packed (rows, col_take)
        DRAM buffer, via a strided SRAM roundtrip. Used to materialize contiguous
        K-halves of the MLP intermediate (S, I) buffer for the down-proj K-split
        (matmat_mul_core_legacy cannot chunk K=16384 in one call; see compile_prefix)."""
        bpe = 2
        row_chunk = max(1, URAM_NEAR_FULL_ELEMENTS // col_take)
        sram = 0x00000
        for start, take in self.chunk_ranges(rows, row_chunk):
            self.accelerator_memory_to_sram(
                src + (start * row_elems + col_offset) * bpe, sram, take * col_take,
                stride_bytes_per_chunk=col_take * bpe, stride_jump_bytes=row_elems * bpe)
            self.sram_to_accelerator_memory(sram, dst + start * col_take * bpe, take * col_take)

    # ---- prefix LM stack (Gemma-2B, ported from pi05_torch_ref.prefix_forward /
    # joint_attention's `pre_tokens is not None` branch) ---------------------
    def build_prefix_attn_bias(self, seq_len, valid_len):
        """Bidirectional additive bias (seq_len, seq_len) bf16: 0 everywhere prefix
        tokens attend to each other; -1e36 on any column >= valid_len (padded lanes),
        matching pi05_torch_ref.build_prefix_attn_bias's placeholder (all-unmasked
        among real tokens, padding excluded). Not float('-inf') -- avoids NaN from
        exp(-inf - -inf) in the softmax kernel."""
        NEG = -1e36
        bias = torch.zeros((seq_len, seq_len), dtype=torch.bfloat16)
        if valid_len < seq_len:
            bias[:, valid_len:] = NEG
        # Mask skipped/zero image slots (openpi image_mask=False) -- their
        # placeholder tokens must contribute nothing to any real token's softmax.
        for a, b in getattr(self, "prefix_masked_cols", []):
            bias[:, a:b] = NEG
        return bias

    def embed_and_concat_prefix(self, token_ids, vision_embeddings=None, seq_len=1024):
        """Text-embedding lookup (host-side gather from self.embedding_table) concatenated
        with vision tokens (already-projected (n_vis, hidden) bf16, e.g. from
        compile_encoder's output), padded to seq_len. Writes the result to
        LAYER0_INPUT_DRAM. Returns valid_len (vision + text, before padding)."""
        H = self.HIDDEN_SIZE
        vis = vision_embeddings if vision_embeddings is not None else torch.zeros((0, H), dtype=torch.bfloat16)
        n_vis = vis.shape[0]

        tid = torch.tensor(token_ids, dtype=torch.long)
        # openpi scales token embeddings by sqrt(width) inside Embedder.encode
        # (gemma.py:149-150 `x *= jnp.sqrt(self.embed_dim)`; the PyTorch port does
        # the same at pi0_pytorch.py `lang_emb * math.sqrt(lang_emb_dim)`). Image
        # embeddings are NOT scaled -- only the text embedder. We loaded the table
        # raw and gathered it raw, so text entered the prefix sqrt(2048)=45.25x too
        # small: measured RMS 0.146 against vision tokens' 5.25 in the same
        # sequence, where openpi puts them at 6.62 vs 5.25. pi05_torch_ref.py had
        # the identical omission, so the CPU oracle agreed with the hardware and
        # the ~29dB action-expert SNR read as "matches CPU-IF4" rather than as a
        # bug in both.
        text_embed = (self.embedding_table[tid].float()
                      * math.sqrt(H)).to(torch.bfloat16)   # (n_text, H) host-side gather

        valid_len = n_vis + text_embed.shape[0]
        assert valid_len <= seq_len, f"prefix valid_len={valid_len} exceeds seq_len={seq_len}"

        # Padding rows [valid_len:seq_len] must NOT be exact zero: rms_norm_core has
        # no epsilon (confirmed by reading user_dma_core.py -- MODE_RSQRT computes
        # sqrt(N)/sqrt(sum(x_i^2)) directly, no +eps), so an all-zero row hits
        # rsqrt(0)=inf, then 0*inf=NaN for that row's "normalized" output. That NaN
        # then contaminates every REAL row too: attention's masked columns get
        # ~0 softmax weight but 0*NaN=NaN in IEEE arithmetic, not 0 -- so a single
        # NaN padding column poisons the weighted sum for every query row. This is
        # exactly the mechanism confirmed via debug_stepwise_prefix.py --dump
        # (checkpoints 14/15/16 all 100% NaN). smolvlm2_test.py hit the identical
        # problem and fixes it the same way: epsilon-fill padding rows instead of
        # leaving them at exact zero (see its "epsilon-fill INPUT padding rows" step).
        full = torch.full((seq_len, H), 1e-6, dtype=torch.bfloat16)
        full[:n_vis] = vis
        full[n_vis:valid_len] = text_embed
        self.dma_to_accelerator_memory(self.LAYER0_INPUT_DRAM, full)
        return valid_len

    def _rope_positions_prefix(self, seq_len, valid_len=None):
        """openpi positions = cumsum(attn_mask) - 1: MASKED prefix tokens do NOT
        advance the position counter, they freeze it. Two things are masked:
          - the unused image slots (self.prefix_masked_cols), and
          - the PADDING rows [valid_len:seq_len] past the real prompt tokens.
        Padding MUST be masked: n_valid is what the action-expert's suffix rope
        table starts from, so counting the ~64 padded prompt slots as real would
        offset every suffix position (n_valid=576 instead of 512+n_text) and
        rotate the action expert at the wrong positions entirely.
        Returns (positions[S], n_valid)."""
        mask = torch.ones(seq_len, dtype=torch.float32)
        for a, b in getattr(self, "prefix_masked_cols", []):
            mask[int(a):int(b)] = 0.0
        if valid_len is not None and valid_len < seq_len:
            mask[int(valid_len):] = 0.0
        positions = torch.cumsum(mask, dim=0) - 1.0
        return positions, int(mask.sum().item())

    def _rope_table(self, positions):
        """gemma3's HF rope table: (npos, 2*head_dim) bf16 = [cos|cos|-sin|sin],
        with sin at column offset head_dim (byte offset head_dim*2)."""
        Dh = self.HEAD_DIM
        Dhalf = Dh // 2
        inv_freq = 1.0 / (self.ROPE_THETA ** (torch.arange(Dhalf, dtype=torch.float32) / Dhalf))
        freqs = torch.outer(positions.float(), inv_freq)
        cos_ = freqs.cos().to(torch.bfloat16)
        sin_ = freqs.sin().to(torch.bfloat16)
        return torch.cat([cos_, cos_, -sin_, sin_], dim=1)

    def _rope_tiled_tables(self, positions, n_tiles):
        """Head-major (n_tiles*npos, head_dim) cos/sin operands for the MATMUL RoPE.

        The packed table above is (npos, 2*Dh) with a 4*Dh-byte row pitch, which
        ``eltwise_core_dram`` cannot consume -- it wants a dense (M, Dh) operand
        with a 2*Dh-byte pitch. So split the packed table's two halves into their
        own dense buffers and TILE each ``n_tiles`` times, because every RoPE'd
        buffer in this model is head-major: row ``h*npos + p`` is head ``h`` at
        position ``p``, so the position table repeats once per head.

        No new host math: the packed table's first half is already [cos|cos] and
        its second half is already [-sin|sin], which is exactly the signed operand
        the swap-permutation formulation wants (see :meth:`_rope_matmul`).
        """
        Dh = self.HEAD_DIM
        packed = self._rope_table(positions)
        cos_tiled = packed[:, :Dh].repeat(n_tiles, 1).contiguous()
        sin_tiled = packed[:, Dh:].repeat(n_tiles, 1).contiguous()
        return cos_tiled, sin_tiled

    def _rope_swap_matrix(self):
        """Static (Dh, Dh) swap permutation P with P[n, (n+Dh/2) % Dh] = 1, so
        ``X @ P == rotate_half'(X) == [x_hi | x_lo]`` (the UNSIGNED swap -- the
        sign lives in the pre-negated sin table). P is symmetric, so the
        accelerator's implicit A@Bᵀ needs no separate transpose."""
        Dh = self.HEAD_DIM
        half = Dh // 2
        P = torch.zeros(Dh, Dh, dtype=torch.bfloat16)
        for n in range(Dh):
            P[n, (n + half) % Dh] = 1.0
        return P

    def _rope_matmul(self, M, src_dram, out_dram, cos_tiled, sin_tiled, rot_dram,
                     gpr_M_reg=None, ue=None):
        """RoPE as one batched matmul + three full-width elementwise passes.

        The per-row cores (``rope_hf_core_dram`` / ``_gqa``) are DMA-LATENCY bound:
        every token costs a handful of 512-byte transfers, and this model calls them
        18x in the prefix and 18x10 in the denoise loop. This reformulation issues
        four large ops over all ``M`` rows instead::

            rot = X @ P_swap        # rotate_half via the static swap permutation
            rot = rot * sin_tiled   # signed sin (lower half pre-negated on host)
            out = X   * cos_tiled
            out = out + rot         # == X*cos + rotate_half(X)*sin

        The matmul costs M*Dh*Dh MACs, ~0.5% of a prefix layer -- the trade is
        deliberate: FLOPs are free here, DMA round-trips are not.

        Stays OUT-OF-PLACE (``src_dram`` is never written) both because in==out is a
        known DMA hazard on this hardware and because the debug snapshots downstream
        read the un-rotated projection. Every operand is row-indexed, so this is
        row-independent over M and legal inside a sharded region -- pass an ``ue``
        and pre-offset addresses to give an engine its own row range.
        """
        D = self.HEAD_DIM
        eng = ue or self
        flops = 0
        eng.matmat_mul_core(M=M, K=D, N=D, A_DRAM_ADDR=src_dram,
                            B_DRAM_ADDR=self.ROPE_P_SWAP_ADDR,
                            OUTPUT_DRAM_ADDR=rot_dram,
                            is_B_quantized=False, gpr_M_reg=gpr_M_reg)
        flops += M * D * D * 2
        flops += eng.eltwise_core_dram(M=M, N=D, dram_a=rot_dram, dram_b=sin_tiled,
                                       dram_out=rot_dram, mode=UE_MODE.ELTWISE_MUL,
                                       gpr_M_reg=gpr_M_reg)
        flops += eng.eltwise_core_dram(M=M, N=D, dram_a=src_dram, dram_b=cos_tiled,
                                       dram_out=out_dram, mode=UE_MODE.ELTWISE_MUL,
                                       gpr_M_reg=gpr_M_reg)
        flops += eng.eltwise_core_dram(M=M, N=D, dram_a=out_dram, dram_b=rot_dram,
                                       dram_out=out_dram, mode=UE_MODE.ELTWISE_ADD,
                                       gpr_M_reg=gpr_M_reg)
        return flops

    def _rope_init(self, seq_len=None, valid_len=None):
        """Build BOTH rope tables (prefix + action-expert suffix) once and cache
        their DRAM addrs. Idempotent -- callable from compile_prefix and
        compile_denoise_loop (skip_prefix runs never touch compile_prefix).
        prefix_masked_cols is set by run_vision before either runs."""
        if getattr(self, "PREFIX_ROPE_ADDR", None) is not None:
            return
        S = seq_len if seq_len is not None else getattr(
            self, "PREFIX_SEQ_LEN", getattr(self, "AE_PREFIX_SEQ_LEN", 1024))
        if valid_len is None:
            valid_len = getattr(self, "prefix_valid_len", None)
        pos_prefix, n_valid = self._rope_positions_prefix(S, valid_len)
        self.PREFIX_ROPE_ADDR = store_weight(self, self._rope_table(pos_prefix))
        # suffix (action expert): positions continue after the VALID prefix tokens
        pos_suffix = n_valid + torch.arange(self.AE_ACTION_HORIZON_PADDED, dtype=torch.float32)
        self.AE_ROPE_ADDR = store_weight(self, self._rope_table(pos_suffix))
        self.ROPE_SIN_OFFSET = self.HEAD_DIM * 2  # bytes; cos at base, sin at base+offset

        # ---- matmul-RoPE operands (see _rope_matmul) --------------------------
        # Both tiled tables are head-major and sized for the WIDEST consumer of
        # their position set; the narrower consumers are a PREFIX of the same
        # buffer, because tiling repeats the whole position block per head:
        #   rows [0, npos)  == exactly one head's worth == the single-head MQA K.
        # So prefix K reuses PREFIX_ROPE_*_TILED at offset 0, and the AE's suffix
        # K reuses AE_ROPE_*_TILED at offset 0. No separate untiled buffers.
        self.ROPE_P_SWAP_ADDR = store_weight(self, self._rope_swap_matrix())
        cos_p, sin_p = self._rope_tiled_tables(pos_prefix, self.NUM_HEADS)
        self.PREFIX_ROPE_COS_TILED = store_weight(self, cos_p)
        self.PREFIX_ROPE_SIN_TILED = store_weight(self, sin_p)
        cos_s, sin_s = self._rope_tiled_tables(pos_suffix, self.AE_HEADS)
        self.AE_ROPE_COS_TILED = store_weight(self, cos_s)
        self.AE_ROPE_SIN_TILED = store_weight(self, sin_s)

    def _build_ae_suffix_bias(self, P, Tkv, S, valid_len=None):
        """The action expert's (Tkv, Tkv) additive suffix attention bias.

        Extracted from tensor_init_action_expert so run_inference can REBUILD it
        per observation: it depends on prefix_valid_len, which is data-dependent
        (it moves with the prompt's token count) while the compiled program is
        not. See _refresh_valid_len_tables.
        """
        NEG_INF = -1e9
        if valid_len is None:
            valid_len = getattr(self, "prefix_valid_len", P)
        bias = torch.zeros(Tkv, Tkv, dtype=torch.bfloat16)
        # Suffix PADDING key columns. S=AE_ACTION_HORIZON_PADDED=64 but only the
        # first AE_ACTION_HORIZON=10 suffix rows are real action tokens; rows
        # [10:64] are 1e-6 filler. Their K/V are NOT small: AdaRMSNorm divides by
        # the row's own RMS, so a 1e-6 row comes out at FULL magnitude and those
        # 54 keys land in every real row's softmax. The old `bias[:, P+S:]` was an
        # EMPTY slice (P+S == Tkv) and masked nothing -- this was the attention
        # corruption (roped Q/K measured clean at ~46dB while rawattn craterd).
        bias[:, P + self.AE_ACTION_HORIZON:] = NEG_INF
        if valid_len < P:
            bias[:, valid_len:P] = NEG_INF
        # Mask skipped/zero image slots (same columns as the prefix bias) so the
        # action expert's cross-attention ignores their placeholder K/V rows.
        for a, b in getattr(self, "prefix_masked_cols", []):
            bias[:, a:b] = NEG_INF
        bias[S:, :] = 0.0           # unused query rows; value irrelevant, never read back
        return bias

    def _refresh_valid_len_tables(self, valid_len):
        """Re-point every valid_len-dependent buffer at THIS observation's value.

        prefix_valid_len is data-dependent and moves EVERY OBSERVATION, not just
        every task: pi0.5 discretizes the robot state into the prompt TEXT, so the
        token count shifts with the state's digit widths (measured 43-47 tokens ->
        valid_len 811-815 over 12 perturbed states). Recompiling per observation is
        therefore not an option -- but the compiled PROGRAM does not depend on
        valid_len at all (geometry is P=PREFIX_SEQ_LEN=832, Tkv=P+64), only these
        host-built constant TABLES do, and re-uploading them is ~2.5MB of DMA:

          * the PREFIX rope table (PREFIX_ROPE_ADDR): positions = cumsum(mask)-1,
            where mask is zeroed on prefix_masked_cols AND on [valid_len:S]. It is
            NOT immune to a stale value -- an earlier version of this docstring
            claimed it was. precompile_all runs before run_vision, which is the only
            place prefix_masked_cols is assigned, so at precompile time it is [] and
            positions degenerate to arange(S): every TEXT token is rotated +256
            positions off (768..812 instead of 512..556).
          * the SUFFIX rope table (AE_ROPE_ADDR): pos_suffix = n_valid + arange(),
            so a wrong valid_len rotates every action token at the wrong position.
          * the suffix attention bias (AE_BIAS_DRAM): masks prefix columns
            [valid_len:P]. When valid_len == P that slice is EMPTY, so the prefix's
            own padding-token K/V leak into every action row's cross-attention.

        (prefix_bias_dram is the fourth, already re-DMA'd by run_inference.)

        precompile_all() called compile_prefix(seq_len, seq_len) with seq_len as a
        placeholder for valid_len on the assumption that "valid_len only shapes the
        bias DATA". It does not -- compile_prefix stores it to self.prefix_valid_len,
        which both consumers above read later. With the placeholder, valid_len was
        832 instead of 813: n_valid became 576 rather than the 557 openpi computes,
        and the padding mask covered nothing.

        Both buffers are plain DRAM the host wrote, so refreshing them is a DMA --
        no recompile, which keeps compile-once intact. Idempotent and cheap.
        """
        prev = getattr(self, "_valid_len_tables_for", None)
        self.prefix_valid_len = valid_len
        if prev == valid_len:
            return
        S_pre = getattr(self, "PREFIX_SEQ_LEN", None)
        if S_pre is not None:
            pos_prefix, n_valid = self._rope_positions_prefix(S_pre, valid_len)
            # BOTH tables or NEITHER. RoPE attention scores depend on the
            # DIFFERENCE of positions, so refreshing one side while the other keeps
            # a stale offset is WORSE than leaving both stale: a uniform shift
            # largely cancels in q.k, a one-sided shift does not. Measured, with
            # precompile baking masked_cols=[] and valid_len=832:
            #   both stale     -> prefix text +256, suffix +275, relative err  19  -> -0.80 grip
            #   suffix only    -> prefix text +256, suffix   +0, relative err 256  -> -0.47 grip
            #   both correct   ->                                relative err   0  -> -1.00 grip
            # The middle row was this function's first version, which refreshed
            # AE_ROPE_ADDR and left PREFIX_ROPE_ADDR frozen (_rope_init early-returns
            # on PREFIX_ROPE_ADDR, so nothing else ever rebuilds it).
            # The TILED cos/sin operands (matmul RoPE) are derived from the exact
            # same positions and must be refreshed in lockstep -- they are what the
            # layer loops actually read now, so a stale tile is the same one-sided
            # position shift catalogued above, just in a different buffer.
            if getattr(self, "PREFIX_ROPE_ADDR", None) is not None:
                tbl_p = self._rope_table(pos_prefix).contiguous()
                self.dma_write(DMA_DEVICE_H2C, self.PREFIX_ROPE_ADDR,
                               tbl_p, tbl_p.numel() * 2)
                cos_p, sin_p = self._rope_tiled_tables(pos_prefix, self.NUM_HEADS)
                self.dma_write(DMA_DEVICE_H2C, self.PREFIX_ROPE_COS_TILED, cos_p, cos_p.numel() * 2)
                self.dma_write(DMA_DEVICE_H2C, self.PREFIX_ROPE_SIN_TILED, sin_p, sin_p.numel() * 2)
            if getattr(self, "AE_ROPE_ADDR", None) is not None:
                pos_suffix = n_valid + torch.arange(self.AE_ACTION_HORIZON_PADDED,
                                                    dtype=torch.float32)
                tbl_s = self._rope_table(pos_suffix).contiguous()
                self.dma_write(DMA_DEVICE_H2C, self.AE_ROPE_ADDR, tbl_s, tbl_s.numel() * 2)
                cos_s, sin_s = self._rope_tiled_tables(pos_suffix, self.AE_HEADS)
                self.dma_write(DMA_DEVICE_H2C, self.AE_ROPE_COS_TILED, cos_s, cos_s.numel() * 2)
                self.dma_write(DMA_DEVICE_H2C, self.AE_ROPE_SIN_TILED, sin_s, sin_s.numel() * 2)
            print(f"  [valid_len] rope tables refreshed: valid_len={valid_len} "
                  f"-> n_valid={n_valid} (was {prev})")
        # The LIVE suffix mask is AE_UATTN_BIAS_DRAM, not AE_BIAS_DRAM. The action
        # expert runs ONE rectangular attention (batch=AE_HEADS*S queries x Tkv keys,
        # unified_attention_core_dynamic's BIAS_DRAM_ADDR), whose (batch, Tkv) bias is
        # built at tensor_init time by replicating row 0 of the square bias. The
        # square AE_BIAS_DRAM buffer it was derived from is vestigial -- left over
        # from the per-head square-flash implementation that the rectangular call
        # replaced -- and is WRITTEN but never READ. Refreshing it (this function's
        # first two versions did) therefore masks nothing: with precompile the live
        # keymask was copied while prefix_masked_cols was still [] and valid_len 832,
        # so the dead camera's 256 columns and the 19 prefix padding columns stayed
        # unmasked in every action row's softmax. Worth ~15dB.
        if getattr(self, "AE_UATTN_BIAS_DRAM", None) is not None:
            P, Tkv, S = (self.AE_PREFIX_SEQ_LEN, self.AE_TKV,
                         self.AE_ACTION_HORIZON_PADDED)
            bias = self._build_ae_suffix_bias(P, Tkv, S, valid_len)
            keymask = bias[0].clone()                       # (Tkv,) column mask
            ubias = keymask.unsqueeze(0).repeat(self.AE_UATTN_BATCH, 1).contiguous()
            self.dma_write(DMA_DEVICE_H2C, self.AE_UATTN_BIAS_DRAM, ubias,
                           self.AE_UATTN_BATCH * Tkv * 2)
        self._valid_len_tables_for = valid_len

    def compile_prefix(self, seq_len, valid_len=None):
        """18-layer Gemma-2B prefix stack: RMSNorm -> MQA flash-attn (bidirectional
        bias) -> residual -> RMSNorm -> gated-GELU MLP -> residual. Per-layer K/V
        projections are staged into the persistent LAYER0_K_DRAM/LAYER0_V_DRAM cache
        (see tensor_init's KV_LAYER_STRIDE/KV_HEAD_STRIDE) for later reuse by the
        action-expert suffix stack (out of scope here).

        Ports pi05_torch_ref.prefix_forward + joint_attention's `pre_tokens is not
        None` branch. suf_tokens branch is out of scope."""
        S, H, I, D = seq_len, self.HIDDEN_SIZE, self.INTERMEDIATE_SIZE, self.HEAD_DIM
        NH, NKV, KV = self.NUM_HEADS, self.NUM_KV_HEADS, self.NUM_KV_HEADS * self.HEAD_DIM
        assert NKV == 1, "compile_prefix assumes pure MQA (num_kv_heads=1); broadcast via num_q_heads"
        bpe = 2

        self._debug_counter = 0
        self._debug_halt_info = None

        valid_len = valid_len if valid_len is not None else S
        self.prefix_bias_dram = store_weight(self, self.build_prefix_attn_bias(S, valid_len))

        bpe = 2
        # Dedicated, non-aliased output buffers for the two residual adds below.
        # eltwise_add_core_dram(A, B, OUT) with OUT == B (in-place) was the confirmed
        # hang trigger (checkpoint layer0_residual2) -- real streaming/DMA hardware
        # reading and writing the same address in one op is a hazard, not just a
        # correctness footgun. Every add below now writes to a buffer distinct from
        # both its inputs.
        self.LAYER0_ATTN_RESIDUAL_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.LAYER0_LAYER_OUT_DRAM = self.allocate_tensor_dram(S * H * bpe)
        # RoPE output buffers (out-of-place: rope in==out would be a DMA hazard).
        # valid_len MUST be passed: it excludes the padded prompt rows from the
        # position count, which is what the suffix rope table is offset by.
        self._rope_init(S, valid_len)
        # NOTE: LAYER0_Q_ROPE_DRAM now holds the HEAD-MAJOR, PRE-rotation Q --
        # see the RoPE block in the layer loop for why permute moved ahead of RoPE.
        self.LAYER0_Q_ROPE_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.LAYER0_K_ROPE_DRAM = self.allocate_tensor_dram(S * KV * bpe)
        # rotate_half scratch for the matmul RoPE (_rope_matmul). Sized for the
        # widest consumer (all NH heads of Q, head-major); the single-head MQA K
        # rope reuses its first S*D elements, and the two never overlap in time.
        self.PREFIX_ROPE_ROT_DRAM = self.allocate_tensor_dram(S * H * bpe)
        # Per-layer snapshots (LAYER0_LAYER_OUT_DRAM itself is reused/overwritten
        # every layer) so a post-run readback can CPU-vs-HW SNR-check every
        # layer's output at once -- same pattern as VIS_LAYER_SNAPSHOT_DRAM.
        # layer0-only op-by-op snapshots (layer0's per-op scratch buffers, e.g.
        # LAYER0_Q_DRAM, get overwritten by every later layer's same op -- these
        # dedicated copies survive the full 18-layer run so a single post-run
        # readback can op-by-op SNR-check exactly where within layer0 things
        # first diverge from the CPU reference, without 19 separate debug-stop runs).
        # DISABLED by default (self._prefix_snap) -- these ~98MB of buffers push
        # the action-expert stack ~98MB higher, the only diff vs the clean --debug
        # run. Allocated only when PREFIX_SNAPSHOTS=True.
        if getattr(self, "PREFIX_SNAPSHOTS", False):
            self.PREFIX_LAYER_SNAPSHOT_DRAM = [self.allocate_tensor_dram(S * H * bpe) for _ in range(self.NUM_LAYERS)]
            self.PREFIX_L0_SNAPSHOT_DRAM = {
                name: self.allocate_tensor_dram(size * bpe) for name, size in (
                    ("ln1", S * H), ("q_proj", S * H), ("k_proj", S * KV), ("v_proj", S * KV),
                    ("q_rope", S * H), ("k_rope", S * KV),
                    ("q_permute", S * H),
                    ("head0", S * D), ("head1", S * D), ("head2", S * D), ("head3", S * D),
                    ("head4", S * D), ("head5", S * D), ("head6", S * D), ("head7", S * D),
                    ("attn_permute", S * H), ("o_proj_residual", S * H), ("ln2", S * H),
                    ("mlp_lo", S * H), ("mlp_hi", S * H), ("mlp_down", S * H),
                )
            }
        else:
            self.PREFIX_LAYER_SNAPSHOT_DRAM = None
            self.PREFIX_L0_SNAPSHOT_DRAM = None

        # Fresh register/inst-pointer allocation per stage (start_capture does
        # NOT reset these per-process counters; drift across stages hands out
        # bad indices -- see compile_denoise_loop's reset for the full writeup).
        self.reset_isa_reg_counter()
        self.reset_inst_ptr_counter()

        # PREFIX_SNAPSHOTS: debug-only per-layer/op SNR snapshot buffers. When
        # OFF (default), skip both the ~98MB of snapshot DRAM allocations AND the
        # per-op _dram_copy instructions -- this keeps compile_prefix from
        # shoving the action-expert buffers ~98MB higher in tensor DRAM (the
        # ONLY thing that differs between a clean --debug denoise run and the
        # NaN'ing full run). Set True to re-enable the per-op SNR report.
        self._prefix_snap = getattr(self, "PREFIX_SNAPSHOTS", False)

        # Inline unified attention (unified_attention_core_dynamic) replaces the
        # old shared-subroutine flash-attention API (flash_attention_core*, deleted
        # in the rebase onto main). PREFIX is MQA self-attention (S x S): the 8
        # query heads can't be head-batched (8*S > S), so attention is emitted
        # INLINE once per head inside the per-layer loop.
        #
        # Scratch sizing (bf16, *2): unified_attention_core_dynamic needs
        # head_dim*aligned_seq_len + aligned_seq_len^2 + batch*head_dim elements.
        # Here batch=aligned_seq_len=S, head_dim=D -> 2*D*S + S*S (S*S dominates).
        #
        # PER_ENGINE, NOT SHARED_FULL: attention is HEAD-SHARDED (see
        # _emit_prefix_attention), and the core WRITES this buffer (V^T, the
        # score/P plane, scaled Q). One shared scratch would have every engine
        # stomping every other engine's score plane mid-flight -- the classic
        # finite-but-scrambled failure, not a hang. One buffer per engine, indexed
        # by engine_idx. At ne == 1 this is a single allocation, i.e. the exact
        # historical tensor-DRAM layout (which the action-expert buffers sit on
        # top of, so any extra allocation here shifts them -- see PREFIX_SNAPSHOTS).
        #
        # ne is resolved HERE rather than at the sharding block below because the
        # scratch count depends on it. _prefix_num_engines is pure but PRINTS on
        # fallback, so it must be called exactly once.
        ne = self._prefix_num_engines(S)
        prefix_attn_scratch = [self.allocate_tensor_dram((2 * D * S + S * S) * bpe)
                               for _ in range(ne)]

        # ---- SHARDING ACROSS ENGINES ----------------------------------------
        # --engines N shards TWO different axes of every layer:
        #   ROWS  the row-independent bulk (both RMSNorms, all 10 matmuls, the 3
        #         eltwise ops) over 64-row blocks of the S prefix tokens.
        #   HEADS the 8 attention calls (see _emit_prefix_attention). Rows are the
        #         wrong axis for attention -- a row block of Q needs ALL S rows of
        #         K/V -- but heads are perfectly independent here, and because the
        #         step-3 permute has already laid Q out as (heads, seq, head_dim),
        #         a head slice is a CONTIGUOUS block, not the strided scatter that
        #         made this look risky.
        # RoPE, the two smart_bf16_permute_core calls and the KV cache staging
        # stay SINGLE-ENGINE on the primary at full S.
        #
        # Four rendezvous per layer (72) + one before the halt:
        #   #1 after the Q/K/V projections -- RoPE reads ALL S rows of buffers
        #      that were written sharded (RAW).
        #   #A after the primary's RoPE/permute/KV-staging -- every engine's
        #      attention reads Q_PERM / K_ROPE / V_PROJ in full (RAW).
        #   #B after the head-sharded attention -- the primary's attention permute
        #      reads ALL NH heads of ATTN_OUT, written by every engine (RAW).
        #   #2 after the attention permute -- the sharded o-projection reads the
        #      primary-written ATTN_RESULT (RAW), and it is also the WAR fence
        #      that stops a worker re-entering layer i+1's Q/K/V projections
        #      while the primary still reads layer i's Q/K/V.
        # #A and #B are the price of head-sharding: two extra rendezvous of ~35
        # instructions each against ~1e5 per layer.
        # No barrier is needed at the layer boundary: layer i writes
        # LAYER_OUT + RH for its OWN rows and layer i+1 reads the same rows.
        # (The prefix does NOT alternate A/B buffers the way the encoder does --
        # LAYER_OUT is read-then-written in place across layers. That is safe
        # only because each engine owns disjoint rows AND rendezvous #2 already
        # fenced the primary's full-S readers.)
        sched = self._prefix_make_scheduler(ne) if ne > 1 else None
        self._prefix_sched = sched
        if ne > 1:
            # _debug_op halts the PRIMARY only; under multi-engine a debug stop
            # would leave the workers spinning at a rendezvous forever.
            assert self.DEBUG_STOP_AFTER is None, (
                "PI05_DEBUG_STOP_AFTER is not supported with a row-sharded prefix "
                f"(engines={ne}): the halt is emitted on the primary only and the "
                "workers would spin at the next rendezvous. Re-run with --engines 1.")
            # The layer0 per-op snapshots at ln1/q/k/v read those buffers BEFORE
            # rendezvous #1, i.e. they would capture the peer's rows half-written.
            assert not self._prefix_snap, (
                "PREFIX_SNAPSHOTS is not supported with a row-sharded prefix "
                f"(engines={ne}): the layer0 op snapshots run before rendezvous #1 "
                "and would capture partial data. Re-run with --engines 1.")
            splits = sched.split_rows(S, mode="blocks")
            engines = sched.engines
            print(f"    [prefix] row-sharded over {ne} engine(s): "
                  f"{[c for _, c in splits]} of {S} rows (64-row blocks)")
            print(f"    [prefix] attention head-sharded: "
                  f"{[c for _, c in self._prefix_head_split(ne)]} of {NH} heads")
        else:
            splits, engines = [(0, S)], [self]

        if sched is not None:
            sched.begin_program()
        for _e, _ue in enumerate(engines):
            _off, _rows = splits[_e]
            self._emit_prefix_body(_ue, _e, ne, _off, _rows, S, prefix_attn_scratch)
        if sched is not None:
            # KEEP the addresses: sched is shared with the encoder and finalize()
            # overwrites sched._worker_prog_addrs.
            self._prefix_worker_prog_addrs = sched.finalize()
            print(f"    [prefix] worker program(s): "
                  f"{[w.get_capture_instruction_size_bytes() for w in sched.workers]} bytes")
            self._assert_worker_programs_fit(sched)

        _lanes, _csplit = self._prefix_mlp_lanes(ne)
        if _csplit:
            print(f"    [prefix] MLP COLUMN-LANE split: {_lanes} lanes of "
                  f"{self.INTERMEDIATE_SIZE // _lanes} cols, one per engine, each at "
                  f"full S={S} -> perfectly balanced (vs the {[c for _, c in splits]} "
                  f"row split); {_lanes - 1} partial adds + 2 rendezvous/layer")
        else:
            print(f"    [prefix] MLP column lanes: {_lanes} (walked per-engine over "
                  f"own rows; no column split)")
        print(f"compile_prefix: {self.NUM_LAYERS} layers compiled, seq_len={S}, "
              f"valid_len={valid_len}, engines={ne}")

        # ---- BUGFIX (interface reconciliation): the action-expert stack
        # (compile_suffix_step / tensor_init_action_expert) expects
        # self.PREFIX_SEQ_LEN + self.prefix_k_cache_addr[l]/prefix_v_cache_addr[l]
        # per-layer DRAM addresses. The real per-layer K/V cache was staged above
        # into LAYER0_K_DRAM/LAYER0_V_DRAM + layer_idx*KV_LAYER_STRIDE (each layer's
        # slice already has shape (S, KV)=(S, NUM_KV_HEADS*HEAD_DIM)=(S, HEAD_DIM)
        # since NUM_KV_HEADS==1 -- exactly the (PREFIX_SEQ_LEN, HEAD_DIM) shape the
        # action-expert code expects). Point the expected attrs directly at those
        # real addresses so tensor_init_action_expert's placeholder fallback never
        # triggers.
        self.PREFIX_SEQ_LEN = S
        self.prefix_valid_len = valid_len
        self.prefix_k_cache_addr = [self.LAYER0_K_DRAM + l * self.KV_LAYER_STRIDE for l in range(self.NUM_LAYERS)]
        self.prefix_v_cache_addr = [self.LAYER0_V_DRAM + l * self.KV_LAYER_STRIDE for l in range(self.NUM_LAYERS)]

        return self.LAYER0_LAYER_OUT_DRAM

    def _emit_prefix_attention(self, ue, engine_idx, ne, layer_idx, S, scratch):
        """Emit THIS engine's share of one layer's MQA self-attention.

        Bidirectional bias (no causal flag), one INLINE
        unified_attention_core_dynamic call per head. Q for head h is the (S, D)
        block at LAYER0_Q_PERM_DRAM + h*S*D*2 -- the step-3 permute already
        separated the heads, so a head slice is a contiguous read and the output
        slice is a contiguous write. K/V need no marshalling at all: MQA means the
        SAME (S, D) buffer is passed for every head. BIAS is the full
        (batch=S, aligned_seq_len=S) prefix_bias_dram, identical per head.
        q_scale=None -> standard 1/sqrt(head_dim) SDPA scale.

        WHY THIS SHARDS CLEANLY, when batch-sharding the same core does not:
        the core's first step is bf16_transpose_core on V, sized by
        aligned_seq_len rather than by batch. Splitting BATCH leaves every engine
        redoing the whole V^T -- the reason the action expert's attention stayed
        serial (see _ae_q_proj_sharded). Splitting HEADS does not change that
        arithmetic at all: this loop already rebuilds V^T once per head, NH times
        per layer, and after sharding it still runs exactly NH times, just spread
        across engines. There is no duplicated work introduced, so the speedup is
        the head count ratio less the two rendezvous.

        ``scratch`` is THIS ENGINE's private buffer. The core writes V^T, the
        S x S score/P plane and scaled Q into it, so sharing one across engines
        would corrupt heads in flight -- finite garbage, not a hang.

        Every engine covers ALL NH heads when ne == 1, so the emitted stream is
        byte-identical to the historical single-engine build.
        """
        D, NH = self.HEAD_DIM, self.NUM_HEADS
        bpe = 2
        head_bytes = S * D * bpe
        h0, nh = self._prefix_head_split(ne)[engine_idx]
        for h in range(h0, h0 + nh):
            ue.unified_attention_core_dynamic(
                batch=S, aligned_seq_len=S, head_dim=D,
                Q_DRAM_ADDR=self.LAYER0_Q_PERM_DRAM + h * head_bytes,
                K_DRAM_ADDR=self.LAYER0_K_ROPE_DRAM,
                V_DRAM_ADDR=self.LAYER0_V_PROJ_DRAM,
                BIAS_DRAM_ADDR=self.prefix_bias_dram,
                OUTPUT_DRAM_ADDR=self.LAYER0_ATTN_OUT_DRAM + h * head_bytes,
                SCRATCH_DRAM_ADDR=scratch,
                IDENTITY_DRAM_ADDR=self.identity_addr)
            self._debug_op(f"layer{layer_idx}_head{h}", self.LAYER0_ATTN_OUT_DRAM + h * head_bytes, S * D, shape=(S, D), ue=ue)
            if layer_idx == 0 and self._prefix_snap:
                self._dram_copy(head_bytes, self.LAYER0_ATTN_OUT_DRAM + h * head_bytes,
                                 self.PREFIX_L0_SNAPSHOT_DRAM[f"head{h}"])

    def _emit_prefix_body(self, ue, engine_idx, ne, row_offset, rows, S, prefix_attn_scratch):
        """Emit ONE engine's complete prefix program over rows
        [row_offset, row_offset+rows) of the S prefix tokens.

        With ne == 1 this is (row_offset, rows) == (0, S), every byte offset is 0,
        every M is S and _vis_barrier emits nothing -- i.e. byte-for-byte the
        historical single-engine stream.

        ADDRESSING CONTRACT
          SHARED_FULL (no offset)  every IF4 weight/scale pair, ln1/ln2 gamma,
                                   identity_addr, prefix_bias_dram,
                                   PREFIX_ROPE_ADDR, and the LAYER0_K/V_DRAM
                                   cache slabs (primary-only).
          SHARED_ROWS              three distinct pitches -- this is where an
                                   offset bug would hide:
              RH = row_offset*H*2      INPUT, LAYER_OUT, PRE_NORM, Q, ATTN_RESULT,
                                       O_PROJ, ATTN_RESIDUAL, MLP_DOWN*
              RK = row_offset*KV*2     K_PROJ, V_PROJ            (KV = 256 -> 512B)
              RF = row_offset*FF_LANE*2  MLP_{GATE,UP,MULT}[lane] (-> 16KB)
          PER_ENGINE               ``prefix_attn_scratch``, a LIST indexed by
                                   engine_idx: the head-sharded attention core
                                   WRITES its scratch, so one shared buffer would
                                   let engines stomp each other's score planes.
                                   Nothing else -- rms_norm_core_dram dispatches
                                   to the dynamic core, which allocates NO DRAM
                                   scratch (no analogue of the encoder's
                                   vis_zeros), and eltwise is pure SRAM streaming.

        HEADS, NOT ROWS, for attention: a row block of Q needs ALL S rows of K/V,
        so the row split does not apply. See _emit_prefix_attention.
        """
        H, I, D = self.HIDDEN_SIZE, self.INTERMEDIATE_SIZE, self.HEAD_DIM
        NH, KV = self.NUM_HEADS, self.NUM_KV_HEADS * self.HEAD_DIM
        lanes, mlp_col_split = self._prefix_mlp_lanes(ne)
        FF_LANE = I // lanes
        bpe = 2
        is_primary = engine_idx == 0

        # Per-engine byte offsets. COMPILE-TIME CONSTANTS folded into the emitted
        # literal -- never a runtime GPR (the ue_selector _addr_tmp clobber class).
        RH = row_offset * H * bpe
        RK = row_offset * KV * bpe
        # Lane-buffer row offset. Used only on the NON-column-split path, where every
        # engine walks all lanes over its own row shard; when mlp_col_split is on the
        # lanes run at full S and the offset is 0 (computed inline as LF).
        RF = row_offset * FF_LANE * bpe
        assert rows % 64 == 0, f"shard row count {rows} must be 64-aligned"

        self._debug_counter = 0
        if is_primary:
            self._debug_halt_info = None

        # PBI dynamic-M loop (mirrors compile_encoder's vis_S_reg): without this,
        # every matmul/RMSNorm below compiles a fully-unrolled static instruction
        # stream per M row-chunk, which for 18 layers blew the compiled program up
        # to ~684MB (vs. vision's 745KB for 27 layers) and triggered a DMA
        # transfer-size failure. gpr_M_reg makes the outer row loop a runtime trip
        # count instead of static unrolling.
        prefix_S_reg = ue.alloc_isa_reg()
        ue.generate_instruction_add_set(prefix_S_reg, S)
        # Head-major Q row count for the matmul RoPE: after the permute, Q is one
        # (NH*S, D) batch rather than S rows of NH*D, so its runtime M differs from
        # every other op in the layer and needs its own register.
        prefix_NHS_reg = ue.alloc_isa_reg()
        ue.generate_instruction_add_set(prefix_NHS_reg, self.NUM_HEADS * S)

        # Norm ABI (post pcie_only sync): rms_norm_core_dram no longer folds the
        # sqrt(N) RSQRT scale implicitly -- the dynamic core reads it from a runtime
        # GPR (float_to_bf19(sqrt(N))) and takes N in its own GPR. N / sqrt(N)
        # describe the WITHIN-ROW normalization width and are unchanged by the row
        # split. Without this the norm is mis-scaled by ~sqrt(N).
        prefix_N_reg = ue.alloc_isa_reg()
        ue.generate_instruction_add_set(prefix_N_reg, H)
        prefix_sqrt_N_reg = ue.alloc_isa_reg()
        ue.generate_instruction_add_set(prefix_sqrt_N_reg, ue.float_to_bf19(float(H ** 0.5)))
        # THIS engine's row count, for every sharded matmul/RMSNorm. prefix_S_reg
        # must SURVIVE alongside it: the two RoPE calls below run on the primary at
        # full S, so on engine 0 both registers are live simultaneously. At ne == 1
        # they are literally the same register, so not one extra instruction is
        # emitted and the stream stays byte-identical to the pre-sharding code.
        if ne > 1:
            prefix_R_reg = ue.alloc_isa_reg()
            ue.generate_instruction_add_set(prefix_R_reg, rows)
        else:
            prefix_R_reg = prefix_S_reg

        try:
            for layer_idx in range(self.NUM_LAYERS):
                la = self.lm_layer_addrs[layer_idx]
                h_in = self.LAYER0_INPUT_DRAM if layer_idx == 0 else self.LAYER0_LAYER_OUT_DRAM

                # 1. pre-attention RMSNorm  [SHARDED]
                ue.rms_norm_core_dram(M=rows, N=H, A_DRAM_ADDR=h_in + RH,
                                         OUTPUT_DRAM_ADDR=self.LAYER0_PRE_NORM_DRAM + RH,
                                         GAMMA_DRAM_ADDR=la["ln1"],
                                         gpr_M_reg=prefix_R_reg, gpr_N_reg=prefix_N_reg,
                                         gpr_sqrt_n_reg=prefix_sqrt_N_reg)
                self._debug_op(f"layer{layer_idx}_ln1", self.LAYER0_PRE_NORM_DRAM, S * H, shape=(S, H), ue=ue)
                if layer_idx == 0 and self._prefix_snap:
                    self._dram_copy(S * H * bpe, self.LAYER0_PRE_NORM_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["ln1"])

                # 2. Q/K/V projections (MQA: K/V project to a single head_dim, not NH*D)
                #    [SHARDED] -- note K/V use the RK (=KV*2) pitch, not RH.
                self._matmul(M=rows, K=H, N=H, A=self.LAYER0_PRE_NORM_DRAM + RH, proj="q", la=la, OUT=self.LAYER0_Q_DRAM + RH, gpr_M_reg=prefix_R_reg, ue=ue)
                self._matmul(M=rows, K=H, N=KV, A=self.LAYER0_PRE_NORM_DRAM + RH, proj="k", la=la, OUT=self.LAYER0_K_PROJ_DRAM + RK, gpr_M_reg=prefix_R_reg, ue=ue)
                self._matmul(M=rows, K=H, N=KV, A=self.LAYER0_PRE_NORM_DRAM + RH, proj="v", la=la, OUT=self.LAYER0_V_PROJ_DRAM + RK, gpr_M_reg=prefix_R_reg, ue=ue)
                self._debug_op(f"layer{layer_idx}_qkv_proj", self.LAYER0_Q_DRAM, S * H, shape=(S, H), ue=ue)
                if layer_idx == 0 and self._prefix_snap:
                    self._dram_copy(S * H * bpe, self.LAYER0_Q_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["q_proj"])
                    self._dram_copy(S * KV * bpe, self.LAYER0_K_PROJ_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["k_proj"])
                    self._dram_copy(S * KV * bpe, self.LAYER0_V_PROJ_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["v_proj"])

                # ---- RENDEZVOUS #1: everything below reads ALL S rows of Q /
                # K_PROJ / V_PROJ, which were just written SHARDED.
                self._vis_barrier(ue, engine_idx, ne)

                # ---- SINGLE-ENGINE REGION (primary, full S) ------------------
                # RoPE, the Q permute and the KV-cache staging. Attention itself
                # is head-sharded below (rendezvous #A/#B); the attn-output
                # permute after it returns to the primary.
                if is_primary:
                    # 2b/3. PERMUTE-THEN-RoPE on Q, and RoPE on K (Gemma rotates
                    # BOTH, every layer -- openpi gemma.py:203/206). Positions come
                    # from cumsum(mask)-1, so the masked image slot freezes the
                    # counter (see _rope_init).
                    #
                    # THE ORDER SWAP: this used to be gqa-RoPE on the interleaved
                    # (S, NH*D) Q, then permute to (NH, S, D). RoPE is applied
                    # per (token, head) independently and the permute is a pure
                    # gather, so the two COMMUTE -- LAYER0_Q_PERM_DRAM ends up
                    # bit-identical either way. Permuting first is what makes the
                    # matmul RoPE usable: head-major Q is a plain (NH*S, D) batch
                    # whose row h*S+s matches the head-major tiled cos/sin table,
                    # whereas the interleaved layout would need a block-diagonal
                    # (NH*D, NH*D) swap matrix at NH times the MACs. It also
                    # retires the gqa RoPE variant and the separate permute pass.
                    #
                    # Consequence: LAYER0_Q_ROPE_DRAM now holds head-major
                    # PRE-rotation Q, and is snapshotted under the "q_rope" key as
                    # such (the golden compare knows -- see compare_prefix_golden).
                    smart_bf16_permute_core(ue, (S, NH, D), [1, 0, 2],
                                             self.LAYER0_Q_DRAM, self.LAYER0_Q_ROPE_DRAM)
                    self._rope_matmul(M=NH * S,
                                      src_dram=self.LAYER0_Q_ROPE_DRAM,
                                      out_dram=self.LAYER0_Q_PERM_DRAM,
                                      cos_tiled=self.PREFIX_ROPE_COS_TILED,
                                      sin_tiled=self.PREFIX_ROPE_SIN_TILED,
                                      rot_dram=self.PREFIX_ROPE_ROT_DRAM,
                                      gpr_M_reg=prefix_NHS_reg, ue=ue)
                    # K is a single MQA head, already (S, D) head-major -- so it is
                    # the FIRST head-tile of the same tiled table, at offset 0.
                    self._rope_matmul(M=S,
                                      src_dram=self.LAYER0_K_PROJ_DRAM,
                                      out_dram=self.LAYER0_K_ROPE_DRAM,
                                      cos_tiled=self.PREFIX_ROPE_COS_TILED,
                                      sin_tiled=self.PREFIX_ROPE_SIN_TILED,
                                      rot_dram=self.PREFIX_ROPE_ROT_DRAM,
                                      gpr_M_reg=prefix_S_reg, ue=ue)
                    self._debug_op(f"layer{layer_idx}_q_rope", self.LAYER0_Q_ROPE_DRAM, S * H, shape=(S, H), ue=ue)
                    self._debug_op(f"layer{layer_idx}_k_rope", self.LAYER0_K_ROPE_DRAM, S * KV, shape=(S, KV), ue=ue)
                    if layer_idx == 0 and self._prefix_snap:
                        self._dram_copy(S * H * bpe, self.LAYER0_Q_ROPE_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["q_rope"])
                        self._dram_copy(S * KV * bpe, self.LAYER0_K_ROPE_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["k_rope"])

                    self._debug_op(f"layer{layer_idx}_q_permute", self.LAYER0_Q_PERM_DRAM, S * H, shape=(S, H), ue=ue)
                    if layer_idx == 0 and self._prefix_snap:
                        self._dram_copy(S * H * bpe, self.LAYER0_Q_PERM_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["q_permute"])

                    # 4. stage this layer's K/V into the persistent KV cache for downstream
                    # reuse. Full S on the primary, so the cache layout is byte-identical to
                    # the single-engine build and prefix_k/v_cache_addr + PREFIX_SEQ_LEN are
                    # unchanged for the action-expert suffix stack. The V copy reads
                    # LAYER0_V_PROJ_DRAM, which is written SHARDED -- it MUST stay after
                    # rendezvous #1. Do not hoist it.
                    k_cache_addr = self.LAYER0_K_DRAM + layer_idx * self.KV_LAYER_STRIDE
                    v_cache_addr = self.LAYER0_V_DRAM + layer_idx * self.KV_LAYER_STRIDE
                    # NOTE: the cached K is the ROTATED k (openpi applies rope before
                    # the kv cache write); V is never rotated.
                    self._dram_copy(S * KV * bpe, self.LAYER0_K_ROPE_DRAM, k_cache_addr, ue=ue)
                    self._dram_copy(S * KV * bpe, self.LAYER0_V_PROJ_DRAM, v_cache_addr, ue=ue)
                    self._debug_op(f"layer{layer_idx}_kv_cache", k_cache_addr, S * KV, shape=(S, KV), ue=ue)

                # ---- RENDEZVOUS #A: the head-sharded attention below reads
                # LAYER0_Q_PERM_DRAM / LAYER0_K_ROPE_DRAM in full, both written by
                # the primary just above (RAW). LAYER0_V_PROJ_DRAM was written
                # sharded and already fenced by #1, but the workers must wait here
                # regardless -- without #A a worker would run layer i's attention
                # against layer i-1's Q permute.
                self._vis_barrier(ue, engine_idx, ne)

                # 5. MQA self-attention  [HEAD-SHARDED]
                self._emit_prefix_attention(ue, engine_idx, ne, layer_idx, S,
                                            prefix_attn_scratch[engine_idx])

                # ---- RENDEZVOUS #B: the attention permute below reads ALL NH
                # heads of LAYER0_ATTN_OUT_DRAM, which every engine just wrote a
                # disjoint slice of (RAW).
                self._vis_barrier(ue, engine_idx, ne)

                if is_primary:
                    # 6. permute attn output (heads, seq, head_dim) -> (seq, heads*head_dim)
                    smart_bf16_permute_core(ue, (NH, S, D), [1, 0, 2],
                                             self.LAYER0_ATTN_OUT_DRAM, self.LAYER0_ATTN_RESULT_DRAM)
                    self._debug_op(f"layer{layer_idx}_attn_permute", self.LAYER0_ATTN_RESULT_DRAM, S * H, shape=(S, H), ue=ue)
                    if layer_idx == 0 and self._prefix_snap:
                        self._dram_copy(S * H * bpe, self.LAYER0_ATTN_RESULT_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["attn_permute"])

                # ---- RENDEZVOUS #2: the sharded o-projection below reads
                # ATTN_RESULT, written by the primary above (RAW); it is also the
                # WAR fence keeping a worker out of layer i+1's Q/K/V projections
                # while the primary is still reading layer i's.
                self._vis_barrier(ue, engine_idx, ne)

                # 7. output projection + residual  [SHARDED]
                # (non-aliased: OUT distinct from both inputs -- in-place eltwise is a
                # confirmed HANG trigger, and the same +RH on all three operands
                # preserves that distinctness.)
                self._matmul(M=rows, K=H, N=H, A=self.LAYER0_ATTN_RESULT_DRAM + RH, proj="o", la=la, OUT=self.LAYER0_O_PROJ_DRAM + RH, gpr_M_reg=prefix_R_reg, ue=ue)
                eltwise_add_core_dram(ue, rows * H, h_in + RH, self.LAYER0_O_PROJ_DRAM + RH, self.LAYER0_ATTN_RESIDUAL_DRAM + RH)
                self._debug_op(f"layer{layer_idx}_o_proj_residual", self.LAYER0_ATTN_RESIDUAL_DRAM, S * H, shape=(S, H), ue=ue)
                if layer_idx == 0 and self._prefix_snap:
                    self._dram_copy(S * H * bpe, self.LAYER0_ATTN_RESIDUAL_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["o_proj_residual"])

                # 8. pre-FFW RMSNorm  [SHARDED]
                ue.rms_norm_core_dram(M=rows, N=H, A_DRAM_ADDR=self.LAYER0_ATTN_RESIDUAL_DRAM + RH,
                                         OUTPUT_DRAM_ADDR=self.LAYER0_PRE_NORM_DRAM + RH,
                                         GAMMA_DRAM_ADDR=la["ln2"],
                                         gpr_M_reg=prefix_R_reg, gpr_N_reg=prefix_N_reg,
                                         gpr_sqrt_n_reg=prefix_sqrt_N_reg)
                self._debug_op(f"layer{layer_idx}_ln2", self.LAYER0_PRE_NORM_DRAM, S * H, shape=(S, H), ue=ue)
                if layer_idx == 0 and self._prefix_snap:
                    self._dram_copy(S * H * bpe, self.LAYER0_PRE_NORM_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["ln2"])

                # 9. gated-GELU MLP + residual, COLUMN-LANE split (parakeet_test.py
                # pattern, adapted for the gated variant -- see _weight_init_lm_prefix
                # for why the split must exist at all: matmat_mul_core_pbi can't do
                # K=16384 in one call, and the strided-DMA extraction alternative
                # (_dram_split_copy) was the confirmed hang trigger). Each lane is
                # computed/multiplied/down-projected independently so down_proj's
                # K-input is naturally contiguous from the moment it's written.
                #
                # TWO MODES (see PREFIX_MLP_LANES):
                #   mlp_col_split False  every engine walks ALL lanes over its OWN row
                #                        shard. lanes == 2 here is byte-identical to
                #                        the historical FF_HALF code.
                #   mlp_col_split True   engine e computes ONLY lane e, at FULL S. The
                #                        row imbalance disappears because every engine
                #                        does exactly S x FF_LANE of work.
                if mlp_col_split:
                    # RENDEZVOUS #C: the lanes read ALL S rows of LAYER0_PRE_NORM_DRAM,
                    # which was just written ROW-SHARDED by every engine (RAW).
                    self._vis_barrier(ue, engine_idx, ne)
                    lane_ids, lane_M, lane_row, lane_Mreg = [engine_idx], S, 0, prefix_S_reg
                else:
                    lane_ids, lane_M, lane_row, lane_Mreg = range(lanes), rows, RH, prefix_R_reg

                for i in lane_ids:
                    LF = 0 if mlp_col_split else row_offset * FF_LANE * bpe
                    self._matmul(M=lane_M, K=H, N=FF_LANE, A=self.LAYER0_PRE_NORM_DRAM + lane_row,
                                 proj=f"gate_l{i}", la=la,
                                 OUT=self.LAYER0_MLP_GATE_DRAM[i] + LF, gelu_enable=True,
                                 gpr_M_reg=lane_Mreg, ue=ue)
                    self._matmul(M=lane_M, K=H, N=FF_LANE, A=self.LAYER0_PRE_NORM_DRAM + lane_row,
                                 proj=f"up_l{i}", la=la,
                                 OUT=self.LAYER0_MLP_UP_DRAM[i] + LF, gpr_M_reg=lane_Mreg, ue=ue)
                    eltwise_mul_core_dram(ue, lane_M * FF_LANE,
                                          self.LAYER0_MLP_GATE_DRAM[i] + LF,
                                          self.LAYER0_MLP_UP_DRAM[i] + LF,
                                          self.LAYER0_MLP_MULT_DRAM[i] + LF)
                    self._matmul(M=lane_M, K=FF_LANE, N=H, A=self.LAYER0_MLP_MULT_DRAM[i] + LF,
                                 proj=f"down_l{i}", la=la,
                                 OUT=self.LAYER0_MLP_PARTIAL_DRAM[i] + lane_row,
                                 gpr_M_reg=lane_Mreg, ue=ue)
                    self._debug_op(f"layer{layer_idx}_mlp_l{i}", self.LAYER0_MLP_PARTIAL_DRAM[i],
                                   S * H, shape=(S, H), ue=ue)
                    if layer_idx == 0 and self._prefix_snap and i < 2:
                        self._dram_copy(S * H * bpe, self.LAYER0_MLP_PARTIAL_DRAM[i],
                                        self.PREFIX_L0_SNAPSHOT_DRAM["mlp_lo" if i == 0 else "mlp_hi"])

                if mlp_col_split:
                    # RENDEZVOUS #D: the reduce below reads EVERY lane's partial, each
                    # written by a different engine (RAW). It is also the WAR fence for
                    # LAYER0_PRE_NORM_DRAM -- without it an engine could race into
                    # layer i+1's ln2 and overwrite rows a peer is still reading here.
                    self._vis_barrier(ue, engine_idx, ne)

                # Reduce the lane partials over THIS engine's row shard. Ping-pong
                # accumulators, last add straight into LAYER0_MLP_DOWN_DRAM: OUT never
                # aliases either input (in-place eltwise is a confirmed hang).
                acc = self.LAYER0_MLP_PARTIAL_DRAM[0] + RH
                for i in range(1, lanes):
                    last = (i == lanes - 1)
                    dst = (self.LAYER0_MLP_DOWN_DRAM if last
                           else self.LAYER0_MLP_ACC_DRAM[i % 2]) + RH
                    eltwise_add_core_dram(ue, rows * H, acc,
                                          self.LAYER0_MLP_PARTIAL_DRAM[i] + RH, dst)
                    acc = dst
                self._debug_op(f"layer{layer_idx}_mlp_down", self.LAYER0_MLP_DOWN_DRAM, S * H, shape=(S, H), ue=ue)
                if layer_idx == 0 and self._prefix_snap:
                    self._dram_copy(S * H * bpe, self.LAYER0_MLP_DOWN_DRAM, self.PREFIX_L0_SNAPSHOT_DRAM["mlp_down"])
                # non-aliased: OUT (LAYER0_LAYER_OUT_DRAM) distinct from both inputs
                eltwise_add_core_dram(ue, rows * H, self.LAYER0_ATTN_RESIDUAL_DRAM + RH, self.LAYER0_MLP_DOWN_DRAM + RH, self.LAYER0_LAYER_OUT_DRAM + RH)
                self._debug_op(f"layer{layer_idx}_residual2", self.LAYER0_LAYER_OUT_DRAM, S * H, shape=(S, H), ue=ue)
                if self._prefix_snap:
                    self._dram_copy(S * H * bpe, self.LAYER0_LAYER_OUT_DRAM, self.PREFIX_LAYER_SNAPSHOT_DRAM[layer_idx])

                # Multi-engine-SAFE early stop (dual_engine_gates' prefix ladder).
                # _debug_op / PI05_DEBUG_STOP_AFTER cannot be used when sharded: it
                # halts mid-layer on the PRIMARY only, and the workers -- which skip
                # the primary-only RoPE/permute/attention region entirely -- do not
                # even agree on what checkpoint index N means. A LAYER BOUNDARY is
                # the one point where every engine's stream is in lockstep, so
                # stopping there is expressible in all of them at once: break out,
                # and the shared exit rendezvous + halt below runs as usual.
                if (self.PREFIX_STOP_AFTER_LAYER is not None
                        and layer_idx >= self.PREFIX_STOP_AFTER_LAYER):
                    break

            # Attention is inline (unified_attention_core_dynamic emitted per head
            # inside the loop), so there is no shared subroutine to compile after the
            # loop -- the program ends right after the final HALT. The final
            # rendezvous makes the primary's halt (the only thing the HOST waits on)
            # unreachable until every worker has written its last rows.
            self._vis_barrier(ue, engine_idx, ne)
            if is_primary:
                self.generate_instruction_halt()
        except _DebugStop:
            pass   # halt already emitted by _debug_op.

        if ne > 1:
            ue.release_isa_reg()  # prefix_R_reg
        ue.release_isa_reg()  # prefix_sqrt_N_reg
        ue.release_isa_reg()  # prefix_N_reg
        ue.release_isa_reg()  # prefix_NHS_reg
        ue.release_isa_reg()  # prefix_S_reg


    # ---- prefill -----------------------------------------------------------
    def compile_prefill(self, seq_len):
        """Standard decoder loop driven by self.OPS. Fill _matmul/weight_init first.
        Confirm the prefill PBI mode matches the current branch."""
        S, H, I, D = seq_len, self.HIDDEN_SIZE, self.INTERMEDIATE_SIZE, self.HEAD_DIM
        for layer_idx in range(self.NUM_LAYERS):
            la = self.lm_layer_addrs[layer_idx]
            h_in = self.LAYER0_INPUT_DRAM if layer_idx == 0 else self.LAYER0_MLP_DOWN_DRAM
            # 1. input norm (fused post-add for layers 1+)
            # 2. q/k/v proj   3. rope   4. attn (GQA, causal)   5. o proj
            # 6. post-attn norm   7. mlp (gated_silu/gelu)
            # See references/op-library.md for the exact call order + flags.
            raise NotImplementedError("wire the op chain from references/op-library.md")

    # ---- decode ------------------------------------------------------------
    def compile_decode(self):
        """Single-token decode loop. Confirm the decode PBI mode matches the branch."""
        raise NotImplementedError("wire the decode op chain")

    # ---- VLM hook ----------------------------------------------------------
    #
    # MULTI-ENGINE ROW SHARDING (--engines N, N > 1)
    # ----------------------------------------------
    # The encoder is a pure row-parallel stack over S=256 patch tokens: every op
    # except attention is row-independent, and attention only mixes rows through
    # K/V. So each engine owns a contiguous 128-row block (S/2), reads the FULL
    # K/V of both blocks for its own queries, and never needs an online-softmax
    # merge (the QUERY axis is what is split).
    #
    # DRAM is ONE FLAT SHARED SPACE: weights are NOT duplicated, buffers stay
    # single full-size allocations, and each engine simply addresses its own row
    # block (byte offset = row_offset * row_pitch). Only scratch that a kernel
    # WRITES is duplicated (see _vis_register_per_engine).
    #
    # Set the engine count to 1 (the default) and every address offset is 0, every
    # M is S, and the scheduler emits zero extra instructions -- the stream is
    # byte-identical to the single-engine encoder (asserted by
    # dual_engine_gates.py's G0 digest check).
    # Generic engine count, set by --engines. Defaults to 1 = today's exact
    # single-engine behaviour. The mechanism is intended to extend to the prefix
    # LM and the action-expert denoise loop, so the knob is deliberately NOT
    # vision-specific; a stage may still pin its own count by setting
    # <STAGE>_NUM_ENGINES (e.g. VIS_NUM_ENGINES) to a non-None value.
    NUM_ENGINES = 1

    # What `--engines max` resolves to. These are CEILINGS SET BY THE ARCHITECTURE,
    # not preferences, and each is a different limit:
    #   VIS      8 -- 2D: 4 row groups x 2 K lanes (_vis_grid). Rows alone still cap
    #                 at 4 (S=VIS_S=256 is exactly 4 blocks of 64), so the 5th-8th
    #                 engines split the MLP's K instead: fc1 N-split -> GELU in lane
    #                 -> fc2 K-split -> 2-way reduce. The attention block stays
    #                 row-parallel and redundant across lanes, because its A operands
    #                 are shared row-major buffers and matmat_mul_core has no
    #                 A-stride, so a K-split of those is not expressible.
    #   PREFIX   8 -- device cap. S=832 is 13 blocks and 13 is prime, so 8 is uneven
    #                 (5x128 + 3x64) at ~81% efficiency. Shorter prefixes degrade:
    #                 S=576 is 56%, S=320 falls back to 1 engine (_prefix_num_engines).
    #   DENOISE  8 -- device cap. M=64 is ONE row block so this is a COLUMN (N) split;
    #                 the binding dim is o proj N=1024 = 16 blocks, comfortably >8.
    STAGE_MAX_ENGINES = {"VIS": 8, "PREFIX": 8, "DENOISE": 8}

    VIS_NUM_ENGINES = None       # per-stage override; None -> NUM_ENGINES
    # The prefix LM is row-sharded too (projections / RMSNorms / MLP; RoPE, the
    # two permutes and attention stay on the primary), so it follows --engines.
    # Set to an int to pin the stage independently of the encoder.
    PREFIX_NUM_ENGINES = None

    # ---- PREFIX MLP COLUMN LANES -------------------------------------------
    # The gated MLP has ALWAYS been column-split: gate/up are N-split and down is
    # K-split into FF_HALF=8192 halves whose partials are summed. That was done for
    # a HARDWARE reason, not for parallelism -- matmat_mul_core_pbi asserts
    # K*16 <= URAM_NEAR_FULL_ELEMENTS (262080), so down_proj's K=16384 cannot run as
    # one matmul, and the strided-DMA alternative was a confirmed hang trigger. See
    # _weight_init_lm_prefix.
    #
    # Widening 2 lanes -> `ne` lanes turns that existing split into the fix for the
    # ROW-BLOCK IMBALANCE. S=832 is 13 blocks of 64 and 13 is prime, so no row split
    # over 8 engines balances: the busiest engine carries 2 blocks where the ideal is
    # 1.625, i.e. ~81% efficiency (measured: t = 0.70 + 5.70*max_blocks +
    # 0.30*heads_per_engine, so 2.1s of the 12.4s stage is pure idle). I=16384 is 256
    # blocks of 64 and divides 8 ways EXACTLY, so a column lane per engine is
    # PERFECTLY balanced -- every engine does S x (I/ne), identical work.
    #
    # The MLP is 91.4% of the row-sharded FLOPs (167.5 of 183.25 GFLOP/layer), so
    # moving just it off the row axis recovers nearly all of the imbalance. The
    # projections and both RMSNorms stay row-split (their 2-block critical path is
    # only ~1.0s) -- splitting them too would need a transpose the hardware has no
    # A-stride for.
    #
    # Cost: two extra rendezvous per layer (#C after ln2, #D after the lanes) and
    # ne-1 serialized partial adds instead of 1.
    PREFIX_MLP_LANES = None      # None -> _prefix_mlp_lanes() derives it

    def _prefix_mlp_lanes(self, resolved_ne=None):
        """Return (lanes, col_split) for the prefix gated MLP.

        THE LANE COUNT IS DERIVED FROM THE CONFIGURED ENGINE COUNT ONLY, never from
        the per-compile resolved one. weight_init, tensor_init and _emit_prefix_body
        all call this, and they run at different times: _prefix_num_engines can fall
        back to 1 at COMPILE time (a seq_len that won't 64-block-split), long after
        the weights were sliced and the buffers allocated. If the lane count moved
        with that fallback, emission would index `gate_l0` -- a 2048-wide slice --
        as if it were 8192 wide. Silent wrong math, not an error.

        ``col_split`` is the only thing the fallback is allowed to change:

          False  every engine walks ALL lanes over its own row shard. The ne == 1
                 path, and the fallback path. At lanes == 2 the emitted stream is
                 byte-identical to the historical FF_HALF code.
          True   engine e computes ONLY lane e, at FULL S -- the balanced path.
                 Requires lanes == resolved_ne exactly.
        """
        raw = self._num_engines("PREFIX")
        override = self.PREFIX_MLP_LANES
        lanes = (raw if override is None else int(override)) if raw > 1 else 2
        if override is not None:
            lanes = int(override)
        I = self.INTERMEDIATE_SIZE
        # Every lane must be a whole number of 64-element blocks: that is the matmul
        # N/K granularity AND the q4_64 block size. q4_64 blocks run along K, so a
        # lane boundary off a 64-multiple would cut a down_proj scale block in half.
        # The down_proj K per lane must also clear the URAM cap that forced this
        # split to exist at all (matmat_mul_core_pbi: K*16 <= URAM_NEAR_FULL_ELEMENTS).
        if (lanes < 2 or I % lanes != 0 or (I // lanes) % 64 != 0
                or (I // lanes) * 16 > URAM_NEAR_FULL_ELEMENTS):
            lanes = 2
        col_split = (resolved_ne is not None and resolved_ne > 1 and lanes == resolved_ne)
        return lanes, col_split

    def _num_engines(self, stage="VIS"):
        override = getattr(self, f"{stage}_NUM_ENGINES", None)
        return int(override if override is not None else self.NUM_ENGINES)

    # Emit a SECOND rendezvous immediately after the per-head attention loop.
    # The audit's minimum is one barrier per layer (before head marshalling, the
    # only point an engine READS rows it did not write -- the peer's K/V). That
    # closes the RAW hazard but not the WAR one: without a second barrier,
    # nothing stops engine0 from finishing layer i's attention+MLP and
    # overwriting VIS_K rows 0..127 for layer i+1 while engine1 is still
    # gathering layer i's K. That requires engine0 to lap engine1 by a whole
    # layer body, which is very unlikely but not architecturally excluded.
    # A rendezvous is ~35 instructions against ~1e5 per layer, so the insurance
    # is free. Set False to A/B the single-barrier variant.
    VIS_BARRIER_AFTER_ATTN = True

    @staticmethod
    def _vis_barrier(ue, engine_idx, num_engines, margin_nops=32):
        """Emit ONE engine's slice of the symmetric all-engine rendezvous.

        MultiEngineScheduler.barrier() emits into every engine at once, which is
        wrong here: the encoder body is emitted one COMPLETE engine stream at a
        time (each engine's program is independent; only the per-stream order
        matters), so the barrier has to be emitted per stream at the right point
        in that stream. The shape is exactly scheduler.barrier()'s per-engine
        slice -- SET / CHECK(every peer) / margin NOPs / CLEAR -- the form proven
        to RE-ARM by user_hw_test.flag_rendezvous_repeat_test.
        """
        if num_engines == 1:
            return   # exact passthrough: not one extra instruction
        ue.generate_instruction_flag_set()
        for j in range(num_engines):
            if j != engine_idx:
                ue.generate_instruction_flag_check(target_engine_idx=j)
        for _ in range(margin_nops):
            ue.generate_instruction_nop()
        ue.generate_instruction_flag_clear()

    # Per-worker DRAM arena carved out of the PRIMARY's own tensor allocator.
    # Carving it from the model's allocator is the only placement that cannot
    # collide with anything: pi05's weight blob runs to ~0xDD400000 and the
    # tensor/program cursors keep moving, so any hand-picked absolute base is a
    # future silent-corruption bug. Layout inside one arena:
    #   +0x00000000  worker params  (layer_norm's auto-allocated INV_N vectors)
    #   +0x00100000  worker tensor  (its PER_ENGINE scratch, ~0.8 MB)
    #   +0x01000000  worker program (the encoder is ~6 MB)
    # Sized for BOTH stages: the encoder worker program is ~5.7MB and the prefix
    # worker program is ~8-10MB (the prefix is PBI'd but still 18 layers of
    # matmul/norm/eltwise), and they share one arena because they share one
    # scheduler. 16MB of program room (the original 32MB arena) left too little
    # headroom, so the arena is 48MB -> 32MB of program space above the offset.
    VIS_WORKER_ARENA_BYTES   = 0x03000000   # 48 MB
    VIS_WORKER_TENSOR_OFFSET = 0x00100000
    VIS_WORKER_PROGRAM_OFFSET = 0x01000000

    # ---- MANY-ENGINE ARENA PROFILE (>4 engines, i.e. --pref_8) ----------------
    # The arena is PER ENGINE and holds EVERY stage's worker program, so all of
    # them are resident simultaneously -- the count is max(stage engine counts),
    # not per stage. At 48 MB that is 7 * 48 = 336 MB for --pref_8, against only
    # ~192 MB of free tensor DRAM (384 MB region, ~191 MB of model tensors), so
    # the 48 MB layout simply cannot host 8 engines.
    #
    # It does not need to. The sizes quoted above are real: ~5.7 MB encoder +
    # ~8-10 MB prefix worker program, i.e. ~16 MB of program room, and 48 MB was
    # picked for headroom rather than need. Dropping to 24 MB (22 MB of program
    # space above a 2 MB offset) still clears the measured requirement with ~35%
    # spare and brings 7 arenas to 168 MB, which fits. Worker PER_ENGINE scratch
    # is ~0.8 MB, so the 1 MB tensor window is untouched by this.
    #
    # If a worker program ever does outgrow it, _assert_worker_programs_fit fires
    # at compile time with an exact byte count -- this trades unused headroom for
    # a loud, early failure, never a silent one.
    # 4 MB: params 1 MB + tensor 3 MB. The 2D vision shard adds per-engine lane
    # buffers (fc1 [64,2176] = 272 KB + fc2 partial [64,1152] = 144 KB) on top of
    # the ~520 KB of flash/zeros scratch, which does not fit a 1 MB tensor window.
    # Free at 64 MB arenas -- program space only drops 62 -> 60 MB.
    VIS_WORKER_PROGRAM_OFFSET_MANY = 0x00400000   #  4 MB

    # Tensor DRAM allocated AFTER the arenas, by tensor_init_action_expert
    # (measured 44.97 MB). Reserved up front because the arenas are allocated at
    # encoder-compile time, long before the action expert asks -- see
    # _resolve_worker_arena_profile.
    VIS_WORKER_AE_TENSOR_RESERVE = 0x03000000     # 48 MB
    # Floor for the computed arena: 2 MB offset + 16 MB program space. A worker's
    # encoder+prefix program measured 15.11 MB (5.48 + 9.64), so anything under
    # this cannot hold both stages and would only fail later, deeper in.
    VIS_WORKER_ARENA_BYTES_MIN   = 0x01200000     # 18 MB
    # Cap for the computed multi-engine arena. 64 MB (62 MB of program space above
    # the 2 MB offset) clears the worst case -- a worker carrying encoder + prefix
    # + denoise, measured 5.48 + 9.64 + 22.44 = 37.55 MB. The old 48 MB arena could
    # NOT: its 16 MB offset left only 32 MB, which --dns_8 overflows. On 4 GB DRAM
    # the tensor region has ~1.8 GB spare, so 7 * 64 MB = 448 MB is not a constraint.
    VIS_WORKER_ARENA_BYTES_MAX   = 0x04000000     # 64 MB

    def _resolve_worker_arena_profile(self, workers):
        """Size the per-engine arena for `workers` worker engines. Idempotent.

        <=3 workers (--engines 4 and below) keeps the historical 48 MB layout
        byte-for-byte; only 5+ engines resizes, so nothing that works today
        changes shape.

        THE ARENAS ARE NOT THE LAST TENSOR ALLOCATION. tensor_init_action_expert
        runs AFTER the encoder/prefix compile and takes another ~45 MB, so sizing
        against the free space that exists at arena-allocation time overcommits by
        exactly that much -- and the failure does not surface here, it surfaces
        later as a dram_region_map overlap between tensor(post-arena) and the
        program region. Hence VIS_WORKER_AE_TENSOR_RESERVE: the arena gets what is
        left AFTER the action expert is accounted for.

        Sizing is computed, not tabulated, so it tracks the real cursor rather
        than a constant that silently rots when model tensors change size.
        """
        # Resize for >3 workers, and ALSO whenever denoise is sharded at any count:
        # the denoise program is 22.44 MB, so an all-three worker needs 37.55 MB and
        # overflows the default layout's 32 MB of program space even at --engines 4.
        if getattr(self, "_arena_profile_many", False):
            return
        if workers <= 3 and self._num_engines("DENOISE") <= 1:
            return
        self._arena_profile_many = True
        avail = (self._program_dram_base - self._tensor_dram_addr
                 - self.VIS_WORKER_AE_TENSOR_RESERVE)
        per = (avail // workers) & ~0xFFFFF               # floor to a whole MB
        per = min(per, self.VIS_WORKER_ARENA_BYTES_MAX)
        # Worker programs now ACCUMULATE across stages (one shared allocator per
        # engine), so the arena must hold every sharded stage's worker program at
        # once. Measured on this model: encoder 5.48 MB, prefix 9.64 MB, denoise
        # 12.15 MB. Check it HERE, where the fix is "drop a flag", rather than
        # letting _assert_worker_programs_fit fire mid-compile.
        # WORKER program sizes, which are NOT the primary's. Vision and prefix are
        # ROW-sharded: a worker runs the same op sequence over fewer rows, so its
        # program tracks the primary's (5.48 / 9.64 MB measured). The prefix
        # estimate is raised above that 9.64 MB because head-sharded attention
        # moved NH/ne inline unified_attention bodies per layer OFF the primary
        # and ONTO every worker -- the primary shrinks by what the workers gain.
        # This is an estimate; _assert_worker_programs_fit is the exact check. Denoise is
        # COLUMN/head-sharded: a worker only carries the sharded REGIONS (q proj,
        # o proj, gated MLP) -- not attention, adaRMS, or the eltwise residuals --
        # so it is a small fraction of the primary's 12.15 MB. Estimated, and
        # _assert_worker_programs_fit is the exact check at compile time.
        est = {"VIS": 6 << 20, "PREFIX": 14 << 20, "DENOISE": 4 << 20}
        sharded = [s for s in ("VIS", "PREFIX", "DENOISE") if self._num_engines(s) > 1]
        need = self.VIS_WORKER_PROGRAM_OFFSET + sum(est[s] for s in sharded)
        assert per >= need, (
            f"worker arena too small for the sharded stages: {per / (1 << 20):.0f} MB "
            f"available per engine, ~{need / (1 << 20):.0f} MB needed "
            f"({' + '.join(s.lower() for s in sharded)} worker programs share ONE "
            f"allocator per engine, plus a "
            f"{self.VIS_WORKER_PROGRAM_OFFSET >> 20} MB params/tensor window). "
            f"{workers} arenas x {need / (1 << 20):.0f} MB exceeds the "
            f"{avail / (1 << 20):.0f} MB of tensor DRAM left after the action-expert "
            f"reserve. Drop a stage: --vis_4 --pref_8 (without --dns_8) fits.")
        assert per >= self.VIS_WORKER_ARENA_BYTES_MIN, (
            f"cannot fit {workers} worker arenas: {avail / (1 << 20):.1f} MB available "
            f"after reserving {self.VIS_WORKER_AE_TENSOR_RESERVE >> 20} MB for the action "
            f"expert -> {per / (1 << 20):.1f} MB each, below the "
            f"{self.VIS_WORKER_ARENA_BYTES_MIN >> 20} MB floor (a worker's encoder+prefix "
            f"program is ~15.1 MB). Use fewer engines for this stage.")
        self.VIS_WORKER_ARENA_BYTES = per
        self.VIS_WORKER_PROGRAM_OFFSET = self.VIS_WORKER_PROGRAM_OFFSET_MANY
        _original_print(
            f"    [engines] {workers} workers -> arena sized to {per >> 20} MB each "
            f"({(per - self.VIS_WORKER_PROGRAM_OFFSET) >> 20} MB program space); "
            f"{workers} * {per >> 20} MB = {(workers * per) >> 20} MB of tensor DRAM, "
            f"{self.VIS_WORKER_AE_TENSOR_RESERVE >> 20} MB reserved for the action expert")

    def _assert_worker_programs_fit(self, sched):
        """Both stages' worker programs share ONE arena; overflowing it would march
        the worker program allocator straight into the model's tensor DRAM (silent
        corruption, not a hang). Check after every finalize()."""
        limit = self.VIS_WORKER_ARENA_BYTES - self.VIS_WORKER_PROGRAM_OFFSET
        for i, w in enumerate(sched.workers):
            used = w.get_program_dram_addr() - (
                self._vis_worker_arena + i * self.VIS_WORKER_ARENA_BYTES
                + self.VIS_WORKER_PROGRAM_OFFSET)
            assert used <= limit, (
                f"worker {i + 1} program arena overflow: {used} B used of {limit} B "
                f"(VIS_WORKER_ARENA_BYTES=0x{self.VIS_WORKER_ARENA_BYTES:X}, "
                f"program offset 0x{self.VIS_WORKER_PROGRAM_OFFSET:X}). Grow the arena.")

    def dram_region_map(self, label="", fatal=True):
        """Print the live DRAM region map and HARD-ASSERT that no region overlaps.

        All three of params/tensor/program are unchecked bump allocators in
        user_dma_core (no bounds test whatsoever), and the worker arenas are carved
        out of the *tensor* allocator. Overrunning tensor into program DRAM does not
        raise -- it silently rewrites compiled instructions, and the run dies later
        as a segfault or an impossible TypeError deep in the DMA layer. Call this
        after every allocation phase so that failure is loud and at startup.
        """
        FOURGB = 0x100000000
        regions = []
        p0, p1 = self._params_dram_base, self._next_params_dram_addr
        t0, t1 = self._tensor_dram_base, self._tensor_dram_addr
        g0, g1 = self._program_dram_base, self._next_program_dram_addr
        regions.append(("params", p0, p1))
        arena = getattr(self, "_vis_worker_arena", None)
        if arena is not None:
            n = getattr(self, "_vis_worker_arena_count", 1)
            # The arenas live INSIDE the tensor region, so split tensor around them
            # rather than double-reporting the same bytes as an overlap.
            a1 = arena + n * self.VIS_WORKER_ARENA_BYTES
            regions.append(("tensor(pre-arena)", t0, arena))
            for i in range(n):
                b = arena + i * self.VIS_WORKER_ARENA_BYTES
                regions.append((f"worker{i+1}_arena", b, b + self.VIS_WORKER_ARENA_BYTES))
            if t1 > a1:
                regions.append(("tensor(post-arena)", a1, t1))
        else:
            regions.append(("tensor", t0, t1))
        regions.append(("program", g0, g1))

        lines = [f"  ---- DRAM region map [{label}] ----"]
        for name, a, b in regions:
            lines.append(f"    {name:<20s} 0x{a:08X}..0x{b:08X}  {(b - a) / (1 << 20):9.2f} MB")
        lines.append(f"    {'(program base)':<20s} 0x{g0:08X}   headroom below it: "
                     f"{(g0 - t1) / (1 << 20):.2f} MB")
        print("\n".join(lines))

        errs = []
        srt = sorted(regions, key=lambda r: r[1])
        for (n0, a0, b0), (n1_, a1_, b1_) in zip(srt, srt[1:]):
            if b0 > a1_:
                errs.append(f"{n0} [0x{a0:X}..0x{b0:X}] OVERLAPS {n1_} [0x{a1_:X}..0x{b1_:X}] "
                            f"by {b0 - a1_} B ({(b0 - a1_) / (1 << 20):.2f} MB)")
        for name, a, b in regions:
            if b > FOURGB:
                errs.append(f"{name} ends at 0x{b:X}, past the 4GB DMA limit 0x{FOURGB:X}")
        if errs and fatal:
            raise AssertionError("DRAM region overlap [" + label + "]:\n  " + "\n  ".join(errs))
        return errs

    def _vis_worker_arena_base(self, num_engines):
        """Allocate (once) the worker arenas and return the base of the first.

        SIZED BY THE PEAK ENGINE COUNT ACROSS ALL STAGES, not this caller's.
        The arena is allocated once, by whichever stage compiles first, and every
        later caller gets that same base back. So with mixed per-stage counts
        (--vis_4 --pref_8: vision compiles first at 4, prefix then wants 8) sizing
        by the caller would allocate 3 arenas and then hand the prefix's workers
        4..7 slot addresses past the end of the allocation -- straight into the
        model's tensor DRAM. That is silent corruption, not a hang, and
        _assert_worker_programs_fit does NOT catch it: it validates each worker's
        program against its own slot, never that the slot was allocated.
        """
        peak = max([int(num_engines)]
                   + [self._num_engines(s) for s in ("VIS", "PREFIX", "DENOISE")])
        if peak <= 1:
            return None
        workers = peak - 1
        self._resolve_worker_arena_profile(workers)
        if num_engines == 1 and getattr(self, "_vis_worker_arena", None) is None:
            # A single-engine stage needs no arena of its own, but must not
            # pre-empt the sizing decision for a later multi-engine stage.
            return None
        if getattr(self, "_vis_worker_arena", None) is None:
            need = workers * self.VIS_WORKER_ARENA_BYTES
            # Reserve what tensor_init_action_expert will take LATER; the raw gap to
            # the program base overstates what the arenas may actually consume.
            free = (self._program_dram_base - self._tensor_dram_addr
                    - self.VIS_WORKER_AE_TENSOR_RESERVE)
            assert need <= free, (
                f"worker arenas do not fit: {workers} worker(s) x "
                f"{self.VIS_WORKER_ARENA_BYTES >> 20} MB = {need >> 20} MB needed, "
                f"{free >> 20} MB usable (region 0x{self._tensor_dram_base:X}.."
                f"0x{self._program_dram_base:X}, "
                f"{(self._tensor_dram_addr - self._tensor_dram_base) >> 20} MB already used by "
                f"model tensors, {self.VIS_WORKER_AE_TENSOR_RESERVE >> 20} MB reserved for the "
                f"action expert). Lower the engine count for this stage.")
            self._vis_worker_arena = self.allocate_tensor_dram(
                need, label="vis_worker_arena")
            self._vis_worker_arena_count = workers
            self.dram_region_map(f"worker arenas x{workers}")
        assert self._vis_worker_arena_count >= num_engines - 1, (
            f"worker arena underflow: {num_engines - 1} worker(s) requested but only "
            f"{self._vis_worker_arena_count} arena(s) allocated. The arena is sized "
            f"from the peak stage engine count at first allocation; a stage raising "
            f"its count afterwards is not supported.")
        return self._vis_worker_arena

    def _worker_engine_pool(self, num_engines):
        """The run's ONE set of worker UnifiedEngines, indices 1..peak-1.

        Built once, for the PEAK stage engine count, and handed to every
        scheduler. The allocators live inside these objects, so sharing them is
        what keeps each stage's worker programs landing AFTER the previous
        stage's instead of on top of it -- see the long note at
        MultiEngineScheduler's ``workers`` parameter for the failure mode
        (stage 2 overwrites stage 1's program, stage 1's next launch desyncs the
        barrier, engines spin forever).

        Construction is guarded: UnifiedEngine.__init__ runs a DRAM self-test
        that writes 16 KB at DRAM_START_ADDR == the head of the weight blob.
        """
        from user_dma_core import UnifiedEngine

        pool = getattr(self, "_worker_pool", None)
        peak = max([int(num_engines)]
                   + [self._num_engines(s) for s in ("VIS", "PREFIX", "DENOISE")])
        if pool is not None:
            assert len(pool) >= num_engines - 1, (
                f"worker pool holds {len(pool)} engine(s) but {num_engines - 1} are "
                f"needed; the pool is sized from the peak stage count at first use, "
                f"so a stage raising its count afterwards is not supported.")
            return pool
        if peak <= 1:
            return []

        base0 = self._vis_worker_arena_base(peak)
        stride = self.VIS_WORKER_ARENA_BYTES
        pool = []
        with self._vis_dram_selftest_guard(peak):
            for i in range(1, peak):
                base = base0 + (i - 1) * stride
                pool.append(UnifiedEngine(
                    BASE_ADDR=user_dma_core.UE_0_BASE_ADDR + i * 0x00010000,
                    params_dram_base=base,
                    tensor_dram_base=base + self.VIS_WORKER_TENSOR_OFFSET,
                    program_dram_base=base + self.VIS_WORKER_PROGRAM_OFFSET,
                ))
        self._worker_pool = pool
        _original_print(f"    [engines] worker pool: {len(pool)} shared engine(s) "
                        f"(one allocator each, reused by every stage)")
        return pool

    def _make_stage_scheduler(self, num_engines):
        """Scheduler for ANY stage, over the shared worker pool.

        Reuses an existing scheduler with the same engine count -- including one
        built for a DIFFERENT stage, which the old per-stage helpers did not do:
        _denoise_make_scheduler only ever compared against _vis_sched, so with
        vis=4/prefix=8/denoise=8 the denoise stage built a THIRD scheduler and
        overwrote prefix's worker programs even though prefix's was identical.
        """
        from multi_engine_shard import MultiEngineScheduler

        # Builds a scheduler for num_engines == 1 too, and that is REQUIRED, not
        # incidental: compile_encoder calls sched.split_rows(S) unconditionally and
        # _emit_encoder_body is written so a 1-engine split is (0, S) -- i.e. the
        # historical single-engine stream. Returning None here broke the default
        # no-flags run with 'NoneType has no attribute split_rows'. A 1-engine
        # scheduler has no workers and emits no barriers, so it costs nothing.
        # The prefix/denoise wrappers still hand back None below 2 engines, which
        # is what their call sites expect.
        cache = self.__dict__.setdefault("_sched_by_ne", {})
        if num_engines in cache:
            return cache[num_engines]
        sched = MultiEngineScheduler(
            self, num_engines=num_engines,
            worker_dram_base=self._vis_worker_arena_base(num_engines),
            worker_dram_stride=self.VIS_WORKER_ARENA_BYTES,
            worker_tensor_offset=self.VIS_WORKER_TENSOR_OFFSET,
            worker_program_offset=self.VIS_WORKER_PROGRAM_OFFSET,
            # This board has more than the 2 engines multi_engine_shard's default
            # guard assumes; the opt-in is explicit at the CLI (--engines/--vis_4/
            # --pref_8/--dns_8 all name a count).
            allow_more_than_two_engines=True,
            workers=self._worker_engine_pool(num_engines))
        cache[num_engines] = sched
        return sched

    @contextlib.contextmanager
    def _vis_dram_selftest_guard(self, num_engines):
        """Protect the head of the weight blob from UnifiedEngine.__init__.

        THE BUG THIS EXISTS FOR (cost half a bring-up day, symptom is NOT a hang):
        constructing ANY UnifiedEngine runs init_unified_engine(), whose "FPGA DRAM
        read/write test" writes 8192 random uint16 -- 16 KB -- to DRAM_START_ADDR.
        For pi05 params_dram_base IS DRAM_START_ADDR (0x80000000), and the first
        thing _weight_init_vision stores there is the SigLIP patch-embed kernel.
        So merely CONSTRUCTING the worker engine after weight_init silently
        shreds the patch-embed weights: the encoder's very first matmul returns
        ~1e38 and everything downstream is NaN. It looks exactly like a sharding
        bug and is not one.

        user_dma_core.py is off-limits, so we snapshot the clobbered window,
        let the constructor run, and put it back.
        """
        n_bytes = 8192 * 2   # must match init_unified_engine's DRAM self-test
        if num_engines == 1:
            yield                      # no engine is constructed: nothing to guard
            return
        base = user_dma_core.DRAM_START_ADDR
        buf = bytearray(n_bytes)
        self._dma_read_checked(base, buf, n_bytes, label="dram_selftest_guard")
        try:
            yield
        finally:
            # Write the raw bytearray back DIRECTLY. Do NOT wrap it in
            # torch.frombuffer(bytes(buf), ...): frombuffer over an immutable
            # `bytes` builds a tensor aliasing a read-only, temporary buffer
            # (PyTorch warns "the given buffer is not writable ... does not
            # support non-writable tensors"). That aliasing smashed the CPython
            # heap and the process then segfaulted at an arbitrary LATER point --
            # observed as a SIGSEGV inside Instructions.get_bytes() (a pure-Python
            # `bytearray(32)`) during compile_encoder or compile_prefix, and once
            # as an impossible "TypeError: string argument without an encoding"
            # on the same line. dma_write/_dma_write_retry already accept
            # bytes/bytearray, so no tensor is needed at all.
            self._dma_write_retry(DMA_DEVICE_H2C, base, bytes(buf), n_bytes)

    def _vis_make_scheduler(self, num_engines):
        """Build the MultiEngineScheduler and duplicate the PER_ENGINE scratch."""
        from multi_engine_shard import MultiEngineScheduler
        bpe = 2
        S, DP = self.VIS_S, self.VIS_DP
        H, I = self.VIS_H, self.VIS_I

        sched = self._make_stage_scheduler(num_engines)
        # PER_ENGINE registration is idempotent-by-name and must happen ONCE per
        # scheduler; _make_stage_scheduler caches, so a second call for the same
        # engine count returns the already-populated scheduler.
        if getattr(sched, "_pi05_vis_registered", False):
            return sched
        sched._pi05_vis_registered = True

        # --- PER_ENGINE: scratch a kernel WRITES, therefore must be duplicated ---
        zeros_n = max(H, I)
        sched.register_per_engine(
            "vis_zeros", self.vis_zeros_addr, zeros_n * bpe,
            init_tensor=torch.zeros(zeros_n, dtype=torch.bfloat16))
        zeros_dp = torch.zeros(S * DP, dtype=torch.bfloat16)
        for name, addr in (("flash_q", self.VIS_FLASH_Q_DRAM),
                           ("flash_k", self.VIS_FLASH_K_DRAM),
                           ("flash_v", self.VIS_FLASH_V_DRAM),
                           ("flash_out", self.VIS_FLASH_OUT_DRAM)):
            sched.register_per_engine(name, addr, S * DP * bpe, init_tensor=zeros_dp)
        # Keep the scratch SIZE unchanged: unified_attention_core_dynamic derives
        # its sub-buffer offsets from the compile-time head_dim/aligned_seq_len,
        # which are still DP/S even though batch drops to the shard row count.
        attn_scratch_n = DP * S + S * S + S * DP
        sched.register_per_engine(
            "attn_scratch", self.VIS_ATTN_SCRATCH_DRAM, attn_scratch_n * bpe,
            init_tensor=torch.zeros(attn_scratch_n, dtype=torch.bfloat16))

        # ---- 2D (rows x K) lane buffers -------------------------------------
        # Both are written scratch, so PER_ENGINE. Sized for the widest row group
        # (S // nr rows) -- a smaller group just uses a prefix of the buffer.
        _, _nk = self._vis_grid(num_engines)
        if _nk > 1:
            _nr = num_engines // _nk
            _rows_max = max(c for _, c in self._col_split(S, _nr))
            _IP = self.VIS_I_PAD                       # padded 4352, NOT VIS_I=4304
            _lane_n = _rows_max * (_IP // _nk)         # fc1 out: [rows, IP/nk] dense
            _part_n = _rows_max * H                    # fc2 out: FULL [rows, H] partial
            sched.register_per_engine("vis_mlp_lane", self.VIS_MLP_INTER_DRAM, _lane_n * bpe,
                                      init_tensor=torch.zeros(_lane_n, dtype=torch.bfloat16))
            # The partial gets its OWN primary buffer rather than reusing
            # VIS_MLP_OUT_DRAM: lane 0's partial would then alias the reduce's
            # OUTPUT (VIS_MLP_OUT_DRAM + RH is +0 for engine 0), and an
            # eltwise_add whose A aliases its OUT is the DMA read/write hazard
            # that is a confirmed hang trigger in this codebase (see
            # _ae_ada_rms_norm's AE_ADARMS_MUL_SCRATCH_DRAM comment).
            self.VIS_MLP_PARTIAL_DRAM = self.allocate_tensor_dram(
                _part_n * bpe, label="vis_mlp_partial")
            sched.register_per_engine("vis_mlp_partial", self.VIS_MLP_PARTIAL_DRAM, _part_n * bpe,
                                      init_tensor=torch.zeros(_part_n, dtype=torch.bfloat16))
            print(f"    [vis] lane buffers/engine: fc1 [{_rows_max},{_IP // _nk}] "
                  f"{_lane_n * bpe >> 10} KB + partial [{_rows_max},{H}] {_part_n * bpe >> 10} KB")
        if sched.workers:
            print(f"    [vis] worker arena base 0x{self._vis_worker_arena:X} "
                  f"({num_engines - 1} worker(s) x "
                  f"{self.VIS_WORKER_ARENA_BYTES >> 20}MB)")
        return sched

    # ---- prefix stage sharding -------------------------------------------
    def _prefix_num_engines(self, S):
        """Resolve the PREFIX engine count, falling back to 1 when S cannot be
        block-split.

        THE SPLIT IS BY 64-ROW BLOCKS, NOT EVENLY. Real prefix lengths are
        320/576/832 (= 256*kept_slots + 64); halving them gives 160/288/416,
        NONE of which is 64-aligned, and every matmul/RMSNorm here assumes
        64-aligned row blocks. Block-splitting gives 832 -> 448/384,
        576 -> 320/256, 320 -> 192/128: uneven (hence a few % off the ideal
        2.0x) but always aligned. Relaxing the alignment instead
        (allow_unaligned_rows) is NOT an option -- see multi_engine_shard."""
        ne = self._num_engines("PREFIX")
        if ne <= 1:
            return 1
        if S % 64 != 0 or S // 64 < ne:
            print(f"    [prefix] seq_len={S} cannot be 64-block-split across {ne} engine(s) "
                  f"(blocks={S // 64}); FALLING BACK TO SINGLE-ENGINE PREFIX")
            return 1
        return ne

    def _prefix_head_split(self, ne):
        """[(head_offset, head_count)] per engine for the prefix's NH attention
        heads. Deliberately routed through MultiEngineScheduler.split_heads so the
        one head-splitting rule in the codebase is the one validated on hardware
        by sharded_scheduler_head_attn_test.

        ``gqa_ratio=NH`` is not a fudge -- it is the literal geometry. The prefix
        is pure MQA (NUM_KV_HEADS == 1, asserted in compile_prefix), so all NH Q
        heads share ONE KV head, i.e. exactly one KV group. ``mode="groups"``
        would therefore refuse to shard at all (one group cannot be split N ways);
        ``mode="qheads"`` splits within that group, which is what this case needs
        and what the mode was added for.

        The usual cost of ``qheads`` -- a duplicated V^T per straddled group --
        is ZERO here, because the per-head loop below already rebuilds V^T on
        every one of its NH calls today. Sharding changes who does those rebuilds,
        not how many there are.

        Uneven splits are fine (NH=8 over 3 engines -> 3/3/2): heads are
        independent whole units with no 64-row alignment rule.
        """
        NH = self.NUM_HEADS
        if ne <= 1:
            return [(0, NH)]
        assert ne <= NH, (
            f"_prefix_head_split: {ne} engines for only {NH} attention head(s). "
            f"Row sharding scales past NH but head sharding cannot; give the "
            f"surplus engines a different axis or lower --engines.")
        # split_heads is a pure function of (H, gqa_ratio, num_engines) -- no
        # emission, no allocator touch -- so calling it on the stage scheduler
        # here (and again inside the body) is free and side-effect-free.
        return self._make_stage_scheduler(ne).split_heads(NH, gqa_ratio=NH,
                                                          mode="qheads")

    def _prefix_make_scheduler(self, num_engines):
        """Scheduler for the row-sharded prefix. Shares the run's worker pool and
        the per-engine-count scheduler cache -- see _make_stage_scheduler."""
        if num_engines <= 1:
            return None
        return self._make_stage_scheduler(num_engines)

    def _denoise_make_scheduler(self, num_engines):
        """Scheduler for the N-sharded denoise stage. Shares the run's worker pool
        and the per-engine-count scheduler cache -- see _make_stage_scheduler.

        This used to compare only against _vis_sched, so vis=4/prefix=8/denoise=8
        built a THIRD scheduler whose fresh allocators rewrote prefix's worker
        programs at identical addresses. Now an existing 8-engine scheduler is
        reused whichever stage created it.
        """
        if num_engines <= 1:
            return None
        return self._make_stage_scheduler(num_engines)

    def _execute_denoise(self, timeout=300.0):
        """EXECUTE the compiled denoise program, launching + joining the column-shard
        workers when the stage is sharded. Workers HALT at the end of every run, so
        they are relaunched on EVERY execution (compile-once/execute-many)."""
        sched = getattr(self, "_denoise_sched", None)
        multi = sched is not None and sched.num_engines > 1
        if multi:
            if not getattr(self, "_vis_flags_precleared", False):
                sched.preclear_flags()
                self._vis_flags_precleared = True
            sched.start_workers(self._denoise_worker_prog_addrs)
        self._execute(self._denoise_prog_addr, label="denoise_loop", timeout=timeout)
        if multi:
            # The primary retires its halt as soon as the last rendezvous clears; a
            # worker may still be draining its (write-free) margin NOPs.
            for w in sched.workers:
                w.wait_queue(60.0)

    def _execute_prefix(self, timeout=250.0):
        """EXECUTE the compiled prefix program, launching + joining the row-shard
        workers when the stage is sharded. Workers HALT at the end of every run,
        so they are relaunched on EVERY execution (compile-once/execute-many)."""
        sched = getattr(self, "_prefix_sched", None)
        multi = sched is not None and sched.num_engines > 1
        if multi:
            if not getattr(self, "_vis_flags_precleared", False):
                sched.preclear_flags()
                self._vis_flags_precleared = True
            sched.start_workers(self._prefix_worker_prog_addrs)
        self._execute(self._prefix_prog_addr, label="prefix", timeout=timeout)
        if multi:
            # The primary retires its halt as soon as the exit rendezvous clears;
            # a worker may still be draining its (write-free) margin NOPs. Wait
            # rather than assert-not-busy, which would be flaky.
            for w in sched.workers:
                w.wait_queue(60.0)

    def compile_encoder(self):
        """Compile the 27-layer SigLIP So400m/14 vision encoder (bidirectional, no RoPE,
        no causal mask — see hw_notes). Structure follows the proven smolvlm2_test.py §7
        shared-subroutine-flash pattern: PBI row loops for matmul/layer_norm/eltwise
        (gpr_M_reg), one flash body shared across every (layer, head) call site via
        strided-DMA head marshalling, head_dim padded 72->128 for the flash kernel (see
        _tensor_init_vision for why no explicit unpad selection-matrix is needed). All
        matmul weights are IF4 q4_64 (quant policy) -> quantized_matmul dispatch.

        With --engines N (N > 1) the same body is emitted once per engine over a
        128-row shard of the 256 patch tokens (see the class-level comment).
        """
        S = self.VIS_S
        ne = self._num_engines("VIS")
        # 2D GRID: rows x K. M is only S//64 = 4 blocks, so rows alone cap at 4
        # engines; the extra engines split the MLP's K instead. engine e owns
        # (row group e // nk, K lane e % nk) -- consecutive engines share a row
        # block, which keeps each reduce pair adjacent.
        nr, nk = self._vis_grid(ne)
        sched = self._vis_make_scheduler(ne)
        self._vis_sched = sched
        # _col_split is the same whole-64-block rule split_rows uses in "blocks"
        # mode; used directly here because the row split is over nr GROUPS, not
        # over all ne engines.
        splits = self._col_split(S, nr) if nk > 1 else sched.split_rows(S)
        if nk > 1:
            print(f"    [vis] 2D shard: {nr} row group(s) x {nk} K lane(s) = {ne} engines "
                  f"(rows {[c for _, c in splits]}; MLP K-split, rest row-parallel)")

        self.start_capture()
        self.reset_isa_reg_counter()
        self.reset_inst_ptr_counter()
        sched.begin_program()
        for e, ue in enumerate(sched.engines):
            row_offset, rows = splits[e // nk]
            self._emit_encoder_body(ue, e, sched, row_offset, rows, kgrp=e % nk, nk=nk)
        # KEEP the returned addresses: compile_prefix reuses THIS scheduler and its
        # finalize() overwrites sched._worker_prog_addrs, so a bare start_workers()
        # in run_vision would relaunch the PREFIX worker program on the next slot.
        self._vis_worker_prog_addrs = sched.finalize()   # halts + writes every WORKER program
        self._assert_worker_programs_fit(sched)
        self.stop_capture()

        all_bytes = bytearray()
        for inst in self.capture_buffer:
            all_bytes.extend(inst.get_bytes())
        program_addr = self.get_program_dram_addr()
        self._dma_write_retry(DMA_DEVICE_H2C, program_addr, all_bytes, len(all_bytes))
        self.allocate_program_dram(len(all_bytes))
        self.clear_capture_buffer()
        self._vis_program_addr = program_addr
        # compile_encoder does its OWN capture/serialize/DMA/allocate (unlike
        # compile_prefix/compile_denoise_loop, which leave the capture buffer full for
        # _compile_once to drain). By the time _compile_once inspects capture_buffer it
        # is already empty, so _compile_once cannot measure this program's length and
        # would record 0 -> a zero-length entry in programs.json and a silently broken
        # run_from_bin. Stash the real length here for _compile_once to pick up.
        self._encoder_prog_len = len(all_bytes)
        # Worker program lengths are NOT part of programs.json (which describes the
        # primary's program allocator only). run_from_bin therefore cannot reproduce a
        # multi-engine encoder -- dump_programs_to_file refuses rather than dumping a
        # bin set that would silently execute half an image.
        self._encoder_worker_prog_lens = [w.get_capture_instruction_size_bytes()
                                          for w in sched.workers]
        extra = (f" + {len(sched.workers)} worker program(s) "
                 f"{self._encoder_worker_prog_lens} bytes") if sched.workers else ""
        print(f"    Vision encoder compiled: {len(all_bytes)} bytes at 0x{program_addr:X}"
              f"{extra} (num_engines={ne})")
        return program_addr

    def _emit_encoder_body(self, ue, engine_idx, sched, row_offset, rows, kgrp=0, nk=1):
        """Emit ONE engine's complete encoder program over rows
        [row_offset, row_offset+rows) of the S=256 patch tokens.

        ``kgrp``/``nk`` add the SECOND grid axis (see _vis_grid). With nk == 1
        this is the historical row-only stream, unchanged. With nk > 1 the engines
        sharing a row block are K lanes: they run the whole layer REDUNDANTLY --
        same inputs, same weights, same addresses, so the writes are identical and
        benign -- except the MLP, which is the one place they divide the work:

            fc1  N-split  : lane owns columns [n0, n0+nc) of the IP-wide
                            intermediate. B is stored N x K so the slice is a
                            contiguous row block -> pure address arithmetic, no
                            host-sliced weights. Writes its own dense [rows, nc]
                            lane buffer (matmat_mul_core's writeback stride is the
                            N it was GIVEN, so this is dense, not strided).
            GELU          : elementwise -> stays in lane, no exchange.
            fc2  K-split  : the lane's [rows, nc] IS the contiguous K-slice of the
                            intermediate, so its A operand is already dense -- the
                            only reason this op can be K-split at all (there is no
                            A-stride in the matmul ABI). Uses the host-sliced
                            fc2_k[kgrp] blob and produces a FULL [rows, H] PARTIAL.
            reduce        : lane 0 sums the partials into VIS_MLP_OUT.

        Redundant execution of the non-MLP ops is deliberate: it costs the extra
        engines nothing that could be used elsewhere (their row block is already
        the minimum 64) and it keeps every barrier count and instruction sequence
        identical across lanes, which a skip-the-work variant would not.

        With num_engines==1 this is (row_offset, rows) == (0, S), every byte
        offset below is 0 and every M is S -- i.e. exactly the historical
        single-engine stream.

        ADDRESSING CONTRACT (per the audit):
          SHARED_FULL  weights / scales / biases / identity / zero-bias  -> no offset
          SHARED_ROWS  every [S, *] activation buffer AND vis_pos_embed   -> +row_offset*pitch
          PER_ENGINE   vis_zeros, VIS_FLASH_{Q,K,V,OUT}, attn scratch     -> ctx-resolved
        K and V are read in FULL by both engines (that is the whole point of the
        rendezvous); only the QUERY rows are split.
        """
        from user_dma_core import TYPE
        S, H, NH, D, DP, IP = (self.VIS_S, self.VIS_H, self.VIS_NH, self.VIS_D, self.VIS_DP,
                                self.VIS_I_PAD)
        bpe = 2
        HP = NH * DP
        HO = self.VIS_HEAD_OUT
        ne = sched.num_engines
        is_primary = engine_idx == 0

        # Per-engine byte offsets into the SHARED_ROWS buffers. COMPILE-TIME
        # CONSTANTS, folded here at capture time -- never computed at runtime via a
        # GPR (that is the ue_selector _addr_tmp clobber class of bug).
        RH = row_offset * H * bpe                    # [S, H]  buffers
        RP = row_offset * HP * bpe                   # [S, HP] buffers (Q/K/V/attn result)
        RI = row_offset * IP * bpe                   # [S, IP] MLP intermediate
        RK = row_offset * self.VIS_PATCH_K * bpe     # [S, PK] patchified pixels
        RO = row_offset * HO * bpe                   # [S, HO] head output
        assert rows % 64 == 0, f"shard row count {rows} must be 64-aligned"

        zeros_addr = sched.per_engine_addr("vis_zeros", engine_idx)
        # 2D-only lane buffers (see the MLP block). Resolved here so the nk == 1
        # stream never touches them and stays byte-identical.
        lane_inter = sched.per_engine_addr("vis_mlp_lane", engine_idx) if nk > 1 else None
        lane_partial = sched.per_engine_addr("vis_mlp_partial", engine_idx) if nk > 1 else None
        FQ = sched.per_engine_addr("flash_q", engine_idx)
        FK = sched.per_engine_addr("flash_k", engine_idx)
        FV = sched.per_engine_addr("flash_v", engine_idx)
        FO = sched.per_engine_addr("flash_out", engine_idx)
        ATTN_SCRATCH = sched.per_engine_addr("attn_scratch", engine_idx)

        self._debug_counter = 0
        if is_primary:
            self._debug_halt_info = None

        # Fresh register/inst-pointer counters per stage (see compile_denoise_loop).
        # (begin_program() already did this for the workers.)

        # Norm ABI (post pcie_only sync): layer_norm_core_dram now dispatches to the
        # dynamic core, where gpr_M_reg is the runtime ROW COUNT, not the old PBI
        # n_chunks, and the sqrt(N) RSQRT scale is a runtime GPR (float_to_bf19(sqrt(N)))
        # rather than an implicit fold. The old code primed gpr_M_reg with n_chunks
        # (correct only for the retired PBI ABI): under the new ABI that normalized only
        # ~n_chunks of S rows, so the un-normalized rows compounded across the 27 encoder
        # layers and overflowed bf16 -> NaN vision tokens. Prime rows=THIS ENGINE'S row
        # count plus N + bf19(sqrt(N)) (vision LayerNorm N = VIS_H) and thread them
        # through every layer_norm below. N / sqrt(N) describe the WITHIN-ROW
        # normalization width and are therefore unchanged by the row split.
        vis_S_reg = ue.alloc_isa_reg()
        vis_N_reg = ue.alloc_isa_reg()
        vis_sqrt_N_reg = ue.alloc_isa_reg()
        ue.generate_instruction_add_set(vis_S_reg, rows)
        ue.generate_instruction_add_set(vis_N_reg, H)
        ue.generate_instruction_add_set(vis_sqrt_N_reg, ue.float_to_bf19(float(H ** 0.5)))

        def vis_matmul(M, K, N, A, la, proj, OUT, bias=None, **kw):
            ue.matmat_mul_core(M=M, K=K, N=N, A_DRAM_ADDR=A, B_DRAM_ADDR=la[f'{proj}_data'],
                OUTPUT_DRAM_ADDR=OUT, is_B_quantized=True, data_type=TYPE.IF4,
                SCALE_DRAM_ADDR=la[f'{proj}_scale'], C_DRAM_ADDR=bias, bias_mode="broadcast_N",
                gpr_M_reg=vis_S_reg, **kw)

        # Per-(layer,head) attention: each call site marshals its head's [rows, D] Q
        # and the FULL [S, D] K/V (padded to DP) into the per-engine VIS_FLASH buffers
        # and runs an INLINE unified_attention_core_dynamic.

        try:
            # === Patch embedding: patchified pixels [rows, 588] -> [rows, 1152] (+ pos) ===
            vis_matmul(rows, self.VIS_PATCH_K, H, self.VIS_PIXEL_IN_DRAM + RK,
                {'embed_data': self.vis_embed_data, 'embed_scale': self.vis_embed_scale}, 'embed',
                self.VIS_PATCH_PROJ_DRAM + RH, bias=self.vis_embed_bias)
            # TRAP: vis_pos_embed is SHARED_ROWS, NOT SHARED_FULL. It is (S, H) -- one
            # row per patch -- and this is a FLAT eltwise add, so element i of B pairs
            # with element i of A. A sharded A REQUIRES the matching B slice; without
            # +RH engine1 would add pos rows 0..127 to patch rows 128..255 (silent
            # half-image corruption, no NaN).
            eltwise_add_core_dram(ue, size=rows * H, A_DRAM_ADDR=self.VIS_PATCH_PROJ_DRAM + RH,
                B_DRAM_ADDR=self.vis_pos_embed + RH, OUTPUT_DRAM_ADDR=self.VIS_IO_A_DRAM + RH)
            self._debug_op("patch_embed_pos", self.VIS_IO_A_DRAM, S * H, shape=(S, H), ue=ue)

            for layer_idx, la in enumerate(self.vis_layer_addrs):
                h_in  = self.VIS_IO_A_DRAM if layer_idx % 2 == 0 else self.VIS_IO_B_DRAM
                h_out = self.VIS_IO_B_DRAM if layer_idx % 2 == 0 else self.VIS_IO_A_DRAM
                # NOTE: no barrier at the layer boundary. Layer i writes h_out+RH for
                # its OWN rows and layer i+1 reads h_in+RH -- the same rows. The only
                # cross-shard read in the whole encoder is the peer's K/V below.
                # LN0 (PBI)
                ue.layer_norm_core_dram(M=rows, N=H, A_DRAM_ADDR=h_in + RH,
                    OUTPUT_DRAM_ADDR=self.VIS_LN_OUT_DRAM + RH,
                    GAMMA_DRAM_ADDR=la['ln0_w'], BETA_DRAM_ADDR=la['ln0_b'], gpr_M_reg=vis_S_reg,
                    gpr_N_reg=vis_N_reg, gpr_sqrt_n_reg=vis_sqrt_N_reg,
                    ZEROS_DRAM_ADDR=zeros_addr)
                self._debug_op(f"layer{layer_idx}_ln0", self.VIS_LN_OUT_DRAM, S * H, shape=(S, H), ue=ue)
                # Q/K/V projections (PBI, IF4). N=NH*DP: weights are pre-padded per-head
                # D->DP=128 (see _weight_init_vision's _pad_proj) so the buffers below are
                # already head-block-aligned at DP=128, no separate real/padded copy needed.
                for proj, dst in [('q', self.VIS_Q_DRAM), ('k', self.VIS_K_DRAM), ('v', self.VIS_V_DRAM)]:
                    vis_matmul(rows, H, HP, self.VIS_LN_OUT_DRAM + RH, la, proj, dst + RP,
                               bias=la[f'{proj}_bias'])

                # ---- RENDEZVOUS: the ONE point an engine reads rows it did not write.
                # Below, K/V are gathered in FULL (both shards) while Q is this shard
                # only, so every engine's K/V projection must have landed first.
                self._vis_barrier(ue, engine_idx, ne)

                # Per-head bidirectional flash attention (no mask, no RoPE). Each head's
                # block is a full DP=128-wide (256B) column slice -> every DMA stride
                # below is AXI-beat (32B) aligned, unlike a bare D=72 (144B) slice.
                elems_q  = rows * DP    # THIS engine's query rows
                elems_kv = S * DP       # FULL K/V -- both shards, on every engine
                col_stride = DP * bpe   # one head's column block width (aligned)
                row_jump = HP * bpe     # full [S, HP] row stride
                for h in range(NH):
                    col = h * col_stride
                    # TRAP: the Q gather and the result scatter carry +RP; the K/V
                    # gathers must NOT. Omitting RP on the scatter makes both engines
                    # write rows 0..127 -> finite, NaN-free, structurally plausible
                    # SCRAMBLED output (project_pi05_denoise_strided_copy_bugs).
                    assert (RP + col) % 32 == 0, "strided DMA base must be AXI-beat aligned"
                    for src, dst, n in ((self.VIS_Q_DRAM + RP + col, FQ, elems_q),
                                        (self.VIS_K_DRAM + col,      FK, elems_kv),
                                        (self.VIS_V_DRAM + col,      FV, elems_kv)):
                        ue.accelerator_memory_to_sram(src, 0x00000, n,
                            stride_bytes_per_chunk=col_stride, stride_jump_bytes=row_jump)
                        ue.sram_to_accelerator_memory(0x00000, dst, n)
                    # INLINE full-MHA self-attention for this head: batch=THIS engine's
                    # query rows, aligned_seq_len=S (the full K/V), head_dim=DP, zero
                    # (unmasked) bias, standard 1/sqrt(DP) scale. Splitting the QUERY
                    # axis needs no online-softmax merge -- each query row's softmax is
                    # already over the full key set.
                    #
                    # NOT a PBI-flash problem: swapping this to
                    # unified_attention_core_legacy produced BIT-IDENTICAL output
                    # (only slower), so the encoder's error is deterministic math, not
                    # PBI back-to-back corruption. Don't re-litigate this -- bisect the
                    # encoder body against pi05_torch_ref.vision_encode_checkpoints.
                    ue.unified_attention_core_dynamic(
                        batch=rows, aligned_seq_len=S, head_dim=DP,
                        Q_DRAM_ADDR=FQ, K_DRAM_ADDR=FK, V_DRAM_ADDR=FV,
                        BIAS_DRAM_ADDR=self.VIS_ZERO_BIAS_DRAM,
                        OUTPUT_DRAM_ADDR=FO,
                        SCRATCH_DRAM_ADDR=ATTN_SCRATCH,
                        IDENTITY_DRAM_ADDR=self.identity_addr)
                    ue.accelerator_memory_to_sram(FO, 0x00000, elems_q)
                    ue.sram_to_accelerator_memory(0x00000, self.VIS_ATTN_RESULT_DRAM + RP + col,
                        elems_q, stride_bytes_per_chunk=col_stride, stride_jump_bytes=row_jump)

                # WAR rendezvous: nothing else stops this engine from racing ahead into
                # layer i+1's K/V projection and overwriting VIS_K/VIS_V rows the peer is
                # still gathering above. See VIS_BARRIER_AFTER_ATTN.
                if self.VIS_BARRIER_AFTER_ATTN:
                    self._vis_barrier(ue, engine_idx, ne)

                # O projection + residual + LN1 (PBI)
                vis_matmul(rows, HP, H, self.VIS_ATTN_RESULT_DRAM + RP, la, 'o',
                           self.VIS_O_PROJ_DRAM + RH, bias=la['o_bias'])
                self._debug_op(f"layer{layer_idx}_o_proj", self.VIS_O_PROJ_DRAM, S * H, shape=(S, H), ue=ue)
                eltwise_add_core_dram(ue, size=rows * H, A_DRAM_ADDR=h_in + RH,
                    B_DRAM_ADDR=self.VIS_O_PROJ_DRAM + RH,
                    OUTPUT_DRAM_ADDR=self.VIS_RESIDUAL_DRAM + RH)
                self._debug_op(f"layer{layer_idx}_residual1", self.VIS_RESIDUAL_DRAM, S * H, shape=(S, H), ue=ue)
                ue.layer_norm_core_dram(M=rows, N=H, A_DRAM_ADDR=self.VIS_RESIDUAL_DRAM + RH,
                    OUTPUT_DRAM_ADDR=self.VIS_LN_OUT_DRAM + RH,
                    GAMMA_DRAM_ADDR=la['ln1_w'], BETA_DRAM_ADDR=la['ln1_b'], gpr_M_reg=vis_S_reg,
                    gpr_N_reg=vis_N_reg, gpr_sqrt_n_reg=vis_sqrt_N_reg,
                    ZEROS_DRAM_ADDR=zeros_addr)
                self._debug_op(f"layer{layer_idx}_ln1", self.VIS_LN_OUT_DRAM, S * H, shape=(S, H), ue=ue)
                # MLP: Dense_0 + GELU (sigmoid-approx — the engine's only hardware GELU; the
                # reference uses tanh-approx GELU, a small documented numeric deviation),
                # Dense_1, residual.
                if nk == 1:
                    vis_matmul(rows, H, IP, self.VIS_LN_OUT_DRAM + RH, la, 'fc1',
                               self.VIS_MLP_INTER_DRAM + RI, bias=la['fc1_bias'], gelu_enable=True)
                    vis_matmul(rows, IP, H, self.VIS_MLP_INTER_DRAM + RI, la, 'fc2',
                               self.VIS_MLP_OUT_DRAM + RH, bias=la['fc2_bias'])
                else:
                    n0, nc = self._col_split(IP, nk)[kgrp]
                    # --- fc1: N-split. All four per-column offsets, and every one
                    # of them silently corrupts if wrong (see multi_engine_shard's
                    # "THE FOUR PER-COLUMN OFFSETS"). Verified bit-exact against a
                    # direct quantization of rows [n0, n0+nc) of the fc1 weight.
                    #   B (IF4) : + (n0*K)//2        two nibbles per byte
                    #   scale   : + ((n0*K)//64)*2   one bf16 per 64-block
                    #   bias    : + n0*2             broadcast_N is INDEXED by N
                    ue.matmat_mul_core(
                        M=rows, K=H, N=nc, A_DRAM_ADDR=self.VIS_LN_OUT_DRAM + RH,
                        B_DRAM_ADDR=la['fc1_data'] + (n0 * H) // 2,
                        SCALE_DRAM_ADDR=la['fc1_scale'] + ((n0 * H) // UE_VECTOR_SIZE) * bpe,
                        C_DRAM_ADDR=la['fc1_bias'] + n0 * bpe, bias_mode="broadcast_N",
                        OUTPUT_DRAM_ADDR=lane_inter, is_B_quantized=True,
                        data_type=TYPE.IF4, gelu_enable=True, gpr_M_reg=vis_S_reg)
                    # --- fc2: K-split over the SAME columns. A is this lane's dense
                    # [rows, nc] buffer, which is why the K-split is expressible at
                    # all. Bias on lane 0 ONLY -- the partials are summed, so a bias
                    # on every lane would be added nk times.
                    fc2_s, fc2_d = la['fc2_k'][kgrp]
                    ue.matmat_mul_core(
                        M=rows, K=nc, N=H, A_DRAM_ADDR=lane_inter,
                        B_DRAM_ADDR=fc2_d, SCALE_DRAM_ADDR=fc2_s,
                        C_DRAM_ADDR=(la['fc2_bias'] if kgrp == 0 else None),
                        bias_mode="broadcast_N",
                        OUTPUT_DRAM_ADDR=lane_partial, is_B_quantized=True,
                        data_type=TYPE.IF4, gpr_M_reg=vis_S_reg)
                    # --- reduce: every lane's partial must have landed first.
                    self._vis_barrier(ue, engine_idx, ne)
                    if kgrp == 0:
                        acc = lane_partial
                        for j in range(1, nk):
                            eltwise_add_core_dram(
                                ue, size=rows * H, A_DRAM_ADDR=acc,
                                B_DRAM_ADDR=sched.per_engine_addr("vis_mlp_partial",
                                                                  engine_idx + j),
                                OUTPUT_DRAM_ADDR=self.VIS_MLP_OUT_DRAM + RH)
                            acc = self.VIS_MLP_OUT_DRAM + RH
                    # --- lane 0's sum must be visible before the residual below,
                    # which every lane recomputes redundantly.
                    self._vis_barrier(ue, engine_idx, ne)
                self._debug_op(f"layer{layer_idx}_mlp_out", self.VIS_MLP_OUT_DRAM, S * H, shape=(S, H), ue=ue)
                eltwise_add_core_dram(ue, size=rows * H,
                    A_DRAM_ADDR=self.VIS_RESIDUAL_DRAM + RH, B_DRAM_ADDR=self.VIS_MLP_OUT_DRAM + RH,
                    OUTPUT_DRAM_ADDR=h_out + RH)
                self._debug_op(f"layer{layer_idx}_residual2", h_out, S * H, shape=(S, H), ue=ue)
                self._dram_copy(rows * H * bpe, h_out + RH,
                                self.VIS_LAYER_SNAPSHOT_DRAM[layer_idx] + RH, ue=ue)

            # Final encoder_norm (PBI) + head projection (IF4). Both row-independent:
            # no barrier needed before them.
            final_vis = self.VIS_IO_A_DRAM if len(self.vis_layer_addrs) % 2 == 0 else self.VIS_IO_B_DRAM
            ue.layer_norm_core_dram(M=rows, N=H, A_DRAM_ADDR=final_vis + RH,
                OUTPUT_DRAM_ADDR=self.VIS_POST_LN_DRAM + RH,
                GAMMA_DRAM_ADDR=self.vis_encoder_norm_w, BETA_DRAM_ADDR=self.vis_encoder_norm_b,
                gpr_M_reg=vis_S_reg, gpr_N_reg=vis_N_reg, gpr_sqrt_n_reg=vis_sqrt_N_reg,
                ZEROS_DRAM_ADDR=zeros_addr)
            self._debug_op("encoder_norm", self.VIS_POST_LN_DRAM, S * H, shape=(S, H), ue=ue)
            vis_matmul(rows, H, HO, self.VIS_POST_LN_DRAM + RH,
                {'head_data': self.vis_head_data, 'head_scale': self.vis_head_scale}, 'head',
                self.VIS_HEAD_OUT_DRAM + RO, bias=self.vis_head_bias)
            self._debug_op("head_out", self.VIS_HEAD_OUT_DRAM, S * HO, shape=(S, HO), ue=ue)

            # Final rendezvous, then halt. The workers' halt is emitted by
            # sched.finalize(); only the primary halts here, so the HOST still waits on
            # engine0's queue alone (run_vision's _wait_with_heartbeat + the full
            # (S, HO) DMA readback are unchanged) -- and engine0 cannot report done
            # until every worker has reached this point and written its rows.
            self._vis_barrier(ue, engine_idx, ne)
            if is_primary:
                ue.generate_instruction_halt()   # encoder ends.
        except _DebugStop:
            pass   # halt already emitted by _debug_op (on THIS engine).

        ue.release_isa_reg()  # vis_sqrt_N_reg
        ue.release_isa_reg()  # vis_N_reg
        ue.release_isa_reg()  # vis_S_reg

    # =========================================================================
    # Action-expert (Gemma-300M) flow-matching denoising stack.
    #
    # Ported from pi05_torch_ref.py: ada_rms_norm / gated_mlp / sincos_pos_embed /
    # joint_attention(suf_tokens branch) / suffix_step / the Euler loop in run_pi05.
    #
    # Geometry (manifest hw_notes): 18 layers, hidden=1024, heads=8, kv_heads=1,
    # head_dim=256 (== self.HEAD_DIM, shared with the prefix Gemma-2B geometry --
    # self.identity_addr from tensor_init() is already sized for this head_dim).
    # intermediate=4096. All multiples of 64: no padding needed on those dims.
    #
    # ASSUMED PREFIX KV-CACHE INTERFACE (not finalized by the prefix agent at the
    # time this was written -- reconcile before running end-to-end):
    #   self.PREFIX_SEQ_LEN            -- int, padded prefix token count (manifest: 1024)
    #   self.prefix_k_cache_addr[l]    -- DRAM base for layer l's cached K, shape
    #                                      (PREFIX_SEQ_LEN, HEAD_DIM) bf16, kv_heads=1 (MQA)
    #   self.prefix_v_cache_addr[l]    -- same for V
    # If those attributes are missing, tensor_init_action_expert() below allocates
    # a zero-filled placeholder buffer per layer so compile still runs; real prefix
    # KV must be DMA'd into that placeholder (or the attrs pointed at the prefix
    # agent's real buffers) before this is numerically correct.
    # =========================================================================
    AE_HIDDEN = 1024
    AE_INTERMEDIATE = 4096
    AE_LAYERS = 18
    AE_HEADS = 8
    AE_KV_HEADS = 1
    AE_ACTION_DIM_PADDED = 32
    AE_XT_WIDTH = 64  # physical width of x_t/v_t buffers (action_dim 32 padded to 64-align)
    # --- roofline / FLOP-util reporting -------------------------------------
    CYCLE_NS = 5.63          # HW clock period (config defaults.cycle_ns) -> ~177.6 MHz
    MACS_PER_CYCLE = 64      # ASSUMPTION: 64-ALU vector unit = 64 MACs/cycle. If the
                             # matmul core is a 64xN systolic array this is higher --
                             # set to the real MAC/cycle to get an accurate %-of-peak.
    AE_ACTION_HORIZON = 10
    AE_ACTION_HORIZON_PADDED = 64  # padded for 64-alignment (flash / matmul row tiling)
    AE_NUM_DENOISE_STEPS = 10
    AE_LOOP_TRIP_OVERRIDE = None  # debug knob, see compile_denoise_loop's loop_start call
    DENOISE_STEP0_PROBE = False  # if True, snapshot step-0 intermediates for reference diff
    # Run the action-expert timestep-embedding MLP (2x 1024x1024 IF4 matmul + 2x
    # SiLU) ON DEVICE instead of constant-folding it on the host. Only the sincos
    # table (transcendental, no HW primitive, input-independent) stays a host
    # constant -- same treatment as the RoPE tables. See _ae_compile_cond_table.
    AE_COND_TABLE_ON_DEVICE = True
    AE_COND_TABLE_CHECK = False  # readback + SNR vs the host oracle after the run

    # The denoise/action-expert stage is N-sharded (output columns), not M-sharded:
    # every op in it has M = AE_ACTION_HORIZON_PADDED = 64, ONE row block, which
    # cannot be split at all. Follows --engines unless pinned to an int.
    DENOISE_NUM_ENGINES = None

    def _vis_grid(self, ne, s=None):
        """(row_groups, k_groups) for `ne` vision engines -- the 2D vision shard.

        The vision encoder's M is only S//64 = 4 blocks of 64 rows, so a pure
        M-split caps at 4 engines. The PROJECTIONS, however, are 94.9% of the
        stage and every one of them has a fat K:

            q/k/v  K=H=1152   (18 blocks)     out  K=NH*DP=2048 (32 blocks)
            fc1    K=H=1152   (18 blocks)     fc2  K=IP=4352    (68 blocks)

        So the grid is rows x K: 8 engines = 4 row groups x 2 K groups. K, not N,
        because a K-split output is FULL-WIDTH -- it lands at exactly the address
        the unsplit matmul wrote, so every downstream buffer, LayerNorm, residual
        and (critically) the flash-attention marshalling are untouched. An N-split
        would force per-engine [rows, cols] buffers, because matmat_mul_core writes
        back with stride cols*bpe, and that WOULD drag in the marshalling.

        The attention op itself (5.1%) is not split; it stays row-parallel.

        Row groups are the largest divisor of `ne` that still fits in S//64, so
        ne=4 -> (4,1) is byte-identical to today and ne=8 -> (4,2).
        """
        max_rows = (s or self.VIS_S) // 64
        nr = max(d for d in range(1, max_rows + 1) if ne % d == 0)
        return nr, ne // nr

    @staticmethod
    def _col_split(N, num_engines, align=64):
        """[(offset, count)] whole-``align``-block column split -- the SAME rule as
        MultiEngineScheduler.split_cols.

        Duplicated here on purpose: the down-projection's K-sliced weight blobs are
        cut at WEIGHT-INIT time, long before any scheduler exists, and a silent
        disagreement between the host slice and the runtime shard is exactly the
        finite-but-wrong failure mode this project keeps paying for. compile time
        asserts the two agree (see _ae_gated_mlp_sharded)."""
        if num_engines == 1:
            return [(0, N)]
        assert N % align == 0, f"_col_split: N={N} not a multiple of {align}"
        blocks = N // align
        assert blocks >= num_engines, f"_col_split: N={N} too few {align}-blocks"
        base, rem = divmod(blocks, num_engines)
        counts = [align * (base + (1 if i < rem else 0)) for i in range(num_engines)]
        offsets = [sum(counts[:i]) for i in range(num_engines)]
        return list(zip(offsets, counts))

    # ---- action-expert weights ---------------------------------------------
    def weight_init_action_expert(self):
        """Load action-expert (Gemma-300M) weights from weights_export/*.npy into
        params DRAM. Additive to weight_init(): hooked in via the hasattr() check
        in weight_init() above, does not touch the prefix/vision weight loading
        owned by the other two agents.

        Quantization policy: all matmul weight matrices (action_in_proj,
        time_mlp_in/out, action_out_proj, q/kv/attn_vec einsum, mlp gating/linear,
        and the AdaRMSNorm conditioning Dense_0 kernels) are IF4 (q4_64) via
        quantize_q4_64 + store_quantized_weight. Biases and norm terms stay bf16
        via store_weight. AdaRMSNorm itself has no learned gamma (plain RMSNorm);
        only its conditioning Dense layer has a kernel+bias.

        Weight layout note: weights_export tensors are JAX-style (in_features,
        out_features) i.e. consumed as ``x @ W``. The engine's matmat_mul_core
        computes ``A @ B^T`` with B stored (N, K) = (out, in). Every matmul
        weight is therefore transposed (last two dims) before quantizing/storing.
        """
        # Resolved once here: the mlp-down K-slice blobs below are only stored when
        # the denoise stage will actually run sharded, so --engines 1 pays no DRAM
        # for them and its weight blob is byte-identical to the pre-sharding one.
        _ne_denoise = self._num_engines("DENOISE")
        wdir = _weights_export_dir(self.script_dir)
        manifest_path = os.path.join(wdir, "manifest.json")
        with open(manifest_path) as f:
            wman = json.load(f)

        def _load(name):
            info = wman[name]
            arr = np.load(os.path.join(wdir, info["file"]))
            return torch.from_numpy(arr.astype(np.float32))

        def _store_matmul(name):
            """Load (..., K, N) JAX-layout weight, transpose last two dims ->
            (..., N, K), quantize to IF4, store. Returns (scale_addr, data_addr)."""
            w = _load(name).transpose(-1, -2).contiguous().to(torch.bfloat16)
            data, _ = _mlc_quantize_q4_64(w)
            return store_quantized_weight(self, data.tobytes())

        def _store_bf16(name):
            return store_weight(self, _load(name).to(torch.bfloat16))

        def _store_matmul_npad(name, n_pad):
            """Like _store_matmul, but zero-pads the N (output) dim up to n_pad.
            Used for action_out_proj: output action_dim=32 padded to 64 so v_t is
            physically 64-wide, matching the 64-wide x_t buffer -- lets the euler
            update and action_in_proj run as plain contiguous ops (no strided
            32->64 staging, which was reading noise rows at 2x stride)."""
            w = _load(name).transpose(-1, -2).contiguous()  # (N_real, K)
            n_real = w.shape[-2]
            if n_real < n_pad:
                w = torch.nn.functional.pad(w, (0, 0, 0, n_pad - n_real))  # pad dim -2 (N)
            w = w.to(torch.bfloat16)
            data, _ = _mlc_quantize_q4_64(w)
            return store_quantized_weight(self, data.tobytes())

        def _store_bf16_npad(name, n_pad):
            t = _load(name)  # (N_real,)
            if t.shape[-1] < n_pad:
                t = torch.nn.functional.pad(t, (0, n_pad - t.shape[-1]))
            return store_weight(self, t.to(torch.bfloat16))

        def _store_matmul_kpad(name, k_pad):
            """Like _store_matmul, but zero-pads the K (reduction) dim up to
            k_pad. Needed for action_in_proj: real action_dim=32 < the
            engine's matmat_mul_core K%64==0 requirement (also the IF4
            block_size=64 boundary)."""
            w = _load(name).transpose(-1, -2).contiguous()  # (N, K_real)
            k_real = w.shape[-1]
            if k_real < k_pad:
                w = torch.nn.functional.pad(w, (0, k_pad - k_real))
            w = w.to(torch.bfloat16)
            data, _ = _mlc_quantize_q4_64(w)
            return store_quantized_weight(self, data.tobytes())

        # --- flow-matching I/O projections + timestep MLP (not per-layer) ---
        # action_in_proj: K=action_dim=32 padded to 64 (matmat_mul_core requires
        # K % UE_VECTOR_SIZE(64) == 0); the caller (compile_denoise_loop) zero-pads
        # AE_XT_DRAM into AE_XT_PAD_DRAM (S, 64) to match.
        self.ae_action_in_scale, self.ae_action_in_data = _store_matmul_kpad("action_in_proj.kernel", 64)
        self.ae_action_in_bias = _store_bf16("action_in_proj.bias")
        self.ae_time_in_scale, self.ae_time_in_data = _store_matmul("time_mlp_in.kernel")
        self.ae_time_in_bias = _store_bf16("time_mlp_in.bias")
        self.ae_time_out_scale, self.ae_time_out_data = _store_matmul("time_mlp_out.kernel")
        self.ae_time_out_bias = _store_bf16("time_mlp_out.bias")
        # action_out_proj output N padded 32->64 so v_t is physically 64-wide
        # (matches the 64-wide x_t buffer -> plain contiguous euler + no staging).
        self.ae_action_out_scale, self.ae_action_out_data = _store_matmul_npad("action_out_proj.kernel", 64)
        self.ae_action_out_bias = _store_bf16_npad("action_out_proj.bias", 64)

        # --- per-layer action-expert transformer weights ---------------------
        self.ae_layer_addrs = []
        for layer in range(self.AE_LAYERS):
            la = {}

            def _store_matmul_layer(name, sl):
                w = _load(name)[sl].transpose(-1, -2).contiguous().to(torch.bfloat16)
                data, _ = _mlc_quantize_q4_64(w)
                return store_quantized_weight(self, data.tobytes())

            # AdaRMSNorm conditioning: Dense_0 (1024 -> 3*1024=3072), kernel quantized,
            # bias stays bf16.
            la["pre_attn_norm_dense_scale"], la["pre_attn_norm_dense_data"] = \
                _store_matmul_layer("PaliGemma.llm.layers.pre_attention_norm_1.Dense_0.kernel", layer)
            la["pre_attn_norm_dense_bias"] = store_weight(
                self, _load("PaliGemma.llm.layers.pre_attention_norm_1.Dense_0.bias")[layer].to(torch.bfloat16))
            la["pre_ffw_norm_dense_scale"], la["pre_ffw_norm_dense_data"] = \
                _store_matmul_layer("PaliGemma.llm.layers.pre_ffw_norm_1.Dense_0.kernel", layer)
            la["pre_ffw_norm_dense_bias"] = store_weight(
                self, _load("PaliGemma.llm.layers.pre_ffw_norm_1.Dense_0.bias")[layer].to(torch.bfloat16))

            # Attention: per-head Q (8, 1024, 256), shared single-head KV (1, 1024, 256), O (8, 256, 1024)
            q_all = _load("PaliGemma.llm.layers.attn.q_einsum_1.w")[layer]     # (8, 1024, 256)
            kv_all = _load("PaliGemma.llm.layers.attn.kv_einsum_1.w")[layer]   # (2, 1, 1024, 256)
            o_all = _load("PaliGemma.llm.layers.attn.attn_vec_einsum_1.w")[layer]  # (8, 256, 1024)
            la["q_scale"], la["q_data"] = [], []
            la["o_scale"], la["o_data"] = [], []
            for h in range(self.AE_HEADS):
                qw = q_all[h].transpose(-1, -2).contiguous().to(torch.bfloat16)  # (256,1024) N,K
                data, _ = _mlc_quantize_q4_64(qw)
                sa, da = store_quantized_weight(self, data.tobytes())
                la["q_scale"].append(sa); la["q_data"].append(da)
                ow = o_all[h].transpose(-1, -2).contiguous().to(torch.bfloat16)  # (1024,256) N,K
                data, _ = _mlc_quantize_q4_64(ow)
                sa, da = store_quantized_weight(self, data.tobytes())
                la["o_scale"].append(sa); la["o_data"].append(da)
            kw = kv_all[0, 0].transpose(-1, -2).contiguous().to(torch.bfloat16)  # (256,1024) N,K
            data, _ = _mlc_quantize_q4_64(kw)
            la["k_scale"], la["k_data"] = store_quantized_weight(self, data.tobytes())
            vw = kv_all[1, 0].transpose(-1, -2).contiguous().to(torch.bfloat16)
            data, _ = _mlc_quantize_q4_64(vw)
            la["v_scale"], la["v_data"] = store_quantized_weight(self, data.tobytes())

            # Gated MLP: gating_einsum (2, 1024, 4096) -> [gate_w, up_w], linear (4096, 1024)
            gating = _load("PaliGemma.llm.layers.mlp_1.gating_einsum")[layer]  # (2,1024,4096)
            gate_w = gating[0].transpose(-1, -2).contiguous().to(torch.bfloat16)  # (4096,1024) N,K
            data, _ = _mlc_quantize_q4_64(gate_w)
            la["mlp_gate_scale"], la["mlp_gate_data"] = store_quantized_weight(self, data.tobytes())
            up_w = gating[1].transpose(-1, -2).contiguous().to(torch.bfloat16)
            data, _ = _mlc_quantize_q4_64(up_w)
            la["mlp_up_scale"], la["mlp_up_data"] = store_quantized_weight(self, data.tobytes())
            # mlp down: (I=4096 -> H=1024). The ONLY op in the action expert whose
            # fat dimension is K, not N, so it is the one that cannot be sharded by
            # pointer arithmetic: B is stored N x K row-major, so B[:, k0:k0+Kc] is
            # strided (one gap per row) and unreachable by shifting B_DRAM_ADDR.
            # It gets host-side pre-sliced blobs, one per engine, cut here at load.
            # WHY K-SPLIT AND NOT AN N-SPLIT WITH A JOIN: the gate/up/gelu-mult
            # chain above it is already N-sharded, so engine i ALREADY HOLDS,
            # contiguously, exactly the K-slice [k0, k0+Kc) of the (S, I)
            # intermediate that this K-shard needs. The K-split is therefore free on
            # the activation side and costs one eltwise add of the two (64, 1024)
            # partials. N-splitting `down` instead would need every engine to hold
            # the FULL 4096-wide intermediate, which means gathering two disjoint
            # per-engine [64, 2048] buffers into a shared [64, 4096] -- a strided
            # DRAM round-trip of 256Ki elements, per layer, per step, 180 times.
            # The reduction is ~64Ki adds against 256 MFLOP; the gather is not.
            dn_w = _load("PaliGemma.llm.layers.mlp_1.linear")[layer] \
                .transpose(-1, -2).contiguous().to(torch.bfloat16)   # (H, I) = (N, K)
            data, _ = _mlc_quantize_q4_64(dn_w)
            la["mlp_down_scale"], la["mlp_down_data"] = store_quantized_weight(self, data.tobytes())
            if _ne_denoise > 1:
                # The IF4 scale blob is one bf16 per 64-element block of the
                # FLATTENED (N, K) weight. Kc is a multiple of 64, so the slice's
                # blocks coincide exactly with a subset of the full weight's blocks
                # and re-quantizing the slice reproduces those scales bit-for-bit.
                la["mlp_down_k"] = []
                for k0, kc in self._col_split(self.AE_INTERMEDIATE, _ne_denoise):
                    sl = dn_w[:, k0:k0 + kc].contiguous()
                    sdata, _ = _mlc_quantize_q4_64(sl)
                    la["mlp_down_k"].append(store_quantized_weight(self, sdata.tobytes()))

            self.ae_layer_addrs.append(la)

        # --- final AdaRMSNorm (applied after all 18 layers, before action_out_proj) ---
        self.ae_final_norm_dense_scale, self.ae_final_norm_dense_data = \
            _store_matmul("PaliGemma.llm.final_norm_1.Dense_0.kernel")
        self.ae_final_norm_dense_bias = _store_bf16("PaliGemma.llm.final_norm_1.Dense_0.bias")

        print(f"weight_init_action_expert done; params DRAM at 0x{self.get_params_dram_addr():X}")

    # ---- action-expert scratch tensors --------------------------------------
    def tensor_init_action_expert(self):
        """Allocate action-expert activation/attention scratch DRAM. Sizes use
        AE_ACTION_HORIZON_PADDED (S=64) for the suffix block and self.PREFIX_SEQ_LEN
        (P) for the cached prefix length -- see the ASSUMED KV-CACHE INTERFACE
        comment above compile_suffix_step for the P source."""
        # COMPILE-ONCE: every allocate_tensor_dram/allocate_params_dram below marches
        # an allocator; run exactly once so repeated run_inference calls don't crawl
        # toward the 4GB ceiling. Buffers persist on self and are re-DMA'd per obs.
        if getattr(self, "_ae_tensors_inited", False):
            return
        self._ae_tensors_inited = True
        bpe = 2
        H, I, D = self.AE_HIDDEN, self.AE_INTERMEDIATE, self.HEAD_DIM
        S = self.AE_ACTION_HORIZON_PADDED
        P = getattr(self, "PREFIX_SEQ_LEN", 1024)
        self.AE_PREFIX_SEQ_LEN = P
        Tkv = P + S
        self.AE_TKV = Tkv

        # Combined per-layer K/V (prefix rows [0:P] + this-step suffix rows [P:P+S]).
        # kv_heads=1 (MQA): single (Tkv, D) buffer per layer, reused across all 10
        # Euler steps (prefix rows copied once at init; suffix rows overwritten/step).
        self.AE_KV_LAYER_STRIDE = Tkv * D * bpe
        self.ae_k_combined = [self.allocate_tensor_dram(self.AE_KV_LAYER_STRIDE) for _ in range(self.AE_LAYERS)]
        self.ae_v_combined = [self.allocate_tensor_dram(self.AE_KV_LAYER_STRIDE) for _ in range(self.AE_LAYERS)]

        # Q buffer: (heads, Tkv, D) -- only rows [0:S] per head are real suffix
        # queries; rows [S:Tkv] are padding so prefill_flash_attention_core (which
        # assumes Q/K share the same seq_len) can run Q against the full Tkv K/V.
        # Only the first S output rows are read back.
        self.AE_Q_DRAM = self.allocate_tensor_dram(self.AE_HEADS * Tkv * D * bpe)
        zero_ae_q = torch.zeros(self.AE_HEADS * Tkv, D, dtype=torch.bfloat16)
        self.dma_write(DMA_DEVICE_H2C, self.AE_Q_DRAM, zero_ae_q.contiguous(), self.AE_HEADS * Tkv * D * bpe)
        # RoPE'd copy of the suffix Q (same (heads*S, D) stacked layout the
        # unified attention reads) and a staging buffer for the un-rotated suffix
        # K projection (rope must be out-of-place: in==out is a DMA hazard).
        self.AE_Q_ROPE_DRAM = self.allocate_tensor_dram(self.AE_HEADS * Tkv * D * bpe)
        self.dma_write(DMA_DEVICE_H2C, self.AE_Q_ROPE_DRAM, zero_ae_q.contiguous(),
                       self.AE_HEADS * Tkv * D * bpe)
        self.AE_K_SUF_DRAM = self.allocate_tensor_dram(S * D * bpe)
        # rotate_half scratch for the matmul RoPE (_rope_matmul), head-major over
        # all AE_HEADS so each engine writes its own head range's disjoint slice.
        # The single-head suffix K rope reuses its first S*D elements: K is rotated
        # before Q in every layer body, so the two never overlap in time.
        self.AE_ROPE_ROT_DRAM = self.allocate_tensor_dram(self.AE_HEADS * S * D * bpe)
        self.AE_ATTN_OUT_DRAM = self.allocate_tensor_dram(self.AE_HEADS * Tkv * D * bpe)
        self.AE_ATTN_SCRATCH_DRAM = self.allocate_tensor_dram((D * Tkv + max(D, 64) * Tkv) * bpe)
        self.AE_ATTN_RESULT_DRAM = self.allocate_tensor_dram(S * H * bpe)  # un-headed (S,H) post-o-proj input
        self.AE_O_PROJ_DRAM = self.allocate_tensor_dram(S * H * bpe)

        # Suffix attention bias: (Tkv, Tkv) additive bf16, 0 for valid prefix+suffix
        # cols (bidirectional per pi0.5 ar_mask all-False), large-negative for the
        # [S:Tkv] padding columns/rows (unused rows are never read back, but the
        # columns feeding real rows' softmax must be masked so padding K/V garbage
        # doesn't pollute attention over rows [0:S]), AND large-negative for
        # [valid_len:P] -- the prefix's OWN internal padding-token columns (compile_prefix
        # pads seq_len=P=832 but only the first valid_len~784-813 rows are real tokens;
        # rows [valid_len:P] hold finite-but-meaningless padding-token K/V that must not
        # leak into the suffix's cross-attention softmax over the real S=64 action rows).
        # Previously unmasked -- a real accuracy bug (not a NaN source), fixed here.
        bias = self._build_ae_suffix_bias(P, Tkv, S)
        self.AE_BIAS_DRAM = self.get_params_dram_addr()
        self.dma_write(DMA_DEVICE_H2C, self.AE_BIAS_DRAM, bias.contiguous(), Tkv * Tkv * bpe)
        self.allocate_params_dram(Tkv * Tkv * bpe)

        # --- Rectangular (batched) attention via unified_attention_core -----------
        # MQA: all AE_HEADS query heads share one K/V head, so stack every head's S
        # suffix queries into a single batch = AE_HEADS*S and run ONE rectangular
        # attention (batch queries x Tkv keys) instead of AE_HEADS square Tkv x Tkv
        # flash calls (which wasted ~93% on padding query rows + per-head DMA).
        # bias is (batch, Tkv): every query row uses the same key-column mask
        # (bidirectional; only key columns are masked), so replicate bias row 0.
        self.AE_UATTN_BATCH = self.AE_HEADS * S
        _keymask = bias[0].clone()                                 # (Tkv,) column mask
        _ubias = _keymask.unsqueeze(0).repeat(self.AE_UATTN_BATCH, 1).contiguous()  # (batch, Tkv)
        self.AE_UATTN_BIAS_DRAM = self.get_params_dram_addr()
        self.dma_write(DMA_DEVICE_H2C, self.AE_UATTN_BIAS_DRAM, _ubias, self.AE_UATTN_BATCH * Tkv * bpe)
        self.allocate_params_dram(self.AE_UATTN_BATCH * Tkv * bpe)
        # scratch: V^T (D*Tkv) + score (Tkv*Tkv) + scaled_q (batch*D) -- see
        # unified_attention_core_dynamic's layout contract.
        _uscratch = D * Tkv + Tkv * Tkv + self.AE_UATTN_BATCH * D
        self.AE_UATTN_SCRATCH_DRAM = self.allocate_tensor_dram(_uscratch * bpe)

        # x / norm / adarms scratch (S, H)
        self.AE_X_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.AE_NORM_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.AE_ATTN_GATED_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.AE_ADARMS_MUL_SCRATCH_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.AE_RESIDUAL_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.AE_MLP_GATE_DRAM = self.allocate_tensor_dram(S * I * bpe)
        self.AE_MLP_UP_DRAM = self.allocate_tensor_dram(S * I * bpe)
        self.AE_MLP_MULT_DRAM = self.allocate_tensor_dram(S * I * bpe)
        self.AE_MLP_DOWN_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.AE_MLP_GATED_DRAM = self.allocate_tensor_dram(S * H * bpe)

        # adarms conditioning scratch: modulation (1, 3*H), and its 3 broadcast-to-S copies
        self.AE_COND_DRAM = self.allocate_tensor_dram(1 * H * bpe)               # timestep embedding, (1,H)
        self.AE_MODULATION_DRAM = self.allocate_tensor_dram(1 * 3 * H * bpe)     # (1, 3H) = [scale,shift,gate]
        self.AE_SCALE_BCAST_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.AE_SHIFT_BCAST_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.AE_GATE_BCAST_DRAM = self.allocate_tensor_dram(S * H * bpe)

        # timestep embedding scratch (sincos -> time_mlp_in -> silu -> time_mlp_out -> silu)
        self.AE_SINCOS_DRAM = self.allocate_tensor_dram(1 * H * bpe)
        self.AE_TIME_HIDDEN_DRAM = self.allocate_tensor_dram(1 * H * bpe)

        # ON-DEVICE time-MLP working set. The whole (N_steps, H) conditioning table
        # is produced in ONE batched pass (M = AE_NUM_DENOISE_STEPS) rather than 10
        # separate M=1 ops: same kernels, 1/10th the instruction count, and the
        # composed-SiLU staging (a single SRAM load of N*H elements) only has to
        # happen twice instead of twenty times. See _ae_compile_cond_table.
        _NST = self.AE_NUM_DENOISE_STEPS
        self.AE_TIME_HID_TABLE_DRAM  = self.allocate_tensor_dram(_NST * H * bpe)  # time_mlp_in out (pre-silu)
        self.AE_TIME_HID_SILU_DRAM   = self.allocate_tensor_dram(_NST * H * bpe)  # silu(time_mlp_in)
        self.AE_COND_TABLE_RAW_DRAM  = self.allocate_tensor_dram(_NST * H * bpe)  # time_mlp_out out (pre-silu)
        self.AE_COND_TABLE_DRAM      = self.allocate_tensor_dram(_NST * H * bpe)  # silu(...) = cond table

        # all-ones gamma constant: rms_norm_core multiplies by gamma directly (no
        # implicit +1, unlike gemma3's pre-offset convention), so AdaRMSNorm's
        # plain (no learned scale) RMSNorm needs gamma=1 rather than gamma=None
        # (rms_norm_core_dram_legacy dereferences GAMMA_DRAM_ADDR unconditionally).
        self.AE_ONES_DRAM = self.get_params_dram_addr()
        self.dma_write(DMA_DEVICE_H2C, self.AE_ONES_DRAM, torch.ones(H, dtype=torch.bfloat16).contiguous(), H * bpe)
        self.allocate_params_dram(H * bpe)

        # action tokens (x_t projected through action_in_proj) and the denoise state.
        # x_t/v_t are physically AE_XT_WIDTH(64)-wide (real action_dim 32 in cols
        # [0:32], cols [32:64] held at 0). Storing x_t already 64-wide lets
        # action_in_proj read it CONTIGUOUSLY (K=64) with no 32->64 strided
        # staging -- that staging was reading noise rows at 2x stride (bug).
        XW = self.AE_XT_WIDTH
        self.AE_ACTION_TOK_DRAM = self.allocate_tensor_dram(S * H * bpe)
        self.AE_XT_DRAM = self.allocate_tensor_dram(S * XW * bpe)
        self.AE_VT_DRAM = self.allocate_tensor_dram(S * XW * bpe)
        # Per-step x_t snapshots (probe_nan_report): AE_XT_DRAM is overwritten in
        # place every step, so only the LAST step's value survives a full run --
        # copy each step's post-euler-update x_t to its own dedicated slot too,
        # so one post-run readback can NaN-check every step at once.
        self.AE_STEP_SNAPSHOT_DRAM = [self.allocate_tensor_dram(S * XW * bpe)
                                       for _ in range(self.AE_NUM_DENOISE_STEPS)]

        # Prefix KV cache placeholder, only used if the prefix agent hasn't wired
        # self.prefix_k/v_cache_addr yet (see ASSUMED PREFIX KV-CACHE INTERFACE).
        if not hasattr(self, "prefix_k_cache_addr"):
            print("[ae] WARNING: self.prefix_k_cache_addr not found -- allocating a "
                  "zero placeholder. Point this at the real prefix KV cache before "
                  "trusting suffix-attention numerics.")
            zero_row = torch.zeros(P, D, dtype=torch.bfloat16)
            self.prefix_k_cache_addr = []
            self.prefix_v_cache_addr = []
            for _ in range(self.AE_LAYERS):
                kaddr = self.get_params_dram_addr()
                self.dma_write(DMA_DEVICE_H2C, kaddr, zero_row.contiguous(), P * D * bpe)
                self.allocate_params_dram(P * D * bpe)
                vaddr = self.get_params_dram_addr()
                self.dma_write(DMA_DEVICE_H2C, vaddr, zero_row.contiguous(), P * D * bpe)
                self.allocate_params_dram(P * D * bpe)
                self.prefix_k_cache_addr.append(kaddr)
                self.prefix_v_cache_addr.append(vaddr)

        # NOTE: the combined K/V buffers' prefix rows [0:P] are seeded by
        # compile_denoise_loop() itself (as the first thing it captures), NOT
        # here -- this method only allocates DRAM and runs before any capture
        # session is open (or after the prefix one was already closed+cleared
        # by _compile_and_run), so instructions emitted here would just get
        # silently discarded the moment compile_denoise_loop's start_capture()
        # resets capture_buffer=[]. That was a real bug: ae_k_combined/
        # ae_v_combined's prefix rows never actually got written on hardware,
        # leaving stale/garbage DRAM content that fed straight into the first
        # suffix layer's attention and NaN'd immediately.
        # Step-0 probe snapshot buffers (allocated LAST so they can't shift the
        # addresses of any critical AE buffer -- address layout is load-bearing
        # here, see the DRAM-layout NaN bug). Each holds one step-0 intermediate
        # so a post-run readback can diff it against the torch reference and
        # localize which action-expert op first diverges.
        if self.DENOISE_STEP0_PROBE:
            self.AE_P0_ACTION_IN = self.allocate_tensor_dram(S * H * bpe)   # action_in_proj out (S,H)
            self.AE_P0_TIME_EMB  = self.allocate_tensor_dram(1 * H * bpe)   # time embed (1,H)
            self.AE_P0_SUF_L0    = self.allocate_tensor_dram(S * H * bpe)   # suffix layer0 out (S,H)
            self.AE_P0_SUF_L17   = self.allocate_tensor_dram(S * H * bpe)   # suffix layer17 out (S,H)
            self.AE_P0_VT        = self.allocate_tensor_dram(S * self.AE_XT_WIDTH * bpe)  # v_t (S,64)
            self.AE_P0_XT_PAD    = self.allocate_tensor_dram(S * self.AE_XT_WIDTH * bpe)  # x_t (S,64) fed to action_in_proj
            self.AE_P0_L0_NORM   = self.allocate_tensor_dram(S * H * bpe)   # layer0 pre-attn AdaRMSNorm out
            self.AE_P0_L0_ATTN   = self.allocate_tensor_dram(S * H * bpe)   # layer0 attention o-proj out
            self.AE_P0_L0_RESID  = self.allocate_tensor_dram(S * H * bpe)   # layer0 post-attn residual
            self.AE_P0_L0_Q      = self.allocate_tensor_dram(2 * S * D * bpe)  # layer0 stacked Q, heads 0-1
            self.AE_P0_L0_ATTNRAW = self.allocate_tensor_dram(self.AE_HEADS * S * D * bpe) # layer0 raw attn out, ALL heads
            self.AE_P0_L0_QROPE  = self.allocate_tensor_dram(2 * S * D * bpe)  # layer0 ROPED Q, heads 0-1
            self.AE_P0_L0_KSUF   = self.allocate_tensor_dram(S * D * bpe)      # layer0 ROPED suffix K rows
        print(f"tensor_init_action_expert done; tensor DRAM at 0x{self.get_tensor_dram_addr():X}")
        self.dram_region_map("after tensor_init_action_expert")

    # ---- small helpers --------------------------------------------------
    def _ae_broadcast_row(self, src_dram, dst_dram, rows, width):
        """Copy a single (1, width) bf16 row from src_dram to `rows` contiguous
        rows at dst_dram (broadcast across the row/batch dim -- used for AdaRMSNorm
        scale/shift/gate and the sincos/timestep conditioning vector)."""
        bpe = 2
        self.accelerator_memory_to_sram(src_dram, 0x00000, width)
        for r in range(rows):
            self.sram_to_accelerator_memory(0x00000, dst_dram + r * width * bpe, width)

    def _ae_matmul(self, M, K, N, A, scale_addr, data_addr, OUT, bias_addr=None, gpr_M_reg=None,
                   ue=None, **kw):
        """IF4 (q4_64) quantized matmul, per the quantization policy in
        weight_init_action_expert. Pass gpr_M_reg (primed with M via ADD_SET by
        the caller) to compile a compact PBI runtime loop instead of static-M
        unrolling -- required here because this body is itself repeated 180x
        (10 Euler steps x 18 layers); static-M was blowing the compiled program
        up to the point compilation didn't finish in 900s (see compile_prefix's
        identical fix for the root-cause writeup).

        ``ue`` selects the EMITTING engine (head-sharded denoise attention block).
        Defaults to the primary, so every existing call site is unchanged -- but a
        sharded region MUST pass ctx.unsafe_ue or the op lands on the primary while
        the workers idle, which looks like "sharding did nothing" rather than an
        error."""
        (ue or self).matmat_mul_core(
            M=M, K=K, N=N, A_DRAM_ADDR=A, B_DRAM_ADDR=data_addr,
            OUTPUT_DRAM_ADDR=OUT, is_B_quantized=True, data_type=TYPE.IF4,
            SCALE_DRAM_ADDR=scale_addr, C_DRAM_ADDR=bias_addr, gpr_M_reg=gpr_M_reg, **kw)

    def _ae_ada_rms_norm(self, M, x_dram, dense_scale, dense_data, dense_bias,
                          norm_out_dram, gate_bcast_dram, apply_gate=True, gpr_M_reg=None):
        """AdaRMSNorm: plain RMSNorm (no gamma) on x, then a conditioning Dense
        (cond(1,1024) -> (1,3*1024)) split into scale/shift/gate, broadcast over
        the M suffix rows, applied as normed*(1+scale)+shift. Writes the gate
        broadcast to gate_bcast_dram for the caller to apply after attn/mlp.
        gpr_M_reg (primed with M) makes the RMSNorm's row loop a runtime PBI
        loop -- see _ae_matmul's docstring for why this matters here."""
        H = self.AE_HIDDEN
        bpe = 2
        # 1. RMSNorm (no gamma)
        # sqrt(N)/N runtime scalars primed in compile_denoise_loop (post-sync norm ABI).
        self.rms_norm_core_dram(M=M, N=H, A_DRAM_ADDR=x_dram, OUTPUT_DRAM_ADDR=self.AE_NORM_DRAM,
                                 GAMMA_DRAM_ADDR=self.AE_ONES_DRAM, gpr_M_reg=gpr_M_reg,
                                 gpr_N_reg=self._ae_rms_N_reg, gpr_sqrt_n_reg=self._ae_rms_sqrt_reg)
        # 2. conditioning matmul: cond (1,H) @ dense (H,3H) -> modulation (1,3H), +bias
        # M=1 always -- one conditioning vector regardless of the caller's M. That is
        # NOT the same as "already minimal": M=1 only collapses the M loop, while the
        # legacy core still unrolls the N axis into ceil(3H / N_chunk) = 16 tiles
        # (N_chunk = (URAM_NEAR_FULL_ELEMENTS // K) // 64 * 64 = 192 at K=H). Passing
        # a GPR-primed M routes to the DYNAMIC (PBI) core, which walks N from a
        # pointer row instead. See _ae_cond_M_reg in compile_denoise_loop.
        # Falls back to the legacy path when the reg is absent, so the standalone
        # callers (_ae_sincos_time_embed, the torch-ref harness) still work.
        self._ae_matmul(1, H, 3 * H, self.AE_COND_DRAM, dense_scale, dense_data,
                         self.AE_MODULATION_DRAM, bias_addr=dense_bias,
                         gpr_M_reg=getattr(self, "_ae_cond_M_reg", None))
        # 3. split scale/shift/gate (each H wide) and broadcast each to M rows
        scale_addr = self.AE_MODULATION_DRAM
        shift_addr = self.AE_MODULATION_DRAM + H * bpe
        gate_addr = self.AE_MODULATION_DRAM + 2 * H * bpe
        self._ae_broadcast_row(scale_addr, self.AE_SCALE_BCAST_DRAM, M, H)
        self._ae_broadcast_row(shift_addr, self.AE_SHIFT_BCAST_DRAM, M, H)
        if apply_gate:
            self._ae_broadcast_row(gate_addr, gate_bcast_dram, M, H)
        # 4. (1 + scale) -- add 1.0 to the broadcast scale buffer in place
        self.accelerator_memory_to_sram(self.AE_SCALE_BCAST_DRAM, 0x00000, M * H)
        self.broadcast_add(scalar=1.0, sram_start_addr=0x00000, sram_wb_addr=0x00000, element_size=M * H)
        self.sram_to_accelerator_memory(0x00000, self.AE_SCALE_BCAST_DRAM, M * H)
        # 5. out = normed * (1+scale) + shift; route through dedicated scratch buffer
        # to avoid the hardware read/write hazard from aliasing an input with the
        # output in one DMA-backed elementwise op (same class as the confirmed hang
        # trigger fixed in compile_prefix -- see that function's comment).
        eltwise_mul_core_dram(self, size=M * H, A_DRAM_ADDR=self.AE_NORM_DRAM,
                               B_DRAM_ADDR=self.AE_SCALE_BCAST_DRAM, OUTPUT_DRAM_ADDR=self.AE_ADARMS_MUL_SCRATCH_DRAM)
        eltwise_add_core_dram(self, size=M * H, A_DRAM_ADDR=self.AE_ADARMS_MUL_SCRATCH_DRAM,
                               B_DRAM_ADDR=self.AE_SHIFT_BCAST_DRAM, OUTPUT_DRAM_ADDR=norm_out_dram)

    def _ae_gated_mlp(self, M, x_dram, la, out_dram, gpr_M_reg=None):
        """Gated MLP: gate=x@gate_w (gelu), up=x@up_w, out=(gate*up)@linear. Uses
        matmat_mul_core's gelu_enable fused activation on the gate branch, per the
        torch reference `F.gelu(x @ gate_w, approximate="none")`."""
        H, I = self.AE_HIDDEN, self.AE_INTERMEDIATE
        self._ae_matmul(M, H, I, x_dram, la["mlp_gate_scale"], la["mlp_gate_data"],
                         self.AE_MLP_GATE_DRAM, gelu_enable=True, gpr_M_reg=gpr_M_reg)
        self._ae_matmul(M, H, I, x_dram, la["mlp_up_scale"], la["mlp_up_data"], self.AE_MLP_UP_DRAM, gpr_M_reg=gpr_M_reg)
        eltwise_mul_core_dram(self, size=M * I, A_DRAM_ADDR=self.AE_MLP_GATE_DRAM,
                               B_DRAM_ADDR=self.AE_MLP_UP_DRAM, OUTPUT_DRAM_ADDR=self.AE_MLP_MULT_DRAM)
        self._ae_matmul(M, I, H, self.AE_MLP_MULT_DRAM, la["mlp_down_scale"], la["mlp_down_data"], out_dram, gpr_M_reg=gpr_M_reg)

    # ---- N-sharded gated MLP (the denoise stage's whole multi-engine win) -----
    #
    # Per action-expert layer the matmul work at M=64 is roughly:
    #     k/v proj    2 x 64x1024x256   =  34 MMAC   ( 3%)
    #     q proj      8 x 64x1024x256   = 134 MMAC   (13%)
    #     o proj      8 x 64x256x1024   = 134 MMAC   (13%)
    #     mlp gate/up 2 x 64x1024x4096  = 537 MMAC   (51%)
    #     mlp down    1 x 64x4096x1024  = 268 MMAC   (26%)
    # so the gated MLP alone is ~77% of it, in exactly three ops, with no strided
    # marshalling anywhere -- which is why it is the whole of v1. gate and up are
    # N-split (1024 -> 4096 becomes 1024 -> 2048 per engine), the GELU-multiply is
    # per-element and never leaves its lane, and `down` consumes the lane it is
    # already sitting in as a K-shard. Two rendezvous per layer.
    def _ae_attn_shardable(self, sched):
        """True iff the head-parallel attention block can run on this engine count.

        The block partitions AE_HEADS=8 whole heads, so it needs ne | 8 (1/2/4/8).
        Other counts (3, 5, 6, 7) keep the SERIAL attention path and shard only the
        gated MLP -- degrade rather than assert, so --engines 6 still works exactly
        as it did before this block existed.
        """
        return (sched is not None and sched.num_engines > 1
                and self.AE_HEADS % sched.num_engines == 0)

    def _ae_head_split(self, ne):
        """Per-engine [first_head, head_count] over AE_HEADS. Requires ne | AE_HEADS.

        The attention block is parallel over HEADS, not rows or columns of one
        matmul: q/o weights are already stored per head (la["q_data"][h]), every
        head's attention is independent (MQA -- they share one K/V), and there are
        exactly AE_HEADS=8 of them, which is the device engine count. So the natural
        unit here is the head, and the split must land on head boundaries.
        """
        NH = self.AE_HEADS
        assert NH % ne == 0, (
            f"denoise attention is HEAD-parallel: engines={ne} must divide "
            f"AE_HEADS={NH} (use 1, 2, 4 or 8) so each engine owns whole heads")
        per = NH // ne
        return [(e * per, per) for e in range(ne)]

    # ATTENTION IS HEAD-PARALLEL TOO, alongside the q/o projections.
    #
    # This REVERSES an earlier decision, and the reversal is the interesting part.
    # The original argument for keeping attention serial was:
    #
    #   "The core's FIRST step is bf16_transpose_core(M=aligned_seq_len,
    #    N=head_dim) on V -- sized by Tkv, NOT by batch. Splitting the batch
    #    across engines leaves every engine transposing the WHOLE V redundantly.
    #    At Tkv=896/D=256 that transpose is ~117 MFLOP against ~59 MFLOP of
    #    per-engine score+context work at batch=64: two thirds of each engine's
    #    attention becomes duplicated overhead, and the stage gets SLOWER."
    #
    # The 117-vs-59 arithmetic is correct. The conclusion does not follow, because
    # the eight V^T builds happen CONCURRENTLY, one per engine -- the duplicated
    # work costs wall-clock ONCE, not eight times:
    #
    #     per engine (8-way):  V^T 117 + real  59 = 176 MFLOP
    #     unsharded 1 call:    V^T 117 + real 470 = 587 MFLOP   -> 3.3x
    #
    # A high duplicated-overhead FRACTION per engine is not the same thing as
    # being slower than serial. It caps the speedup at 3.3x instead of 8x; it does
    # not invert the sign. And attention is 17.5% of this stage's FLOPs (M=64 is
    # one row block, so the projections are small while Tkv=896 keeps attention
    # full-size) -- the largest attention share of the three stages, and ~6x the
    # prefix's 3.0%.
    #
    # The second objection -- "attention marshalling is the strided-copy class
    # that needs per-index destination row offsets" -- simply does not apply here.
    # There IS no marshalling: step 3 already writes head h's queries as a
    # contiguous (S, D) block at h*S*D, and the core emits head h's output the
    # same way (see step 5's comment). So consecutive heads are CONTIGUOUS ROW
    # RANGES of one batch, and an engine owning heads [h0, h0+nh) covers them in
    # ONE call at batch=nh*S -- pure address arithmetic, exactly like the prefix
    # head shard. That is the vision encoder's problem, not this one.
    #
    # Coverage is now ~97% of the stage instead of ~80%.

    def _ae_q_proj_sharded(self, sched, M, la, gpr_M_regs):
        """HEAD-PARALLEL q projection + RoPE. Joins: the primary's attention reads
        every head's Q.

        q proj IS a column shard of the combined (H -> NH*D) projection, and each
        256-column block is exactly one head -- an N-split whose blocks happen to be
        head-aligned. The per-head weight blobs already exist
        (weight_init_action_expert slices them), so unlike the mlp-down K-split
        there is NOTHING to pre-slice on the host.

        AE_Q_DRAM / AE_Q_ROPE_DRAM are indexed by head (h*M*D*bpe), so engines write
        DISJOINT slices of the shared buffers -- no per-engine copies needed.
        """
        H, D, NH = self.AE_HIDDEN, self.HEAD_DIM, self.AE_HEADS
        bpe = 2
        heads = self._ae_head_split(sched.num_engines)

        def _body(ctx):
            i = ctx.engine_idx
            h0, nh = heads[i]
            assert (ctx.col_offset, ctx.cols) == (h0 * D, nh * D), (
                f"head shard mismatch on engine {i}: scheduler gives "
                f"{(ctx.col_offset, ctx.cols)}, heads {h0}..{h0 + nh - 1} need "
                f"{(h0 * D, nh * D)}")
            raw, mreg = ctx.unsafe_ue, gpr_M_regs[i]
            for h in range(h0, h0 + nh):
                self._ae_matmul(M, H, D, self.AE_NORM_DRAM, la["q_scale"][h], la["q_data"][h],
                                 self.AE_Q_DRAM + h * M * D * bpe, gpr_M_reg=mreg, ue=raw)
            # ONE matmul RoPE for this engine's whole head range instead of nh
            # per-head calls: heads are contiguous (M, D) blocks at h*M*D, so
            # heads [h0, h0+nh) are the row range [h0*M, (h0+nh)*M) of one
            # (NH*M, D) batch -- the same address arithmetic the attention shard
            # below uses. The tiled cos/sin tables are head-major over exactly
            # this layout, so engine i just offsets them by h0*M rows too, and
            # every engine writes a disjoint slice of the shared ROT scratch.
            row0 = h0 * M
            self._rope_matmul(M=nh * M,
                              src_dram=self.AE_Q_DRAM + row0 * D * bpe,
                              out_dram=self.AE_Q_ROPE_DRAM + row0 * D * bpe,
                              cos_tiled=self.AE_ROPE_COS_TILED + row0 * D * bpe,
                              sin_tiled=self.AE_ROPE_SIN_TILED + row0 * D * bpe,
                              rot_dram=self.AE_ROPE_ROT_DRAM + row0 * D * bpe,
                              gpr_M_reg=self._ae_rope_M_regs[i], ue=raw)

        # join=True, and it is load-bearing: the very next op is the primary's
        # attention over the FULL NH*M batch, which reads rows every worker wrote.
        sched.col_sharded_region(NH * D, _body, join=True)

    def _ae_attention_sharded(self, sched, S, Tkv, k_combined, v_combined):
        """HEAD-PARALLEL rectangular attention -- the middle of the q/attn/o block.

        The serial path issues ONE call at batch=AE_HEADS*S over the whole Q blob.
        This issues one call PER ENGINE at batch=nh*S, because head h's S queries
        live at h*S*D and head h's output comes back the same way, so the nh heads
        an engine owns are one CONTIGUOUS row range [h0*S, (h0+nh)*S) of that same
        batch. Engine i therefore shifts three addresses by h0*S rows and shrinks
        batch -- no marshalling, no strided writeback, no gather.

        THE FOUR PER-HEAD OFFSETS (row0 = h0 * S):
            Q       AE_Q_ROPE_DRAM  + row0 * D * bpe
            OUT     AE_ATTN_OUT_DRAM+ row0 * D * bpe
            BIAS    AE_UATTN_BIAS   + row0 * Tkv * bpe     # (batch, Tkv), row-indexed
            SCRATCH per-engine buffer, NOT an offset (see below)

        The bias offset is the one that looks droppable and is not. Today every row
        of AE_UATTN_BIAS_DRAM is the same key mask (`keymask.repeat(batch, 1)`), so
        passing the unshifted base would happen to work -- and would silently break
        the day the mask becomes per-query (causal suffix, per-head bias). Offset it
        properly and the shard stays correct by construction rather than by luck.

        SCRATCH MUST BE PER ENGINE. The core writes V^T, the score/P plane and
        scaled Q into it; one shared buffer would have eight engines interleaving
        writes into the same score plane. That is the finite-but-scrambled failure,
        not a hang -- it would show up as a quietly wrong action, which is exactly
        the class of bug worth spending 8 x ~2 MB of DRAM to make impossible.

        K/V are read-only and shared: MQA (AE_KV_HEADS == 1) means every head reads
        the same k_combined/v_combined, so there is nothing to slice and no
        cross-engine write hazard on them.
        """
        D = self.HEAD_DIM
        bpe = 2
        ne = sched.num_engines
        heads = self._ae_head_split(ne)

        def _body(ctx):
            i = ctx.engine_idx
            h0, nh = heads[i]
            assert (ctx.col_offset, ctx.cols) == (h0 * D, nh * D), (
                f"head shard mismatch on engine {i}: scheduler gives "
                f"{(ctx.col_offset, ctx.cols)}, heads {h0}..{h0 + nh - 1} need "
                f"{(h0 * D, nh * D)}")
            row0 = h0 * S
            ctx.unsafe_ue.unified_attention_core_dynamic(
                batch=nh * S, aligned_seq_len=Tkv, head_dim=D,
                Q_DRAM_ADDR=self.AE_Q_ROPE_DRAM + row0 * D * bpe,
                K_DRAM_ADDR=k_combined,          # MQA: shared, read-only
                V_DRAM_ADDR=v_combined,
                BIAS_DRAM_ADDR=self.AE_UATTN_BIAS_DRAM + row0 * Tkv * bpe,
                OUTPUT_DRAM_ADDR=self.AE_ATTN_OUT_DRAM + row0 * D * bpe,
                SCRATCH_DRAM_ADDR=self.AE_UATTN_SCRATCH_SHARDED[i],
                IDENTITY_DRAM_ADDR=self.identity_addr)

        # join=True: _ae_o_proj_sharded's own opening rendezvous already fences
        # AE_ATTN_OUT_DRAM, but the o-proj is only ONE of this buffer's readers --
        # the DENOISE_STEP0_PROBE dump and the serial fallback read it too. Paying
        # one rendezvous here keeps the buffer's contract "complete after this
        # call" rather than "complete once the next region happens to fence it".
        sched.col_sharded_region(self.AE_HEADS * D, _body, join=True)

    def _ae_o_proj_sharded(self, sched, M, la, gpr_M_regs, partial_name):
        """HEAD-PARALLEL o projection + cross-engine reduction.

        o proj is the reduction: head h contributes a FULL [M, H] term, summed over
        heads. Serially that is the C_DRAM_ADDR accumulate chain; sharded, each
        engine accumulates ITS heads into a private partial and reduce_add combines
        them. Identical arithmetic, different association order (bf16 addition is
        not associative, so expect small numeric deltas vs --engines 1, not
        bit-identity).

        The region's OPENING rendezvous is the RAW fence for AE_ATTN_OUT_DRAM, which
        the primary just wrote in full and every engine now reads its heads from.
        """
        H, D, NH = self.AE_HIDDEN, self.HEAD_DIM, self.AE_HEADS
        bpe = 2
        ne = sched.num_engines
        heads = self._ae_head_split(ne)

        def _body(ctx):
            i = ctx.engine_idx
            h0, nh = heads[i]
            assert (ctx.col_offset, ctx.cols) == (h0 * D, nh * D), (
                f"head shard mismatch on engine {i}: scheduler gives "
                f"{(ctx.col_offset, ctx.cols)}, heads {h0}..{h0 + nh - 1} need "
                f"{(h0 * D, nh * D)}")
            raw, mreg = ctx.unsafe_ue, gpr_M_regs[i]
            part = sched.per_engine_addr(partial_name, i)
            # Same C_DRAM_ADDR chain as the serial path, over a subset of heads.
            # First head WRITES (no bias), the rest accumulate with bias_mode
            # full_matrix -- the (M,H) running sum is a MATRIX, not a broadcast row
            # vector, and the default broadcast_N would add only row 0 to every row.
            for j, h in enumerate(range(h0, h0 + nh)):
                head_slice = self.AE_ATTN_OUT_DRAM + h * M * D * bpe
                self._ae_matmul(M, D, H, head_slice, la["o_scale"][h], la["o_data"][h],
                                 part, bias_addr=(part if j > 0 else None),
                                 gpr_M_reg=mreg, ue=raw,
                                 **({"bias_mode": "full_matrix"} if j > 0 else {}))

        # join=False: reduce_add opens with its own rendezvous and the partials are
        # meaningless until it runs, so joining here would just add a barrier.
        sched.col_sharded_region(NH * D, _body, join=False)
        sched.reduce_add([sched.per_engine_addr(partial_name, i) for i in range(ne)],
                         self.AE_O_PROJ_DRAM, M, H, join=False)

    def _ae_gated_mlp_sharded(self, sched, M, x_dram, la, out_dram, gpr_M_regs, partial_name):
        H, I = self.AE_HIDDEN, self.AE_INTERMEDIATE
        ne = sched.num_engines
        k_split = self._col_split(I, ne)

        def _body(ctx):
            i = ctx.engine_idx
            # The host cut the down-projection blobs at weight-init time using
            # _col_split; if the scheduler ever partitions differently the result is
            # finite garbage, not a crash. Assert they agree.
            assert (ctx.col_offset, ctx.cols) == k_split[i], (
                f"mlp shard mismatch on engine {i}: scheduler gives "
                f"{(ctx.col_offset, ctx.cols)}, weight blobs were cut for {k_split[i]}")
            raw = ctx.unsafe_ue
            mreg = gpr_M_regs[i]
            Nc = ctx.cols
            # gate (fused gelu) and up: N-split. A (the normed x) is read in FULL by
            # every engine -- it is the same M x K activation; only B/scale move.
            raw.matmat_mul_core(
                M=M, K=H, N=Nc, A_DRAM_ADDR=x_dram,
                B_DRAM_ADDR=ctx.b_addr(la["mlp_gate_data"], H, TYPE.IF4),
                SCALE_DRAM_ADDR=ctx.scale_addr(la["mlp_gate_scale"], H),
                OUTPUT_DRAM_ADDR=ctx.col_out("ae_mlp_gate"),
                is_B_quantized=True, data_type=TYPE.IF4, gelu_enable=True, gpr_M_reg=mreg)
            raw.matmat_mul_core(
                M=M, K=H, N=Nc, A_DRAM_ADDR=x_dram,
                B_DRAM_ADDR=ctx.b_addr(la["mlp_up_data"], H, TYPE.IF4),
                SCALE_DRAM_ADDR=ctx.scale_addr(la["mlp_up_scale"], H),
                OUTPUT_DRAM_ADDR=ctx.col_out("ae_mlp_up"),
                is_B_quantized=True, data_type=TYPE.IF4, gpr_M_reg=mreg)
            # gelu(gate) * up -- purely per-element, so a column shard of the inputs
            # is a column shard of the output and no engine needs a peer's columns.
            # unsafe_ue because nn_lib's wrapper drives the SRAM staging directly
            # (accelerator_memory_to_sram/eltwise_mul_core) rather than the single
            # allowlisted eltwise_core_dram entry point; the op itself is exactly the
            # row/column-independent kind the allowlist exists to admit.
            eltwise_mul_core_dram(raw, size=ctx.elems(M),
                                   A_DRAM_ADDR=ctx.col_out("ae_mlp_gate"),
                                   B_DRAM_ADDR=ctx.col_out("ae_mlp_up"),
                                   OUTPUT_DRAM_ADDR=ctx.col_out("ae_mlp_mult"))
            # down: K-SHARD, not a column shard. This engine's [M, Nc] lane IS the
            # contiguous K-slice [col_offset, col_offset+Nc) of the (M, I)
            # intermediate, so no gather is needed -- only the pre-sliced weight.
            # Result is a FULL [M, H] PARTIAL SUM; reduce_add below combines them.
            b_scale, b_data = la["mlp_down_k"][i]
            raw.matmat_mul_core(
                M=M, K=Nc, N=H, A_DRAM_ADDR=ctx.col_out("ae_mlp_mult"),
                B_DRAM_ADDR=b_data, SCALE_DRAM_ADDR=b_scale,
                OUTPUT_DRAM_ADDR=sched.per_engine_addr(partial_name, i),
                is_B_quantized=True, data_type=TYPE.IF4, gpr_M_reg=mreg)

        # join=False: reduce_add opens with its own rendezvous, and the partials are
        # meaningless until it runs, so a join here would just be a second barrier.
        sched.col_sharded_region(I, _body, join=False)
        # join=False again: the ONLY thing a worker can do after this is block on the
        # NEXT region's opening rendezvous, so the exit barrier is redundant. That
        # halves the barrier count over 180 layer executions (360 instead of 540).
        sched.reduce_add([sched.per_engine_addr(partial_name, i) for i in range(ne)],
                         out_dram, M, H, join=False)

    def _ae_sincos_time_embed(self, t_scalar):
        """Host-computed sincos timestep embedding (dim=AE_HIDDEN, matches
        sincos_pos_embed in pi05_torch_ref.py) DMA'd to AE_SINCOS_DRAM, then
        time_mlp_in -> silu -> time_mlp_out -> silu -> AE_COND_DRAM (the AdaRMSNorm
        conditioning vector for this Euler step).

        Only used by the legacy fully-unrolled path (kept for reference/tests).
        compile_denoise_loop itself uses the table + runtime-address variant
        below (_ae_build_sincos_table / _ae_time_embed_from_table) so the whole
        10-step Euler loop can be a single compiled body run via a real
        hardware loop_start/loop_end instead of 10 statically unrolled copies."""
        H = self.AE_HIDDEN
        min_period, max_period = 4e-3, 4.0
        frac = torch.linspace(0.0, 1.0, H // 2)
        period = min_period * (max_period / min_period) ** frac
        sinusoid = t_scalar * (1.0 / period) * 2 * math.pi
        emb = torch.cat([torch.sin(sinusoid), torch.cos(sinusoid)]).to(torch.bfloat16)
        self.dma_write(DMA_DEVICE_H2C, self.AE_SINCOS_DRAM, emb.contiguous(), H * 2)

        self._ae_matmul(1, H, H, self.AE_SINCOS_DRAM, self.ae_time_in_scale, self.ae_time_in_data,
                         self.AE_TIME_HIDDEN_DRAM, bias_addr=self.ae_time_in_bias, silu_enable=True)
        self._ae_matmul(1, H, H, self.AE_TIME_HIDDEN_DRAM, self.ae_time_out_scale, self.ae_time_out_data,
                         self.AE_COND_DRAM, bias_addr=self.ae_time_out_bias, silu_enable=True)

    def _ae_build_sincos_table(self):
        """Host-precompute all AE_NUM_DENOISE_STEPS sincos timestep embeddings
        (t = 1.0, 0.9, ..., 0.1 -- matches the Euler loop's t=1.0, dt=-1/N
        schedule) as one contiguous (N, AE_HIDDEN) bf16 table in DRAM. Lets the
        runtime loop body read the correct row via a GPR-held address instead
        of a fresh host DMA write per step (which would require re-running
        Python between hardware loop iterations -- impossible)."""
        H = self.AE_HIDDEN
        N = self.AE_NUM_DENOISE_STEPS
        min_period, max_period = 4e-3, 4.0
        frac = torch.linspace(0.0, 1.0, H // 2)
        period = min_period * (max_period / min_period) ** frac
        dt = -1.0 / N
        rows = []
        t = 1.0
        for _ in range(N):
            sinusoid = t * (1.0 / period) * 2 * math.pi
            rows.append(torch.cat([torch.sin(sinusoid), torch.cos(sinusoid)]))
            t += dt
        table = torch.stack(rows).to(torch.bfloat16).contiguous()  # (N, H)
        addr = self.get_params_dram_addr()
        self.dma_write(DMA_DEVICE_H2C, addr, table, N * H * 2)
        self.allocate_params_dram(N * H * 2)
        return addr

    def _ae_compile_cond_table(self):
        """ON-DEVICE AdaRMSNorm conditioning table.

        Emits, into the denoise program, the FULL time-embedding MLP for all
        AE_NUM_DENOISE_STEPS Euler steps at once:

            sincos table (N,H)   [host constant, see below]
              -> time_mlp_in  (H,H) IF4 + bias      ON DEVICE  (matmat_mul_core)
              -> SiLU                                ON DEVICE  (composed)
              -> time_mlp_out (H,H) IF4 + bias      ON DEVICE  (matmat_mul_core)
              -> SiLU                                ON DEVICE  (composed)
              -> AE_COND_TABLE_DRAM (N,H)

        WHY THE SINCOS TABLE STAYS ON THE HOST: sincos_pos_embed is sin/cos over
        512 geometrically-spaced periods -- transcendental. The LALU exposes
        exp/sigmoid/silu/gelu/tanh, but no sine or cosine primitive anywhere in
        the ISA, so there is nothing to lower it onto. It is also purely a
        function of the fixed Euler schedule (t = 1.0, 0.9, ... 0.1) with no
        dependence on any input, i.e. a CONSTANT. It is therefore handled exactly
        the way this repo already handles the RoPE cos/sin tables (_rope_init,
        PREFIX_ROPE_ADDR / AE_ROPE_ADDR): computed once on the host and DMA'd in
        as a read-only constant. Every MATMUL and every ACTIVATION runs on device.

        WHY COMPOSED SiLU: matmat_mul_core's fused silu_enable=True uses the LALU's
        piecewise-approximate SILU, which measured -6dB on this tensor (see the
        history in _ae_precompute_cond_table). silu_core_dram computes a true
        x*sigmoid(x) -- identity-matmul sigmoid then an elementwise multiply.
        The SiLU is elementwise, so the (N,H) tensor is reshaped to
        (N*H/64, 64) and run against the shared 64x64 identity matrix rather than
        needing an HxH one.

        Emitted on the PRIMARY engine only, outside every sharded region: it is
        ~0.02 GFLOP of the denoise stage's ~200, so sharding it would buy nothing
        and cost two rendezvous. --engines 1 and --engines 2 execute identical
        instructions here.
        """
        H, NST = self.AE_HIDDEN, self.AE_NUM_DENOISE_STEPS
        V = UE_VECTOR_SIZE
        assert (NST * H) % V == 0
        sincos_addr = self._ae_build_sincos_table()      # host constant (N,H)
        self.AE_SINCOS_TABLE_DRAM = sincos_addr

        self._ae_matmul(NST, H, H, sincos_addr, self.ae_time_in_scale, self.ae_time_in_data,
                         self.AE_TIME_HID_TABLE_DRAM, bias_addr=self.ae_time_in_bias)
        silu_core_dram(self, M=(NST * H) // V, N=V,
                       A_DRAM_ADDR=self.AE_TIME_HID_TABLE_DRAM,
                       OUTPUT_DRAM_ADDR=self.AE_TIME_HID_SILU_DRAM,
                       IDENTITY_DRAM_ADDR=self.identity_addr)
        self._ae_matmul(NST, H, H, self.AE_TIME_HID_SILU_DRAM, self.ae_time_out_scale,
                         self.ae_time_out_data, self.AE_COND_TABLE_RAW_DRAM,
                         bias_addr=self.ae_time_out_bias)
        silu_core_dram(self, M=(NST * H) // V, N=V,
                       A_DRAM_ADDR=self.AE_COND_TABLE_RAW_DRAM,
                       OUTPUT_DRAM_ADDR=self.AE_COND_TABLE_DRAM,
                       IDENTITY_DRAM_ADDR=self.identity_addr)
        return self.AE_COND_TABLE_DRAM

    def _ae_host_cond_table(self):
        """Host ORACLE for the conditioning table (exact, matches pi05_torch_ref:
        IF4-quantized time-MLP kernels + F.silu). Returns an (N,H) float tensor.
        Used to score the on-device path and, when AE_COND_TABLE_ON_DEVICE is
        False, as the shipped constant (see _ae_precompute_cond_table)."""
        import pi05_torch_ref as _ref
        H, N = self.AE_HIDDEN, self.AE_NUM_DENOISE_STEPS
        min_period, max_period = 4e-3, 4.0
        frac = torch.linspace(0.0, 1.0, H // 2)
        period = min_period * (max_period / min_period) ** frac
        Win  = _ref.maybe_quantize(self._npy("time_mlp_in.kernel").to(torch.bfloat16), "if4").float()
        bin_ = self._npy("time_mlp_in.bias").float()
        Wout = _ref.maybe_quantize(self._npy("time_mlp_out.kernel").to(torch.bfloat16), "if4").float()
        bout = self._npy("time_mlp_out.bias").float()
        dt = -1.0 / N
        rows, t = [], 1.0
        for _ in range(N):
            sinusoid = t * (1.0 / period) * 2 * math.pi
            emb = torch.cat([torch.sin(sinusoid), torch.cos(sinusoid)]).to(torch.bfloat16).float()
            emb = torch.nn.functional.silu(emb @ Win + bin_)
            emb = torch.nn.functional.silu(emb @ Wout + bout)
            rows.append(emb)
            t += dt
        return torch.stack(rows)

    def _ae_check_cond_table(self):
        """Read back the DEVICE-computed (N,H) conditioning table and score it
        against the host oracle. Called once after the denoise execution."""
        H, N = self.AE_HIDDEN, self.AE_NUM_DENOISE_STEPS
        buf = bytearray(N * H * 2)
        self._dma_read_checked(self.AE_COND_TABLE_DRAM, buf, len(buf))
        got = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(N, H).float()
        ref = self._ae_host_cond_table()

        def _snr(a, b):
            noise = (a - b).pow(2).sum().item()
            return 10 * math.log10(b.pow(2).sum().item() / noise) if noise > 0 else float("inf")
        print("  [cond_table] on-device time-MLP vs host oracle:")
        for i in range(N):
            print(f"    step {i}: SNR {_snr(got[i], ref[i]):7.2f} dB   "
                  f"cos {torch.nn.functional.cosine_similarity(got[i], ref[i], dim=0).item():.6f}")
        overall = _snr(got, ref)
        print(f"    OVERALL: SNR {overall:.2f} dB  "
              f"max|abs err| {(got - ref).abs().max().item():.5f}  "
              f"nan={torch.isnan(got).sum().item()}")
        return overall

    def _ae_precompute_cond_table(self):
        """The AdaRMSNorm conditioning vector is INPUT-INDEPENDENT -- it depends
        only on t (fixed per Euler step). So sincos -> time_mlp_in -> silu ->
        time_mlp_out -> silu is a compile-time constant for all N steps. Compute
        the whole (N, H) cond table on the host (matching pi05_torch_ref exactly,
        IF4 weights + F.silu) and DMA it in, instead of running the time MLP +
        fused-silu on hardware (whose approximate silu was cratering time_embed
        to -6dB). Zero accuracy loss -- it's exact constants. Returns table addr."""
        import pi05_torch_ref as _ref
        H, N = self.AE_HIDDEN, self.AE_NUM_DENOISE_STEPS
        min_period, max_period = 4e-3, 4.0
        frac = torch.linspace(0.0, 1.0, H // 2)
        period = min_period * (max_period / min_period) ** frac
        # IF4-fake-quantize the time-MLP kernels the same way the reference does
        # (Weights.__getitem__ applies maybe_quantize to ".kernel" tensors).
        Win  = _ref.maybe_quantize(self._npy("time_mlp_in.kernel").to(torch.bfloat16), "if4").float()
        bin_ = self._npy("time_mlp_in.bias").float()
        Wout = _ref.maybe_quantize(self._npy("time_mlp_out.kernel").to(torch.bfloat16), "if4").float()
        bout = self._npy("time_mlp_out.bias").float()
        dt = -1.0 / N
        rows = []
        t = 1.0
        for _ in range(N):
            sinusoid = t * (1.0 / period) * 2 * math.pi
            emb = torch.cat([torch.sin(sinusoid), torch.cos(sinusoid)]).to(torch.bfloat16).float()  # (H,)
            emb = torch.nn.functional.silu(emb @ Win + bin_)
            emb = torch.nn.functional.silu(emb @ Wout + bout)  # (H,) = AdaRMSNorm cond
            rows.append(emb)
            t += dt
        table = torch.stack(rows).to(torch.bfloat16).contiguous()  # (N, H)
        addr = self.get_params_dram_addr()
        self.dma_write(DMA_DEVICE_H2C, addr, table, N * H * 2)
        self.allocate_params_dram(N * H * 2)
        return addr

    def _ae_time_embed_from_table(self, addr_reg):
        """Runtime-loop-body version of _ae_sincos_time_embed: read the CURRENT
        row (address held in addr_reg, advanced by the caller each iteration)
        into AE_SINCOS_DRAM via general_reg_src, then the same time_mlp_in ->
        silu -> time_mlp_out -> silu -> AE_COND_DRAM chain as before."""
        H = self.AE_HIDDEN
        sram = 0x00000
        self.accelerator_memory_to_sram(0, sram, H, general_reg_src=addr_reg)
        self.sram_to_accelerator_memory(sram, self.AE_SINCOS_DRAM, H)

        self._ae_matmul(1, H, H, self.AE_SINCOS_DRAM, self.ae_time_in_scale, self.ae_time_in_data,
                         self.AE_TIME_HIDDEN_DRAM, bias_addr=self.ae_time_in_bias, silu_enable=True)
        self._ae_matmul(1, H, H, self.AE_TIME_HIDDEN_DRAM, self.ae_time_out_scale, self.ae_time_out_data,
                         self.AE_COND_DRAM, bias_addr=self.ae_time_out_bias, silu_enable=True)
        # advance to next step's row for the next loop iteration
        self.generate_instruction_add_imm(addr_reg, H * 2)

    # ---- one action-expert transformer layer (attention + gated MLP) --------
    def compile_suffix_step(self, layer_idx, x_in_dram, x_out_dram, gpr_M_reg=None, flash_ctx=None, step=None,
                             sched=None, gpr_M_regs=None):
        """One action-expert layer body: AdaRMSNorm -> MQA attention (suffix Q vs
        combined prefix+suffix K/V) -> gated residual -> AdaRMSNorm -> gated MLP
        -> gated residual. Mirrors suffix_step()'s per-layer loop body in
        pi05_torch_ref.py (the `suf_tokens is not None` branch of joint_attention).
        gpr_M_reg (primed with S by the caller) makes every M=S matmul/RMSNorm in
        this body a compact PBI runtime loop -- this body is itself repeated 180x
        (10 Euler steps x 18 layers), so static-M unrolling blew the compiled
        program up past the point compilation could finish in any reasonable time.
        flash_ctx (dict from compile_denoise_loop): {prog_base, gpr_bucket, gpr_ret,
        call_sites} -- shared across all 180 calls; the flash body itself is
        compiled ONCE by the caller after every call site has been emitted."""
        la = self.ae_layer_addrs[layer_idx]
        H, D = self.AE_HIDDEN, self.HEAD_DIM
        S = self.AE_ACTION_HORIZON_PADDED
        Tkv, P = self.AE_TKV, self.AE_PREFIX_SEQ_LEN
        k_combined = self.ae_k_combined[layer_idx]
        v_combined = self.ae_v_combined[layer_idx]

        _pfx = f"step{step}_layer{layer_idx}" if step is not None else f"layer{layer_idx}"

        # 1. AdaRMSNorm (attention conditioning)
        self._ae_ada_rms_norm(S, x_in_dram, la["pre_attn_norm_dense_scale"], la["pre_attn_norm_dense_data"],
                               la["pre_attn_norm_dense_bias"], self.AE_NORM_DRAM, self.AE_GATE_BCAST_DRAM,
                               gpr_M_reg=gpr_M_reg)
        self._debug_op(f"{_pfx}_preattn_norm", self.AE_NORM_DRAM, S * H, shape=(S, H))
        self._debug_op(f"{_pfx}_attn_gate", self.AE_GATE_BCAST_DRAM, S * H, shape=(S, H))
        _p0l0 = self.DENOISE_STEP0_PROBE and step == 0 and layer_idx == 0
        if _p0l0:
            self._dram_copy(S * H * 2, self.AE_NORM_DRAM, self.AE_P0_L0_NORM)

        # 2. K/V projection for the suffix rows only -> combined buffer rows [P:P+S].
        #    K is projected into a staging buffer first, then RoPE'd (positions
        #    continue after the valid prefix, see _rope_init) straight into the
        #    combined buffer's suffix rows -- the cache holds the ROTATED k, same
        #    as the prefix. V is never rotated, so it projects in directly.
        self._ae_matmul(S, H, D, self.AE_NORM_DRAM, la["k_scale"], la["k_data"],
                         self.AE_K_SUF_DRAM, gpr_M_reg=gpr_M_reg)
        # Single MQA head, already (S, D) head-major -- the FIRST head-tile of the
        # tiled suffix table, at offset 0. Writes straight into the combined
        # buffer's suffix rows, so the RoPE stays out-of-place and costs no copy.
        self._rope_matmul(M=S,
                          src_dram=self.AE_K_SUF_DRAM,
                          out_dram=k_combined + P * D * 2,
                          cos_tiled=self.AE_ROPE_COS_TILED,
                          sin_tiled=self.AE_ROPE_SIN_TILED,
                          rot_dram=self.AE_ROPE_ROT_DRAM,
                          gpr_M_reg=gpr_M_reg)
        self._ae_matmul(S, H, D, self.AE_NORM_DRAM, la["v_scale"], la["v_data"],
                         v_combined + P * D * 2, gpr_M_reg=gpr_M_reg)
        self._debug_op(f"{_pfx}_kv_proj", k_combined + P * D * 2, S * D, shape=(S, D))
        if _p0l0:
            self._dram_copy(S * D * 2, k_combined + P * D * 2, self.AE_P0_L0_KSUF)

        # 3. Q projection, contiguous as (batch=AE_HEADS*S, D): head h's S queries
        #    at h*S*D so the whole buffer is the (batch, D) input the unified
        #    rectangular attention expects (each head's queries stacked in batch).
        #    RoPE per head: each head's block is already a plain (S, D) row-major
        #    tile, so the non-GQA core applies (the GQA variant expects the
        #    interleaved (S, heads*D) layout, which is NOT what this buffer is).
        # HEAD-SHARDED q PROJECTION. Only the MATMULS shard -- the attention op in
        # step 4 stays on the primary, same convention as the gated MLP and the
        # vision encoder. See the note above _ae_q_proj_sharded for why attention
        # is deliberately excluded.
        _proj_sharded = self._ae_attn_shardable(sched)
        if _proj_sharded:
            self._ae_q_proj_sharded(sched, S, la, gpr_M_regs)
        for h in range(self.AE_HEADS if not _proj_sharded else 0):
            self._ae_matmul(S, H, D, self.AE_NORM_DRAM, la["q_scale"][h], la["q_data"][h],
                             self.AE_Q_DRAM + h * S * D * 2, gpr_M_reg=gpr_M_reg)
        if not _proj_sharded:
            # All AE_HEADS at once: head h's queries are the contiguous (S, D)
            # block at h*S*D, so the whole buffer is one (AE_HEADS*S, D) batch and
            # the tiled cos/sin tables are laid out over exactly that. One RoPE
            # call per layer instead of AE_HEADS of them.
            self._rope_matmul(M=self.AE_HEADS * S,
                              src_dram=self.AE_Q_DRAM,
                              out_dram=self.AE_Q_ROPE_DRAM,
                              cos_tiled=self.AE_ROPE_COS_TILED,
                              sin_tiled=self.AE_ROPE_SIN_TILED,
                              rot_dram=self.AE_ROPE_ROT_DRAM,
                              gpr_M_reg=self._ae_rope_M_regs[0])
        self._debug_op(f"{_pfx}_q_proj", self.AE_Q_DRAM, S * D, shape=(S, D))
        self._debug_op(f"{_pfx}_q_rope", self.AE_Q_ROPE_DRAM, S * D, shape=(S, D))
        if getattr(self, "DENOISE_STEP0_PROBE", False) and step == 0 and layer_idx == 0:
            self._dram_copy(2 * S * D * 2, self.AE_Q_DRAM, self.AE_P0_L0_Q)  # heads 0-1 stacked Q
            self._dram_copy(2 * S * D * 2, self.AE_Q_ROPE_DRAM, self.AE_P0_L0_QROPE)  # heads 0-1 ROPED Q

        # 4. Rectangular attention: batch=AE_HEADS*S queries x Tkv keys, shared
        #    MQA K/V read directly from ae_k/v_combined (no per-layer staging), one
        #    (batch, Tkv) bias. Replaces the AE_HEADS per-head square-flash calls +
        #    all their per-head Q/out DMA. Dynamic (PBI) variant keeps the 180
        #    statically-unrolled bodies compact. q_scale=None -> 1/sqrt(head_dim).
        #    HEAD-SHARDED when the engine count divides AE_HEADS: consecutive heads
        #    are consecutive row ranges of this one batch, so each engine runs the
        #    same call over its own slice (see _ae_attention_sharded). Otherwise the
        #    single full-batch call below, byte-identical to the serial path.
        if _proj_sharded:
            self._ae_attention_sharded(sched, S, Tkv, k_combined, v_combined)
        else:
            self.unified_attention_core_dynamic(
                batch=self.AE_UATTN_BATCH, aligned_seq_len=Tkv, head_dim=D,
                Q_DRAM_ADDR=self.AE_Q_ROPE_DRAM, K_DRAM_ADDR=k_combined, V_DRAM_ADDR=v_combined,
                BIAS_DRAM_ADDR=self.AE_UATTN_BIAS_DRAM, OUTPUT_DRAM_ADDR=self.AE_ATTN_OUT_DRAM,
                SCRATCH_DRAM_ADDR=self.AE_UATTN_SCRATCH_DRAM, IDENTITY_DRAM_ADDR=self.identity_addr)
        self._debug_op(f"{_pfx}_flash_attn_out", self.AE_ATTN_OUT_DRAM, S * D, shape=(S, D))
        if getattr(self, "DENOISE_STEP0_PROBE", False) and step == 0 and layer_idx == 0:
            self._dram_copy(self.AE_HEADS * S * D * 2, self.AE_ATTN_OUT_DRAM, self.AE_P0_L0_ATTNRAW)  # all heads raw attn

        # 5. o projection, per-head (D,H) -> accumulate into AE_O_PROJ_DRAM via
        #    C_DRAM_ADDR-chained adds (first head writes, rest accumulate).
        #    A for head h is read STRAIGHT out of AE_ATTN_OUT_DRAM: the unified
        #    attention already emits head h's S rows as a CONTIGUOUS (S, D) block
        #    at h*S*D, which is exactly the row-major (M=S, K=D) matrix the matmul
        #    wants (it strides rows by K*2 bytes).
        #    The old code first scattered each head into an (S, H) token-major
        #    buffer and then handed the matmul `AE_ATTN_RESULT_DRAM + h*D*2` --
        #    but that buffer's row stride is H*2=2048B, not D*2=512B, so the matmul
        #    walked one row of (S,H) as four rows of (S,D): every row m>0 of every
        #    head read the WRONG head's columns. That un-stack step is also simply
        #    unnecessary -- nothing else consumes AE_ATTN_RESULT_DRAM.
        if _proj_sharded:
            self._ae_o_proj_sharded(sched, S, la, gpr_M_regs, "ae_o_proj_partial")
        for h in range(self.AE_HEADS if not _proj_sharded else 0):
            head_slice = self.AE_ATTN_OUT_DRAM + h * S * D * 2
            # bias_mode MUST be "full_matrix": C here is the running (S,H) partial
            # sum, not a (1,H) bias vector. matmat_mul_core defaults to
            # bias_mode="broadcast_N", which would add only ROW 0 of the partial sum
            # to every row -- heads 1..7 accumulated the wrong thing entirely
            # (o-proj measured 12.9dB on 50dB-clean inputs).
            self._ae_matmul(S, D, H, head_slice, la["o_scale"][h], la["o_data"][h],
                             self.AE_O_PROJ_DRAM, bias_addr=(self.AE_O_PROJ_DRAM if h > 0 else None),
                             gpr_M_reg=gpr_M_reg,
                             **({"bias_mode": "full_matrix"} if h > 0 else {}))
        self._debug_op(f"{_pfx}_o_proj", self.AE_O_PROJ_DRAM, S * H, shape=(S, H))
        if _p0l0:
            self._dram_copy(S * H * 2, self.AE_O_PROJ_DRAM, self.AE_P0_L0_ATTN)

        # 6. gated residual: x = x + gate * attn_out
        eltwise_mul_core_dram(self, size=S * H, A_DRAM_ADDR=self.AE_O_PROJ_DRAM,
                               B_DRAM_ADDR=self.AE_GATE_BCAST_DRAM, OUTPUT_DRAM_ADDR=self.AE_ATTN_GATED_DRAM)
        eltwise_add_core_dram(self, size=S * H, A_DRAM_ADDR=x_in_dram,
                               B_DRAM_ADDR=self.AE_ATTN_GATED_DRAM, OUTPUT_DRAM_ADDR=self.AE_RESIDUAL_DRAM)
        self._debug_op(f"{_pfx}_attn_residual", self.AE_RESIDUAL_DRAM, S * H, shape=(S, H))
        if _p0l0:
            self._dram_copy(S * H * 2, self.AE_RESIDUAL_DRAM, self.AE_P0_L0_RESID)

        # 7. AdaRMSNorm (mlp conditioning)
        self._ae_ada_rms_norm(S, self.AE_RESIDUAL_DRAM, la["pre_ffw_norm_dense_scale"],
                               la["pre_ffw_norm_dense_data"], la["pre_ffw_norm_dense_bias"],
                               self.AE_NORM_DRAM, self.AE_GATE_BCAST_DRAM, gpr_M_reg=gpr_M_reg)
        self._debug_op(f"{_pfx}_preffw_norm", self.AE_NORM_DRAM, S * H, shape=(S, H))

        # 8. gated MLP + gated residual
        if sched is not None and sched.num_engines > 1:
            # AE_NORM_DRAM was just written by the primary and is read in full by
            # every engine; the region's OPENING rendezvous is that RAW fence.
            self._ae_gated_mlp_sharded(sched, S, self.AE_NORM_DRAM, la, self.AE_MLP_DOWN_DRAM,
                                        gpr_M_regs, "ae_mlp_down_partial")
        else:
            self._ae_gated_mlp(S, self.AE_NORM_DRAM, la, self.AE_MLP_DOWN_DRAM, gpr_M_reg=gpr_M_reg)
        self._debug_op(f"{_pfx}_mlp_out", self.AE_MLP_DOWN_DRAM, S * H, shape=(S, H))
        eltwise_mul_core_dram(self, size=S * H, A_DRAM_ADDR=self.AE_MLP_DOWN_DRAM,
                               B_DRAM_ADDR=self.AE_GATE_BCAST_DRAM, OUTPUT_DRAM_ADDR=self.AE_MLP_GATED_DRAM)
        eltwise_add_core_dram(self, size=S * H, A_DRAM_ADDR=self.AE_RESIDUAL_DRAM,
                               B_DRAM_ADDR=self.AE_MLP_GATED_DRAM, OUTPUT_DRAM_ADDR=x_out_dram)

    # ---- full flow-matching denoising loop -----------------------------------
    def compile_denoise_loop(self):
        """10-step Euler integration (dt = -1/10, t: 1.0 -> 0.0), each step running
        action_in_proj -> timestep embed -> 18 action-expert layers -> final
        AdaRMSNorm -> action_out_proj -> x_t += dt * v_t. Mirrors the loop body in
        run_pi05() (pi05_torch_ref.py).

        Compiled ONCE as a single body wrapped in a real hardware loop_start/
        loop_end (runtime trip count = AE_NUM_DENOISE_STEPS), not 10 statically
        unrolled copies -- all 10 steps share identical dims/shapes (S, H, I,
        Tkv, NH), the only thing that varies per step is the scalar timestep
        t, which is now handled by precomputing all N sincos embeddings into
        one DRAM table (_ae_build_sincos_table) and reading the current row at
        runtime via a GPR-held address that advances each iteration
        (_ae_time_embed_from_table) -- a true hardware loop can't re-run host
        Python between iterations, so the old per-step host DMA write had to
        go. This also collapses the flash-attention shared-subroutine call
        sites from 1440 (10 x 18 x 8, one set per statically-unrolled step) down
        to 144 (18 x 8, one copy of the loop body), and the compiled
        instruction count by roughly the same ~10x.

        Every matmul/RMSNorm inside the loop body still runs through a PBI
        runtime M-loop (gpr_M_reg, primed once below) -- required independent
        of the outer step-loop change, since M=S rows per call still needs a
        runtime trip count to avoid static-M unrolling blowup within a single
        18-layer body.

        Assumes self.AE_XT_DRAM already holds the initial noise sample (S, 32) --
        caller (run harness) DMAs it in before invoking compile_denoise_loop(), or
        it defaults to whatever tensor_init_action_expert() left there (uninitialized).
        """
        S, H = self.AE_ACTION_HORIZON_PADDED, self.AE_HIDDEN
        dt = -1.0 / self.AE_NUM_DENOISE_STEPS
        t = 1.0

        self._debug_counter = 0
        self._debug_halt_info = None

        # THE denoise-NaN fix. alloc_isa_reg/alloc_inst_ptr use per-PROCESS
        # counters that start_capture() does NOT reset -- and any inner PBI op
        # in vision (27 layers) or prefix (18 layers) that leaks an allocation
        # drifts these counters upward. Without resetting them here, denoise's
        # ae_S_reg / flash gpr_bucket / PBI inst-pointers get DIFFERENT physical
        # indices in a full run (after vision+prefix) than in a --debug run
        # (denoise first), landing on reserved/stale regs -> 100% NaN, not a
        # crash. This is a PYTHON-allocator drift, which is why software_reset()
        # (hardware-only) did NOT fix it. mobilesam resets these counters at the
        # start of every stage for exactly this reason; pi05 never did.
        self.reset_isa_reg_counter()
        self.reset_inst_ptr_counter()

        # ---- N-axis (output-column) sharding of the gated MLP -----------------
        # M is AE_ACTION_HORIZON_PADDED = 64 EVERYWHERE in this stage: one row
        # block, so the M-split that shards vision and prefix is not merely
        # inefficient here, it is inexpressible. N is the axis with room
        # (1024 -> 4096), and the gated MLP is ~77% of the per-layer matmul work.
        ne = self._num_engines("DENOISE")
        sched = self._denoise_make_scheduler(ne) if ne > 1 else None
        self._denoise_sched = sched
        if sched is not None:
            # _debug_op / DEBUG_STOP halt the PRIMARY only; under multi-engine the
            # workers would spin forever at the next rendezvous.
            assert self.DEBUG_STOP_AFTER is None, (
                "PI05_DEBUG_STOP_AFTER is not supported with a sharded denoise stage "
                f"(engines={ne}): the halt is emitted on the primary only. Use --engines 1.")
            for la in self.ae_layer_addrs:
                assert "mlp_down_k" in la, (
                    "the denoise stage is sharded but weight_init_action_expert did not "
                    "store the K-sliced mlp-down blobs -- DENOISE_NUM_ENGINES must be "
                    "resolvable to the same value at weight-init time as it is here.")
            # Per-engine [S, I/ne] lanes for gate / up / gelu-mult. matmat_mul_core's
            # writeback stride is N*bpe for the N IT WAS GIVEN, so calling it with
            # N=cols writes a DENSE [S, cols] block -- each engine owns its own
            # buffer and nothing is strided.
            for nm in ("ae_mlp_gate", "ae_mlp_up", "ae_mlp_mult"):
                sched.alloc_col_output(nm, S, self.AE_INTERMEDIATE)
            # The K-split partial sums are FULL [S, H] per engine (a reduction does
            # not partition its output). The primary accumulates in place into the
            # existing AE_MLP_DOWN_DRAM, so downstream code is untouched.
            sched.register_per_engine("ae_mlp_down_partial", self.AE_MLP_DOWN_DRAM, S * H * 2,
                                      init_tensor=torch.zeros(S * H, dtype=torch.bfloat16))
            # ---- head-parallel attention block (q proj / attention / o proj) ----
            if self._ae_attn_shardable(sched):
                self._ae_head_split(ne)      # validate the split at compile entry,
                                             # not 180 layer-bodies deep
                # o-proj partials: a reduction does not partition its output, so each
                # is a FULL [S, H]. The primary accumulates in place into the existing
                # AE_O_PROJ_DRAM, leaving step 6 (the gated residual) untouched.
                sched.register_per_engine("ae_o_proj_partial", self.AE_O_PROJ_DRAM, S * H * 2,
                                          init_tensor=torch.zeros(S * H, dtype=torch.bfloat16))
                # PER-ENGINE ATTENTION SCRATCH. unified_attention_core_dynamic WRITES
                # its scratch (V^T, the score/P plane, scaled Q), so the head-sharded
                # calls cannot share one -- see _ae_attention_sharded. Sized by the
                # SHARDED batch (nh*S), not AE_UATTN_BATCH, using the same formula as
                # the serial buffer; the Tkv*Tkv score term dominates and is
                # unchanged, so this is ~2 MB per engine rather than a full copy.
                # Plain allocate_tensor_dram (not register_per_engine): these are
                # pure scratch that no engine reads across a barrier and that never
                # needs a primary-address alias or an init tensor.
                _nh = self.AE_HEADS // ne
                _D, _Tkv = self.HEAD_DIM, self.AE_TKV
                _ushard = _D * _Tkv + _Tkv * _Tkv + _nh * S * _D
                self.AE_UATTN_SCRATCH_SHARDED = [
                    self.allocate_tensor_dram(_ushard * 2) for _ in range(ne)]
                print(f"    [denoise] head-parallel attention block: {self.AE_HEADS} heads "
                      f"over {ne} engine(s), {_nh} head(s) each "
                      f"(q proj + ATTENTION + o proj), "
                      f"{_ushard * 2 * ne / (1 << 20):.1f} MB of per-engine attn scratch")
            else:
                print(f"    [denoise] engines={ne} does not divide AE_HEADS="
                      f"{self.AE_HEADS}; attention stays SERIAL, only the gated MLP is "
                      f"sharded (~60% coverage). Use 2, 4 or 8 for the full ~97%.")
            self.dram_region_map(f"denoise sharded x{ne}")
            sched.begin_program()

        # rope tables (idempotent -- normally already built by compile_prefix, but
        # a skip_prefix run never calls it)
        self._rope_init()

        ae_S_reg = self.alloc_isa_reg()
        self.generate_instruction_add_set(ae_S_reg, S)
        # One M=S GPR PER ENGINE: gpr_M_reg indices are per-engine ISA registers and
        # a worker's allocator was just reset by begin_program(), so the primary's
        # index is meaningless on a worker. Primed here, once, outside every region.
        ae_S_regs = [ae_S_reg]
        for w in (sched.workers if sched is not None else []):
            r = w.alloc_isa_reg()
            w.generate_instruction_add_set(r, S)
            ae_S_regs.append(r)

        # M = nh*S for the matmul RoPE, which covers an engine's WHOLE head range
        # in one call rather than S rows at a time -- a different trip count from
        # ae_S_regs, so it needs its own per-engine register (same reasoning: a
        # worker's register indices are its own).
        ne_ae = sched.num_engines if sched is not None else 1
        nh_per = (self.AE_HEADS // ne_ae) if self._ae_attn_shardable(sched) else self.AE_HEADS
        self._ae_rope_M_regs = []
        for eng in ([self] + list(sched.workers if sched is not None else [])):
            r = eng.alloc_isa_reg()
            eng.generate_instruction_add_set(r, nh_per * S)
            self._ae_rope_M_regs.append(r)

        # Norm ABI (post pcie_only sync): rms_norm_core_dram no longer folds sqrt(N)
        # implicitly -- the dynamic core reads N and bf19(sqrt(N)) from runtime GPRs.
        # Prime them once here (N = AE_HIDDEN) and thread them through the AdaRMSNorm
        # helper via instance attrs so every suffix-layer + final norm is scaled right.
        ae_N_reg = self.alloc_isa_reg()
        self.generate_instruction_add_set(ae_N_reg, H)
        ae_sqrt_N_reg = self.alloc_isa_reg()
        self.generate_instruction_add_set(ae_sqrt_N_reg, self.float_to_bf19(float(H ** 0.5)))
        self._ae_rms_N_reg = ae_N_reg
        self._ae_rms_sqrt_reg = ae_sqrt_N_reg

        # PBI DISPATCH FOR THE AdaRMSNorm CONDITIONING MATMUL.
        # matmat_mul_core routes to the DYNAMIC (PBI) core as soon as any dimension
        # GPR is supplied, and to matmat_mul_core_legacy -- compile-time M/K/N
        # tiling, fully unrolled -- when none is. The conditioning matmul is
        # (1, H) @ (3H, H)^T, and its M=1 made "a single-row matmul is already
        # minimal" look true. It is not: legacy tiles the N axis, and with K=H the
        # budget gives
        #     N_chunk = (URAM_NEAR_FULL_ELEMENTS // K) // 64 * 64 = 192
        # so N=3H=3072 unrolls into 16 tiles. That happens TWICE per layer body and
        # the body is emitted 180x (18 layers x 10 Euler steps) = 5760 unrolled
        # tiles in the denoise program. Handing it a GPR-primed M collapses each
        # call to one PBI loop.
        # One SHARED register, primed once: allocating per call would burn two ISA
        # registers on every one of the 360 invocations.
        ae_one_reg = self.alloc_isa_reg()
        self.generate_instruction_add_set(ae_one_reg, 1)
        self._ae_cond_M_reg = ae_one_reg

        # Seed the combined K/V buffers' prefix rows [0:P] once (unchanged across
        # all 10 Euler steps / all layers' repeated suffix_step calls). MUST be
        # captured here (inside this function's own start_capture session) --
        # tensor_init_action_expert() runs too early (before any capture is
        # open, or after a prior one was already cleared) for instructions
        # emitted there to ever actually execute; see its docstring/comment.
        P, D = self.AE_PREFIX_SEQ_LEN, self.HEAD_DIM
        for layer in range(self.AE_LAYERS):
            self.accelerator_memory_to_sram(self.prefix_k_cache_addr[layer], 0x00000, P * D)
            self.sram_to_accelerator_memory(0x00000, self.ae_k_combined[layer], P * D)
            self.accelerator_memory_to_sram(self.prefix_v_cache_addr[layer], 0x00000, P * D)
            self.sram_to_accelerator_memory(0x00000, self.ae_v_combined[layer], P * D)

        # Attention runs inline per (step, layer) via unified_attention_core_dynamic
        # inside compile_suffix_step -- no shared flash subroutine, no jump-site
        # patching. Static unrolling (10 steps x 18 layers = 180 layer bodies) is
        # retained (matching compile_prefix/compile_encoder's proven pattern; the
        # loop_start/loop_end runtime-loop variant hung on real backward branches).

        # (N,H) AdaRMSNorm conditioning table. Default: computed ON DEVICE (two
        # IF4 matmuls + two composed SiLUs, batched over all N Euler steps) from a
        # host-constant sincos table -- see _ae_compile_cond_table. Set
        # AE_COND_TABLE_ON_DEVICE=False to fall back to the host constant-fold.
        if self.AE_COND_TABLE_ON_DEVICE:
            self._ae_compile_cond_table()
        else:
            self.AE_COND_TABLE_DRAM = self._ae_precompute_cond_table()

        try:
            for step in range(self.AE_NUM_DENOISE_STEPS):
                # action_in_proj: x_t (S,64) -> action_tokens (S,H). x_t is already
                # physically 64-wide (cols [0:32] real, [32:64] zero), so the matmul
                # reads it CONTIGUOUSLY -- no 32->64 strided staging (which was
                # reading noise rows at 2x stride). action_in weight is K-padded 64.
                if self.DENOISE_STEP0_PROBE and step == 0:
                    self._dram_copy(S * self.AE_XT_WIDTH * 2, self.AE_XT_DRAM, self.AE_P0_XT_PAD)
                self._ae_matmul(S, self.AE_XT_WIDTH, H, self.AE_XT_DRAM,
                                 self.ae_action_in_scale, self.ae_action_in_data,
                                 self.AE_ACTION_TOK_DRAM, bias_addr=self.ae_action_in_bias, gpr_M_reg=ae_S_reg)
                self._debug_op(f"step{step}_action_in_proj", self.AE_ACTION_TOK_DRAM, S * H, shape=(S, H))
                if self.DENOISE_STEP0_PROBE and step == 0:
                    self._dram_copy(S * H * 2, self.AE_ACTION_TOK_DRAM, self.AE_P0_ACTION_IN)

                # timestep embedding -> AE_COND_DRAM (this step's AdaRMSNorm
                # conditioning): copy the precomputed constant row for this step
                # (host-exact) instead of running the HW time-MLP + fused silu.
                self._dram_copy(H * 2, self.AE_COND_TABLE_DRAM + step * H * 2, self.AE_COND_DRAM)
                self._debug_op(f"step{step}_time_embed", self.AE_COND_DRAM, H, shape=(1, H))
                if self.DENOISE_STEP0_PROBE and step == 0:
                    self._dram_copy(1 * H * 2, self.AE_COND_DRAM, self.AE_P0_TIME_EMB)

                # 18 action-expert layers
                x_cur = self.AE_ACTION_TOK_DRAM
                for layer_idx in range(self.AE_LAYERS):
                    x_next = self.AE_X_DRAM if x_cur is not self.AE_X_DRAM else self.AE_ACTION_TOK_DRAM
                    self.compile_suffix_step(layer_idx, x_cur, x_next, gpr_M_reg=ae_S_reg, step=step,
                                              sched=sched, gpr_M_regs=ae_S_regs)
                    self._debug_op(f"step{step}_suffix_layer{layer_idx}", x_next, S * H, shape=(S, H))
                    if self.DENOISE_STEP0_PROBE and step == 0 and layer_idx == 0:
                        self._dram_copy(S * H * 2, x_next, self.AE_P0_SUF_L0)
                    if self.DENOISE_STEP0_PROBE and step == 0 and layer_idx == self.AE_LAYERS - 1:
                        self._dram_copy(S * H * 2, x_next, self.AE_P0_SUF_L17)
                    x_cur = x_next

                # final AdaRMSNorm (no gate applied -- action_out_proj consumes the
                # normed output directly, per the real bug noted in pi05_torch_ref.py)
                self._ae_ada_rms_norm(S, x_cur, self.ae_final_norm_dense_scale,
                                       self.ae_final_norm_dense_data, self.ae_final_norm_dense_bias,
                                       self.AE_NORM_DRAM, self.AE_GATE_BCAST_DRAM, apply_gate=False,
                                       gpr_M_reg=ae_S_reg)
                self._debug_op(f"step{step}_final_ada_rms_norm", self.AE_NORM_DRAM, S * H, shape=(S, H))

                # action_out_proj: (S,H) -> v_t (S,64). Output N padded 32->64 (weight
                # rows [32:64]=0) so v_t is physically 64-wide, matching x_t -> the
                # euler update is a plain contiguous add (no strided 32-of-64 write).
                self._ae_matmul(S, H, self.AE_XT_WIDTH, self.AE_NORM_DRAM,
                                 self.ae_action_out_scale, self.ae_action_out_data,
                                 self.AE_VT_DRAM, bias_addr=self.ae_action_out_bias, gpr_M_reg=ae_S_reg)
                self._debug_op(f"step{step}_action_out_proj", self.AE_VT_DRAM, S * self.AE_XT_WIDTH,
                                shape=(S, self.AE_XT_WIDTH))
                if self.DENOISE_STEP0_PROBE and step == 0:
                    self._dram_copy(S * self.AE_XT_WIDTH * 2, self.AE_VT_DRAM, self.AE_P0_VT)

                # Euler step: x_t = x_t + dt * v_t  (both physically S*64-wide)
                # NOTE: OUTPUT_DRAM_ADDR aliases A_DRAM_ADDR (both AE_XT_DRAM) here --
                # same aliasing shape as the compile_prefix bug we fixed, but this
                # buffer is tiny (S*64 elements, a single chunk) so it's mathematically
                # safe by the same per-chunk read-before-write analysis. Left as-is
                # (not the confirmed bug class) but flagging since we've been burned
                # by this exact pattern before.
                self.accelerator_memory_to_sram(self.AE_VT_DRAM, 0x00000, S * self.AE_XT_WIDTH)
                self.broadcast_mul(scalar=dt, sram_start_addr=0x00000, sram_wb_addr=0x00000,
                                    element_size=S * self.AE_XT_WIDTH)
                self.sram_to_accelerator_memory(0x00000, self.AE_VT_DRAM, S * self.AE_XT_WIDTH)
                eltwise_add_core_dram(self, size=S * self.AE_XT_WIDTH, A_DRAM_ADDR=self.AE_XT_DRAM,
                                       B_DRAM_ADDR=self.AE_VT_DRAM, OUTPUT_DRAM_ADDR=self.AE_XT_DRAM)
                self._debug_op(f"step{step}_euler_update", self.AE_XT_DRAM, S * self.AE_XT_WIDTH,
                                shape=(S, self.AE_XT_WIDTH))
                self._dram_copy(S * self.AE_XT_WIDTH * 2, self.AE_XT_DRAM, self.AE_STEP_SNAPSHOT_DRAM[step])
                t += dt

            # Main per-(step,layer) program ends here. Attention is now inline
            # (unified_attention_core_dynamic in compile_suffix_step) so there is no
            # shared flash subroutine to compile/patch after the loop.
            self.generate_instruction_halt()
        except _DebugStop:
            pass   # halt already emitted by _debug_op.

        if sched is not None:
            # KEEP the addresses: this scheduler is SHARED with the encoder and the
            # prefix, and finalize() overwrites sched._worker_prog_addrs -- a bare
            # start_workers() later would relaunch the wrong stage's worker program.
            self._denoise_worker_prog_addrs = sched.finalize()
            print(f"    [denoise] worker program(s): "
                  f"{[w.get_capture_instruction_size_bytes() for w in sched.workers]} bytes")
            self._assert_worker_programs_fit(sched)

        self.release_isa_reg()  # ae_sqrt_N_reg
        self.release_isa_reg()  # ae_N_reg
        self.release_isa_reg()  # _ae_rope_M_regs[0]
        self.release_isa_reg()  # ae_S_reg
        print("compile_denoise_loop done: 10-step Euler action-expert flow-matching stack compiled "
              "(statically unrolled, inline unified attention)")

    # =========================================================================
    # End-to-end driver: real sample images -> vision (x3) -> prefix -> denoise
    # loop -> readback. Integration pass reconciling the vision/prefix/action-
    # expert stacks written independently above.
    # =========================================================================
    def _patchify(self, image_hwc):
        """image_hwc: (224,224,3) float32 in [-1,1] -> (256, 588) float32, matching
        pi05_torch_ref.vision_encode's unfold+reshape (patch_size=14, 16x16 patches)."""
        ps, n_side = 14, 16
        x = image_hwc.reshape(n_side, ps, n_side, ps, 3)
        x = x.transpose(0, 2, 1, 3, 4).reshape(n_side * n_side, ps * ps * 3)
        return x

    def run_vision(self, images_hwc):
        """images_hwc: list of 3 (224,224,3) float32 numpy arrays in [-1,1].
        Runs compile_encoder() once per image slot, returns (3*256, 2048) bf16
        tensor of concatenated vision tokens (host-side, read back via DMA)."""
        HO = self.VIS_HEAD_OUT
        S = self.VIS_S
        PK = self.VIS_PATCH_K
        outs = []

        # layer_norm_core_dram treats ZEROS_DRAM_ADDR as SCRATCH, not as a read-only
        # constant: it WRITES into vis_zeros_addr. The encoder calls it 55x (2 per
        # layer x 27 + the final encoder_norm), so after one execution the buffer no
        # longer holds zeros and EVERY LayerNorm of the next execution starts from
        # garbage, compounding over 27 layers.
        #
        # MEASURED (md5 of every constant the encoder reads, before vs after one
        # execution): vis_zeros is the ONLY region that changes -- identity matrix,
        # zero-bias, pos-embed and all IF4 weights come back clean. That single dirty
        # buffer is what made the 2nd vision execution wrong: same image in slot0 and
        # slot1 returned exec#1-vs-exec#2 SNR 9.31dB, cos 0.9396, output range
        # compressed [-206,35] -> [-192,30] (structurally right, systematically shrunk
        # -- a broken-LayerNorm signature, not corruption).
        #
        # So: re-zero it before every execution. This is also why the encoder can go
        # back to COMPILE-ONCE -- the old per-slot recompile was chasing this bug and
        # never fixed it (both slots stayed wrong), while burning ~106MB of program
        # DRAM per slot.
        zeros_n = max(self.VIS_H, self.VIS_I)
        zeros_t = torch.zeros(zeros_n, dtype=torch.bfloat16)

        # Skip the encoder for any all-zero (padding) image slot -- e.g. LIBERO's
        # 3rd camera, which openpi masks out (image_mask=False for pi0.5). Its 256
        # tokens are emitted as a 1e-6 placeholder (NOT exact 0 -- rms_norm has no
        # epsilon, 0-rows NaN) and their columns are masked in both the prefix and
        # suffix attention bias (self.masked_vision_slots), so they contribute
        # nothing. Saves one full 27-layer encoder pass per zero slot.
        masked_slots = []
        for i, img in enumerate(images_hwc):
            is_zero = not np.any(img)  # all-zero placeholder image (e.g. LIBERO 3rd cam)
            if is_zero:
                # ALWAYS attention-mask a zero slot (openpi image_mask=False),
                # whether or not we spend the encoder pass on it.
                masked_slots.append(i)
            if is_zero and self.SKIP_ZERO_VISION_SLOTS:
                outs.append(torch.full((S, HO), 1e-6, dtype=torch.bfloat16))
                print(f"  [vision] slot {i} SKIPPED (zero image, masked out)")
                continue
            patches = self._patchify(img)  # (256, 588)
            patches_pad = np.zeros((S, PK), dtype=np.float32)
            patches_pad[:, :patches.shape[1]] = patches
            pixel_t = torch.from_numpy(patches_pad).to(torch.bfloat16)
            self.dma_write(DMA_DEVICE_H2C, self.VIS_PIXEL_IN_DRAM, pixel_t, S * PK * 2)

            # Restore the LayerNorm zeros scratch -- the previous execution dirtied it.
            self.dma_write(DMA_DEVICE_H2C, self.vis_zeros_addr, zeros_t, zeros_n * 2)

            prog_addr = self._compile_once("encoder", self.compile_encoder, label="vision encoder")
            sched = getattr(self, "_vis_sched", None)
            if sched is not None and sched.num_engines > 1:
                # A flag left SET by an earlier program would make the first CHECK of
                # the first rendezvous pass spuriously. Once, before the first launch.
                if not getattr(self, "_vis_flags_precleared", False):
                    sched.preclear_flags()
                    self._vis_flags_precleared = True
                # The zeros restore above only re-zeroed the PRIMARY's copy; every
                # engine has its own (layer_norm_core_dram writes it as scratch).
                sched.refresh_per_engine("vis_zeros", zeros_t)
                # Workers HALT at the end of every run, so they must be relaunched
                # before EVERY primary launch -- this collides with compile-once/
                # execute-many, hence the explicit call here rather than at compile time.
                # Workers first, then the primary (proven order; primary-first also
                # works since it blocks at its first CHECK).
                sched.start_workers(self._vis_worker_prog_addrs)
            self.start_execute_from_dram(prog_addr)
            self._wait_with_heartbeat(f"vision slot {i}", timeout=180.0)
            if sched is not None and sched.num_engines > 1:
                # The primary can retire its halt while a worker is still draining
                # the ~33 no-op instructions of the exit rendezvous (they write
                # nothing, so the data is already there) -- so WAIT rather than
                # assert-not-busy, which would be flaky. A worker genuinely stuck
                # at a rendezvous trips the timeout.
                for widx, w in enumerate(sched.workers):
                    w.wait_queue(60.0)

            buf = bytearray(S * HO * 2)
            self._dma_read_checked(self.VIS_HEAD_OUT_DRAM, buf, len(buf))
            out = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(S, HO).clone()
            outs.append(out)
            print(f"  [vision] slot {i} done")

        # Overwrite any masked (all-zero) slot's encoded tokens with the finite
        # 1e-6 placeholder before they enter the prefix. The slot is -inf-masked
        # out of all attention anyway, so its encoded content is never used; this
        # keeps the carried rows finite/clean (identical to the skip path) while
        # still having run the encoder pass above for representative timing.
        for i in masked_slots:
            outs[i] = torch.full((S, HO), 1e-6, dtype=torch.bfloat16)

        # DROP dead slots from the prefix entirely -- do not carry them as masked
        # placeholder rows.
        #
        # An earlier comment here claimed dropping "shifts every text token's RoPE
        # position and breaks language conditioning". That is WRONG, and it cost real
        # FPGA time. It reasons about positions = arange(seq_len), under which deleting
        # 256 rows would indeed shift everything after them. But _rope_positions_prefix
        # computes openpi's actual formula:
        #
        #     positions = cumsum(attn_mask) - 1
        #
        # A masked row contributes 0 to the cumsum, so it NEVER advances the counter.
        # Present-and-masked and physically-absent therefore give IDENTICAL positions
        # to every surviving token (vision 0..511, text 512..512+n_text-1), and an
        # identical n_valid (=512+n_text) for the action expert's suffix rope. The dead
        # columns were also -inf-masked in attention, i.e. softmax weight exactly 0, so
        # nothing ever read from them either.
        #
        # Masking killed their INFLUENCE but not their FLOPs: those 256 rows still ran
        # every QKV/O projection and MLP of all 18 layers. Dropping them takes the
        # prefix 832 -> 576 tokens (-31% FLOPs, 148s -> ~102s) and the whole inference
        # ~196s -> ~150s, bit-for-bit equivalent.
        #
        # VERIFIED on pi05_torch_ref (identical rope/mask logic): 3-slots-masked vs
        # 2-slots-dropped = 50.5 dB (bf16 noise floor). Control: keeping the slot but
        # NOT masking it (a genuine rope shift) craters to 15.9 dB -- so the check is
        # sensitive to exactly the failure the old comment feared, and it does not fire.
        #
        # NOTE: the text budget is unchanged. Before: 832-768=64 text tokens. After:
        # 576-512=64. Worst real LIBERO prompt is 62 tokens (libero_spatial t4).
        self.masked_vision_slots = masked_slots
        if self.KEEP_MASKED_SLOTS:
            # A/B control path (--keep-masked-slots): carry the dead slots as masked
            # placeholder rows -- the pre-2026-07-14 behaviour. Prefix goes back to 832
            # tokens and burns ~1050 GFLOP on them. Output must be IDENTICAL to the
            # drop path (measured 251 dB); that equality IS the experiment.
            # NB: vision cost is unchanged either way -- the encoder still skips zero
            # slots. This toggle only moves the PREFIX.
            self.prefix_masked_cols = [(i * S, (i + 1) * S) for i in masked_slots]
            return torch.cat(outs, dim=0)          # (3*256, 2048)
        self.prefix_masked_cols = []   # nothing masked in-sequence: the rows are gone
        kept = [o for i, o in enumerate(outs) if i not in masked_slots]
        return torch.cat(kept, dim=0)  # (n_valid_slots*256, 2048), e.g. (512, 2048)

    def run_encoder_only(self, images_hwc, dump_prefix=None):
        """--encoderend: compile + run ONLY the vision encoder, over ALL image slots.

        A/B harness for the row-sharded encoder. Deliberately does no prefix and no
        denoise, but it walks the SAME slot set run_vision() walks (LIBERO's base
        camera, wrist camera, and the all-zero 3rd camera), with the same
        SKIP_ZERO_VISION_SLOTS / masked-slot semantics -- so the reported total is
        the full encoder cost of one real inference, not one third of it.

        `--encoderend --engines 1` and `--encoderend --engines 2` print a
        format-identical ENC_ONLY block (same lines, same order, same count) and
        dump one .npy per slot, so the two runs can be scored against EACH OTHER
        per slot. That cross-run comparison is the real gate -- sharding is a pure
        work partition, so the two runs must be bit-identical -- and it does not
        depend on the (independently weak) CPU-oracle number.

        Composes with PI05_DEBUG_STOP_AFTER: when a debug halt is armed, the
        checkpoint's buffer is read back instead of head_out, on every slot.
        """
        S, HO, PK = self.VIS_S, self.VIS_HEAD_OUT, self.VIS_PATCH_K
        ne = self._num_engines("VIS")
        if isinstance(images_hwc, np.ndarray):     # tolerate a single image
            images_hwc = [images_hwc]

        t0 = time.perf_counter()
        prog_addr = self._compile_once("encoder", self.compile_encoder, label="vision encoder")
        compile_s = time.perf_counter() - t0
        sched = getattr(self, "_vis_sched", None)
        multi = sched is not None and sched.num_engines > 1
        if multi:
            sched.preclear_flags()

        # A debug halt fires wherever the checkpoint is, so read THAT buffer.
        info = self._debug_halt_info
        if info is not None:
            name, addr, shape = info["name"], info["addr"], info["shape"]
        else:
            name, addr, shape = "head_out", self.VIS_HEAD_OUT_DRAM, (S, HO)

        zeros_n = max(self.VIS_H, self.VIS_I)
        zeros_t = torch.zeros(zeros_n, dtype=torch.bfloat16)

        import pi05_torch_ref as _ref
        W = _ref.Weights(device="cpu", dtype=torch.bfloat16, quant="if4")

        def _snr(hw, cpu):
            n = (hw.float() - cpu.float()).pow(2).sum().sqrt()
            g = cpu.float().pow(2).sum().sqrt()
            return float("inf") if n == 0 else float(20 * torch.log10(g / n.clamp_min(1e-12)))

        rows = []
        masked_slots = []
        total_wall = 0.0
        for i, img in enumerate(images_hwc):
            # Mirror run_vision's slot semantics EXACTLY so the timing is
            # representative: an all-zero slot is ALWAYS attention-masked (openpi
            # image_mask=False), and is only SKIPPED when SKIP_ZERO_VISION_SLOTS
            # is on -- which defaults to False, i.e. every slot is really encoded.
            is_zero = not np.any(img)
            if is_zero:
                masked_slots.append(i)
            if is_zero and self.SKIP_ZERO_VISION_SLOTS:
                rows.append({"slot": i, "masked": 1, "skipped": 1, "wall": 0.0,
                             "snr": float("nan"), "lo": float("nan"), "hi": float("nan"),
                             "mn": 1e-6, "mx": 1e-6, "nan": 0, "dump": "-"})
                print(f"  [encoderend] slot {i} SKIPPED (zero image, masked out)")
                continue

            patches = self._patchify(img)
            patches_pad = np.zeros((S, PK), dtype=np.float32)
            patches_pad[:, :patches.shape[1]] = patches
            pixel_t = torch.from_numpy(patches_pad).to(torch.bfloat16)
            self.dma_write(DMA_DEVICE_H2C, self.VIS_PIXEL_IN_DRAM, pixel_t, S * PK * 2)
            # Restore the LayerNorm zeros scratch on EVERY engine -- the previous
            # slot's execution dirtied it (layer_norm_core_dram writes it).
            self.dma_write(DMA_DEVICE_H2C, self.vis_zeros_addr, zeros_t, zeros_n * 2)
            if multi:
                sched.refresh_per_engine("vis_zeros", zeros_t)
                sched.start_workers()   # workers halt after every run
            t1 = time.perf_counter()
            self.start_execute_from_dram(prog_addr)
            self._wait_with_heartbeat(f"encoder slot {i}", timeout=300.0)
            if multi:
                for w in sched.workers:
                    w.wait_queue(300.0)
            wall = time.perf_counter() - t1
            total_wall += wall

            buf = bytearray(shape[0] * shape[1] * 2)
            self._dma_read_checked(addr, buf, len(buf))
            out = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(*shape).clone()

            # CPU oracle at the SAME checkpoint, same IF4 weights. An all-zero image
            # is NOT a degenerate case here: the patch-embed bias makes every row
            # non-zero before the first LayerNorm, so the oracle is well defined and
            # the HW must not produce NaN either (nan_count below is the check).
            images_t = torch.from_numpy(img)[None].to(torch.bfloat16)
            cpu = None
            for ck_name, ck in _ref.vision_encode_checkpoints(images_t, W):
                if ck_name == name:
                    cpu = ck.detach().clone()
                    break
            if cpu is None:
                cpu = _ref.vision_encode(images_t, W).reshape(S, HO)

            half = shape[0] // 2
            dump = (dump_prefix or os.path.join(self.script_dir, f"enc_only_ne{ne}")) \
                + f"_slot{i}_{name}.npy"
            np.save(dump, out.float().numpy())
            rows.append({"slot": i, "masked": int(is_zero), "skipped": 0, "wall": wall,
                         "snr": _snr(out, cpu),
                         "lo": _snr(out[:half], cpu[:half]),
                         "hi": _snr(out[half:], cpu[half:]),
                         "mn": float(out.float().min()), "mx": float(out.float().max()),
                         "nan": int(out.float().isnan().sum()), "dump": dump})
            print(f"  [encoderend] slot {i} done in {wall:.3f}s")

        # Downstream, run_vision replaces a masked slot's tokens with the finite 1e-6
        # placeholder and records prefix_masked_cols. --encoderend stops at the encoder,
        # so it reports the RAW encoder output (that is the thing being A/B'd) and
        # just flags the slot; nothing in that path is changed or bypassed here.
        self.masked_vision_slots = masked_slots

        worker_lens = getattr(self, "_encoder_worker_prog_lens", []) or []
        half = shape[0] // 2
        encoded = [r for r in rows if not r["skipped"]]
        nan_total = sum(r["nan"] for r in encoded)

        # ---- greppable, format-identical summary (diff the two runs by eye) ----
        print("")
        print("=== ENC-ONLY SUMMARY ===")
        print(f"ENC_ONLY vis_num_engines   : {ne}")
        print(f"ENC_ONLY checkpoint        : {name} shape={tuple(shape)}")
        print(f"ENC_ONLY num_slots         : {len(rows)} (encoded={len(encoded)}, "
              f"masked={sorted(masked_slots)}, skip_zero_slots={self.SKIP_ZERO_VISION_SLOTS})")
        print(f"ENC_ONLY compile_seconds   : {compile_s:.3f}")
        print(f"ENC_ONLY primary_prog_bytes: {getattr(self, '_encoder_prog_len', 0)}")
        print(f"ENC_ONLY worker_prog_bytes : {worker_lens}")
        for r in rows:
            print(f"ENC_ONLY slot{r['slot']} masked={r['masked']} skipped={r['skipped']} "
                  f"wall_s={r['wall']:.3f} snr_db={r['snr']:.2f} "
                  f"snr_rows0_{half}_db={r['lo']:.2f} snr_rows{half}_{shape[0]}_db={r['hi']:.2f} "
                  f"min={r['mn']:.4f} max={r['mx']:.4f} nan={r['nan']}")
        print(f"ENC_ONLY total_wall_seconds: {total_wall:.3f}")
        print(f"ENC_ONLY mean_wall_seconds : "
              f"{(total_wall / len(encoded) if encoded else float('nan')):.3f}")
        print(f"ENC_ONLY nan_count_total   : {nan_total}")
        for r in rows:
            print(f"ENC_ONLY dump_slot{r['slot']}       : {r['dump']}")
        print("=== END ENC-ONLY SUMMARY ===")
        print("")
        assert nan_total == 0, (
            f"--encoderend produced {nan_total} NaN(s) in the encoder output -- an "
            f"all-zero (masked) slot must still encode to finite values.")
        base = os.path.join(self.script_dir, "enc_only_ne%d")
        print("[encoderend] compare the ne=1 and ne=2 runs per slot with:")
        for r in rows:
            if r["skipped"]:
                continue
            a = (base % 1) + f"_slot{r['slot']}_{name}.npy"
            b = (base % 2) + f"_slot{r['slot']}_{name}.npy"
            print(f"    python -c \"import numpy as np,sys;a=np.load(sys.argv[1]);"
                  f"b=np.load(sys.argv[2]);d=a-b;print(sys.argv[1].split('/')[-1],"
                  f"'bit-exact' if not d.any() else 'SNR %.2f dB'%"
                  f"(20*np.log10(np.linalg.norm(a)/np.linalg.norm(d))))\" {a} {b}")
        return [r["dump"] for r in rows]

    def run_prefix_end(self, images_hwc, prompt_tokens, dump_path=None):
        """--prefixend: encoder -> prefix (Gemma-2B KV-cache build) -> STOP.

        The next rung of the same ladder as --encoderend: identical greppable
        summary style, per-stage + cumulative wall-clock, oracle SNR, and a .npy
        dump so an --engines 1 run and an --engines 2 run can be scored against
        EACH OTHER (the real gate). No action-expert, no denoise loop, no actions.

        STAGE SHARDING: --engines N shards BOTH stages -- the vision encoder over
        its 256 patch tokens and the prefix over 64-row blocks of its S tokens
        (RoPE / permutes / attention stay on the primary). The summary prints the
        per-stage engine counts and the prefix's actual block split.

        Composes with --engines and PI05_DEBUG_STOP_AFTER (the latter halts the
        ENCODER program at its checkpoint; the prefix is then meaningless, so it
        is skipped and the summary says so).
        """
        ne_vis, ne_pre = self._num_engines("VIS"), self._num_engines("PREFIX")

        # ---- stage 1: vision encoder (sharded iff --engines > 1) ----
        t0 = time.perf_counter()
        vision_tokens = self.run_vision(images_hwc)
        t_vision = time.perf_counter() - t0
        n_enc = self._n_vision_slots_encoded()
        self._report_gflops(f"vision ({n_enc} slots)", self._vision_flops(), t_vision)

        if self._debug_halt_info is not None:
            print("")
            print("=== PREFIX-END SUMMARY ===")
            print(f"PREFIX_END engines_vision  : {ne_vis}")
            print(f"PREFIX_END engines_prefix  : {ne_pre}"
                  f"{' (row-sharded)' if ne_pre > 1 else ' (single-engine)'}")
            print(f"PREFIX_END aborted         : PI05_DEBUG_STOP_AFTER halted the encoder at "
                  f"checkpoint {self._debug_halt_info['idx']} "
                  f"({self._debug_halt_info['name']}); prefix skipped")
            print("=== END PREFIX-END SUMMARY ===")
            return None

        # ---- stage 2: prefix LM (row-sharded iff --engines > 1) ----
        t1 = time.perf_counter()
        seq_len = vision_tokens.shape[0] + self.PREFIX_TEXT_BUDGET
        valid_len = self.embed_and_concat_prefix(prompt_tokens, vision_tokens, seq_len=seq_len)
        if not getattr(self, "_prefix_compiled", False):
            self._prefix_prog_addr = self._compile_once(
                "prefix", lambda: self.compile_prefix(seq_len, valid_len), label="prefix")
            self._prefix_bias_dram = self.prefix_bias_dram
            self._prefix_compiled = True
        else:
            bias = self.build_prefix_attn_bias(seq_len, valid_len).contiguous()
            self.dma_write(DMA_DEVICE_H2C, self._prefix_bias_dram, bias.flatten(), bias.numel() * 2)
        self._execute_prefix(timeout=250.0)
        t_prefix = time.perf_counter() - t1
        self._report_gflops(f"prefix ({seq_len} tok)", self._prefix_flops(seq_len), t_prefix)

        # ---- read back the prefix stage's OUTPUT: the K/V cache ----
        # (2, n_layers, valid_len, HEAD_DIM) -- the only thing the prefix produces
        # and the only thing the action expert consumes.
        P, D, L = self.PREFIX_SEQ_LEN, self.HEAD_DIM, self.NUM_LAYERS
        hw = torch.empty(2, L, valid_len, D, dtype=torch.float32)
        for layer in range(L):
            for j, addr in enumerate((self.prefix_k_cache_addr[layer],
                                      self.prefix_v_cache_addr[layer])):
                buf = bytearray(P * D * 2)
                self._dma_read_checked(addr, buf, len(buf))
                t = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(P, D).float()
                hw[j, layer] = t[:valid_len]

        # ---- CPU oracle: pi05_torch_ref.prefix_forward, same IF4 weights ----
        # Fed the HW's OWN vision tokens, so this isolates the PREFIX stage's
        # execution rather than re-measuring the encoder's (already-known) drift.
        import pi05_torch_ref as _ref
        W = _ref.Weights(device="cpu", dtype=torch.bfloat16, quant="if4")
        embed_table = W["PaliGemma.llm.embedder.input_embedding"]
        text_tokens = embed_table[torch.tensor(prompt_tokens, dtype=torch.long)].to(torch.bfloat16)
        prefix_tokens = torch.cat([vision_tokens.to(torch.bfloat16), text_tokens], dim=0)[None]
        assert prefix_tokens.shape[1] == valid_len, \
            f"prefix rows {prefix_tokens.shape[1]} != valid_len {valid_len}"
        # MUST mirror the HW bias and rope positions or the comparison is
        # meaningless: build_prefix_attn_bias() masks the dead image slots
        # (prefix_masked_cols), and _rope_positions_prefix uses openpi's
        # positions = cumsum(mask) - 1, under which a masked slot FREEZES the
        # counter. Feeding the oracle an unmasked bias + arange positions scores
        # ~3 dB on a correct cache -- the same latent flaw the older
        # _prefix_snr_check has.
        masked_cols = getattr(self, "prefix_masked_cols", []) or None
        prefix_bias = _ref.build_prefix_attn_bias(valid_len, "cpu", torch.float32,
                                                  masked_cols=masked_cols)
        pmask = torch.ones(1, valid_len, dtype=torch.float32)
        for _a, _b in (masked_cols or []):
            pmask[:, int(_a):int(_b)] = 0.0
        prefix_positions = torch.cumsum(pmask, dim=1) - 1.0
        _, (k_cache, v_cache) = _ref.prefix_forward(prefix_tokens, prefix_bias, W,
                                                     positions=prefix_positions)
        cpu = torch.empty_like(hw)
        for layer in range(L):
            cpu[0, layer] = k_cache[layer].reshape(-1, D).float()[:valid_len]
            cpu[1, layer] = v_cache[layer].reshape(-1, D).float()[:valid_len]

        def _snr(a, b):
            n = (a - b).pow(2).sum().sqrt()
            g = b.pow(2).sum().sqrt()
            return float("inf") if n == 0 else float(20 * torch.log10(g / n.clamp_min(1e-12)))

        if dump_path is None:
            dump_path = os.path.join(self.script_dir, f"prefix_end_ne{ne_vis}_kv.npy")
        np.save(dump_path, hw.numpy())

        nan_total = int(hw.isnan().sum())
        # ---- greppable, format-identical summary ----
        print("")
        print("=== PREFIX-END SUMMARY ===")
        print(f"PREFIX_END engines_vision  : {ne_vis}"
              f"{' (row-sharded)' if ne_vis > 1 else ' (single-engine)'}")
        # Report what the prefix ACTUALLY ran on: _prefix_num_engines falls back to
        # 1 when seq_len cannot be 64-block-split, so the requested count can lie.
        _psplit = getattr(self, "_prefix_sched", None)
        ne_pre = _psplit.num_engines if _psplit is not None else 1
        print(f"PREFIX_END engines_prefix  : {ne_pre}"
              f"{' (row-sharded)' if ne_pre > 1 else ' (single-engine: prefix not sharded)'}")
        if _psplit is not None and _psplit.num_engines > 1:
            print(f"PREFIX_END prefix_split    : "
                  f"{[c for _, c in _psplit.split_rows(seq_len, mode='blocks')]} rows "
                  f"(64-row blocks of {seq_len})")
        print(f"PREFIX_END vision_slots    : {n_enc} encoded, "
              f"masked={sorted(getattr(self, 'masked_vision_slots', []))}")
        print(f"PREFIX_END seq_len         : {seq_len} (valid={valid_len}, "
              f"keep_masked_slots={self.KEEP_MASKED_SLOTS})")
        print(f"PREFIX_END kv_shape        : {tuple(hw.shape)} (K/V, layers, rows, head_dim)")
        # Masked (dead image slot) rows are -1e36'd out of every softmax, so their
        # K/V is never read by anything -- scoring them would poison the number
        # (feedback_masked_rows_poison_snr). Report the LIVE rows as the headline.
        live = torch.ones(valid_len, dtype=torch.bool)
        for _a, _b in (masked_cols or []):
            live[int(_a):int(_b)] = False
        print(f"PREFIX_END live_rows       : {int(live.sum())}/{valid_len} "
              f"(masked_cols={masked_cols or []})")
        print(f"PREFIX_END snr_kv_db       : {_snr(hw[:, :, live], cpu[:, :, live]):.2f}")
        print(f"PREFIX_END snr_kv_allrows_db: {_snr(hw, cpu):.2f}")
        print(f"PREFIX_END snr_k_db        : {_snr(hw[0][:, live], cpu[0][:, live]):.2f}")
        print(f"PREFIX_END snr_v_db        : {_snr(hw[1][:, live], cpu[1][:, live]):.2f}")
        print(f"PREFIX_END snr_layer0_db   : {_snr(hw[:, 0][:, live], cpu[:, 0][:, live]):.2f}")
        print(f"PREFIX_END snr_layer{L - 1}_db  : {_snr(hw[:, L - 1][:, live], cpu[:, L - 1][:, live]):.2f}")
        print(f"PREFIX_END wall_vision_s   : {t_vision:.3f}")
        print(f"PREFIX_END wall_prefix_s   : {t_prefix:.3f}")
        print(f"PREFIX_END wall_cumulative_s: {t_vision + t_prefix:.3f}")
        print(f"PREFIX_END out_min_max     : {float(hw.min()):.4f} {float(hw.max()):.4f}")
        print(f"PREFIX_END nan_count       : {nan_total}")
        print(f"PREFIX_END dump_npy        : {dump_path}")
        print("=== END PREFIX-END SUMMARY ===")
        print("")
        assert nan_total == 0, f"--prefixend produced {nan_total} NaN(s) in the prefix K/V cache"
        a = os.path.join(self.script_dir, "prefix_end_ne1_kv.npy")
        b = os.path.join(self.script_dir, "prefix_end_ne2_kv.npy")
        print(f"[prefixend] compare the ne=1 and ne=2 runs directly with:\n"
              f"    python -c \"import numpy as np,sys;a=np.load(sys.argv[1]);"
              f"b=np.load(sys.argv[2]);d=a-b;print('bit-exact' if not d.any() else "
              f"'SNR %.2f dB'%(20*np.log10(np.linalg.norm(a)/np.linalg.norm(d))))\" {a} {b}")
        return hw

    def _vision_snr_check(self, images_hwc, hw_vision_tokens):
        """CPU-vs-HW SNR check for the vision encoder output, using the SAME
        IF4-quantized weights (pi05_torch_ref.py's Weights(quant='if4')) so
        this isolates HW execution/precision drift, not a quantization-policy
        mismatch. images_hwc: the same list of 3 (224,224,3) float32 arrays
        [-1,1] passed to run_vision(). hw_vision_tokens: run_vision()'s return
        value -- only the KEPT (non-zero) slots, e.g. (512, 2048) for LIBERO's
        2 real cameras. Prints per-slot and overall SNR in dB (>=40dB is this
        codebase's usual correctness bar, see
        feedback_mobilesam_snr_validation_contract)."""
        import pi05_torch_ref as _ref
        W = _ref.Weights(device="cpu", dtype=torch.bfloat16, quant="if4")
        # Encode exactly the slots run_vision ACTUALLY returned, derived from the HW
        # row count -- do not assume a policy. Both are reachable from the CLI:
        #   --keep-masked-slots (DEFAULT ON): every slot is encoded and masked slots
        #     ride along as -inf-masked placeholder rows -> 3 slots, 768 rows.
        #   --no-keep-masked-slots / --skip-zero-vision-slots: all-zero slots are
        #     dropped from the prefix entirely -> 2 slots, 512 rows.
        # This check hardcoded the second one ("it drops all-zero slots from the
        # prefix entirely now"), which stopped being true when keep-masked-slots
        # became the default, so it asserted 768 != 512 before printing a number.
        masked = set(getattr(self, "masked_vision_slots", []))
        n_hw_slots = hw_vision_tokens.shape[0] // self.VIS_S
        if n_hw_slots == len(images_hwc):
            kept_idx = list(range(len(images_hwc)))          # masked slots carried
        else:
            kept_idx = [i for i in range(len(images_hwc)) if i not in masked]
        assert len(kept_idx) == n_hw_slots, (
            f"run_vision returned {n_hw_slots} slot(s) ({hw_vision_tokens.shape[0]} rows "
            f"/ VIS_S={self.VIS_S}) but the CPU side selected {len(kept_idx)} of "
            f"{len(images_hwc)} images (masked_vision_slots={sorted(masked)})")
        images_t = torch.stack([torch.from_numpy(images_hwc[i]) for i in kept_idx],
                               dim=0).to(torch.bfloat16)
        cpu_tokens = _ref.vision_encode(images_t, W).reshape(-1, hw_vision_tokens.shape[-1])

        hw = hw_vision_tokens.float()
        cpu = cpu_tokens.float()
        assert hw.shape == cpu.shape, f"vision rows {hw.shape} != cpu {cpu.shape}"
        print("=== vision encoder CPU-vs-HW SNR check ===")
        S = self.VIS_S
        _names = ("main", "wrist", "pad")
        # A masked slot's HW rows are NOT an encode: run_vision overwrites them with
        # the finite 1e-6 placeholder (see the "Overwrite any masked slot" step),
        # because the slot is -inf-masked out of all attention and its content is
        # never read. The CPU oracle still encodes that image for real, so the two
        # are structurally incomparable and score ~0 dB by construction. Folding
        # them into `overall` buried 512 good rows under 256 meaningless ones and
        # reported 5.95 dB for an encoder whose real slots were at ~22-24 dB --
        # the masked-rows-poison-SNR trap the README warns about. Score the real
        # slots, and report the masked ones as the placeholders they are.
        live = []
        for j, i in enumerate(kept_idx):
            name = _names[i] if i < len(_names) else f"slot{i}"
            h, c = hw[j * S:(j + 1) * S], cpu[j * S:(j + 1) * S]
            if i in masked:
                print(f"  slot {i} ({name}): MASKED placeholder (1e-6 rows, -inf-masked "
                      f"in attention) -- not scored, excluded from overall")
                continue
            live.append((h, c))
            noise = (h - c).pow(2).sum().sqrt()
            signal = c.pow(2).sum().sqrt()
            snr_db = 20 * torch.log10(signal / noise.clamp_min(1e-12))
            print(f"  slot {i} ({name}): SNR={snr_db:.2f}dB  hw[min={h.min():.3f},max={h.max():.3f}] "
                  f"cpu[min={c.min():.3f},max={c.max():.3f}]")
        if live:
            hw_live = torch.cat([h for h, _ in live], dim=0)
            cpu_live = torch.cat([c for _, c in live], dim=0)
            noise = (hw_live - cpu_live).pow(2).sum().sqrt()
            signal = cpu_live.pow(2).sum().sqrt()
            overall_snr_db = 20 * torch.log10(signal / noise.clamp_min(1e-12))
            print(f"  overall (unmasked slots only): SNR={overall_snr_db:.2f}dB")

    def _prefix_snr_check(self, prompt_tokens, vision_tokens, valid_len):
        """CPU-vs-HW SNR check for the prefix's K/V cache (layer 0 and the
        last layer), same IF4-quantized weights as _vision_snr_check. Runs
        the CPU reference's prefix_forward on the UNPADDED (vision + real
        text tokens only, valid_len rows) prefix -- our HW pads to seq_len
        with epsilon-fill rows the CPU reference has no equivalent of, so
        only the first valid_len rows of the HW K/V cache are comparable."""
        import pi05_torch_ref as _ref
        W = _ref.Weights(device="cpu", dtype=torch.bfloat16, quant="if4")

        embed_table = W["PaliGemma.llm.embedder.input_embedding"]
        tid = torch.tensor(prompt_tokens, dtype=torch.long)
        text_tokens = embed_table[tid].to(torch.bfloat16)  # (n_text, 2048)
        n_vis = vision_tokens.shape[0]
        prefix_tokens = torch.cat([vision_tokens.to(torch.bfloat16), text_tokens], dim=0)[None]  # (1, valid_len, 2048)
        assert prefix_tokens.shape[1] == valid_len

        prefix_bias = _ref.build_prefix_attn_bias(valid_len, "cpu", torch.float32)
        _, (k_cache, v_cache) = _ref.prefix_forward(prefix_tokens, prefix_bias, W)

        P, D = self.PREFIX_SEQ_LEN, self.HEAD_DIM
        print("=== prefix K/V CPU-vs-HW SNR check ===")
        for layer in (0, self.NUM_LAYERS - 1):
            for name, hw_addr, cpu_t in (
                ("K", self.prefix_k_cache_addr[layer], k_cache[layer]),
                ("V", self.prefix_v_cache_addr[layer], v_cache[layer]),
            ):
                buf = bytearray(P * D * 2)
                self._dma_read_checked(hw_addr, buf, len(buf))
                hw = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(P, D).float()[:valid_len]
                cpu = cpu_t.reshape(-1, D).float()[:valid_len]
                noise = (hw - cpu).pow(2).sum().sqrt()
                signal = cpu.pow(2).sum().sqrt()
                snr_db = 20 * torch.log10(signal / noise.clamp_min(1e-12))
                print(f"  layer{layer} {name}: SNR={snr_db:.2f}dB  hw[min={hw.min():.3f},max={hw.max():.3f}] "
                      f"cpu[min={cpu.min():.3f},max={cpu.max():.3f}]")

    def _prefix_layer_snr_report(self, prompt_tokens, vision_tokens, valid_len):
        """Per-layer CPU-vs-HW SNR for the prefix's hidden-state output (post
        residual2, every layer), using PREFIX_LAYER_SNAPSHOT_DRAM. Answers
        'is the divergence already there in layer0, or does it accumulate?' --
        reimplements pi05_torch_ref.prefix_forward's loop body layer-by-layer
        (instead of calling it directly) so we can grab x after each layer,
        not just the final K/V cache."""
        import pi05_torch_ref as _ref
        W = _ref.Weights(device="cpu", dtype=torch.bfloat16, quant="if4")

        embed_table = W["PaliGemma.llm.embedder.input_embedding"]
        tid = torch.tensor(prompt_tokens, dtype=torch.long)
        text_tokens = embed_table[tid].to(torch.bfloat16)
        prefix_tokens = torch.cat([vision_tokens.to(torch.bfloat16), text_tokens], dim=0)[None]
        assert prefix_tokens.shape[1] == valid_len
        prefix_bias = _ref.build_prefix_attn_bias(valid_len, "cpu", torch.float32)

        x = prefix_tokens
        print("=== prefix per-layer hidden-state CPU-vs-HW SNR report ===")
        for layer in range(self.NUM_LAYERS):
            norm_s = W["PaliGemma.llm.layers.pre_attention_norm.scale"][layer]
            h = _ref.rms_norm(x, norm_s)
            attn_out, _, _ = _ref.joint_attention(h, None, prefix_bias, layer, W)
            x = x + attn_out

            norm2_s = W["PaliGemma.llm.layers.pre_ffw_norm.scale"][layer]
            h2 = _ref.rms_norm(x, norm2_s)
            mlp_out = _ref.gated_mlp(h2, W["PaliGemma.llm.layers.mlp.gating_einsum"][layer],
                                      W["PaliGemma.llm.layers.mlp.linear"][layer])
            x = x + mlp_out
            cpu_layer = x[0].float()  # (valid_len, H)

            addr = self.PREFIX_LAYER_SNAPSHOT_DRAM[layer]
            S, H = self.PREFIX_SEQ_LEN, self.HIDDEN_SIZE
            buf = bytearray(S * H * 2)
            self._dma_read_checked(addr, buf, len(buf))
            hw_layer = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(S, H).float()[:valid_len]

            noise = (hw_layer - cpu_layer).pow(2).sum().sqrt()
            signal = cpu_layer.pow(2).sum().sqrt()
            snr_db = 20 * torch.log10(signal / noise.clamp_min(1e-12))
            print(f"  layer{layer}: SNR={snr_db:.2f}dB  hw[min={hw_layer.min():.3f},max={hw_layer.max():.3f}] "
                  f"cpu[min={cpu_layer.min():.3f},max={cpu_layer.max():.3f}]")

    def _prefix_layer0_op_snr_report(self, prompt_tokens, vision_tokens, valid_len):
        """Op-by-op CPU-vs-HW SNR for layer0 ONLY, using PREFIX_L0_SNAPSHOT_DRAM
        (layer0's scratch buffers snapshotted before layer1 overwrites them).
        Reimplements joint_attention's internals manually (instead of calling
        it as a black box) so every HW checkpoint (ln1, q/k/v proj, q_permute,
        head0-7, attn_permute, o_proj_residual, ln2, mlp_lo/hi/down) has a
        directly matching CPU intermediate to diff against -- pinpoints
        exactly which op inside layer0 first diverges."""
        import pi05_torch_ref as _ref
        import torch.nn.functional as _F
        W = _ref.Weights(device="cpu", dtype=torch.bfloat16, quant="if4")

        embed_table = W["PaliGemma.llm.embedder.input_embedding"]
        tid = torch.tensor(prompt_tokens, dtype=torch.long)
        text_tokens = embed_table[tid].to(torch.bfloat16)
        x_in = torch.cat([vision_tokens.to(torch.bfloat16), text_tokens], dim=0)[None]  # (1, valid_len, H)
        assert x_in.shape[1] == valid_len

        S, H, D = self.PREFIX_SEQ_LEN, self.HIDDEN_SIZE, self.HEAD_DIM
        NH = self.NUM_HEADS
        snap = self.PREFIX_L0_SNAPSHOT_DRAM

        def _hw(name, numel, shape):
            buf = bytearray(numel * 2)
            self._dma_read_checked(snap[name], buf, len(buf))
            return torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(shape).clone().float()

        def _snr(hw_t, cpu_t):
            hw_t, cpu_t = hw_t.float(), cpu_t.float()
            noise = (hw_t - cpu_t).pow(2).sum().sqrt()
            signal = cpu_t.pow(2).sum().sqrt()
            return (20 * torch.log10(signal / noise.clamp_min(1e-12))).item(), hw_t, cpu_t

        def _report(name, hw_t, cpu_t):
            snr_db, hw_t, cpu_t = _snr(hw_t, cpu_t)
            print(f"  {name}: SNR={snr_db:.2f}dB  hw[min={hw_t.min():.3f},max={hw_t.max():.3f}] "
                  f"cpu[min={cpu_t.min():.3f},max={cpu_t.max():.3f}]")

        print("=== prefix layer0 op-by-op CPU-vs-HW SNR report ===")

        # 1. ln1
        norm_s = W["PaliGemma.llm.layers.pre_attention_norm.scale"][0]
        h = _ref.rms_norm(x_in, norm_s)
        _report("ln1", _hw("ln1", S * H, (S, H))[:valid_len], h[0])

        # 2. q/k/v proj
        q_ein = W["PaliGemma.llm.layers.attn.q_einsum.w"][0]     # (8, 2048, 256)
        kv_ein = W["PaliGemma.llm.layers.attn.kv_einsum.w"][0]   # (2, 1, 2048, 256)
        q_pre = torch.einsum("btd,hdk->bthk", h, q_ein)          # (1, T, 8, 256)
        k_pre = torch.einsum("btd,hdc->bthc", h, kv_ein[0])      # (1, T, 1, 256)
        v_pre = torch.einsum("btd,hdc->bthc", h, kv_ein[1])
        _report("q_proj", _hw("q_proj", S * H, (S, H))[:valid_len], q_pre[0].reshape(-1, NH * D))
        _report("k_proj", _hw("k_proj", S * D, (S, D))[:valid_len], k_pre[0].reshape(-1, D))
        _report("v_proj", _hw("v_proj", S * D, (S, D))[:valid_len], v_pre[0].reshape(-1, D))


        # 2b. RoPE on q/k (the HW now rotates both before permute/attention, and caches
        # the ROTATED k). Golden must rotate too, else q_permute/head* diverge spuriously.
        # Positions = cumsum(mask)-1 -- same helper the HW table is built from.
        pos_full, _n_valid = self._rope_positions_prefix(S, valid_len)
        pos = pos_full[:valid_len].to(torch.float32)[None]           # (1, T)
        q_rope = _ref.apply_rope(q_pre, pos)                          # (1, T, 8, 256)
        k_rope = _ref.apply_rope(k_pre, pos)                          # (1, T, 1, 256)
        if "q_rope" in snap:
            # The "q_rope" SNAPSHOT is no longer roped Q. compile_prefix permutes
            # BEFORE rotating (the matmul RoPE wants a head-major (NH*S, D) batch),
            # so LAYER0_Q_ROPE_DRAM is the head-major PRE-rotation Q and its true
            # layout is (NH, S, D), not (S, H). Roped Q is still fully checked one
            # step below, as q_permute. Compare this against the permuted q_pre so
            # the checkpoint still isolates the permute from the rotation.
            _report("q_perm_preroped",
                    _hw("q_rope", S * H, (NH, S, D))[:, :valid_len, :],
                    q_pre[0].permute(1, 0, 2))
            _report("k_rope", _hw("k_rope", S * D, (S, D))[:valid_len],
                    k_rope[0].reshape(-1, D))
        if os.environ.get("PI05_DUMP_L0"):
            _p = os.path.join(os.path.dirname(__file__), "debug_l0.npz")
            np.savez(_p,
                     hw_ln1=_hw("ln1", S * H, (S, H))[:valid_len].numpy(),
                     cpu_ln1=h[0].float().numpy(),
                     hw_q=_hw("q_proj", S * H, (S, H))[:valid_len].numpy(),
                     cpu_q=q_pre[0].reshape(-1, NH * D).float().numpy(),
                     hw_k=_hw("k_proj", S * D, (S, D))[:valid_len].numpy(),
                     cpu_k=k_pre[0].reshape(-1, D).float().numpy(),
                     hw_v=_hw("v_proj", S * D, (S, D))[:valid_len].numpy(),
                     cpu_v=v_pre[0].reshape(-1, D).float().numpy(),
                     # hw_qrope is head-major PRE-rotation Q now (see above); the
                     # roped comparison lives in hw/cpu q_permute.
                     hw_qperm_preroped=_hw("q_rope", S * H, (NH, S, D))[:, :valid_len, :].numpy(),
                     cpu_qperm_preroped=q_pre[0].permute(1, 0, 2).float().numpy(),
                     hw_krope=_hw("k_rope", S * D, (S, D))[:valid_len].numpy(),
                     cpu_qrope=q_rope[0].reshape(-1, NH * D).float().numpy(),
                     cpu_krope=k_rope[0].reshape(-1, D).float().numpy(),
                     pos=pos[0].numpy(),
                     valid_len=np.array([valid_len]))
            print(f"  [dump] wrote {_p}")

        # 3. q_permute: (seq,heads,D) -> (heads,seq,D); HW buffer's TRUE layout is
        # (NH, S, D) flattened, NOT a plain (S,H) reshape despite the debug_op shape arg.
        # HW permutes the ROPED q, so compare against the roped golden.
        q_perm_cpu = q_rope[0].permute(1, 0, 2)  # (8, T, 256)
        q_perm_hw = _hw("q_permute", S * H, (NH, S, D))[:, :valid_len, :]
        _report("q_permute", q_perm_hw, q_perm_cpu)

        # 4. per-head attention (bidirectional, no mask -- prefix_bias is all-zero)
        qf = q_rope.permute(0, 2, 1, 3).float()                     # (1, 8, T, 256) ROPED
        kf = k_rope.permute(0, 2, 1, 3).float().expand(-1, NH, -1, -1)  # ROPED
        vf = v_pre.permute(0, 2, 1, 3).float().expand(-1, NH, -1, -1)   # V is NOT roped
        attn = _F.scaled_dot_product_attention(qf, kf, vf)         # (1, 8, T, 256)
        for hd in range(NH):
            hw_head = _hw(f"head{hd}", S * D, (S, D))[:valid_len]
            _report(f"head{hd}", hw_head, attn[0, hd])

        # 5. attn_permute: (heads,seq,D) -> (seq, heads*D), token-major again
        attn_permuted_cpu = attn[0].permute(1, 0, 2).reshape(-1, NH * D)  # (T, 2048)
        _report("attn_permute", _hw("attn_permute", S * H, (S, H))[:valid_len], attn_permuted_cpu)

        # 6. o_proj + residual
        o_ein = W["PaliGemma.llm.layers.attn.attn_vec_einsum.w"][0]  # (8, 256, 2048)
        pre_attn_out = torch.einsum("thk,hkd->td", attn[0].permute(1, 0, 2).to(x_in.dtype), o_ein)
        o_proj_residual_cpu = x_in[0] + pre_attn_out
        _report("o_proj_residual", _hw("o_proj_residual", S * H, (S, H))[:valid_len], o_proj_residual_cpu)

        # 7. ln2
        norm2_s = W["PaliGemma.llm.layers.pre_ffw_norm.scale"][0]
        h2 = _ref.rms_norm(o_proj_residual_cpu[None], norm2_s)
        _report("ln2", _hw("ln2", S * H, (S, H))[:valid_len], h2[0])

        # 8. gated-GELU MLP, FF_HALF split (matches HW's parakeet-style N-split)
        gating = W["PaliGemma.llm.layers.mlp.gating_einsum"][0]  # (2, H, I)
        linear = W["PaliGemma.llm.layers.mlp.linear"][0]         # (I, H)
        I = gating.shape[-1]
        FF_HALF = I // 2
        gate_w, up_w = gating[0], gating[1]
        mlp_halves = {}
        for name, sl in (("mlp_lo", slice(0, FF_HALF)), ("mlp_hi", slice(FF_HALF, I))):
            gate_act = _F.gelu(h2 @ gate_w[:, sl], approximate="none")
            up = h2 @ up_w[:, sl]
            mlp_half = (gate_act * up) @ linear[sl, :]
            mlp_halves[name] = mlp_half
            _report(name, _hw(name, S * H, (S, H))[:valid_len], mlp_half[0])

        mlp_down_cpu = (mlp_halves["mlp_lo"] + mlp_halves["mlp_hi"])[0]
        _report("mlp_down", _hw("mlp_down", S * H, (S, H))[:valid_len], mlp_down_cpu)

    def probe_nan_report(self):
        """Post-run bulk NaN/Inf scan of every vision layer + every denoise step,
        using the snapshot buffers compile_encoder/compile_denoise_loop copy
        each layer/step's output into during the single real run (see
        VIS_LAYER_SNAPSHOT_DRAM / AE_STEP_SNAPSHOT_DRAM). Cheap: one DMA read
        per layer/step, no recompiling or re-executing anything -- call this
        once after run_inference() (or run_vision()/compile_denoise_loop()
        individually) to see exactly where (if anywhere) NaN first appears,
        instead of guessing or paying for N separate halt-recompile-rerun probes."""
        S_vis, H_vis = self.VIS_S, self.VIS_H
        print("=== vision layer NaN report ===")
        first_bad = None
        for i, addr in enumerate(getattr(self, "VIS_LAYER_SNAPSHOT_DRAM", [])):
            buf = bytearray(S_vis * H_vis * 2)
            self._dma_read_checked(addr, buf, len(buf))
            out = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(S_vis, H_vis).float()
            n_nan, n_inf = torch.isnan(out).sum().item(), torch.isinf(out).sum().item()
            flag = " <-- FIRST BAD" if (n_nan or n_inf) and first_bad is None else ""
            if flag:
                first_bad = f"vision_layer{i}"
            print(f"  vision_layer{i}: nan={n_nan} inf={n_inf} min={out.min():.4f} max={out.max():.4f}{flag}")

        print("=== denoise step NaN report ===")
        S_ae, AD = self.AE_ACTION_HORIZON_PADDED, self.AE_XT_WIDTH  # snapshots are 64-wide
        for i, addr in enumerate(getattr(self, "AE_STEP_SNAPSHOT_DRAM", [])):
            buf = bytearray(S_ae * AD * 2)
            self._dma_read_checked(addr, buf, len(buf))
            out = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(S_ae, AD).float()
            n_nan, n_inf = torch.isnan(out).sum().item(), torch.isinf(out).sum().item()
            flag = " <-- FIRST BAD" if (n_nan or n_inf) and first_bad is None else ""
            if flag:
                first_bad = f"denoise_step{i}"
            print(f"  denoise_step{i}: nan={n_nan} inf={n_inf} min={out.min():.4f} max={out.max():.4f}{flag}")

        print(f"first bad checkpoint: {first_bad or 'none -- all clean'}")
        return first_bad

    def dump_prefix_kv(self, path):
        """Dump the persistent prefix K/V cache (LAYER0_K_DRAM/LAYER0_V_DRAM,
        all NUM_LAYERS layers) + PREFIX_SEQ_LEN/prefix_valid_len to a single
        .npz on disk, so a later --debug run can reload it and skip the ~185s
        vision+prefix recompute entirely when only iterating on the denoise
        loop. Call after compile_prefix has run (self.prefix_valid_len set)."""
        kv_total = self.NUM_LAYERS * self.KV_LAYER_STRIDE
        buf_k = bytearray(kv_total)
        buf_v = bytearray(kv_total)
        self._dma_read_checked(self.LAYER0_K_DRAM, buf_k, kv_total)
        self._dma_read_checked(self.LAYER0_V_DRAM, buf_v, kv_total)
        mcols = np.array(getattr(self, "prefix_masked_cols", []), dtype=np.int64).reshape(-1, 2)
        np.savez(path, k=np.frombuffer(bytes(buf_k), dtype=np.uint16),
                  v=np.frombuffer(bytes(buf_v), dtype=np.uint16),
                  prefix_seq_len=self.PREFIX_SEQ_LEN, prefix_valid_len=self.prefix_valid_len,
                  masked_cols=mcols)
        print(f"[dump_prefix_kv] wrote {path} ({kv_total*2/1024/1024:.1f} MB K + V, "
              f"seq_len={self.PREFIX_SEQ_LEN}, valid_len={self.prefix_valid_len})")
    def verify_denoise_step0(self, kv_npz_path, device="cuda"):
        """Diff the FPGA's step-0 action-expert intermediates against a torch
        reference computed with the SAME noise and the SAME prefix K/V (loaded
        from kv_npz_path). Feeding the reference the FPGA's own K/V isolates the
        action-expert forward -- any divergence here is a kernel bug, not a
        prefix problem. Prints SNR per intermediate so the FIRST one that craters
        pinpoints the broken op. Requires DENOISE_STEP0_PROBE=True during compile."""
        import pi05_torch_ref as _ref
        import torch.nn.functional as F
        if not torch.cuda.is_available():
            device = "cpu"
        S, H, D = self.AE_ACTION_HORIZON_PADDED, self.AE_HIDDEN, self.HEAD_DIM
        AH, AD = self.AE_ACTION_HORIZON, self.AE_ACTION_DIM_PADDED

        def _read(addr, numel):
            buf = bytearray(numel * 2)
            self._dma_read_checked(addr, buf, numel * 2)
            return torch.frombuffer(bytes(buf), dtype=torch.bfloat16).float()

        fpga_in   = _read(self.AE_P0_ACTION_IN, S * H).reshape(S, H)[:AH]
        fpga_time = _read(self.AE_P0_TIME_EMB, H).reshape(1, H)
        fpga_l0   = _read(self.AE_P0_SUF_L0, S * H).reshape(S, H)[:AH]
        fpga_l17  = _read(self.AE_P0_SUF_L17, S * H).reshape(S, H)[:AH]
        XW = self.AE_XT_WIDTH
        fpga_vt   = _read(self.AE_P0_VT, S * XW).reshape(S, XW)[:AH, :7]
        fpga_xtpad = _read(self.AE_P0_XT_PAD, S * XW).reshape(S, XW)[:AH]  # 64-wide input to action_in_proj
        fpga_l0norm  = _read(self.AE_P0_L0_NORM, S * H).reshape(S, H)[:AH]
        fpga_l0attn  = _read(self.AE_P0_L0_ATTN, S * H).reshape(S, H)[:AH]
        fpga_l0resid = _read(self.AE_P0_L0_RESID, S * H).reshape(S, H)[:AH]
        # heads 0-1 stacked Q and raw attention output (pre o-proj), (2, S, D)
        fpga_l0q    = _read(self.AE_P0_L0_Q, 2 * S * D).reshape(2, S, D)[:, :AH]
        NH_ = self.AE_HEADS
        fpga_l0raw  = _read(self.AE_P0_L0_ATTNRAW, NH_ * S * D).reshape(NH_, S, D)[:, :AH]
        fpga_l0qrope = _read(self.AE_P0_L0_QROPE, 2 * S * D).reshape(2, S, D)[:, :AH]
        fpga_l0ksuf  = _read(self.AE_P0_L0_KSUF, S * D).reshape(S, D)[:AH]

        # --- reference step-0 with FPGA's own K/V ---
        npz = np.load(kv_npz_path)
        vlen = int(npz["prefix_valid_len"])
        stride = npz["k"].size // (self.NUM_LAYERS * D)
        fk = torch.frombuffer(npz["k"].tobytes(), dtype=torch.bfloat16).float().reshape(self.NUM_LAYERS, stride, D)
        fv = torch.frombuffer(npz["v"].tobytes(), dtype=torch.bfloat16).float().reshape(self.NUM_LAYERS, stride, D)
        W = _ref.Weights(device=device, dtype=torch.bfloat16, quant="if4")
        dt_ = W.dtype
        # (b,P,1,D) kv cache from the FPGA's cached prefix rows [0:vlen]
        k_cache = [fk[L, :vlen].to(device, dt_)[None, :, None, :] for L in range(self.NUM_LAYERS)]
        v_cache = [fv[L, :vlen].to(device, dt_)[None, :, None, :] for L in range(self.NUM_LAYERS)]
        kv_cache = (k_cache, v_cache)

        noise = torch.zeros(1, AH, AD, device=device, dtype=torch.float32)
        noise[..., :7] = torch.from_numpy(np.random.RandomState(0).randn(AH, 7).astype(np.float32)).to(device)
        x_t = noise
        t = torch.ones(1, device=device, dtype=torch.float32)

        ref_in = (x_t.to(dt_) @ W["action_in_proj.kernel"]) + W["action_in_proj.bias"]  # (1,AH,H)
        time_emb = _ref.sincos_pos_embed(t, dim=H).to(dt_)
        time_emb = F.silu((time_emb @ W["time_mlp_in.kernel"]) + W["time_mlp_in.bias"])
        time_emb = F.silu((time_emb @ W["time_mlp_out.kernel"]) + W["time_mlp_out.bias"])  # (1,H)

        suffix_bias = _ref.build_suffix_attn_bias(vlen, AH, device, torch.float32,
                                                   masked_cols=getattr(self, "prefix_masked_cols", []))
        # Suffix RoPE positions: same rule as pi05_torch_ref.run_pi05 --
        #   sum(prefix_mask) + cumsum(suffix_mask) - 1  ==  vlen + arange(AH).
        # WITHOUT this the golden below runs a rope-FREE suffix, which is exactly
        # what hid the suffix-rope bug (every L0 number below was measured against
        # an un-roped reference).
        # NOTE: n_valid is NOT vlen -- the masked image slot's 256 rows are inside
        # [0:vlen] but do not advance the position counter (cumsum(mask)-1).
        _, _n_valid = self._rope_positions_prefix(self.PREFIX_SEQ_LEN, vlen)
        print(f"  [rope] prefix valid_len={vlen}  n_valid(positions)={_n_valid}  "
              f"suffix positions {_n_valid}..{_n_valid + AH - 1}")
        suffix_positions = (_n_valid + torch.arange(AH, device=device, dtype=torch.float32))[None, :]  # (1, AH)

        x = ref_in
        ref_layer_out = {}
        for layer in range(self.NUM_LAYERS):
            dw = W["PaliGemma.llm.layers.pre_attention_norm_1.Dense_0.kernel"][layer]
            db = W["PaliGemma.llm.layers.pre_attention_norm_1.Dense_0.bias"][layer]
            h, gate = _ref.ada_rms_norm(x, time_emb, dw, db)
            _, attn_out, _ = _ref.joint_attention(None, h, suffix_bias, layer, W, kv_cache=kv_cache,
                                                  positions=suffix_positions)
            if layer == 0:
                ref_l0norm, ref_l0attn = h, attn_out
                # per-head Q + raw attention (pre o-proj) for the Q-population / attn split
                _qe = W["PaliGemma.llm.layers.attn.q_einsum_1.w"][0]
                _kve = W["PaliGemma.llm.layers.attn.kv_einsum_1.w"][0]
                _qs = torch.einsum("btd,hdk->bthk", h.to(dt_), _qe)          # (1,AH,8,D) PRE-rope
                _ks = torch.einsum("btd,hdc->bthc", h.to(dt_), _kve[0])       # (1,AH,1,D) PRE-rope
                _vs = torch.einsum("btd,hdc->bthc", h.to(dt_), _kve[1])
                _qsr = _ref.apply_rope(_qs, suffix_positions)                 # ROPED
                _ksr = _ref.apply_rope(_ks, suffix_positions)                 # ROPED
                _kall = torch.cat([k_cache[0], _ksr.to(dt_)], dim=1).permute(0, 2, 1, 3).float().expand(-1, 8, -1, -1)
                _vall = torch.cat([v_cache[0], _vs], dim=1).permute(0, 2, 1, 3).float().expand(-1, 8, -1, -1)
                _qf = _qsr.permute(0, 2, 1, 3).float()
                _b = suffix_bias.float()
                _b = _b[None, None] if _b.dim() == 2 else _b[:, None]
                _raw = F.scaled_dot_product_attention(_qf, _kall, _vall, attn_mask=_b).permute(0, 2, 1, 3)  # (1,AH,8,D)
                ref_l0q = _qs[0].permute(1, 0, 2)          # (8, AH, D) pre-rope
                ref_l0qrope = _qsr[0].permute(1, 0, 2)     # (8, AH, D) roped
                ref_l0ksuf = _ksr[0, :, 0, :]              # (AH, D) roped suffix K
                ref_l0raw = _raw[0].permute(1, 0, 2)   # (8, AH, D)
                ref_o_ein = W["PaliGemma.llm.layers.attn.attn_vec_einsum_1.w"][0]  # (8, D, H)
            x = x + gate[:, None, :] * attn_out
            if layer == 0:
                ref_l0resid = x
            dw2 = W["PaliGemma.llm.layers.pre_ffw_norm_1.Dense_0.kernel"][layer]
            db2 = W["PaliGemma.llm.layers.pre_ffw_norm_1.Dense_0.bias"][layer]
            h2, gate2 = _ref.ada_rms_norm(x, time_emb, dw2, db2)
            mlp_out = _ref.gated_mlp(h2, W["PaliGemma.llm.layers.mlp_1.gating_einsum"][layer],
                                     W["PaliGemma.llm.layers.mlp_1.linear"][layer])
            x = x + gate2[:, None, :] * mlp_out
            ref_layer_out[layer] = x
        fdw = W["PaliGemma.llm.final_norm_1.Dense_0.kernel"]
        fdb = W["PaliGemma.llm.final_norm_1.Dense_0.bias"]
        x_norm, _ = _ref.ada_rms_norm(x, time_emb, fdw, fdb)
        ref_vt = ((x_norm.float() @ W["action_out_proj.kernel"].float()) + W["action_out_proj.bias"].float())[..., :7]

        def _snr(a, b):
            a, b = a.float().cpu(), b.float().cpu()
            return 20 * torch.log10(b.norm() / (a - b).norm().clamp_min(1e-12)).item()

        # staged x_t_pad check: expected (AH,64) = [noise(AH,32) | zeros(AH,32)]
        exp_xtpad = torch.zeros(AH, 64)
        exp_xtpad[:, :AD] = noise.squeeze(0).float().cpu()
        print("=== Step-0 action-expert intermediate SNR: FPGA vs reference (same noise + FPGA K/V) ===")
        print(f"  x_t_pad (staged input) : {_snr(fpga_xtpad, exp_xtpad):7.2f}dB   "
              f"[cols0:7 {'OK' if torch.allclose(fpga_xtpad[:, :7], exp_xtpad[:, :7], atol=0.05) else 'MISMATCH'}, "
              f"cols32:64 max={fpga_xtpad[:, 32:].abs().max().item():.3f} (expect ~0)]")
        torch.set_printoptions(precision=4, sci_mode=False)
        print(f"    [raw] FPGA x_t_pad rows0-2, cols0:8:\n{fpga_xtpad[:3, :8]}")
        print(f"    [raw] EXPECTED       rows0-2, cols0:8:\n{exp_xtpad[:3, :8]}")
        print(f"    [raw] FPGA x_t_pad col0 (all 10 rows): {fpga_xtpad[:, 0].tolist()}")
        print(f"    [raw] EXPECTED       col0 (all 10 rows): {exp_xtpad[:, 0].tolist()}")
        print(f"  action_in_proj : {_snr(fpga_in,   ref_in.squeeze(0)):7.2f}dB")
        print(f"  time_embed     : {_snr(fpga_time, time_emb):7.2f}dB")
        print(f"  -- layer0 internals --")
        print(f"    L0 preattn_norm : {_snr(fpga_l0norm,  ref_l0norm.squeeze(0)):7.2f}dB")
        print(f"    L0 Q head0      : {_snr(fpga_l0q[0], ref_l0q[0]):7.2f}dB   (Q population)")
        print(f"    L0 Q head1      : {_snr(fpga_l0q[1], ref_l0q[1]):7.2f}dB")
        print(f"    L0 Qrope head0  : {_snr(fpga_l0qrope[0], ref_l0qrope[0]):7.2f}dB   (suffix RoPE on Q)")
        print(f"    L0 Qrope head1  : {_snr(fpga_l0qrope[1], ref_l0qrope[1]):7.2f}dB")
        print(f"    L0 Ksuf rope    : {_snr(fpga_l0ksuf, ref_l0ksuf):7.2f}dB   (suffix RoPE on K)")
        print(f"    L0 rawattn head0: {_snr(fpga_l0raw[0], ref_l0raw[0]):7.2f}dB   (attention, pre o-proj)")
        print(f"    L0 rawattn head1: {_snr(fpga_l0raw[1], ref_l0raw[1]):7.2f}dB")
        for _h in range(2, NH_):
            print(f"    L0 rawattn head{_h}: {_snr(fpga_l0raw[_h], ref_l0raw[_h]):7.2f}dB")
        # o-proj ISOLATION: golden o-proj applied to the FPGA's OWN raw attention.
        # If this is high but L0 attn_out is low, the o-proj matmul/accumulate is
        # the broken op (not its input).
        _oproj_from_fpga = torch.einsum("htk,hkd->td",
                                        fpga_l0raw.to(ref_o_ein.device).to(ref_o_ein.dtype),
                                        ref_o_ein).float().cpu()
        print(f"    L0 o-proj(iso)  : {_snr(fpga_l0attn, _oproj_from_fpga):7.2f}dB   "
              f"(golden o-proj on FPGA's own rawattn -> isolates the o-proj matmul)")
        print(f"    L0 attn_out     : {_snr(fpga_l0attn,  ref_l0attn.squeeze(0)):7.2f}dB   (post o-proj)")
        print(f"    L0 attn_residual: {_snr(fpga_l0resid, ref_l0resid.squeeze(0)):7.2f}dB")
        print(f"  suffix_layer0  : {_snr(fpga_l0,   ref_layer_out[0].squeeze(0)):7.2f}dB")
        print(f"  suffix_layer17 : {_snr(fpga_l17,  ref_layer_out[self.NUM_LAYERS-1].squeeze(0)):7.2f}dB")
        print(f"  v_t (out_proj) : {_snr(fpga_vt,   ref_vt.squeeze(0)):7.2f}dB")
        print("  ^ first line that craters (<~10dB) = the op that breaks. All high = bug is downstream (euler/snapshot).")

    def _run_sanity_matmul(self, M, K, N, use_pbi):
        """Compile+run ONE plain bf16 A(M,K) @ B(K,N) matmul (A @ B^T) and
        return (hw_out, cpu_out). If use_pbi, drive the M-loop through a
        freshly-allocated gpr primed with ADD_SET(M) -- byte-for-byte the same
        register-priming path compile_denoise_loop uses for ae_S_reg (which,
        in a full run, reuses the exact physical GPR index prefix left dirty).
        If not use_pbi, use the legacy static-M path (what the first passing
        sanity check exercised)."""
        torch.manual_seed(0)
        A = torch.randn(M, K, dtype=torch.bfloat16)
        B = torch.randn(N, K, dtype=torch.bfloat16)  # (N,K), matmat_mul_core computes A @ B^T
        bpe = 2
        a_addr = store_weight(self, A)
        b_addr = store_weight(self, B)
        out_addr = self.allocate_tensor_dram(M * N * bpe)

        self.start_capture()
        gpr_M_reg = None
        if use_pbi:
            gpr_M_reg = self.alloc_isa_reg()
            self.generate_instruction_add_set(gpr_M_reg, M)
        self.matmat_mul_core(M=M, K=K, N=N, A_DRAM_ADDR=a_addr, B_DRAM_ADDR=b_addr,
                              OUTPUT_DRAM_ADDR=out_addr, gpr_M_reg=gpr_M_reg)
        self.generate_instruction_halt()
        all_bytes = bytearray()
        for inst in self.capture_buffer:
            all_bytes.extend(inst.get_bytes())
        prog_addr = self.get_program_dram_addr()
        self._dma_write_retry(DMA_DEVICE_H2C, prog_addr, all_bytes, len(all_bytes))
        self.allocate_program_dram(len(all_bytes))
        self.clear_capture_buffer()
        self.stop_capture()
        if use_pbi:
            self.release_isa_reg()

        self.start_execute_from_dram(prog_addr)
        self._wait_with_heartbeat(f"sanity_matmul_{'pbi' if use_pbi else 'legacy'}", timeout=30.0)

        buf = bytearray(M * N * bpe)
        self._dma_read_checked(out_addr, buf, len(buf))
        hw_out = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(M, N).clone().float()
        cpu_out = (A.float() @ B.float().T)
        return hw_out, cpu_out

    def sanity_matmul_check(self, M=64, K=64, N=64):
        """Post-vision+prefix hardware-health check. Runs the SAME plain bf16
        matmul twice: once via the legacy static-M path (which the first
        passing sanity check used), once via the PBI runtime-M path (gpr_M_reg
        primed with ADD_SET -- exactly what compile_denoise_loop's every op
        uses, and which reuses the physical GPR index prefix left dirty). If
        legacy PASSes but PBI FAILs, the bug is isolated to register/PBI state
        carried over from prefix's execution, NOT the compute datapath and NOT
        anything denoise-specific."""
        results = {}
        for use_pbi in (False, True):
            hw_out, cpu_out = self._run_sanity_matmul(M, K, N, use_pbi)
            n_nan = torch.isnan(hw_out).sum().item()
            n_inf = torch.isinf(hw_out).sum().item()
            snr_db = 20 * torch.log10(cpu_out.norm() / (hw_out - cpu_out).norm().clamp_min(1e-12)).item()
            passed = n_nan == 0 and n_inf == 0 and snr_db >= 30.0
            tag = "PBI (gpr_M_reg, like denoise)" if use_pbi else "legacy (static-M, like 1st sanity)"
            print(f"[sanity_matmul_check] {tag} M={M} K={K} N={N}: nan={n_nan} inf={n_inf} "
                  f"SNR={snr_db:.2f}dB hw[min={hw_out.min():.4f},max={hw_out.max():.4f}] "
                  f"-- {'PASS' if passed else 'FAIL'}")
            results[use_pbi] = passed
        if results[False] and not results[True]:
            print("[sanity_matmul_check] >>> LEGACY PASS + PBI FAIL: the NaN is a PBI/register "
                  "state carryover from prefix, NOT the compute datapath. Prime/reset gpr_M_reg "
                  "state before denoise. <<<")
        return results

    def load_prefix_kv(self, path):
        """Inverse of dump_prefix_kv: DMA the saved K/V bytes back into
        LAYER0_K_DRAM/LAYER0_V_DRAM (already allocated by tensor_init) and
        restore PREFIX_SEQ_LEN/prefix_valid_len/prefix_k_cache_addr/
        prefix_v_cache_addr -- the exact state compile_prefix normally leaves
        behind -- so tensor_init_action_expert/compile_denoise_loop can run
        with no vision/prefix stage at all."""
        npz = np.load(path)
        kv_total = self.NUM_LAYERS * self.KV_LAYER_STRIDE
        assert npz["k"].nbytes == kv_total, \
            f"dumped K size {npz['k'].nbytes} != current KV_LAYER_STRIDE*NUM_LAYERS {kv_total} (shape mismatch)"
        self._dma_write_retry(DMA_DEVICE_H2C, self.LAYER0_K_DRAM, npz["k"].tobytes(), kv_total)
        self._dma_write_retry(DMA_DEVICE_H2C, self.LAYER0_V_DRAM, npz["v"].tobytes(), kv_total)
        self.PREFIX_SEQ_LEN = int(npz["prefix_seq_len"])
        self.prefix_valid_len = int(npz["prefix_valid_len"])
        self.prefix_masked_cols = [(int(a), int(b)) for a, b in npz["masked_cols"]] if "masked_cols" in npz else []
        self.prefix_k_cache_addr = [self.LAYER0_K_DRAM + l * self.KV_LAYER_STRIDE for l in range(self.NUM_LAYERS)]
        self.prefix_v_cache_addr = [self.LAYER0_V_DRAM + l * self.KV_LAYER_STRIDE for l in range(self.NUM_LAYERS)]
        print(f"[load_prefix_kv] loaded {path}: seq_len={self.PREFIX_SEQ_LEN}, valid_len={self.prefix_valid_len}")

    @staticmethod
    def _xformer_flops(M, Mkv, hidden, inter, layers, nq, nkv, hd, gated):
        """Total multiply-add FLOPs (2*MACs) for `layers` transformer layers,
        M query tokens attending to Mkv keys. gated=True -> 3-matrix gated MLP
        (Gemma), False -> 2-matrix MLP (SigLIP)."""
        qd, kvd = nq * hd, nkv * hd
        per = 0
        per += 2 * M * hidden * qd          # Q proj
        per += 2 * (2 * M * hidden * kvd)   # K, V proj
        per += 2 * M * qd * hidden          # O proj
        per += 2 * M * Mkv * qd             # QK^T scores
        per += 2 * M * Mkv * qd             # scores @ V
        per += 2 * (3 if gated else 2) * M * hidden * inter  # MLP
        return per * layers

    # Real (unpadded) action_dim -- the x_t width the model semantically operates
    # on; AE_XT_WIDTH (64) is the padded physical buffer the HW tiles.
    AE_ACTION_DIM_REAL = 32

    def _report_gflops(self, label, flops, seconds):
        """Live achieved-throughput readout. `flops` is an (effective, hw_issued)
        tuple (or a scalar -> both equal): EFFECTIVE = model-dim FLOPs (real
        head_dim / horizon / action_dim); HW-ISSUED = what the FPGA actually runs
        on the padded dims (head_dim 72->128, horizon 10->64, action 32->64,
        MLP 4304->4352). %-peak is computed off the hw-issued figure."""
        if seconds <= 0:
            return
        eff, hw = flops if isinstance(flops, (tuple, list)) else (flops, flops)
        peak = self.MACS_PER_CYCLE * 2 / (self.CYCLE_NS * 1e-9) / 1e9  # GFLOP/s
        print(f"  ⚡ {label:<18} {seconds:6.1f}s")
        print(f"       effective : {eff/1e9:8.1f} GFLOP  {eff/seconds/1e9:7.1f} GFLOP/s")
        print(f"       hw-issued : {hw/1e9:8.1f} GFLOP  {hw/seconds/1e9:7.1f} GFLOP/s  "
              f"[{100*(hw/seconds/1e9)/peak:4.0f}% peak]")

    def _n_vision_slots_encoded(self):
        """Image slots the encoder actually RAN: all of them unless zero slots are
        skipped (SKIP_ZERO_VISION_SLOTS), matching the GPU which encodes all slots."""
        n = _CFG["vision"]["num_image_slots"]
        if self.SKIP_ZERO_VISION_SLOTS:
            n -= len(getattr(self, "masked_vision_slots", []))
        return n

    def _vision_flops(self):
        """(effective, hw_issued). effective = real head_dim 72 / inter 4304;
        hw_issued = the padded dims the FPGA actually runs -- Q/K/V/O projections
        and attention at per-head DP=128 (weights pre-padded 72->128), MLP at
        VIS_I_PAD=4352. That padding is real work, ~30% above effective."""
        v = _CFG["vision"]
        n = self._n_vision_slots_encoded()
        def one(hd, inter):
            return n * self._xformer_flops(
                M=v["num_patches"], Mkv=v["num_patches"], hidden=v["hidden_size"],
                inter=inter, layers=27, nq=v["num_heads"], nkv=v["num_heads"],
                hd=hd, gated=False)
        eff = one(self.VIS_D, self.VIS_I)         # 72,  4304
        hw = one(self.VIS_DP, self.VIS_I_PAD)     # 128, 4352 (what silicon runs)
        return eff, hw

    def _prefix_flops(self, M=None):
        """(effective, hw_issued) -- prefix dims are all 64-aligned, no padding,
        so both columns are identical."""
        if M is None:
            M = _CFG["model"]["prefill_max_seq_len"]
        f = self._xformer_flops(
            M=M, Mkv=M, hidden=self.HIDDEN_SIZE, inter=self.INTERMEDIATE_SIZE,
            layers=self.NUM_LAYERS, nq=self.NUM_HEADS, nkv=self.NUM_KV_HEADS,
            hd=self.HEAD_DIM, gated=True)
        return f, f

    def _denoise_flops(self):
        """(effective, hw_issued). effective uses the real action horizon (10) and
        action_dim (32); hw_issued uses the padded 64/64 the FPGA tiles."""
        P = self.PREFIX_SEQ_LEN
        H = self.AE_HIDDEN
        def one(S, W, Mkv):
            layer = self._xformer_flops(
                M=S, Mkv=Mkv, hidden=H, inter=self.AE_INTERMEDIATE, layers=self.AE_LAYERS,
                nq=self.AE_HEADS, nkv=self.AE_KV_HEADS, hd=self.HEAD_DIM, gated=True)
            io = 2 * (2 * S * W * H) + 2 * (2 * S * H * W)  # action_in + action_out proj
            return (layer + io) * self.AE_NUM_DENOISE_STEPS
        eff = one(self.AE_ACTION_HORIZON, self.AE_ACTION_DIM_REAL, P + self.AE_ACTION_HORIZON)
        hw = one(self.AE_ACTION_HORIZON_PADDED, self.AE_XT_WIDTH, P + self.AE_ACTION_HORIZON_PADDED)
        return eff, hw

    def precompile_all(self):
        """Compile encoder + prefix + denoise UP FRONT, so run_inference executes
        all three back-to-back with no compilation in between.

        Nothing here needs a previous stage's RESULTS -- only its addresses and
        shapes, all of which are known before any hardware runs:

          * seq_len is DERIVED, not measured: run_vision returns
            slots_encoded * VIS_S rows, and the prefix adds PREFIX_TEXT_BUDGET.
            (Asserted against the real value in run_inference, so a config change
            that breaks the derivation is caught rather than mis-compiled.)
          * valid_len does NOT shape the prefix PROGRAM, so a placeholder is safe
            FOR COMPILATION. It is NOT safe as a stored value: compile_prefix
            assigns it to self.prefix_valid_len, and the action expert later reads
            that for the suffix rope offset (pos_suffix = n_valid + arange) and the
            suffix bias's [valid_len:P] padding mask. Passing seq_len here left
            valid_len=832 instead of 813 -- n_valid 576 vs openpi's 557, and a mask
            slice [832:832] that covered nothing. Cost: 13dB vs the oracle where
            29.5dB was available. run_inference now calls
            _refresh_valid_len_tables(valid_len) per observation to re-DMA both
            buffers with the REAL value; this placeholder only has to be legal
            enough to compile.
          * tensor_init_action_expert needs prefix_k/v_cache_addr, which
            compile_prefix publishes at the END OF COMPILATION, not execution.

        Leaves _prefix_compiled/_denoise_compiled set, so run_inference takes its
        cached branches. Idempotent.
        """
        if getattr(self, "_precompiled", False):
            return
        t0 = time.perf_counter()
        _original_print("\n[precompile] compiling all three stages before execution "
                        "(one-time; keeps the inference loop compile-free)")

        self._compile_once("encoder", self.compile_encoder, label="vision encoder")

        seq_len = self._n_vision_slots_encoded() * self.VIS_S + self.PREFIX_TEXT_BUDGET
        self._precompiled_seq_len = seq_len
        if not getattr(self, "_prefix_compiled", False):
            # valid_len only sizes the bias mask DATA; pass the full length as the
            # placeholder so anything that does read it sees a legal value.
            self._prefix_prog_addr = self._compile_once(
                "prefix", lambda: self.compile_prefix(seq_len, seq_len), label="prefix")
            self._prefix_bias_dram = self.prefix_bias_dram
            self._prefix_compiled = True

        if not getattr(self, "_ae_tensors_inited", False):
            self._ae_alloc_ckpt = (self.get_tensor_dram_addr() - self._tensor_dram_base,
                                   self.get_params_dram_usage())
        self.tensor_init_action_expert()
        if not getattr(self, "_denoise_compiled", False):
            self._denoise_prog_addr = self._compile_once(
                "denoise", self.compile_denoise_loop, label="denoise_loop")
            self._denoise_compiled = True

        self._precompiled = True
        self._precompile_secs = time.perf_counter() - t0
        # The run summary subtracts _compile_times from the stage timers to separate
        # compile from exec. That is only correct when compilation happened INSIDE
        # the timed region. It no longer does, so clear the map (the total is kept
        # in _precompile_secs and reported on its own line) -- otherwise every stage
        # would be credited a compile cost it did not pay and read too fast.
        self.__dict__.setdefault("_compile_times", {}).clear()
        _original_print(f"[precompile] all stages ready in {self._precompile_secs:.1f}s "
                        f"(seq_len={seq_len}); inference is now execute-only\n")

    def run_inference(self, images_hwc, prompt_tokens, noise32=None, skip_prefix=False, dump_prefix_path=None,
                       sanity_check=False):
        """Full forward pass on real hardware. images_hwc: list of 3 (224,224,3)
        float32 arrays in [-1,1]. prompt_tokens: 1-D list/array of token ids.
        Returns (10,32) numpy action array (caller slices [:, :7]).

        skip_prefix: if True, skip run_vision()/compile_prefix() entirely and
        assume load_prefix_kv() was already called to populate LAYER0_K_DRAM/
        LAYER0_V_DRAM/PREFIX_SEQ_LEN/prefix_valid_len -- for fast denoise-only
        iteration (--debug flag in main()). images_hwc/prompt_tokens are
        ignored in this mode.
        dump_prefix_path: if set (and skip_prefix is False), dump the fresh
        prefix K/V cache to this path right after compile_prefix, for a later
        --debug run to reload.
        sanity_check: (--sanity-check in main()) after vision+prefix run for
        real, run sanity_matmul_check() instead of the action-expert/denoise
        stage and return None -- tests raw hardware health with the simplest
        possible op after vision+prefix's execution, independent of anything
        denoise-loop-specific."""
        # Reset the per-inference compile ledger at the START of the timed region.
        # The summary computes exec = total - compile, which is only right when the
        # compile it subtracts happened INSIDE this inference. _compile_once caches,
        # so compilation happens at most once per process -- but _compile_times kept
        # its entries forever, and precompile_all() was the only thing that ever
        # cleared them. Callers that skip precompile (libero_eval.py builds the
        # engine and goes straight to run_inference) therefore compiled inline on
        # inference #0, then subtracted that same 11.9s from EVERY later inference:
        # a 36.9s pass reported "vision 1.6s exec" while the slot lines right above
        # it plainly showed 3 x 2.3s = 6.9s, and claimed a 24.9s steady state that
        # was really 36.9s. Clearing here keeps #0 honest (its compile IS inside the
        # region and is still reported) and makes #1+ show compile 0.0s / exec = total.
        self.__dict__.setdefault("_compile_times", {}).clear()
        t0 = time.perf_counter()
        if skip_prefix:
            t_vision = 0.0
            t1 = time.perf_counter()
            t_prefix = time.perf_counter() - t1
        else:
            vision_tokens = self.run_vision(images_hwc)
            t_vision = time.perf_counter() - t0
            n_enc = self._n_vision_slots_encoded()
            self._report_gflops(f"vision ({n_enc} slots)", self._vision_flops(), t_vision)
            if getattr(self, "VISION_SNR_CHECK", False):
                self._vision_snr_check(images_hwc, vision_tokens)

            t1 = time.perf_counter()
            # DERIVED, not read from config: however many vision rows run_vision
            # actually returned (512 dropped / 768 kept / 768 on a real 3-camera
            # robot) + the text budget.
            seq_len = vision_tokens.shape[0] + self.PREFIX_TEXT_BUDGET
            # precompile_all() DERIVED this same number before anything ran. If the
            # derivation is ever wrong the prefix program was compiled for the wrong
            # M, which would be silent corruption -- so check, do not hope.
            _pre = getattr(self, "_precompiled_seq_len", None)
            assert _pre is None or _pre == seq_len, (
                f"precompile_all() compiled the prefix for seq_len={_pre} but the "
                f"encoder produced {seq_len} ({vision_tokens.shape[0]} vision rows + "
                f"{self.PREFIX_TEXT_BUDGET} text). The derivation in precompile_all "
                f"is stale -- fix it there rather than compiling per-obs.")
            valid_len = self.embed_and_concat_prefix(prompt_tokens, vision_tokens, seq_len=seq_len)
            # COMPILE-ONCE: the prefix program is invariant to valid_len (M is
            # always seq_len; valid_len only shapes the DMA'd bias DATA). Compile
            # the first obs, then re-DMA just the fresh bias mask to the SAME
            # baked bias addr and re-execute -- no re-alloc, no 4GB march.
            if not getattr(self, "_prefix_compiled", False):
                self._prefix_prog_addr = self._compile_once(
                    "prefix", lambda: self.compile_prefix(seq_len, valid_len), label="prefix")
                self._prefix_bias_dram = self.prefix_bias_dram
                self._prefix_compiled = True
            else:
                bias = self.build_prefix_attn_bias(seq_len, valid_len).contiguous()
                self.dma_write(DMA_DEVICE_H2C, self._prefix_bias_dram,
                               bias.flatten(), bias.numel() * 2)
            # THIS observation's valid_len -- not the one the program was compiled
            # with. Must run on BOTH branches: the compile branch because
            # precompile_all() may have baked a placeholder, and the cached branch
            # because valid_len moves with the prompt's token count across tasks.
            self._refresh_valid_len_tables(valid_len)
            self._execute_prefix(timeout=250.0)
            t_prefix = time.perf_counter() - t1
            self._report_gflops(f"prefix ({seq_len} tok)", self._prefix_flops(seq_len), t_prefix)

            if getattr(self, "PREFIX_SNAPSHOTS", False):
                self._prefix_layer0_op_snr_report(prompt_tokens, vision_tokens, valid_len)

            if dump_prefix_path is not None:
                self.dump_prefix_kv(dump_prefix_path)

        if sanity_check:
            print(f"timing: vision={t_vision:.2f}s prefix={t_prefix:.2f}s (sanity-check mode, "
                  f"skipping action-expert/denoise)")
            self.sanity_matmul_check()
            return None

        t2 = time.perf_counter()
        # Snapshot both bump allocators BEFORE the AE buffers are carved out, so
        # dump_programs_to_file can tell run_from_bin where to rewind to. Recorded on the
        # first call only (tensor_init_action_expert is idempotent, so later calls would
        # snapshot a post-AE pointer). Read-only bookkeeping: no allocation happens here.
        if not getattr(self, "_ae_tensors_inited", False):
            self._ae_alloc_ckpt = (self.get_tensor_dram_addr() - self._tensor_dram_base,
                                   self.get_params_dram_usage())
        self.tensor_init_action_expert()
        S, AD = self.AE_ACTION_HORIZON_PADDED, self.AE_XT_WIDTH  # x_t buffer is 64-wide
        if noise32 is None:
            # Padding rows/cols must NOT be exact zero: rms_norm_core has no
            # epsilon, so an all-zero row -> rsqrt(0)=inf -> NaN, which then
            # contaminates every real row too since self-attention mixes all
            # S=64 rows together (same bug class fixed in embed_and_concat_prefix).
            noise32 = np.full((S, AD), 1e-6, dtype=np.float32)
            noise32[:10, :7] = np.random.RandomState(0).randn(10, 7)
        self.dma_write(DMA_DEVICE_H2C, self.AE_XT_DRAM,
                        torch.from_numpy(noise32).to(torch.bfloat16), S * AD * 2)
        # compile_denoise_loop is statically unrolled (10 steps x 18 layers = 180
        # static layer bodies, 1440 flash-attention jump sites) -- same proven
        # pattern as compile_prefix/compile_encoder. A loop_start/loop_end runtime
        # loop was tried (single small compiled body, runtime trip count) but hung
        # on any real repeat even after fixing a genuine found bug (missing 64B
        # alignment before the backward-branch jump target); that combination
        # (loop_start/loop_end wrapping an internal shared-subroutine jump-and-
        # return) isn't proven anywhere else in this codebase, so static unrolling
        # was reverted to. Confirmed clean: full run completed in 123.9s (close to
        # the ~120-150s predicted from a standalone single-step measurement).
        # COMPILE-ONCE: denoise is fully static -- re-execution re-seeds the prefix
        # K/V from fixed LAYER0_K/V_DRAM (refreshed by the prefix stage above) and
        # re-reads the fresh noise DMA'd to AE_XT_DRAM. Compile the first obs, then
        # just re-execute the stored program (noise already written just above).
        if not getattr(self, "_denoise_compiled", False):
            self._denoise_prog_addr = self._compile_once(
                "denoise", self.compile_denoise_loop, label="denoise_loop")
            self._denoise_compiled = True
        self._execute_denoise(timeout=300.0)
        t_denoise = time.perf_counter() - t2
        if self.AE_COND_TABLE_ON_DEVICE and self.AE_COND_TABLE_CHECK:
            self._ae_check_cond_table()
        self._report_gflops("denoise (10 steps)", self._denoise_flops(), t_denoise)

        # DRAM-overlap check: adding PREFIX_LAYER_SNAPSHOT_DRAM/PREFIX_L0_SNAPSHOT_DRAM
        # shifted the tensor-DRAM allocator base by ~96MB (0xEE398AC0 -> 0xF3F68AC0)
        # vs the last known-clean run -- this codebase has hit exactly this bug class
        # before (see LocateAnything's decode-NaN/DRAM-overlap postmortem), so check
        # ae_k_combined (seeded by compile_denoise_loop's own captured copy) directly
        # before trusting the final action output.
        if self.DENOISE_STEP0_PROBE:
            P_chk, D_chk = self.AE_PREFIX_SEQ_LEN, self.HEAD_DIM
            Tkv = self.AE_TKV
            for layer in (0, self.AE_LAYERS - 1):
                for name, addr in (("k", self.ae_k_combined[layer]), ("v", self.ae_v_combined[layer])):
                    buf_kv = bytearray(Tkv * D_chk * 2)
                    self._dma_read_checked(addr, buf_kv, len(buf_kv))
                    full = torch.frombuffer(bytes(buf_kv), dtype=torch.bfloat16).reshape(Tkv, D_chk).float()
                    for tag, sl in (("prefix", full[:P_chk]), ("suffix", full[P_chk:])):
                        print(f"  [ae_kv_check] layer{layer:2d} {name} {tag}: "
                              f"nan={torch.isnan(sl).sum().item()} inf={torch.isinf(sl).sum().item()} "
                              f"min={sl.min():.4f} max={sl.max():.4f}")

        buf = bytearray(S * AD * 2)
        self._dma_read_checked(self.AE_XT_DRAM, buf, len(buf))
        out = torch.frombuffer(bytes(buf), dtype=torch.bfloat16).reshape(S, AD).float().numpy()
        actions = out[:10, :7]

        total = t_vision + t_prefix + t_denoise
        # Split ONE-TIME compilation out of the wall clock. The stage timers wrap
        # compile+execute, but _compile_once caches, so every inference after the
        # first pays only the exec column -- which is the number that matters for
        # a LIBERO rollout, and the one to compare across changes.
        ct = getattr(self, "_compile_times", {})
        comp = {"vision": ct.get("encoder", 0.0), "prefix": ct.get("prefix", 0.0),
                "denoise": ct.get("denoise", 0.0)}
        t_comp = sum(comp.values())
        t_exec = total - t_comp
        print("\n  " + "─" * 62)
        print(f"  {'stage':<10}{'total':>9}{'compile':>10}{'exec':>9}{'  share(exec)':>14}")
        print("  " + "─" * 62)
        for name, t in (("vision", t_vision), ("prefix", t_prefix), ("denoise", t_denoise)):
            e = t - comp[name]
            share = (100 * e / t_exec) if t_exec else 0.0
            print(f"  {name:<10}{t:>7.1f}s{comp[name]:>9.1f}s{e:>8.1f}s{share:>13.1f}%")
        print("  " + "─" * 62)
        print(f"  {'TOTAL':<10}{total:>7.1f}s{t_comp:>9.1f}s{t_exec:>8.1f}s{'100.0':>13}%")
        print("  " + "─" * 62)
        pre = getattr(self, "_precompile_secs", None)
        if pre is not None:
            print(f"  all 3 stages pre-compiled up front in {pre:.1f}s (not in the times "
                  f"above); this {t_exec:.1f}s is pure back-to-back execution\n")
        elif t_comp > 0:
            # Compile ran INSIDE this inference (no precompile_all()), so this pass
            # is the slow one and t_exec is what every later pass will cost.
            print(f"  compile is ONE-TIME (cached): steady-state inference is {t_exec:.1f}s\n")
        else:
            # Nothing compiled this pass -- the whole wall clock was execution.
            print(f"  this {t_exec:.1f}s is pure execution (all programs already cached)\n")
        return actions

    # XDMA driver has a per-os.write() transfer size limit (~16-64MB, matching
    # parakeet_test.py's/mobilenetv2_224_test.py's documented workaround). A
    # single-shot dma_write of a large program blob fails deterministically
    # with `[Errno 512]` after
    # transferring a partial chunk (~57MB observed) -- this was misread at
    # first as an address-boundary bug (it correlated with >4GB addresses by
    # coincidence: a small program always fit under the limit, while a large one
    # never does, regardless of address). NOTE: the "~684MB prefix program" figure
    # this comment used to quote is long stale -- after the shared-subroutine flash
    # rework the three programs are ~5.4MB (vision) / 7.5MB (prefix) / 19.5MB
    # (denoise), ~33MB total. Chunking is still correct and still required.
    # Real fix: chunk large writes, exactly like parakeet/mobilenetv2 already do.
    DMA_CHUNK_BYTES = 1 * 1024 * 1024        # 1 MB per chunk (writes)
    DMA_READ_CHUNK_BYTES = 256 * 1024        # 256 KB per chunk (reads -- see _dma_read_checked)
    DMA_READ_MIN_CHUNK_BYTES = 4 * 1024      # floor for the bisect-on-EIO fallback

    def _dma_write_retry(self, device, address, buffer, size, attempts=5):
        """Chunked + retried DMA write. A failed/incomplete program-blob write
        here means start_execute_from_dram runs stale/garbage DRAM content --
        this bit us for real (denoise-loop program silently didn't get written,
        producing garbage action output) so this is NOT optional."""
        data = bytes(buffer[:size]) if isinstance(buffer, (bytes, bytearray)) else buffer
        if size <= self.DMA_CHUNK_BYTES:
            for i in range(attempts):
                n = self.dma_write(device, address, data, size)
                if n == size:
                    return n
                print(f"  [dma_write_retry] attempt {i+1}/{attempts} failed (wrote {n}, wanted {size}), retrying...")
            raise RuntimeError(f"dma_write to 0x{address:X} failed after {attempts} attempts")

        # Tensors must be flattened to BYTES once up front. Slicing a tensor with
        # byte offsets ([offset:offset+chunk_size]) indexes ELEMENTS, so for any
        # >1MB bf16 tensor every chunk after the first started at the wrong place
        # and the tail chunks sliced past the end -> a short buffer handed to
        # dma_write with a full-size length.
        if not isinstance(data, (bytes, bytearray)):
            t = data.flatten().contiguous()
            data = (t.view(torch.uint16) if t.dtype == torch.bfloat16 else t).numpy().tobytes()
            assert len(data) >= size, f"buffer has {len(data)} B, asked to write {size} B"
        offset = 0
        while offset < size:
            chunk_size = min(self.DMA_CHUNK_BYTES, size - offset)
            self._dma_write_retry(device, address + offset, data[offset:offset + chunk_size],
                                  chunk_size, attempts=attempts)
            offset += chunk_size
        return size

    def _dma_read_checked(self, address, buffer, size, attempts=5, label=""):
        """Chunked + retried + CHECKED DMA read -- the read-side mirror of
        _dma_write_retry, and just as non-optional.

        The raw dma_read() returns -1 on failure after merely PRINTING the errno;
        it does not raise. Callers were passing a freshly-allocated bytearray (which
        is zero-filled) and ignoring that -1, so a failed read looked exactly like
        "the hardware computed all zeros" -- silently, with a success message.

        This bit us for real: dump_prefix_kv issued two 9 MB reads, the driver
        rejected both with EIO (transfer-size limit -- reads <=1MB succeed), and it
        wrote an 18 MB .npz of pure zeros while printing "wrote 18.0 MB K + V".
        Every downstream consumer then compared against zeros: the prefix K/V SNR
        report read a flat 0.00dB on all 18 layers (K and V), which we very nearly
        mis-diagnosed as a model bug. --debug and --probe-step0 would have denoised
        against a zero K/V cache too.

        The EIO itself is a driver-side limit, not a model bug: dma_read() lowers to a
        single os.read(fd, size) with no chunking, and the XDMA C2H path rejects some
        (address, size) combinations outright. MEASURED: at LAYER0_K_DRAM (0xE0000000)
        reads of 128B/4KB/64KB/256KB succeed but 1MB EIOs, while the *same* 1MB read
        succeeds at VIS_HEAD_OUT_DRAM -- so it is an address/size interaction, not a
        flat transfer cap, and no single chunk size is safe everywhere (a 9MB sweep at
        256KB still failed on 18 of 36 chunks).

        So don't try to model the driver's bad windows -- bisect around them. Start at
        DMA_READ_CHUNK_BYTES; if a chunk keeps failing, halve it and re-read that span,
        down to DMA_READ_MIN_CHUNK_BYTES (4KB succeeded at every address we ever probed).
        Only if even a 4KB read fails do we RAISE. Never return a partially-filled
        buffer to a caller that can't tell it from real data.
        """
        mv = memoryview(buffer)
        offset = 0
        chunk_bytes = self.DMA_READ_CHUNK_BYTES
        tag = f" {label}" if label else ""
        while offset < size:
            n = min(chunk_bytes, size - offset)
            chunk = bytearray(n)
            for i in range(attempts):
                rc = self.dma_read(DMA_DEVICE_C2H, address + offset, chunk, n)
                if rc == n:
                    break
            else:
                if chunk_bytes > self.DMA_READ_MIN_CHUNK_BYTES:
                    chunk_bytes //= 2
                    print(f"  [dma_read_checked{tag}] EIO at 0x{address + offset:X} "
                          f"(+{offset}/{size}B) -- halving chunk to {chunk_bytes >> 10}KB")
                    continue      # retry this same offset with the smaller chunk
                raise RuntimeError(
                    f"dma_read{tag} FAILED at 0x{address + offset:X} (offset {offset}/{size}B) "
                    f"even at the {self.DMA_READ_MIN_CHUNK_BYTES >> 10}KB floor after {attempts} "
                    f"attempts -- refusing to return a zero-filled buffer that would silently "
                    f"masquerade as real data")
            mv[offset:offset + n] = chunk
            offset += n
        return size

    def _wait_with_heartbeat(self, label, timeout=180.0, heartbeat_every=10.0):
        """wait_queue wrapper that prints elapsed seconds every heartbeat_every
        seconds on a background thread, so a real hang (dead silent, no CPU
        activity) is visually distinguishable from a slow-but-alive execute --
        we were guessing this blind before and burning time on ambiguous kills.

        CRITICAL: user_dma_core.wait_queue() does NOT raise on timeout -- it
        just prints "Error: wait_queue() timed out..." and returns normally,
        so callers silently proceed as if the FPGA finished. This wrapper
        checks is_queue_busy() itself after wait_queue returns and raises for
        real if the hardware is still busy, so a genuine hang surfaces as a
        hard failure instead of silently corrupting every downstream stage
        (this bit us for real: prefix's execution may never have actually
        finished before we compiled and ran the denoise loop on top of it)."""
        import threading
        t0 = time.perf_counter()
        stop = threading.Event()
        def _hb():
            while not stop.wait(1.0):
                _original_print(f"  [{label}] running... {time.perf_counter()-t0:.0f}s", end="\r", flush=True)
        hb_th = threading.Thread(target=_hb, daemon=True)
        hb_th.start()
        try:
            self.wait_queue(timeout)
        finally:
            stop.set()
            hb_th.join(timeout=1.0)
        if self.is_queue_busy():
            _original_print()
            raise RuntimeError(
                f"[{label}] FPGA queue still busy after {timeout:.0f}s timeout -- "
                f"real hang, not a silent success. wait_queue() does not raise on "
                f"its own; this check exists specifically to catch that.")
        _original_print(f"  [{label}] done in {time.perf_counter()-t0:.1f}s" + " " * 20)

    def _compile_and_run(self, compile_fn, label="compile_and_run", timeout=250.0):
        """compile_fn must itself do start_capture/.../stop_capture + DMA the
        program bytes and return the program addr (compile_prefix/compile_denoise_loop
        don't currently do the capture/dma/execute bookkeeping compile_encoder does --
        wrap them the same way here). Compile-phase prints (per-op FLOPs/URAM
        dumps from user_dma_core) are noisy and drown the timing/NaN signal we
        actually care about, so they're silenced the same way qwen3_4b/
        locateanything_3b do it (global _SILENT_MODE flag over builtins.print)."""
        global _SILENT_MODE
        _original_print(f"  [{label}] compiling...", end="\r", flush=True)
        t_compile0 = time.perf_counter()
        _SILENT_MODE = True
        prog_len = 0
        try:
            self.start_capture()
            prog_addr = compile_fn()
            # compile_prefix/compile_denoise_loop don't call stop_capture/emit themselves
            # (only compile_encoder does) -- if compile_fn already stopped capture and
            # returned an addr (compile_encoder-style), reuse it; else emit now.
            if self.capture_buffer:
                all_bytes = bytearray()
                for inst in self.capture_buffer:
                    all_bytes.extend(inst.get_bytes())
                prog_addr = self.get_program_dram_addr()
                prog_len = len(all_bytes)
                self._dma_write_retry(DMA_DEVICE_H2C, prog_addr, all_bytes, prog_len)
                self.allocate_program_dram(prog_len)
                self.clear_capture_buffer()
            self.stop_capture()
        finally:
            _SILENT_MODE = False
        prog_end = prog_addr + prog_len
        tensor_end = self.get_tensor_dram_addr()
        FOURGB = 0x100000000
        prog_base = getattr(self, "_program_dram_base", 0xF8000000)
        _original_print(
            f"  [{label}] ADDR: prog=[0x{prog_addr:X}..0x{prog_end:X}] len={prog_end-prog_addr}B "
            f"tensor_end=0x{tensor_end:X} prog_base=0x{prog_base:X} 4GB=0x{FOURGB:X} | "
            f"prog_crosses_4GB={prog_end > FOURGB} tensor_hits_prog={tensor_end > prog_base}")
        _original_print(f"  [{label}] compiled in {time.perf_counter()-t_compile0:.1f}s" + " " * 20)
        self.dram_region_map(f"after compile {label}")
        self.start_execute_from_dram(prog_addr)
        self._wait_with_heartbeat(label, timeout=timeout)
        return prog_addr

    # ------------------------------------------------------------------
    # Binary dump (consumed by Pi05Libero_Run below)
    # ------------------------------------------------------------------

    def dump_params_to_file(self, bin_dir):
        """Dump the whole params DRAM region to bin_dir/params.bin + params.json.

        pi05 CANNOT regenerate params.bin from HF (weights come from weights_export/*.npy,
        13GB, offline), so this follows mobilesam's dump-DRAM approach: read back exactly
        the bytes the run just used. No per-tensor map is written -- pi05 has far too many
        buffers to hand-list, and run_from_bin re-derives every address by re-running the
        real tensor_init* allocators instead.
        """
        os.makedirs(bin_dir, exist_ok=True)
        bin_path = os.path.join(bin_dir, "params.bin")
        meta_path = os.path.join(bin_dir, "params.json")
        total = self.get_params_dram_usage()
        CHUNK = self.DMA_READ_CHUNK_BYTES
        with open(bin_path, "wb") as f:
            offset = 0
            while offset < total:
                sz = min(CHUNK, total - offset)
                buf = bytearray(sz)
                self._dma_read_checked(self._params_dram_base + offset, buf, sz)
                f.write(buf)
                offset += sz
        with open(meta_path, "w") as f:
            json.dump({"size": total}, f)
        print(f"  Params: {total / 1024**2:.1f} MB ({total} bytes) -> {bin_path}")

    def dump_programs_to_file(self, bin_dir):
        """Dump the three compiled programs to bin_dir/programs.bin + programs.json.

        Sizes come from _prog_meta (recorded by _compile_once at capture time), NOT from
        differencing consecutive program addresses -- allocate_program_dram rounds each
        allocation up to 64B, so address-differencing over-reports every size.

        The `sig` block is run_from_bin's refuse-on-mismatch guard. All three programs
        bake ABSOLUTE jump targets and ABSOLUTE tensor DRAM addresses (denoise is
        statically unrolled: 10 steps x 18 layers = 180 bodies, 1440 flash-attn jump
        sites), so a bin set is only valid for the exact config it was compiled under.
        """
        # programs.json describes the PRIMARY's program allocator only. A multi-engine
        # encoder also compiles one worker program per extra engine, into a separate
        # scheduler-owned allocator arena that the bin format has no slot for -- a bin
        # set dumped from such a run would execute engine0's half of the image and
        # leave rows 128..255 as stale garbage. Refuse rather than dump it.
        assert self._num_engines("VIS") == 1, (
            f"dump_programs_to_file: vision engines={self._num_engines('VIS')} -- the bin "
            f"format only carries the primary engine's programs, so a multi-engine "
            f"encoder cannot be dumped. Re-run with --engines 1 to produce bins.")
        _pre_sched = getattr(self, "_prefix_sched", None)
        _dn_sched = getattr(self, "_denoise_sched", None)
        assert _dn_sched is None or _dn_sched.num_engines == 1, (
            f"dump_programs_to_file: denoise engines={_dn_sched.num_engines} -- the bin "
            "format carries ONE program stream per stage and cannot express the worker "
            "programs. Re-run with --engines 1 to produce a bin.")
        assert _pre_sched is None or _pre_sched.num_engines == 1, (
            f"dump_programs_to_file: prefix engines={_pre_sched.num_engines} -- same"
            f"reason as the encoder above: the worker programs live in a scheduler-owned "
            f"arena the bin format has no slot for, and a bin set dumped from a sharded "
            f"prefix would run only the primary's row block. Re-run with --engines 1.")
        os.makedirs(bin_dir, exist_ok=True)
        bin_path = os.path.join(bin_dir, "programs.bin")
        meta_path = os.path.join(bin_dir, "programs.json")
        meta = getattr(self, "_prog_meta", {})
        for _k in ("encoder", "prefix", "denoise"):
            assert _k in meta, (
                f"dump_programs_to_file: program {_k!r} was never compiled this run "
                f"(have {sorted(meta)}). Dump only after a full non-debug inference.")
        for _attr in ("_ae_alloc_ckpt", "_params_ofs_after_weight_init", "prefix_bias_dram",
                      "PREFIX_SEQ_LEN"):
            assert hasattr(self, _attr), (
                f"dump_programs_to_file: {_attr} missing -- dump only after a full "
                f"non-debug vision->prefix->denoise inference on this engine instance.")
        # Weight-init-derived vision geometry (see _BIN_DERIVED_ATTRS). Self-defending:
        # if someone adds a new non-DRAM VIS_* scalar to _weight_init_vision and forgets
        # this list, the dump fails HERE (loud, on the compile run) instead of the bin run
        # dying with an AttributeError deep inside tensor_init -- or worse, silently
        # reading a stale value.
        for _a in _BIN_DERIVED_ATTRS:
            assert hasattr(self, _a), (
                f"dump_programs_to_file: {_a} missing -- dump only after weight_init has run.")
        _uncovered = sorted(
            a for a, v in vars(self).items()
            if a.startswith("VIS_") and isinstance(v, int) and not isinstance(v, bool)
            and not a.endswith("_DRAM") and not a.endswith("_ADDR")
            and a not in _BIN_DERIVED_ATTRS)
        assert not _uncovered, (
            f"dump_programs_to_file: new weight-init-derived vision scalar(s) {_uncovered} "
            f"are not in _BIN_DERIVED_ATTRS. Add them there (and they will be restored by "
            f"Pi05Libero_Run) or run_from_bin will not see them.")
        derived = {a: getattr(self, a) for a in _BIN_DERIVED_ATTRS}

        manifest = {"programs": {}, "sig": {}, "derived": derived}
        all_bytes = bytearray()
        CHUNK = self.DMA_READ_CHUNK_BYTES
        # Order matters and MUST match run_from_bin's load order: program DRAM is a bump
        # allocator, so encoder->prefix->denoise is what reproduces each baked address.
        for name in ("encoder", "prefix", "denoise"):
            addr, size = meta[name]
            offset_in_file = len(all_bytes)
            read = 0
            while read < size:
                sz = min(CHUNK, size - read)
                buf = bytearray(sz)
                self._dma_read_checked(addr + read, buf, sz)
                all_bytes.extend(buf)
                read += sz
            manifest["programs"][name] = {"offset": offset_in_file, "size": size}
        manifest["sig"] = {
            "prefix_seq_len": int(self.PREFIX_SEQ_LEN),
            "denoise_steps": int(self.AE_NUM_DENOISE_STEPS),
            "keep_masked_slots": bool(self.KEEP_MASKED_SLOTS),
            "program_dram_base": hex(self._program_dram_base),
            "tensor_dram_base": hex(self._tensor_dram_base),
            "params_dram_base": hex(self._params_dram_base),
            # Params-region offset of the prefix attention bias. This is the ONE address
            # run_from_bin must be told rather than re-derive: the bias DATA depends on
            # per-obs valid_len, so it is re-DMA'd every inference to the addr baked into
            # the prefix program (mirrors run_inference's own _prefix_bias_dram reuse).
            "prefix_bias_ofs": int(self.prefix_bias_dram - self._params_dram_base),
            # Allocator checkpoints taken immediately BEFORE tensor_init_action_expert.
            # NOT redundant: compile_prefix itself allocates tensor AND params DRAM, so
            # the AE buffers' addresses depend on that compile having advanced both bump
            # allocators first. run_from_bin never compiles, so it must restore both
            # pointers to these values before calling tensor_init_action_expert, or every
            # AE_* address (incl. AE_XT_DRAM, where noise goes in and actions come out)
            # lands somewhere the denoise program never reads.
            "tensor_ofs_before_ae": int(self._ae_alloc_ckpt[0]),
            "params_ofs_before_ae": int(self._ae_alloc_ckpt[1]),
            # Where the params allocator stood when weight_init finished. load_params
            # rewinds to this (not to params.json's total) so tensor_init's
            # store_identity_matrix re-lands on its original address. See weight_init.
            "params_ofs_after_weight_init": int(self._params_ofs_after_weight_init),
        }
        with open(bin_path, "wb") as f:
            f.write(all_bytes)
        with open(meta_path, "w") as f:
            json.dump(manifest, f, indent=2)
        _sz = len(all_bytes)
        print(f"  Programs: {_sz / 1024**2:.1f} MB ({_sz} bytes) -> {bin_path}")
        for name, m in manifest["programs"].items():
            print(f"    {name:<8} offset={m['offset']:>10}  size={m['size']:>10}")
        print(f"  Derived vision geometry persisted: {derived}")

    def dump_bins(self, bin_dir):
        """Dump params + programs. Safe to call after any full non-debug inference."""
        self.dump_params_to_file(bin_dir)
        self.dump_programs_to_file(bin_dir)

    def _compile_once(self, key, compile_fn, label="compile_once"):
        """COMPILE-ONCE half of compile-once/execute-many. Captures + serializes +
        DMAs the program bytes and advances the program-DRAM allocator EXACTLY the
        first time a given key is seen, caching prog_addr; on every later call it
        returns the cached addr with NO capture and NO allocation (so the program
        pointer never marches toward the 4GB ceiling -- the run_inference-per-call
        crash). Unlike _compile_and_run it does NOT execute; caller runs _execute.
        Mirrors _compile_and_run's capture/serialize/dma/allocate bookkeeping."""
        cache = self.__dict__.setdefault("_prog_cache", {})
        # _prog_meta mirrors _prog_cache but stores (prog_addr, prog_len) so
        # dump_programs_to_file knows each program's exact byte length. It is a SEPARATE
        # dict on purpose: _prog_cache's value stays a bare prog_addr so existing call
        # sites (run_vision / run_inference) keep working unchanged.
        meta = self.__dict__.setdefault("_prog_meta", {})
        if key in cache:
            return cache[key]
        global _SILENT_MODE
        _original_print(f"  [{label}] compiling ONCE...", end="\r", flush=True)
        t0 = time.perf_counter()
        _SILENT_MODE = True
        prog_addr, prog_len = None, 0
        try:
            self.start_capture()
            prog_addr = compile_fn()
            if self.capture_buffer:
                all_bytes = bytearray()
                for inst in self.capture_buffer:
                    all_bytes.extend(inst.get_bytes())
                prog_addr = self.get_program_dram_addr()
                prog_len = len(all_bytes)
                self._dma_write_retry(DMA_DEVICE_H2C, prog_addr, all_bytes, prog_len)
                self.allocate_program_dram(prog_len)
                self.clear_capture_buffer()
            self.stop_capture()
        finally:
            _SILENT_MODE = False
        if prog_len == 0:
            # compile_fn drained its own capture buffer (compile_encoder does) and
            # stashed the length itself. See compile_encoder's _encoder_prog_len.
            prog_len = getattr(self, "_encoder_prog_len", 0) if key == "encoder" else 0
        assert prog_len > 0, (
            f"_compile_once({key!r}): could not determine program length. A 0-length entry "
            f"would silently corrupt programs.json/run_from_bin -- if this compile_fn drains "
            f"its own capture buffer, it must stash its byte length like compile_encoder does.")
        cache[key] = prog_addr
        meta[key] = (prog_addr, prog_len)
        elapsed = time.perf_counter() - t0
        # Record per-key compile cost so the run summary can separate ONE-TIME
        # compilation from steady-state execution. The stage timers wrap
        # compile+execute together, so a first-run "denoise 10.7s" is really
        # 4.2s of compile plus 6.5s of hardware -- and every later inference in
        # the same process pays only the 6.5s, because _compile_once is cached.
        # Reporting them merged makes the model look ~20% slower than it is and
        # hides which half a change actually moved.
        self.__dict__.setdefault("_compile_times", {})[key] = elapsed
        _original_print(f"  [{label}] compiled ONCE in {elapsed:.1f}s "
                        f"prog=0x{prog_addr:X} len={prog_len}B (cached)" + " " * 8)
        return prog_addr

    def _execute(self, prog_addr, label="execute", timeout=250.0):
        """EXECUTE-MANY half: re-run an already-compiled/stored program. No capture,
        no allocation, no pointer advance. Caller must DMA fresh inputs to their
        baked DRAM addresses BEFORE calling (absolute addresses + GPR/PBI setup are
        baked into the program bytes, so re-execution is deterministic)."""
        self.start_execute_from_dram(prog_addr)
        self._wait_with_heartbeat(label, timeout=timeout)
        return prog_addr


# ======================================================================================
# Bin-backed engine: inference from pre-compiled bins (no weight unpack, no compile).
# ======================================================================================
#
# WHY THIS SUBCLASSES THE ENGINE (rather than re-implementing it, as qwen3's
# fully-self-contained run_from_bin template does):
#   * pi05's engine is ~3300 lines across three stacks (SigLIP vision encoder, Gemma-2B
#     prefix LM, Gemma-300M action expert). A weight-free re-implementation is not
#     realistic to keep in sync with the validated path.
#   * pi05 CANNOT regenerate params.bin from HF: the weights come from the offline
#     weights_export/*.npy tree, so params.bin is a DRAM snapshot (mobilesam's approach)
#     rather than a re-derivable artifact.
#
# WHAT THE BINS BAKE (and why the sig guard refuses rather than adapts):
# All three programs bake ABSOLUTE jump targets and ABSOLUTE tensor DRAM addresses --
# the denoise program is statically unrolled to 10 steps x 18 layers = 180 layer bodies
# with 1440 flash-attention jump sites. Nothing about a compiled program can be
# retargeted after the fact. A bin set is valid for exactly ONE (prefix_seq_len,
# denoise_steps, keep_masked_slots, dram-base) combination. On mismatch we REFUSE with
# an actionable error -- we do NOT pad, do NOT silently recompile, do NOT ship multiple
# bin sets.
#
# HOW EXECUTION IS REUSED (the trick that keeps this small): every compile routes through
# _compile_once(key, fn), which returns a cached prog_addr and skips compilation on a hit.
# load_programs() PRE-SEEDS _prog_cache with the bin-loaded addresses, so the stock,
# validated run_vision()/run_inference() execute as they always do and never compile.
# No inference logic is duplicated.

# Program load order is load-bearing: program DRAM is a bump allocator, so replaying
# encoder -> prefix -> denoise is what reproduces the absolute addresses the programs
# were compiled against. MUST match dump_programs_to_file's write order.
_PROGRAM_ORDER = ("encoder", "prefix", "denoise")


class Pi05Libero_Run(Pi05Libero_UnifiedEngine):
    """Bin-backed pi05_libero engine. Inherits the entire validated inference path;
    only weight loading and program provisioning are replaced."""

    def __init__(self, bin_dir=None, **kw):
        self.bin_dir = bin_dir or BIN_DIR
        meta_path = os.path.join(self.bin_dir, "programs.json")
        if not os.path.exists(meta_path):
            raise FileNotFoundError(
                f"No compiled bins at {self.bin_dir} (missing programs.json).\n"
                f"Generate them first with a full run of the golden path:\n"
                f"    python {os.path.abspath(__file__)}")
        with open(meta_path) as f:
            self._manifest = json.load(f)
        self.sig = self._manifest["sig"]
        super().__init__(**kw)

        # --- sig guard, part 1: everything knowable before the model sees an obs ---
        # (part 2 -- prefix_seq_len -- can only be checked once vision has told us how
        # many image rows this obs actually produced; see embed_and_concat_prefix.)
        self._sig_check("denoise_steps", int(self.AE_NUM_DENOISE_STEPS),
                        int(self.sig["denoise_steps"]),
                        "pass --steps to match, or regenerate the bins")
        self._sig_check("keep_masked_slots", bool(self.KEEP_MASKED_SLOTS),
                        bool(self.sig["keep_masked_slots"]),
                        "toggle --keep-masked-slots to match, or regenerate the bins")
        for _name, _live in (("program_dram_base", self._program_dram_base),
                             ("tensor_dram_base", self._tensor_dram_base),
                             ("params_dram_base", self._params_dram_base)):
            self._sig_check(_name, hex(_live), self.sig[_name],
                            "pi05_libero_config.json's dram_layout changed since the bins "
                            "were compiled -- regenerate the bins")

        # PREFIX_SEQ_LEN is normally set by compile_prefix, which never runs here.
        # tensor_init_action_expert reads it (P -> Tkv -> every AE buffer size), so it
        # must be restored from the sig BEFORE that runs, or the AE buffers get sized
        # for the getattr default of 1024 and land at addresses the denoise program
        # does not reference.
        self.PREFIX_SEQ_LEN = int(self.sig["prefix_seq_len"])

        # Vision geometry that _weight_init_vision normally derives and publishes
        # (see _BIN_DERIVED_ATTRS). weight_init() below replaces that whole path with a
        # params.bin restore, so these would never exist -- yet tensor_init ->
        # _tensor_init_vision reads them within milliseconds of construction. Restored
        # verbatim from the dump (NOT recomputed from config) so they always match what
        # the loaded programs were compiled against.
        derived = self._manifest.get("derived")
        if not derived:
            raise RuntimeError(
                f"\n*** Bin set at {self.bin_dir} predates the `derived` block ***\n"
                f"  programs.json has no derived vision geometry, so this engine cannot\n"
                f"  reconstruct VIS_* without the weights_export unpack.\n"
                f"  Regenerate:  rm -f {os.path.join(self.bin_dir, '*.bin')} "
                f"{os.path.join(self.bin_dir, '*.json')} && "
                f"python {os.path.abspath(__file__)}\n"
                f"  (Do NOT rm -rf the bin dir: weights_export/ lives inside it.)\n")
        missing = [a for a in _BIN_DERIVED_ATTRS if a not in derived]
        if missing:
            raise RuntimeError(
                f"bin set at {self.bin_dir} is missing derived attrs {missing} "
                f"(stale bin set -- regenerate)")
        for _a, _v in derived.items():
            setattr(self, _a, _v)

    # ------------------------------------------------------------------
    # sig guard
    # ------------------------------------------------------------------

    def _sig_check(self, name, live, want, hint):
        if live != want:
            raise RuntimeError(
                f"\n*** REFUSING TO RUN: pre-compiled bins do not match this run ***\n"
                f"  {name}: bins were compiled for {want!r}, this run wants {live!r}\n"
                f"  bins: {self.bin_dir}\n"
                f"  The compiled programs bake absolute jump targets and absolute tensor\n"
                f"  DRAM addresses; they CANNOT be adapted to a different {name}.\n"
                f"  Fix: {hint}.\n"
                f"  Regenerate with:  rm -f {os.path.join(self.bin_dir, '*.bin')} "
                f"{os.path.join(self.bin_dir, '*.json')} && "
                f"python {os.path.abspath(__file__)}\n"
                f"  (Do NOT rm -rf the bin dir: weights_export/ lives inside it.)\n")

    # ------------------------------------------------------------------
    # Weights / params
    # ------------------------------------------------------------------

    def weight_init(self):
        """Replaces the weights_export unpack with a params.bin DRAM restore.

        The ONE thing still read from weights_export is the token embedding table: it is
        a HOST-side gather table (embed_and_concat_prefix indexes it per obs), never a
        params-DRAM resident, so it is not in params.bin and cannot be. Read-only.
        """
        self.embedding_table = self._npy(
            "PaliGemma.llm.embedder.input_embedding").to(torch.bfloat16)
        self.load_params()

    def load_params(self):
        """Restore the params DRAM snapshot and rewind the params allocator to the
        post-weight_init boundary."""
        bin_path = os.path.join(self.bin_dir, "params.bin")
        meta_path = os.path.join(self.bin_dir, "params.json")
        for p in (bin_path, meta_path):
            if not os.path.exists(p):
                raise FileNotFoundError(f"missing {p} -- regenerate the bins")
        with open(meta_path) as f:
            total = json.load(f)["size"]
        actual = os.path.getsize(bin_path)
        assert actual == total, (
            f"params.bin is {actual}B but params.json declares {total}B -- truncated or "
            f"stale bin set; regenerate.")
        CHUNK = self.DMA_CHUNK_BYTES
        with open(bin_path, "rb") as f:
            offset = 0
            while offset < total:
                data = f.read(min(CHUNK, total - offset))
                self._dma_write_retry(DMA_DEVICE_H2C, self._params_dram_base + offset,
                                      data, len(data))
                offset += len(data)

        # Rewind to the post-weight_init boundary, NOT to `total`. params.bin is dumped
        # at the END of a full run, so it also contains what tensor_init (identity
        # matrix), compile_prefix (attn bias, rope tables) and tensor_init_action_expert
        # allocated afterwards. Those later allocations are replayed below by the very
        # same methods the golden path uses; if the pointer started at `total` they would
        # be re-allocated PAST every weight instead of landing back on the addresses the
        # programs bake. The bytes are all already correct on-device either way -- this
        # only fixes where the allocator thinks it is.
        self._next_params_dram_addr = (self._params_dram_base
                                       + int(self.sig["params_ofs_after_weight_init"]))
        _original_print(
            f"  Params: {total / 1024**2:.1f} MB from bin "
            f"(allocator rewound to +{self.sig['params_ofs_after_weight_init']}B)")
        return True

    # ------------------------------------------------------------------
    # Programs
    # ------------------------------------------------------------------

    def load_programs(self):
        """DMA the three compiled programs back to DRAM and pre-seed the caches the
        stock run_vision()/run_inference() consult, so neither ever compiles."""
        bin_path = os.path.join(self.bin_dir, "programs.bin")
        if not os.path.exists(bin_path):
            raise FileNotFoundError(f"missing {bin_path} -- regenerate the bins")
        with open(bin_path, "rb") as f:
            blob = f.read()

        cache = self.__dict__.setdefault("_prog_cache", {})
        meta = self.__dict__.setdefault("_prog_meta", {})
        for name in _PROGRAM_ORDER:
            m = self._manifest["programs"][name]
            data = blob[m["offset"]:m["offset"] + m["size"]]
            assert len(data) == m["size"], (
                f"programs.bin truncated: {name} wants {m['size']}B, got {len(data)}B")
            addr = self.get_program_dram_addr()
            self._dma_write_retry(DMA_DEVICE_H2C, addr, data, len(data))
            self.allocate_program_dram(len(data))
            cache[name] = addr
            meta[name] = (addr, len(data))
            _original_print(f"    {name:<8} {len(data):>10}B -> 0x{addr:X}")

        # The first program must land exactly on the program base; if it does not, the
        # allocator was already advanced and every baked jump target is off.
        assert cache[_PROGRAM_ORDER[0]] == self._program_dram_base, (
            f"program allocator was not at its base when load_programs ran "
            f"(0x{cache[_PROGRAM_ORDER[0]]:X} != 0x{self._program_dram_base:X}) -- "
            f"every baked absolute jump target would be wrong.")

        # Pre-seed run_inference's compile-once latches so it takes its execute-only
        # branches. _prefix_bias_dram is the one address that cannot be re-derived: the
        # bias DATA depends on this obs's valid_len, so run_inference re-DMAs a fresh
        # bias to the addr baked into the prefix program.
        self._prefix_prog_addr = cache["prefix"]
        self._prefix_bias_dram = self._params_dram_base + int(self.sig["prefix_bias_ofs"])
        self._prefix_compiled = True
        self._denoise_prog_addr = cache["denoise"]
        self._denoise_compiled = True
        _original_print(f"  Programs: {len(blob) / 1024**2:.1f} MB from bin")
        return dict(cache)

    # ------------------------------------------------------------------
    # Allocator replay hooks
    # ------------------------------------------------------------------

    def tensor_init(self, max_seq_len=512):
        """Run the REAL allocator unchanged, then restore the two prefix K/V cache
        pointers that compile_prefix normally publishes.

        Load-bearing, and silent if missed: tensor_init_action_expert falls back to
        allocating a ZERO PLACEHOLDER prefix K/V (36 buffers out of the params arena) if
        prefix_k_cache_addr is absent. In a bin run compile_prefix never executes, so
        without this the action expert would (a) attend over zeros instead of the real
        prefix cache and (b) drag both allocators off-layout, moving every AE buffer away
        from the addresses the denoise program bakes. Same derivation compile_prefix and
        load_prefix_kv use -- pure arithmetic over tensor_init's own buffers.
        """
        super().tensor_init(max_seq_len)
        self.prefix_k_cache_addr = [self.LAYER0_K_DRAM + l * self.KV_LAYER_STRIDE
                                    for l in range(self.NUM_LAYERS)]
        self.prefix_v_cache_addr = [self.LAYER0_V_DRAM + l * self.KV_LAYER_STRIDE
                                    for l in range(self.NUM_LAYERS)]

    def tensor_init_action_expert(self):
        """Restore both bump allocators to their pre-AE positions, then run the REAL
        allocator unchanged.

        Without this the AE buffers move. In the golden path compile_prefix runs before
        this and allocates from BOTH the tensor arena (residual/rope buffers) and the
        params arena (attn bias + rope tables). A bin run never compiles, so both
        pointers are short by exactly that much, and every AE_* address -- including
        AE_XT_DRAM, where the noise goes in and the action chunk comes out -- would be
        computed at an address the denoise program never touches. The failure mode is a
        finite-but-garbage action chunk, not a crash.
        """
        if not getattr(self, "_ae_tensors_inited", False):
            self._tensor_dram_addr = (self._tensor_dram_base
                                      + int(self.sig["tensor_ofs_before_ae"]))
            self._next_params_dram_addr = (self._params_dram_base
                                           + int(self.sig["params_ofs_before_ae"]))
        return super().tensor_init_action_expert()

    def embed_and_concat_prefix(self, token_ids, vision_embeddings=None, seq_len=1024):
        """sig guard, part 2. This is the earliest point prefix_seq_len is known: it is
        DERIVED from however many vision rows run_vision actually returned (dead camera
        slots are dropped) plus PREFIX_TEXT_BUDGET. Checked here -- before the prefix or
        denoise programs execute -- so a mismatched obs refuses instead of running a
        program compiled for a different sequence length. (run_vision's encoder has
        already executed by now, but the encoder program is per-image-slot and entirely
        independent of prefix_seq_len, so that is harmless.)
        """
        self._sig_check(
            "prefix_seq_len", int(seq_len), int(self.sig["prefix_seq_len"]),
            f"this observation produced {seq_len - self.PREFIX_TEXT_BUDGET} vision rows "
            f"+ {self.PREFIX_TEXT_BUDGET} text budget = {seq_len} prefix tokens, but the "
            f"bins were compiled for {self.sig['prefix_seq_len']}. This usually means a "
            f"different number of live camera slots (a dead/all-zero slot is dropped). "
            f"Regenerate the bins from an observation with this camera configuration")
        valid_len = super().embed_and_concat_prefix(token_ids, vision_embeddings, seq_len)
        # Normally set by compile_prefix (which never runs here). dump_prefix_kv reads it,
        # so a bin run would AttributeError on the --debug K/V dump without this. The
        # prefix program is invariant to valid_len -- it only shapes the bias DATA that
        # run_inference re-DMAs -- so tracking it per obs is correct, not just defensive.
        self.prefix_valid_len = valid_len
        return valid_len

    def dump_bins(self, bin_dir):
        raise RuntimeError(
            "refusing to re-dump bins from a bin-backed run: this engine never compiled "
            "anything, so it would only write back what it just loaded (and its allocator "
            "checkpoints are restored, not measured). Dump from a fresh compile run.")


def _load_sample_images():
    """The 3 LIBERO image slots: base camera, wrist camera, all-zero 3rd camera.

    In-repo sample frames (physical-intelligence/libero dataset); the PNGs are
    pixel-identical to the original .npy arrays. SINGLE source of truth -- both the
    normal inference path and --encoderend call this, so --encoderend's timing is the
    real encoder cost of one inference rather than a differently-built slot set.
    The 3rd slot is all-zero on purpose: that is LIBERO's masked camera, and
    SKIP_ZERO_VISION_SLOTS (default False) decides whether it is still encoded.
    """
    from PIL import Image
    import torch.nn.functional as _F
    sample_dir = Path(__file__).parent / "sample_data"

    def _load_png(name):
        return np.asarray(Image.open(sample_dir / name).convert("RGB"),
                          dtype=np.float32) / 127.5 - 1.0

    def _resize(a):
        t = torch.from_numpy(a).permute(2, 0, 1).unsqueeze(0).float()
        t = _F.interpolate(t, size=(224, 224), mode="bilinear", align_corners=False)
        return t.squeeze(0).permute(1, 2, 0).numpy()

    img = _load_png("sample_0_image.png")
    wrist = _load_png("sample_0_wrist_image.png")
    pad = np.zeros_like(img)
    return [_resize(img), _resize(wrist), _resize(pad)]


def _load_norm_stats():
    """openpi's LIBERO norm_stats (state + actions quantiles). Shared by the
    prompt-token builder (state discretization) and main's action unnormalize --
    main used to read a `norm_stats` that only existed inside
    _load_sample_prompt_tokens's scope, which NameError'd after a full run.

    Read from the checkpoint inside <model>_bin/ (the model convention). The legacy
    ~/.cache/openpi location is still accepted so an existing machine keeps working
    if only assets/ was left behind there."""
    rel = Path("assets") / "physical-intelligence" / "libero" / "norm_stats.json"
    candidates = [Path(_ckpt_local_dir()) / rel,
                  Path.home() / ".cache" / "openpi" / "openpi-assets" / "checkpoints"
                  / "pi05_libero" / rel]
    for path in candidates:
        if path.exists():
            return json.loads(path.read_text())["norm_stats"]
    raise FileNotFoundError(
        "norm_stats.json not found. Looked in:\n  " + "\n  ".join(str(p) for p in candidates)
        + "\nIt ships with the pi05 checkpoint -- re-run the export to fetch it.")


def _load_sample_state():
    """The sample observation's raw (un-normalized) proprioceptive state.

    Same reason _load_norm_stats exists: `meta` was a local of
    _load_sample_prompt_tokens, and main's --verify-denoise branch read a
    `meta["state_example"]` that was never in its scope -- so --verify-denoise
    NameError'd after every full run and has never actually produced a number.
    One loader, both callers.
    """
    sample_dir = Path(__file__).parent / "sample_data"
    meta = json.loads((sample_dir / "meta.json").read_text())
    return np.array(meta["state_example"], dtype=np.float32)


def _load_sample_prompt_tokens():
    """Real tokenization of the sample observation (matches openpi's
    PaligemmaTokenizer.tokenize, Pi05 format -- the state is discretized INTO the
    language prompt text, not fed as a separate continuous input):
    "Task: {prompt}, State: {digitized state};\nAction: ", sentencepiece + BOS.

    SINGLE source of truth, shared by the normal path and --prefixend, so the
    prefix stage sees identical tokens in both (a random-token placeholder used to
    live here and produced garbage language conditioning).
    """
    import sentencepiece
    norm_stats = _load_norm_stats()
    state = _load_sample_state()
    state_q01 = np.array(norm_stats["state"]["q01"], dtype=np.float32)
    state_q99 = np.array(norm_stats["state"]["q99"], dtype=np.float32)
    state_norm = np.clip((state - state_q01) / (state_q99 - state_q01 + 1e-6) * 2.0 - 1.0, -1.0, 1.0)
    digitized_state = np.digitize(state_norm, bins=np.linspace(-1, 1, 257)[:-1]) - 1
    state_str = " ".join(map(str, digitized_state))
    full_prompt = (f"Task: {_CFG['defaults'].get('prompt', 'pick up the object')}, "
                   f"State: {state_str};\nAction: ")
    sp = sentencepiece.SentencePieceProcessor(model_file=ensure_tokenizer())
    return np.array(sp.encode(full_prompt, add_bos=True), dtype=np.int64)


def configure_engines(engines=1, vis_4=False, pref_8=False, dns_8=False, tag="main"):
    """Set the engine-count class attributes. Returns True if this is multi-engine.

    SHARED by pi05_libero_test.main() and libero_eval.py. It lives here as a
    function rather than inline in main() because libero_eval constructs
    Pi05Libero_UnifiedEngine() directly and never calls main() -- so before this
    existed, every closed-loop LIBERO episode silently ran SINGLE-ENGINE no matter
    what the caller thought, because the knobs are class attributes that only
    main()'s argument parsing ever wrote.

    `engines` is an int 1-8 or the literal "max"; normalize ONCE here so no
    downstream comparison has to know which it got.
    """
    eng_max = (engines == "max")
    eng_n = max(Pi05Libero_UnifiedEngine.STAGE_MAX_ENGINES.values()) if eng_max \
        else int(engines)
    multi = eng_max or eng_n > 1

    if eng_max:
        # Each stage's OWN ceiling, read from STAGE_MAX_ENGINES rather than assumed.
        # Those ceilings are all 8 today (vision reached 8 once it became 2D: 4 row
        # groups x 2 K lanes -- it capped at 4 while it was row-sharded only, since
        # S=256/slot is just 4 blocks of 64), so "max" and a flat 8 currently agree.
        # They are NOT guaranteed to: any stage whose ceiling drops below 8 makes
        # them diverge again, which is the whole reason this reads the dict.
        # Applied as the same <STAGE>_NUM_ENGINES overrides --vis_4/--pref_8/--dns_8
        # use, so the explicit flags below can still override any single stage.
        for stage, n in Pi05Libero_UnifiedEngine.STAGE_MAX_ENGINES.items():
            setattr(Pi05Libero_UnifiedEngine, f"{stage}_NUM_ENGINES", n)
        Pi05Libero_UnifiedEngine.NUM_ENGINES = eng_n
        print(f"[{tag}] --engines max: per-stage ceilings -- "
              + ", ".join(f"{s.lower()}={n}"
                          for s, n in Pi05Libero_UnifiedEngine.STAGE_MAX_ENGINES.items())
              + " (vision is 2D: 4 row groups x 2 K lanes -- S=256/slot is only 4 blocks)")
    else:
        Pi05Libero_UnifiedEngine.NUM_ENGINES = eng_n
        if eng_n > 1:
            print(f"[{tag}] NUM_ENGINES={eng_n} -- vision encoder AND prefix LM "
                  f"row-sharded (M) and the denoise gated MLP column-sharded (N) across "
                  f"{eng_n} engines (bins cannot be dumped in this mode)")

    # Per-stage engine overrides. These set <STAGE>_NUM_ENGINES, which
    # _num_engines() prefers over NUM_ENGINES, so they compose with --engines and
    # with each other: `--vis_4 --pref_8` runs vision on 4 and the prefix on 8
    # while denoise stays on --engines. Sharding a stage is not free in DRAM --
    # see _vis_worker_arena_base, which sizes ONE arena set from the PEAK count.
    if vis_4:
        Pi05Libero_UnifiedEngine.VIS_NUM_ENGINES = 4
        print(f"[{tag}] --vis_4: vision encoder row-sharded across 4 engines "
              "(S=256/slot = 4 blocks of 64 -> perfect even split; 4 is this stage's max)")
    if pref_8:
        Pi05Libero_UnifiedEngine.PREFIX_NUM_ENGINES = 8
        print(f"[{tag}] --pref_8: prefix LM row-sharded across 8 engines "
              "(S=832 -> 13 blocks of 64, uneven 5x128 + 3x64, ~81% efficient; "
              "shorter prefixes degrade or fall back -- see _prefix_num_engines)")
    if dns_8:
        Pi05Libero_UnifiedEngine.DENOISE_NUM_ENGINES = 8
        print(f"[{tag}] --dns_8: denoise stage column-sharded (N) across 8 engines "
              "(M=64 is one row block -> row-sharding impossible; mlp down uses "
              "split_k + reduce_add)")
    if multi or vis_4 or pref_8 or dns_8:
        print(f"[{tag}] multi-engine: bins cannot be dumped in this mode")
    return multi or vis_4 or pref_8 or dns_8


def main():
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument("--debug", action="store_true",
                     help="skip vision+prefix (~185s) and reload the last-dumped prefix K/V "
                          "cache from PREFIX_KV_DUMP_PATH instead -- for fast denoise-loop-only "
                          "iteration. Requires a prior non-debug run (which auto-dumps).")
    ap.add_argument("--steps", type=int, default=None,
                     help="override AE_NUM_DENOISE_STEPS (e.g. --steps 1 to stop after the first "
                          "Euler step, since step0 already NaNs -- no point paying for all 10).")
    ap.add_argument("--sanity-check", action="store_true",
                     help="isolation test: run vision + prefix for real, then instead of the full "
                          "denoise loop, run a small basic bf16 matmul (no IF4 quant, no PBI, no "
                          "special registers) and diff it against a CPU reference. Tests raw "
                          "post-vision+prefix hardware health with the simplest possible op, "
                          "independent of anything denoise-loop-specific.")
    ap.add_argument("--verify-vision", action="store_true",
                     help="after run_vision(), diff the HW vision tokens against "
                          "pi05_torch_ref.vision_encode with the SAME IF4 weights. The vision "
                          "encoder has no RoPE, so it was never invalidated by the rope bug -- "
                          "and it was also never actually checked (the checker existed but was "
                          "dead code). Image tokens are 512 of the 557 unmasked prefix rows, so "
                          "any vision drift dominates the prefix K/V SNR.")
    ap.add_argument("--verify-denoise", action="store_true",
                     help="after the full FPGA run, run pi05_torch_ref.run_pi05 on CPU with the "
                          "SAME quant (IF4, matching lm_quant/vision_quant=q4_64), SAME images, "
                          "SAME prompt tokens, SAME state, and the SAME RandomState(0) noise -- so "
                          "the only variable is HW-vs-CPU execution -- and report per-dim / "
                          "per-timestep / overall SNR of the (10,7) action output.")
    ap.add_argument("--probe-step0", action="store_true",
                     help="snapshot step-0 action-expert intermediates and diff each against the "
                          "torch reference (fed the FPGA's own K/V) to localize which op first "
                          "diverges. Works with --debug for a fast ~75s iteration loop.")
    ap.add_argument("--keep-masked-slots", action=argparse.BooleanOptionalAction, default=True,
                     help="Carry all-zero image slots as -inf-masked placeholder rows -> prefix "
                          "832 tokens (matches the GPU, which processes all image tokens). "
                          "DEFAULT ON. Pass --no-keep-masked-slots to DROP them (prefix 576 "
                          "tokens, -1050 GFLOP). Output is bit-identical either way.")
    ap.add_argument("--skip-zero-vision-slots", action=argparse.BooleanOptionalAction, default=False,
                     help="Skip the encoder for all-zero (padding) image slots. DEFAULT OFF -- "
                          "every slot is encoded (full 3-slot vision pass, matches the GPU). "
                          "Pass --skip-zero-vision-slots to skip the encoder for zero slots. "
                          "Attention masking is unaffected either way.")
    ap.add_argument("--encoderend", action="store_true",
                     help="Run ONLY the vision encoder, over ALL 3 image slots (the same "
                          "slot set the real pipeline feeds through run_vision), and stop: "
                          "no prefix, no denoise loop, no action output. Prints a "
                          "format-identical ENC_ONLY summary block and dumps head_out to .npy "
                          "so a --engines 1 run and a --engines 2 run can be "
                          "diffed directly against each other.")
    ap.add_argument("--encdump", default=None,
                     help="--encoderend: PREFIX for the per-slot .npy dumps; each slot is "
                          "written to <prefix>_slot<i>_<checkpoint>.npy (default prefix: "
                          "models/pi05_libero/enc_only_ne<N>).")
    ap.add_argument("--prefixend", action="store_true",
                     help="Run the pipeline through the END OF THE PREFIX stage and stop: "
                          "vision encoder, then the Gemma-2B prefix pass that builds the "
                          "K/V cache, then stop. No action-expert denoise loop, no action "
                          "output. Next rung of the same ladder as --encoderend. --engines N "
                          "shards BOTH stages; the summary prints the per-stage engine "
                          "counts and the prefix's 64-row block split.")
    ap.add_argument("--prefixdump", default=None,
                     help="--prefixend: path for the prefix K/V .npy dump (default: "
                          "models/pi05_libero/prefix_end_ne<N>_kv.npy).")
    def _engines_arg(value):
        """--engines N | max.  'max' == each stage's own ceiling, not a flat 8."""
        if str(value).strip().lower() == "max":
            return "max"
        try:
            n = int(value)
        except ValueError:
            raise argparse.ArgumentTypeError(
                f"--engines takes an integer 1-8 or 'max', got {value!r}")
        if not 1 <= n <= 8:
            raise argparse.ArgumentTypeError(
                f"--engines must be 1-8 (the ISA's flag-check addresses engines 0-7), "
                f"got {n}")
        return n

    ap.add_argument("--engines", type=_engines_arg, default=1, metavar="N|max",
                     help="Number of accelerator engines to row-shard across. DEFAULT 1 = "
                          "the single-engine path, byte-identical to before; only an "
                          "explicit --engines N>1 enables sharding. Applies to the vision "
                          "encoder (M=256 -> N blocks of 256/N rows) AND the prefix LM "
                          "(S rows -> N uneven-but-64-aligned block groups); the denoise "
                          "stage will adopt the same knob. 8 is the device max (the ISA's "
                          "flag-check addresses engine 0-7).\n"
                          "--engines max applies EACH STAGE'S OWN CEILING rather than one "
                          "number: vision 4, prefix 8, denoise 8 (STAGE_MAX_ENGINES). A flat "
                          "--engines 8 is NOT the same thing and is wrong for vision, which "
                          "asserts above 4 -- S=256/slot is only 4 blocks of 64. This is the "
                          "recommended way to run fully sharded; it is exactly equivalent to "
                          "--vis_4 --pref_8 --dns_8. Those three still exist for isolating one "
                          "stage at a time (e.g. --vis_4 alone gives a single-engine prefix "
                          "baseline) and take precedence over this flag.")
    ap.add_argument("--pref_8", action="store_true",
                     help="Row-shard the PREFIX LM across 8 engines (PREFIX_NUM_ENGINES=8), "
                          "independently of --engines. The prefix is ~73%% of total FLOPs, so "
                          "it is where engine count pays. S=832 (3 image slots) is 13 blocks "
                          "of 64 rows and 13 is prime, so the split is uneven -- 5 engines get "
                          "128 rows, 3 get 64 -> 81%% efficiency, ~6.4x. NOTE the shorter "
                          "prefixes: S=576 is only 56%% efficient and S=320 (5 blocks) cannot "
                          "be split 8 ways at all and falls back to a single engine "
                          "(_prefix_num_engines). Forces the 24 MB worker-arena profile.")
    ap.add_argument("--precompile", action=argparse.BooleanOptionalAction, default=True,
                     help="Compile all three stages (encoder, prefix, denoise) BEFORE any "
                          "of them executes, so the inference runs back-to-back with no "
                          "compilation in between. DEFAULT ON. Nothing in a compile depends "
                          "on an earlier stage's RESULTS -- only its addresses and shapes -- "
                          "so seq_len is derived (slots*VIS_S + PREFIX_TEXT_BUDGET, asserted "
                          "against the real value later) and valid_len is a placeholder, "
                          "since it shapes only the bias DATA that is re-DMA'd per obs. "
                          "--no-precompile restores the old lazy compile-on-first-use, where "
                          "the first inference carries ~8s of compile inside its stage times.")
    ap.add_argument("--dns_8", action="store_true",
                     help="COLUMN-shard (N) the DENOISE stage across 8 engines "
                          "(DENOISE_NUM_ENGINES=8), independently of --engines. Denoise is "
                          "M=AE_ACTION_HORIZON_PADDED=64 -- ONE 64-row block at every op -- so "
                          "it cannot be row-sharded at any count; the fat OUTPUT dims are split "
                          "instead: mlp gate/up 4096->512, adaRMS 3072->384, q 2048->256 "
                          "(exactly one head per engine), o 1024->128. k/v proj (N=256, 4 "
                          "blocks) stays unsharded, and mlp down is K-fat (4096->1024) so it "
                          "goes through split_k + reduce_add -- 7 serialized adds and two "
                          "rendezvous per layer per step. Must be set before weight_init: the "
                          "K-sliced mlp-down blobs are built there for THIS engine count.")
    ap.add_argument("--vis_4", action="store_true",
                     help="Row-shard the VISION encoder across 4 engines "
                          "(VIS_NUM_ENGINES=4), independently of --engines. 4 is the HARD "
                          "maximum for this stage: it shards S=VIS_S=256 patch tokens PER "
                          "IMAGE SLOT, which is exactly 4 blocks of 64, so 64-row alignment "
                          "makes 8 impossible (split_rows asserts). At 4 it is a perfect even "
                          "split -- 64 rows each, 100%% balanced.")
    ap.add_argument("--cond-table-on-device", action=argparse.BooleanOptionalAction, default=True,
                     help="Run the action-expert timestep-embedding MLP (2x 1024x1024 IF4 "
                          "matmul + 2x composed SiLU) on the accelerator (default). "
                          "--no-cond-table-on-device falls back to the host constant-fold.")
    ap.add_argument("--check-cond-table", action="store_true",
                     help="After the denoise run, read back the device-computed (N,1024) "
                          "AdaRMSNorm conditioning table and report per-step + overall SNR "
                          "against the exact host oracle.")
    # Every other entry point in the repo (user_hw_test.py:6047, multi_engine_hw_test.py,
    # randomize_dram.py, the *_run_from_bin.py set) takes --dev/--base-addr and calls
    # set_dma_device; this file did not, so it silently inherited the user_dma_core
    # module defaults (/dev/xdma0_*, UE_0_BASE_ADDR=0x02000000). That matters most under
    # model_auto_test.py, which calls set_dma_device(dev) for the DRAM-poison step and
    # then launches this script as a SUBPROCESS -- a fresh interpreter where that call
    # never happened, so a non-default --dev was honored for the poison and dropped here.
    ap.add_argument("--dev", type=str, default="xdma0",
                     help="DMA device name (e.g. xdma0, xdma1). Default: xdma0.")
    ap.add_argument("--device", type=str, default="kintex7",
                     help="FPGA profile (e.g. rk, rk_256, kintex7, bittware, efinix).")
    ap.add_argument("--base-addr", type=lambda x: int(x, 0), default=None,
                     help="AXI-Lite register base address (default: device-specific).")

    # parse_known_args (not parse_args) because libero_eval.py imports this module and
    # passes its own flags through. That tolerance silently swallows TYPOS too --
    # `--pref_9` parsed fine and did nothing -- so say what was dropped.
    args, _unknown = ap.parse_known_args()
    if _unknown:
        print(f"[main] WARNING: ignoring unrecognized argument(s): {' '.join(_unknown)}")

    # Before ANY UnifiedEngine is constructed: __init__ snapshots the live
    # DMA_DEVICE_* globals into the instance (user_dma_core.py:566), so an engine
    # built before this call stays bound to the default device for its lifetime --
    # including every worker in _worker_engine_pool.
    user_dma_core.set_dma_device(
        "efinix" if args.device == "efinix" else args.dev, base_addr=args.base_addr)
    print(f"[main] DMA dev={args.dev} (H2C={user_dma_core.DMA_DEVICE_H2C}, "
          f"C2H={user_dma_core.DMA_DEVICE_C2H}, USER={user_dma_core.DMA_DEVICE_USER}), "
          f"UE_0_BASE_ADDR={user_dma_core.UE_0_BASE_ADDR:#010x}")

    Pi05Libero_UnifiedEngine.AE_COND_TABLE_ON_DEVICE = bool(args.cond_table_on_device)
    Pi05Libero_UnifiedEngine.AE_COND_TABLE_CHECK = bool(args.check_cond_table)
    if not args.cond_table_on_device:
        print("[main] cond table: HOST constant-fold (on-device time-MLP disabled)")

    assert not (args.encoderend and args.prefixend), (
        "--encoderend and --prefixend are mutually exclusive: they are two different "
        "stopping points on the same ladder (encoder -> prefix -> full). Pick one.")

    _multi = configure_engines(args.engines, vis_4=args.vis_4, pref_8=args.pref_8,
                               dns_8=args.dns_8, tag="main")

    PREFIX_KV_DUMP_PATH = os.path.join(os.path.dirname(__file__), "debug_prefix_kv.npz")

    if args.steps is not None:
        Pi05Libero_UnifiedEngine.AE_NUM_DENOISE_STEPS = args.steps
        print(f"[main] AE_NUM_DENOISE_STEPS overridden to {args.steps}")

    if args.probe_step0:
        Pi05Libero_UnifiedEngine.DENOISE_STEP0_PROBE = True
        print("[main] DENOISE_STEP0_PROBE enabled -- will snapshot + diff step-0 intermediates")

    if args.verify_vision:
        Pi05Libero_UnifiedEngine.VISION_SNR_CHECK = True
        print("[main] VISION_SNR_CHECK enabled -- will diff the vision encoder vs the IF4 reference")

    Pi05Libero_UnifiedEngine.KEEP_MASKED_SLOTS = bool(args.keep_masked_slots)
    if args.keep_masked_slots:
        print("[main] KEEP_MASKED_SLOTS enabled (default) -- dead image slots carried as "
              "masked placeholder rows (prefix 832 tok)")
    else:
        print("[main] KEEP_MASKED_SLOTS disabled (--no-keep-masked-slots) -- dead slots "
              "dropped (prefix 576 tok)")

    Pi05Libero_UnifiedEngine.SKIP_ZERO_VISION_SLOTS = bool(args.skip_zero_vision_slots)
    if args.skip_zero_vision_slots:
        print("[main] SKIP_ZERO_VISION_SLOTS enabled -- encoder skips all-zero image slots")
    else:
        print("[main] SKIP_ZERO_VISION_SLOTS disabled (default) -- every image slot "
              "encoded on-HW (full 3-slot vision pass)")

    if os.environ.get("PI05_L0_REPORT"):
        Pi05Libero_UnifiedEngine.PREFIX_SNAPSHOTS = True
        print("[main] PREFIX_SNAPSHOTS enabled -- layer0 op-by-op report")

    # --- Compile-from-weights vs load-from-bins -------------------------------
    # Bins are only usable for a full non-debug run: --debug/--sanity-check/--probe-step0
    # take paths that compile extra probe programs or skip prefix entirely, which would
    # desync the program allocator from the dumped layout.
    # ... and --engines>1 must COMPILE (the bins only hold engine0's encoder).
    # --vis_4/--pref_8 must invalidate the bins for the same reason --engines>1 does:
    # the bins hold ONLY engine0's single-engine programs, so replaying them would
    # run the unsharded model while printing that sharding is on -- the flags would
    # silently do nothing. Any knob that changes the compiled program must be listed
    # here, or it is quietly ignored whenever a bin set happens to be present.
    _bin_ok = not (args.debug or args.sanity_check or args.probe_step0
                   or _multi or args.vis_4 or args.pref_8 or args.dns_8
                   or args.encoderend or args.prefixend)
    bins_exist = _bin_ok and os.path.exists(os.path.join(BIN_DIR, "params.bin")) \
                          and os.path.exists(os.path.join(BIN_DIR, "programs.bin")) \
                          and os.path.exists(os.path.join(BIN_DIR, "programs.json"))

    if bins_exist:
        print(f"[main] loading pre-compiled bins from {BIN_DIR} (no weight unpack, no compile)")
        ue = Pi05Libero_Run(bin_dir=BIN_DIR)
    else:
        ue = Pi05Libero_UnifiedEngine()
    init_hang_prevention(ue)
    ue.weight_init()          # Pi05Libero_Run overrides this to load params.bin
    ue.tensor_init(_CFG["defaults"].get("max_seq", 512))
    if bins_exist:
        # Must follow tensor_init: load_programs only touches the program allocator, but
        # keeping the order identical to the compile path keeps the two flows comparable.
        ue.load_programs()

    # --- --encoderend: vision encoder A/B over ALL slots, nothing else -----------
    if args.encoderend:
        # EXACTLY the slot construction the normal path uses below (base camera,
        # wrist camera, all-zero 3rd camera) so the total wall-clock is the real
        # encoder cost of one inference. Do not invent a third image.
        images = _load_sample_images()
        ue.run_encoder_only(images, dump_prefix=args.encdump)
        return

    # --- --prefixend: encoder + prefix, then stop -----------------------------
    if args.prefixend:
        ue.run_prefix_end(_load_sample_images(), _load_sample_prompt_tokens(),
                          dump_path=args.prefixdump)
        return

    # Full end-to-end: vision -> prefix -> action-expert denoise loop.
    # Vision: confirmed hang-free (all 3 slots, 432 head-jumps).
    # Prefix: NaN (padding-row epsilon) and hang (_dram_split_copy strided DMA)
    # bugs fixed -- see embed_and_concat_prefix's padding comment and
    # _weight_init_lm_prefix's FF_HALF-split comment -- confirmed clean for the
    # FULL 18 layers with real vision data (182s).
    # Denoise loop: confirmed clean standalone with a placeholder (zero-filled)
    # K/V cache (123.9s, statically unrolled -- see compile_denoise_loop's
    # docstring for why it's not a loop_start/loop_end runtime loop). This is
    # the first time all three stages run back-to-back together with the REAL
    # prefix K/V cache feeding the action-expert -- genuinely uncharted, so
    # treat any failure here as new territory, not a regression.
    if args.debug:
        # Fast path: skip vision+prefix (~185s), reload the prefix K/V cache
        # dumped by a prior non-debug run. images/prompt_tokens are unused.
        assert os.path.exists(PREFIX_KV_DUMP_PATH), (
            f"--debug requires a prior non-debug run to have dumped {PREFIX_KV_DUMP_PATH} first "
            f"(run without --debug once, then rerun with --debug for fast iteration).")
        ue.load_prefix_kv(PREFIX_KV_DUMP_PATH)
        actions = ue.run_inference(None, None, skip_prefix=True)
    else:
        # In-repo sample frames (LIBERO base + wrist camera, physical-intelligence/libero
        # dataset). PNGs are pixel-identical to the original .npy arrays. Self-contained.
        images = _load_sample_images()

        prompt_tokens = _load_sample_prompt_tokens()

        # Compile encoder + prefix + denoise BEFORE any of them executes, so the
        # inference itself is three back-to-back hardware runs with no compilation
        # interleaved. Skipped for --sanity-check, which deliberately stops after
        # prefix and never builds the action expert.
        if args.precompile and not args.sanity_check:
            ue.precompile_all()

        actions = ue.run_inference(
            images, prompt_tokens, dump_prefix_path=PREFIX_KV_DUMP_PATH,
            sanity_check=args.sanity_check)

        if args.sanity_check:
            return

        # Dump bins after the first successful full inference so later runs can skip
        # weight-unpack + compile entirely. Gated on the bins not already existing (a
        # bin-backed run has nothing new to dump, and re-dumping would just read back
        # what it loaded). Everything the dump needs -- _prog_meta, prefix_bias_dram,
        # _ae_alloc_ckpt -- only exists after a real vision->prefix->denoise pass.
        # Multi-engine runs cannot be dumped (the bin format carries only the primary's
        # programs -- dump_programs_to_file refuses). Skip rather than assert, so a
        # successful --engines N inference does not exit non-zero after the fact.
        if not bins_exist and ue._num_engines("VIS") == 1:
            print(f"\n[main] dumping pre-compiled bins to {BIN_DIR} ...")
            ue.dump_bins(BIN_DIR)
        elif not bins_exist:
            print("\n[main] skipping bin dump: multi-engine run "
                  "(bins carry only the primary engine's programs). Use --engines 1.")

    if args.probe_step0:
        ue.verify_denoise_step0(PREFIX_KV_DUMP_PATH)

    np.set_printoptions(precision=4, suppress=True)
    if not args.debug:
        # Unnormalize to real robot action space (openpi Unnormalize transform:
        # (x+1)/2*(q99-q01)+q01) using the actions norm_stats -- the deployable output.
        norm_stats = _load_norm_stats()
        act_q01 = np.array(norm_stats["actions"]["q01"], dtype=np.float32)
        act_q99 = np.array(norm_stats["actions"]["q99"], dtype=np.float32)
        actions_unnorm = (actions + 1.0) / 2.0 * (act_q99 - act_q01 + 1e-6) + act_q01
        print("action_chunk (real robot actions):", actions_unnorm.shape)
        print(actions_unnorm)
    else:
        # --debug has no norm_stats loaded; show the raw normalized [-1,1] output.
        print("action_chunk (raw, normalized [-1,1] -- --debug, no norm_stats):", actions.shape)
        print(actions)
    print(f"nan={np.isnan(actions).any()} inf={np.isinf(actions).any()} "
          f"min={actions.min():.4f} max={actions.max():.4f}")

    if args.verify_denoise and not args.debug:
        # CPU IF4 reference, matched apples-to-apples: same quant our model uses
        # (q4_64 == if4), same images/prompt/state, and CRUCIALLY the same
        # RandomState(0) noise the FPGA denoise seeds (run_inference uses
        # noise32[:10,:7] = RandomState(0).randn(10,7); the reference's own
        # main() uses torch.manual_seed(0) -- a DIFFERENT RNG -- so we must
        # feed the exact numpy array here, not let it reseed). Isolates pure
        # HW-vs-CPU execution error (no noise-seed, no quant-policy confound).
        import pi05_torch_ref as _ref
        ref_device = "cuda" if torch.cuda.is_available() else "cpu"
        print(f"[verify-denoise] running IF4 reference (pi05_torch_ref.run_pi05) on "
              f"{ref_device}... vision+prefix+denoise"
              + (" on GPU (fast)" if ref_device == "cuda"
                 else " on CPU (bf16, slow -- pass --ref-device cuda if you have a GPU)"))
        W = _ref.Weights(device=ref_device, dtype=torch.bfloat16, quant="if4")
        ref_images = torch.stack([torch.from_numpy(im).to(torch.bfloat16) for im in images], dim=0).to(ref_device)
        ref_prompt = torch.from_numpy(prompt_tokens).long().unsqueeze(0).to(ref_device)
        # run_pi05 reads `state` ONLY for b = state.shape[0] -- Pi05 feeds the
        # state through the prompt TEXT (see _load_sample_prompt_tokens), not as a
        # continuous input. Shape is what matters; we still pass the real sample
        # state so this matches pi05_torch_ref.main() exactly.
        ref_state = torch.from_numpy(_load_sample_state()).unsqueeze(0).to(ref_device)
        noise7 = np.random.RandomState(0).randn(10, 7).astype(np.float32)  # SAME as run_inference
        noise32 = torch.zeros(1, 10, 32, dtype=torch.float32)
        noise32[..., :7] = torch.from_numpy(noise7)
        noise32 = noise32.to(ref_device)
        ref_actions, ref_kv = _ref.run_pi05(ref_images, ref_prompt, ref_state, W,
                                            noise=noise32, return_kv=True,
                                            masked_cols=getattr(ue, "prefix_masked_cols", []))
        ref_actions = ref_actions[..., :7]
        ref_np = ref_actions.squeeze(0).float().cpu().numpy()

        # --- Prefix K/V comparison: FPGA dumped cache vs reference cache ---
        # Splits the failure: if prefix K/V matches, the bug is in the action
        # head; if it diverges, the break is at/inside prefix.
        try:
            kv_path = PREFIX_KV_DUMP_PATH
            npz = np.load(kv_path)
            NL, D = ue.NUM_LAYERS, ue.HEAD_DIM
            vlen = int(npz["prefix_valid_len"])
            # per-layer row stride is the ALLOCATED seq (max_seq_len, padded),
            # not PREFIX_SEQ_LEN -- derive it from the buffer size so we don't
            # assume. total_elems = NL * stride_rows * D.
            stride_rows = npz["k"].size // (NL * D)
            fpga_k = torch.frombuffer(npz["k"].tobytes(), dtype=torch.bfloat16).float().reshape(NL, stride_rows, D)
            fpga_v = torch.frombuffer(npz["v"].tobytes(), dtype=torch.bfloat16).float().reshape(NL, stride_rows, D)
            ref_k_list, ref_v_list = ref_kv  # each: list of 18 (b,P,1,256)
            print(f"=== Prefix K/V SNR: FPGA cache vs CPU-IF4 reference (valid_len={vlen}) ===")
            def _snr(a, b):
                return 20 * torch.log10(b.norm() / (a - b).norm().clamp_min(1e-12)).item()
            # Compare ONLY the rows that actually participate in attention. The masked
            # image slot's rows legitimately differ (FPGA writes a 1e-6 placeholder;
            # the reference runs SigLIP on the zero image and gets real values) -- they
            # are masked out of every softmax, so including them buries the real signal
            # (they alone made this metric read ~4dB even when the model was correct).
            _mc = npz["masked_cols"] if "masked_cols" in npz else np.zeros((0, 2), dtype=np.int64)
            keep = torch.ones(min(int(ref_k_list[0].shape[1]), vlen), dtype=torch.bool)
            for a, b in [(int(x), int(y)) for x, y in np.asarray(_mc).reshape(-1, 2)]:
                if a < keep.shape[0]:
                    keep[a:min(b, keep.shape[0])] = False
            for L in range(NL):
                rk = ref_k_list[L].squeeze(0).squeeze(1).float().cpu()  # (P,256)
                rv = ref_v_list[L].squeeze(0).squeeze(1).float().cpu()
                P = min(rk.shape[0], vlen)
                m = keep[:P]
                fk = fpga_k[L, :P][m]
                fv = fpga_v[L, :P][m]
                print(f"  layer{L:2d}: K_SNR={_snr(fk, rk[:P][m]):6.2f}dB  "
                      f"V_SNR={_snr(fv, rv[:P][m]):6.2f}dB")
        except Exception as e:
            print(f"[prefix-kv-compare] skipped: {e}")

        hw = torch.from_numpy(actions).float()      # (10,7) FPGA
        cpu = torch.from_numpy(ref_np).float()      # (10,7) CPU IF4
        def _snr(a, b):
            return 20 * torch.log10(b.norm() / (a - b).norm().clamp_min(1e-12)).item()
        print("=== FPGA vs CPU-IF4 denoise SNR (matched noise/inputs) ===")
        print(f"  overall: SNR={_snr(hw, cpu):.2f}dB  MSE={((hw-cpu)**2).mean().item():.6f}")
        for d in range(7):
            print(f"  dim{d}: SNR={_snr(hw[:, d], cpu[:, d]):.2f}dB  "
                  f"hw[{hw[:,d].min():.3f},{hw[:,d].max():.3f}] cpu[{cpu[:,d].min():.3f},{cpu[:,d].max():.3f}]")
        for tstep in range(10):
            print(f"  step{tstep}: SNR={_snr(hw[tstep], cpu[tstep]):.2f}dB")
        # Print the reference in BOTH spaces. The SNR block above is computed in
        # NORMALIZED space, but main prints the FPGA chunk UNNORMALIZED ("real
        # robot actions"). Printing ref_np raw next to it invited a false
        # side-by-side: e.g. the gripper's q01/q99 are +/-1 so dim6 is identity
        # and looks comparable, while dim0 is scaled by a different factor
        # entirely and is not.
        print("CPU-IF4 reference action_chunk (10,7) [normalized, matches SNR block]:")
        print(ref_np)
        _ns = _load_norm_stats()
        _q01 = np.array(_ns["actions"]["q01"], dtype=np.float32)
        _q99 = np.array(_ns["actions"]["q99"], dtype=np.float32)
        print("CPU-IF4 reference action_chunk (10,7) [real robot actions, "
              "directly comparable to the FPGA chunk above]:")
        print((ref_np + 1.0) / 2.0 * (_q99 - _q01 + 1e-6) + _q01)

    if args.probe_step0:
        ue.probe_nan_report()


if __name__ == "__main__":
    main()
